  Item_10025_StoryDesc = {
    Text = "風が四方から吹き寄せ、あなたは蝋燭を持って迷宮の入口に立っている。\n少し混乱している。\nついさっきまで、ミサゴの食堂でシャーロットが図書館の地下迷宮の伝説を話していたのを聞いていたようだ。\nそして今、あなたはパジャマを着て、眠そうに次々と通路を歩いている。\n「シャーロット、シャーロット…………」\nささやかな音と共に、白い蜘蛛が波のように押し寄せる。\nそれらは白い少女に凝結し、肉塊で作られたブランコに座って揺れている。\n\n「来たのね」彼女は言った。\n「シャーロットを探しに来たんだ、友達なんだ。彼女は迷子になった、見つけなきゃ…………」\nあなたはほとんど泣きそうになっている。\n少女はくすくす笑い、ブランコから飛び降りてあなたの前に来た。\n「忘れたの？私たちの取引…………」\n少女は手を伸ばしてあなたのお腹に触れ、はっとした。\n「そうだね。もう私の子孫になっているから、何も覚えていないんだ」\n「子孫…………？」\nあなたは肌が触れ合う場所を感じた。\n温かい感触が蜘蛛の巣のように皮膚の下に入り込み、血管の奥深くまで広がっていく。\n少女は神秘的にウインクし、あなたの耳元でささやいた：\n「シャーロットは、あなたのお腹の中にいるのよ」"
  },
  Item_10026_Desc = {
