  Item_10056_Name = {Text = "同調率"},
  Item_100577_Desc = {
    Text = "このキーオーダーを記録すると、編成時にキーオーダースキル「束の間の夢」を選択可能。\n\n美しく、満ち足りた、柔らかなものすべては人を堕落させる。だがあなたは、自ら処刑人となる道を選び、夢という温床から魂をその手で切り離した。\n偽りの幕を突き破った先で振り返れば、あの笑顔たちは青白い線の中で凍りつき、あなたが真の意味で帰ってくるのを待っている。"
  },
  Item_100577_Name = {
    Text = "束の間の夢"
  },
  Item_100577_StoryDesc = {
    Text = "美しく、満ち足りた、柔らかなものすべては人を堕落させる。だがあなたは、自ら処刑人となる道を選び、夢という温床から魂をその手で切り離した。\n偽りの幕を突き破った先で振り返れば、あの笑顔たちは青白い線の中で凍りつき、あなたが真の意味で帰ってくるのを待っている。"
  },
