  },
  Item_10063_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nアルバを再度獲得した際に変換され、アルバの霊知啓発を起動するために使用。"
  },
  Item_10063_Name = {
    Text = "欠片・アルバ"
  },
  Item_10063_StoryDesc = {
    Text = "アルバを再度獲得した際に変換され、アルバの霊知啓発を起動するために使用。"
  },
  Item_10064_Desc = {
    Text = "ミサゴ大学の創始者が研究した、覚醒体の能力を高める薬剤。\nシルバーコアと秘薬で調合され、奇妙な色合いを持つ。\n覚醒体に500経験値を提供。"
  },
  Item_10064_Name = {
    Text = "霊知の薬剤Ⅰ"
  },
  Item_10065_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「小さな願い」を選択可能。\n\n少女は6歳の誕生日に願いをかけた——「ポポ」という名前のぬいぐるみのクマと、少しの愛——沢山はいらない。\nほんのちょっとでいい。\n\n少女は決して空想が得意ではなく、欲深いわけでもなかった。"
  },
  Item_10065_Name = {
    Text = "小さな願い"
  },
  Item_10065_StoryDesc = {
    Text = "少女は6歳の誕生日に願いをかけた——「ポポ」という名前のぬいぐるみのクマと、少しの愛——沢山はいらない。\nほんのちょっとでいい。\n\n少女は決して空想が得意ではなく、欲深いわけでもなかった。"
  },
  Item_10066_Desc = {
    Text = "霊知が無限に拡大されると、真実の一端に触れる。\nシルバーコアで駆動する特殊装置で、設定値に従って覚醒体の能力を永久に向上させる。\n守秘者がレベル40に達すると、任意の覚醒体を選び、以下の強化を受けることができる：\n・レベル50に増加\n・全スキルがレベル3に増加\n・突破等階が4階に増加"
  },
  Item_10066_Name = {
    Text = "霊知増幅器Ⅴ"
  },
  Item_10067_Desc = {
    Text = "伝説の最初のゴーレム創造主、ゴーレムを自らの手で殺す。\nランダムで深紅の抱擁の密契がドロップする。"
  },
  Item_10067_Name = {
    Text = "深紅の抱擁"
  },
  Item_10068_Desc = {
    Text = "霊知が無限に拡大されると、真実の一端に触れる。\nシルバーコアで駆動する特殊装置で、設定値に従って覚醒体の能力を永久に向上させる。\n守秘者がレベル50に達すると、任意の覚醒体を選び、以下の強化を受けることができる：\n・レベル60に増加\n・全スキルがレベル4に増加\n・突破等階が5階に増加"
  },
  Item_10068_Name = {
    Text = "霊知増幅器Ⅵ"
  },
  Item_10069_Desc = {
    Text = "生存と持久能力を全面的かつ総合的に向上させ、追加の深紅の炉蓄積上限とダメージ成長がより多くの可能性をもたらす回復型の運命の札。"
  },
  Item_10069_Name = {
    Text = "神言の石板"
  },
  Item_10069_StoryDesc = {
    Text = "創生の父なる神は星空より降り立った。\n\nその時、大地は赤く燃える熱土であり、烈火がが燃えていた。父なる神は炎の上に足を踏みしめた。\n\n父なる神は言った「火はやがて鎮まる」火はそうあった。\n\n流れる土は地となり、父なる神はその地に神言を刻んだ——\n『地は生ける物の基となる』\n\n谷は谷となり、平原は平原となった。\n\n神言は揺ぎ無く、これが第一の石板である。\n\n父なる神は厚い雲を見て言った「雲はやがて雨を降らせる」\n雲はそうあった。\n\n雨は流れとなり、父なる神はその上に神言を刻んだ——\n『水は命の温床となる』\n\n水は湖となり、海となった。\n海は地を覆った。\n\n神言は揺ぎ無く、これが第二の石板である。\n\n父なる神は水の暗さを見て言った「光が降りるべきだ」\n光はそうあった。\n\n光はが水に降り注ぎ、父なる神は光の上に神言を刻んだ——\n『光は命を育む』\n\n光は暖かさをもたらした。\n\n神言は揺ぎ無く、これが第三の石板である。\n\n父なる神は揃った地、水、光を見て言った「生命は訪れる」\n\n父なる神は自身の血を流し、その上に神言を刻んだ——\n『血は新たな命を生む』\n\n父なる神の血は広がり、生命あるものとなり、海で繁殖した。\n\n神言は揺ぎ無く、これが第四の石板である。\n\n父なる神は生命の誕生を見て言った「生き物は永遠に変化する」\n生き物はそうあった。\n\n微細な存在が引いた海の地を這い上がった。\n父なる神は変化するものに神言を刻んだ——\n『変化は止まることがない』\n\n陸に上がったものは根を張り、四肢を持ち、様々な姿へと変化した。\n\n神言は揺ぎ無く、これが第五の石板である。\n\n父なる神は生があり、変化もあるのを見て言った「死は訪れる」\n死は訪れた。\n\n老いた者は死に、病弱な者は死んだ。父なる神は死の上に神言を刻んだ——\n『死者は始まりへと還る』\n\n死者の体はゆっくりと消え、父なる神の懐に戻った。\n\n神言は揺ぎ無く、これが第六の石板である。\n\n父なる神は生、死、変化がすべてあるのを見て言った「これらは我が遺物であり、我は祝福を残す」\n\n父なる神は自身の骨を取り出し、その上に神言を刻んだ——\n『万物の終わりに、我が骨を使い、我が権を代行せよ。\n血肉の代価により生を与える』\n\n神言は揺ぎ無く、これが第七の石板である。\n\n父なる神はすべてが整ったのを見て、休むことにした。\n水は父なる神を包み、光は父なる神を暖かくし、地は父なる神を覆った。\n\nそして父なる神は永き眠りにつき、万物は父なる神の残された神言に従い生きる。\n\nそれが今の世界である。"
  },
  Item_10070_Desc = {
    Text = "霊知が無限に拡大されると、真実の一端に触れる。\nシルバーコアで駆動する特殊な装置で、設定値に従って覚醒体の能力を永久に向上。\n守秘者がレベル20に達すると、任意の覚醒体を選び、以下の増幅を獲得。：\n・レベル30に増加\n・突破等級2に増加"
  },
  Item_10070_Name = {
    Text = "霊知増幅器Ⅲ"
  },
  Item_10071_Desc = {
    Text = "メイン能力は、界域知識、狂気増加、黒章ドロップ、キーチャージの中からランダムに1つを獲得。"
