  Item_10071_Name = {
    Text = "少女の蛹Ⅳ"
  },
  Item_10071_StoryDesc = {
    Text = "純潔な殻を捧げます。"
  },
  Item_10072_Desc = {
    Text = "「心配しないで、私たちはいつもあなたの最強の後ろ盾です」\nミサゴ大学の貴重な特殊装置。\n強力な精神力を内包し、瞬時に覚醒体の潜在能力を引き出し、状態を回復する。\n毎日15:00に、残り回数が5未満の場合、自動で1回分が追加。"
  },
  Item_10072_Name = {
    Text = "復活の魂魄"
  },
  Item_10073_Desc = {
    Text = "属性がシルバーキー充電レベルに基づく命輪。"
  },
  Item_10073_Name = {
    Text = "精神集中"
  },
  Item_10073_StoryDesc = {
    Text = "調査員たちの間には、一つの不文律がある：\n\n鍵塚の儀式の夜、経験豊富な調査員が新任調査員を導くこと。\n\n彼らは寮の裏庭に集まり、蝋燭の灯芯の下、銀の鍵を手に輪を作る。\nベテラン調査員は新人に、それぞれの鍵が持つ唯一無二の物語を語るのだ。\n\nそこでは必ず、I-0001とK-0001、「初代」の鍵たちが話題の中心となる。\n初代守秘者が手ずから作り上げたK-0001シルバーキーは、今や主人と共に地下に眠っている。昼夜の区別もない果てしない時の中で、亡き者への囁きを静かに聞き続けているのだ。\n\n「彼はここにいないと知っているでしょう、アリステア」ドールが言う。\n「それは確かに君の師のシルバーコアで作られたかもしれないけど、彼の魂ではないわ」\n「ただの精神の集中のための手段さ、ドール」アリステアは笑った。\n「大丈夫、僕は安定している。新たな守秘者が成長するまで倒れるわけにはいかないよ。そうだろ？」"
  },
  Item_10074_Desc = {
    Text = "適量のシルバーコアが入ったギフト。努力を尽くした守秘者への報酬。"
  },
  Item_10074_Name = {
    Text = "上級シルバーコアギフト"
  },
  Item_10075_Desc = {
    Text = "属性がダメージ強化の運命の札。"
  },
  Item_10075_Name = {
    Text = "切断と危害"
  },
  Item_10075_StoryDesc = {
    Text = "医者の使命は、患者を治すこと。\n\nしかし、ある治療法は、鋭い刃で皮膚を切り裂き、組織を貫き、胸を開き、病巣を取り除き、人体の自然治癒力に再生を願うものだ。\n\nこれは彼女の罪ではないはずだった。\nだが手術のたびに、彼女はその少女に物語を語らずにはいられなかった。\n彼女は良い語り手ではなく、言葉は断片的だったが、虚構の物語は少女を真剣に引き込んだ。\n彼女が切り裂いた場所は、言葉の力をゆっくりと吸収し、自然に癒えていった……"
  },
  Item_10076_Desc = {
    Text = "ワックス像館に逸散した感情粒子。触れると「来ないで」という叫び声が聞こえるような気がする。\nシークレットキーパーが調査イベント「以蜡像之名」における共鳴を高めるために使用する。\n「以蜡像之名」ステージの初回クリア報酬で入手可能。"
  },
  Item_10076_Name = {
    Text = "痙攣する心"
  },
  Item_10077_Desc = {
    Text = "属性がブラックマークドロップの運命の札。"
  },
  Item_10077_Name = {
    Text = "旅の荷物"
  },
  Item_10077_StoryDesc = {
    Text = "誰も生まれつき船長ではない、少なくともエルトンはそうではなかった。\n\n船長になる前、彼は海軍と商船の間を行き来し、何度も海賊になりかけたが、最終的には探検船に落ち着いた。\n\n探検船は極地大陸を航行し、上陸するたびに新たな冒険が待っていた。\n彼の役目は体の弱い科学者の荷物を背負うことだったが、それを誇りに思っていた——荷物には世界を変えるかもしれないものが詰まっていた。\nそして彼らは、歴史を変えるかもしれない人々だった。\n\n氷の嵐が彼らを氷の洞窟に閉じ込める前、神秘的な教徒たちが夜襲をかける前、エルトンはそう信じていた。"
  },
  Item_10078_Desc = {
    Text = "属性がクリティカル率の運命の札。"
  },
  Item_10078_Name = {
    Text = "死の分析"
  },
  Item_10078_StoryDesc = {
    Text = "彼はいつも無口で勤勉な学生だった。\n\n朝8時、他の研究員がたちがパンをくわえて、慌ただしく研究棟へ駆け込んでくるころには、彼は既に実験報告を書き終えていた。\n夜12時、実験棟の灯りがすべて消えると、重い腰を上げて静かに帰る。\n\nそういえば、彼は毎日近くの野良猫に餌をやっていた。\nだが、ある日、野良猫は姿を消した。誰もどこに行ったのか知らない。\n\n指導教官のクロウリーは彼の実験記録と報告を分析した。\n簡潔で細かく、特に目立つ点はないが、欠点もなかった。\n\nこの学生は彼に疑念を抱かせた。\nもっとも「疑念」とは決して悪いものではない。\nそれはしばしば「好奇心への扉」となる。\n\nもちろん、その時のクロウリーは思いもしなかった。\nそれが「死への扉」にもなりうることを——"
  },
  Item_10079_Desc = {
    Text = "クリティカルダメージの能力を持つ命輪。"
  },
  Item_10079_Name = {Text = "親友へ"},
  Item_10079_StoryDesc = {
    Text = "「いつの間にか、君が去ってからこんなに経ってしまった。\n\n私はまだ夢の中であの日に戻ることがある、左腕の銃創の痛み、失血による幻覚、暴動する鼠の群れの追撃……\nその混乱の中で、ミサゴの制服を着た君が現れ、私を不吉な古城から逃がしてくれた。\n\nその夢の最後で、君は病床の前に立ち、調査員にとって死は常に影のように付きまとうと警告した。\nそれが現実か幻想か、私はもう判断できない。\nそんな時、私は左腕に触れる。冷たく精巧な金属の表面に触れられれば、それが現実だ。\n\nしかし、より多くの夢の中で、私はただ虚空を掴むだけだ」"
  },
  Item_10080_Desc = {
    Text = "属性が死亡耐性の運命の札。"
  },
  Item_10080_Name = {
    Text = "記憶障害"
  },
  Item_10080_StoryDesc = {
    Text = "クロウリーは在職中ずっと「一番人気の教師」の称号を保ち続けた。\n\nややぎこちないコンスタン西部訛りと、誠実な笑顔は、多くの学生たちの好感をもたらし、ハーバートもその一人だった。\n\nA.F.2@1年、クロウリーは反対意見を押し切り、目立たない存在だったハーバートを自分の弟子として迎え入れた。\n\nハーバートは彼と共に山を越え、川を渡り、砂漠を横断し、いくつもの融蝕裂け目の傍らに足跡を残していった。\n\n彼は初めて融蝕の裂け目を見た時の衝撃を今でも覚えている。\nクロウリーが黒煙のように立ち上る霧の前に立っていた。\n彼の姿はとても小さく見えた。\n\n「しっ——聞こえるか？」\nハーバートは目を閉じ、静かな海の波音のような響きを聞いた。\n世界が遠く離れていくかのようだった。\n\nクロウリーは非常に興奮して言った。\n「これは詩だ。宇宙で最も神秘的で、最も深い詩だ」\n\nそれから何年も経ち、ハーバートの中でクロウリーとの記憶はすでに曖昧になっていた。\nどのように共に働き、争い、そして——自分がどうやって彼を「誤って」殺してしまったのかも。\n\nしかし、彼はあの黒い霧の下の笑顔を永遠に忘れない。\nその瞬間、彼は詩を見た。"
  },
  Item_10081_Desc = {
    Text = "蠕動し、ねじれ、暗闇を這い回る……シュー……シュー……\n寄生された虫蛹。\n血肉界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_10081_Name = {
    Text = "原生虫の蛹"
  },
  Item_10082_Desc = {
    Text = "任意の紫の運命の札を強化するために使用。（開発用）"
  },
  Item_10082_Name = {
    Text = "紫の運命の札強化素材（開発用）"
  },
  Item_10083_Desc = {
    Text = "あなたは不滅。\n超越存在からドロップする記憶の結晶で、ミサゴ商店でアイテムと交換可能。"
  },
  Item_10083_Name = {
    Text = "PVPコイン（廃止済み）"
  },
  Item_10084_Desc = {
    Text = "そう、すべては精錬可能だ。あなたの本能、理性、そして心さえも……結局、あなたは彼らと何も変わらないことに気づくでしょう。\n深海界域の覚醒体を昇格させるための素材。"
