  },
  Item_10092_Desc = {
    Text = "神秘的な紫色の輝きを放つ。カンブリア渓谷に隕石が落ちた際の残骸と言われている。\n超次元界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_10092_Name = {
    Text = "隕石の破片"
  },
  Item_10093_Desc = {
    Text = "専門家の助けを借りて開けてください。\n古代の密約が封印された神秘の木箱、闇の境界で入手可能。\n歪みの双子白の密約セット部品を入手可能"
  },
  Item_10093_Name = {
