  },
  Item_10095_Desc = {
    Text = "人類存続のため。\n額縁に保存された記憶。\n血肉界域の覚醒体を昇格させるための素材。"
  },
  Item_10095_Name = {
    Text = "記憶のコピー"
  },
  Item_10096_Desc = {
    Text = "未知の認知を与える。\n映画詩クラブの特殊フィルムから生まれ、人の知識を転写できる。\n超次元界域の覚醒体の昇格素材として使用。"
  },
  Item_10096_Name = {
    Text = "認知テンプレート"
  },
  Item_10097_Desc = {
    Text = "花言葉：近寄らないで。\n低茎ウミユリの化石。深海界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_10097_Name = {
    Text = "低茎ウミユリ"
  },
  Item_10098_Desc = {
    Text = "ジェンキンは彼女の鼠の仲間ブラウンのように機敏で素早く、神出鬼没だ。\n・超次元跳躍を利用して大量のダメージを与える\n・臨機応変なダメージ能力を持つ。"
  },
  Item_10098_Name = {
    Text = "ジェンキン"
  },
  Item_10099_Desc = {
    Text = "メイン能力は、クリティカル率、クリティカルダメージ、キーチャージ、狂気増加の中からランダムに1つを獲得。"
  },
  Item_10099_Name = {
    Text = "生命力搾取Ⅰ"
  },
  Item_10099_StoryDesc = {
    Text = "へその緒は無限の未来に繋がっている。"
  },
  Item_10100_Desc = {
    Text = "狂気解放後に追加で狂気と臨時クリティカルダメージを獲得でき、絶好の運は味方と共に自身の幸運を分かち合える。"
  },
  Item_10100_Name = {
    Text = "幸運の時"
  },
  Item_10100_StoryDesc = {
    Text = "テムズ川沿いを下り、右に曲がってベックマン通りに入り、約100フィート進むと、その目立たない角に「ライカー探偵事務所」が見えてくる。\n\nロンディニウムで最も解決率の高い探偵事務所でありながら、ここには専門書でいっぱいの大きな本棚も、切り抜きが貼られた壁も、優雅なアフタヌーンティーもない。\n大抵の場合、あなたが出会うのは「外出中」の看板と、そばで寝そべる疲れた老犬だけだろう。\n\n運が良ければ、晴れた日曜の朝に、二日酔いで帰ってくる名探偵に会えるかもしれない。\nその時、彼は賭け事を終え、ポケットにはほとんどお金が残っていないので、あなたは無理な依頼を思い切り頼むことができる。猫探し、カルトに入った母親の救出、夫の浮気の証拠集め……\nあなたが持っている限り、彼は受けてくれる。\n\n「死の間際の瞬間を楽しむから、俺はギャンブラーになる運命なんだ」\n「じゃあ、探偵になるのは？失礼ながら、猫探しと死の間際の関連性が見えないんだが」\n「いや、君は分かってない……真実を探す過程自体がすでに魅力的なんだ、大きさに関係なく。それはまるで……」\n「死とのデートに向かうようなものさ」"
  },
  Item_10101_Desc = {
    Text = "狂気と毒の付与を強化すると同時に、敵の生命を犠牲にして一時的なクリティカルダメージに変換し、敬虔な信仰がより多くの触腕を駆り立てる。"
  },
  Item_10101_Name = {
    Text = "信仰の力"
  },
  Item_10101_StoryDesc = {
    Text = "ルルイエの主よ、どうか私の祈りをお聞きください。\n\nあなた様の予言を授け、啓示をお与えください――あなた様の王国を復元できますよう。\n\nさすれば、この信仰なき地、この海に囲まれた氷原にて、石柱を立て、あなた様の寝殿を築きましょう。\n\n深淵を滑る主よ、祭壇に捧げたるはあなた様への供物。\n\n純なる肉体は満月の子羊より、強き心は成牛より、鋭き眼は空を翔る雄鷹より、堅き骨は巡洋の鯨より。\n\nラピスラズリはあなた様の王座、黄金はあなた様の王冠。\n\nどうか私に夢を授け、神の言葉をお告げください――あなた様の御身を復元できますよう。\n\nさすればこの氷下の深淵にて、この海底の領域にて正しき刻に生まれる母体を捧げましょう。\n\n万象を知りたるリモリアの王よ\n私の祈りにお応えください。\n\nあなた様が海に沈み、眠りにつかれ、幾千年が過ぎました。\n\n私はあなた様の御名のもとに、あなた様の御業を広め、その尊き御名を讃え続けてきました。\n\n揺るぎなきは、私の信仰。\n誠実なるは、私の心。\n\nあなた様こそ、唯一の神王。\n不朽なる者の化身。\n\nこの、待ち望む時を終わらせ、再びこの世に降臨し、どうか、あなた様の叡智の言葉を、再び私にお聞かせください。"
  },
  Item_10102_Desc = {
    Text = "メイン能力は、狂気増加、死亡抵抗、キーチャージ、ダメージ強化の中からランダムに1つを獲得。"
  },
  Item_10102_Name = {
    Text = "深紅の鼓動Ⅴ"
  },
  Item_10102_StoryDesc = {
    Text = "伝説の最初のゴーレム創造主、血液でゴーレムを養う。"
  },
  Item_10103_Desc = {
