  Item_10106_Desc = {
    Text = "ハレト学長代理特別支給の豊富な補給。\n貴重な材料が封入された木箱で、課題任務を遂行する守秘者に援助を提供。\n以下の素材から1つ選択：\n純白の秘篇×12\n精神の精錬×12\n意識のコピー×12\n霊知テンプレート×12"
