  },
  Item_116596_Name = {
    Text = "拝謁の礼"
  },
  Item_116597_Desc = {
    Text = "聖子に謁見するために必要な証明。光明を求める決意を聖子にお見せしよう。\n\n最低{s1}個ドロップ"
  },
  Item_116597_Name = {
    Text = "拝謁の礼"
  },
  Item_116715_Desc = {
    Text = "藤の輪と鳥の羽で作られた簡易的な夢捕り網は、あまり信頼できない霊性を持ち、使用後は大抵の場合失敗するが、時折夢の欠片を拾い上げることができる。それはほとんどが速いフラッシュバックの映像に過ぎない。"
  },
  Item_116715_Name = {
    Text = "ダークドリームキャッチャー"
  },
  Item_116716_Desc = {
    Text = "奇妙な古代の鳥の骨で編まれた夢捕りの網は、夢の中の出来事をあなたの頭の中に鮮明に映し出し、まるであなたが本当にその物語を体験し、夢の中の人々に出会ったかのように感じさせる。美しい夢は素晴らしいが、夢中になりすぎないように注意して。"
  },
  Item_116716_Name = {
    Text = "蜃景キャッチャーネット"
  },
  Item_116717_Desc = {
    Text = "鹿皮の紐と水晶で飾られた夢を捕らえる網は、目玉のような宝石がより良い霊性を与え、使用することでぼんやりとした完全な夢を垣間見ることができます。現実から逃避する人よ、美しい夢を掬い上げるために努力してください。"
  },
  Item_116717_Name = {
    Text = "精霊の夢捕りネット"
  },
  Item_116762_Desc = {
    Text = "幻衣「幻夢の休日」を取得した後に解除。\n「守秘者、私と一緒に海辺に行って風を感じませんか？」"
  },
  Item_116762_Name = {
    Text = "環行・ラモンナ・ファントムホリデー"
  },
  Item_116763_Desc = {
    Text = "環行・ラモンナにとって、命とは慌ただしく繰り返される試練だった。\n訓練し、謎を解き、世界が未来へと進む確率を演算し、そして救いたいと願い、守りたいと切望した美しきものたちが砕け散るのを、目の当たりにする。\n何度も、何度も。\nやがて、その人生は孤独で終わりのない待機へと変わった。\n希望を失い、破滅した世界で、彼女は無限に広がる漆黒の夜空を見上げ、遥か彼方の次元からの呼び声を待ち続ける。\n来る日も、来る日も。\nそれが彼女の宿命だった。彼女はその宿命に慣れ、受け入れていた。——「その時」が来るまでは。\n「ラモンナ、せっかくのバカンスなんだから、そんな顔しないで、ほら、笑って～」\n「ラモンナ、見た？リリーたちが砂のお城を作ったんだって。私たちも一緒にどう？」\n「ラモンナ、夏といったらアイスクリームでしょ！今日はわたくしのおごりよ。はい、あなたの分」\n「ラモンナ……」\n「ラモンナ」\n「ラモンナ！」\n幾度となく自分を呼ぶ懐かしい声の中、夏の日差しは容赦なく万物を焼き焦がしていた。\n彼女は陽光を受けてきらめく浜辺の「城」を見つめ、溶けたアイスクリームが手に残す、べたべたした感触を感じていた。\n海水は冷たく、砂は熱い。\nマーフィーが用意したチュロスは甘く、ライカーが奢ってくれたトニックウォーターは苦い。\nそのすべてがあまりに新鮮で、もっと感じたい、もっと味わいたいという衝動を、彼女は抑えることができなかった。\nそして何よりも、あの人がまだここにいる。すぐ隣に、こんなにも生き生きと、こんなにも確かな存在として。\nまるで、かつての破滅も、崩壊も、苦痛も、絶望も、すべてが幻だったかのように。\n「……」\n灼熱の陽光が降り注ぐ海辺で、環行・ラモンナは沈黙し、そしてゆっくりと、しかし確かに微笑みを浮かべた。\n「そう、私たちは休暇中なんだ。だから守秘者、少し一緒に歩かないか？海辺で風を感じながら」\n同時に、果てしない漆黒の夜空の下にいる彼女もまた、涙に濡れた眼帯の奥、目覚めを拒んだ明晰夢の中で、同じような笑みを浮かべていた。\n今回、ついに彼女は手に入れたのだ。幾度となく砕け散った、あの輝かしい日々を。\nたとえそれが、ただの夢に過ぎないとしても。"
  },
  Item_116763_Name = {
    Text = "夢のような休日"
  },
  Item_116764_Desc = {
    Text = "アンロック後、「刻まれた出発」の全タスクを完了すると、以下の追加報酬を得られます"
  },
  Item_116764_Name = {
    Text = "刻印の出発"
  },
  Item_116792_Desc = {
    Text = "「来て、楽しく遊ぼう～」"
  },
  Item_116792_EmojiName = {Text = "誘惑"},
  Item_116792_Name = {
    Text = "タイイス·誘惑"
  },
  Item_116872_Name = {
    Text = "エリカの木の人"
  },
  Item_116873_Name = {
    Text = "リリのボードツリー"
  },
  Item_116874_Name = {
    Text = "オルラの木人"
  },
  Item_116875_Name = {
    Text = "私の家の樹人"
  },
  Item_116878_Desc = {
    Text = "界域知識の能力を持つ命輪。"
  },
  Item_116878_Name = {
    Text = "再会の誓い"
  },
  Item_116878_StoryDesc = {
    Text = "あなたとラモンナは、再び会う約束など交わしたことはなかった。\n扉が目の前でゆっくりと閉ざされた刹那、二人の胸に刻まれた別れの期限は、すでに変えようのない「永遠」となっていた。\n\nだからこそ、時の狭間、そのほんの一瞬の邂逅の中で、彼女がそっと小指を絡めてきた時……\nそれは予期せぬ、けれどあまりに幸福な巡り合わせだった。\n「あなたは、少しも変わらないわね」彼女はそう言った。\n\nその一言のために。指先に残る、かすかな温もりのために……たとえ二つの世界に隔てられていようとも、あなたはすべてを賭して、銀河を越えてでも彼女に会いに行くのだろう。\n来年の今日、指切りの約束に誓って。"
  },
