    Text = "誰かの夢の中に散逸した感情粒子。触れると、誰かが来し方を振り返る時の迷いのつぶやきが聞こえるようだ。\n守秘者の調査事件「楽園」における共鳴のレベルアップに使用。"
  },
  Item_117263_Name = {
