  },
  Item_119432_StoryDesc = {
    Text = "ローカライズ有志のアイコンフレーム"
  },
  Item_119689_Desc = {
    Text = "幻装「孽宴狂欲」を獲得後に解放。\n「さあ小さな苗木よ、欲望を解き放ち、終わりなき狂宴に加わるがいい！」"
  },
  Item_119689_Name = {
    Text = "背徳の狂宴"
  },
  Item_119690_Desc = {
    Text = "ポタッ……ポタッ……\nアランで最も優秀な狩人である私は、あらゆる過酷な環境に慣れている。砂漠、密林、沼地——たとえ胃酸で満ちた巨大な獣の腹の中であろうと、微塵も動揺することはない。\nだが、なぜだろう。身にまとわりつく粘ついた感触に、私は思わず身を震わせた。それはまるで、人間が決して触れてはならない「異質な何か」のように感じられた。\n「いい子……いい子ね……」\n私は赤ん坊になったのか？確信は持てないが、自分の身に何らかの異変が起きていることだけは理解できた。\n温かな手が優しく私を抱き上げ、背後にいる存在の胸元へと引き寄せる。満たされた感覚に包まれ、それは羊水のように温かく、安心感を与えてくれた。\nようやく目を開けた私は、目の前の恐ろしい光景に思わず身をよじり、その豊満な胸に体をうずめようとした。\n触手が絡み合う角、頭部を縦に割る巨大な口、絶えず滴り落ちる緑色の粘液……これほど恐ろしい怪物は見たことがない。視線を逸らそうとしたが、まるで魅入られたかのように、目の前の異形から目を離すことができなかった。相手もまた、じっと私を見つめている。その眼差しから、私の肉体に対する渇望を読み取るのは容易だった。\nだが、なぜ……その狂気に満ちた眼差しの中に、これほどまでに純粋な期待が込められているのだろうか？\n「いい子ね……怖がらないで……」\n母のように優しい言葉が耳元で響く。温かい掌が全身を撫でていく感覚に、私の心は次第に穏やかになっていった。まるで背後にいる人物が本当に私の母であり、今ここが最も安全な場所であるかのように。\n理性ではあり得ないと分かっていても、私は甘えるように、毛並みを整えてくれる彼女に体を摺り寄せた……待て、毛並みだと？\nふと違和感を覚えた私は自分の体に触れようとした。だが、目の前にあったのは、かつての傷だらけの手ではなく、漆黒の羊の蹄だった。\nああ、そうか……これが私の本来の姿。母が私に与えた——\nその瞬間、血脈の奥底に眠っていたすべてが、脳裏に浮かび上がった。私は自分の正体、使命、そして……抑えきれない欲望を理解した。\n「グルルァァァ————！！」\n私はたまらず母の懐から飛び降り、耳をつんざくような咆哮を上げると、兄弟姉妹の中へと駆け込んだ。\n私は自分の責務を果たさなければならない。母の意志を遂行するのだ。\n「オォォォ————！！！！」\n私の合流を合図に、すべての兄弟姉妹が一斉に狂喜の雄叫びを上げた。その咆哮は天地を震わせ、宴の始まりを告げる。\n我々は舐め合い、絡み合い、太い触手で相手の隅々まで深く入り込み、互いに噛みつき合い、血肉を交わし合った。\nさらに外へと走り出し、目の前のあらゆるものを無差別に貪り食らう。我らは狂欲の母が産み落とした不吉なる子、この宴における唯一の主役だ。\n欲望を抑え込む必要はない。我々はすでに俗世の殻を脱ぎ捨てた。欲しいままに貪り、欲しいままに繁殖し、母から受け継いだ至高の欲望を欲しいままに解き放つのだ。\nこれは、母に捧げる宴。我々はこの世界を穢れた血肉へと変え、至高なる母に捧げるのだ！\n\nタイスは宴の中央に立ち、世界が喰い尽くされる哀鳴に耳を傾けていた。\n「そう、その調子よ」\n狂乱に踏み込んだ子らを見つめ、慈愛に満ちた母は、その本質である狂気を露わにした。\n「お行きなさい。もうあんな脆い殻で偽る必要はないわ。世界にあなたたちの真の姿を見せつけるのよ！」\n\n薄絹が舞に合わせて翻り、その隙間から蜜色の肌が覗く。\n「あなたたちは原初の使徒。誰の承認もいらない。世俗に認められぬ欲望を、もう抑え込む必要はないわ」\nそれは終わることなき舞。終わることなき宴だ。\n「この世界をすべて、あなたたちの兄弟姉妹で満たすのよ！」"
  },
  Item_119690_Name = {
    Text = "背徳の狂宴"
  },
