    Text = "コレクション切手：パンディア"
  },
  Item_120965_StoryDesc = {
    Text = "第28期学期課題"
  },
  Item_121027_Desc = {
    Text = "「金羊の狂舞」の全任務完了で、獲得できる追加報酬の総数"
  },
  Item_121027_Name = {
    Text = "金羊の狂舞"
  },
  Item_121436_Name = {Text = "聖嬰"},
  Item_121771_Desc = {
    Text = "幻衣「毒花の盛衰」解放後に解放。\n「仕えよ、従え、そして愛せよ」"
  },
  Item_121771_Name = {
    Text = "ワンダ・毒花の盛衰"
  },
  Item_121772_Desc = {
    Text = "カンブリアでは誰もがあなたの名を知り、そして誰もがあなたに警告を発していた。\n\nそれは世を欺く悪名、傲慢なる魔、欲望の化身。\n残虐と放蕩で故郷を支配した妖婦。\n\n騎士よ、カンブリアの金雀花よ。\n彼女は鋭い剣であろうか？緩やかに蝕む毒であろうか？\n——彼女の葬送こそが、あなたの叙事詩の始まりとなるのだ。\n\n「ワンダ」\nあなたの妻。\n\n「ワンダ夫人」\n\n黄金の光が、夜のように艶めく女領主の肌を流れる。\n美しく、豊かで、放蕩的で、尊大なる者。\n\nやがて領土が滅びるまで、数多の俗悪な歌が語られた。\n高潔な騎士の犠牲と反抗の物語。\n\nだが誰も知らない。\n彼女自身さえ知らない。\n\nさあ、新しい物語を語ろう。\nあなたが「カンブリアの金雀花」と呼ばれるより前の物語を。\n\n信仰は一人の騎士の魂を縛り、彼は光に満ちているかのように見えたが、その光のために生まれたわけではなかった。\n\n湖の都から現れた妖女が、雷鳴のごとき力と、蜜のように甘く長い拷問を以て、すべての者にその真実を示すまでは。\n\n騎士は見た。\n彼女の足元に棘が生えるのを。\n\nそして想像した……\n自らの背に棘が生え、やがて脳裏に棘が育つことを。\n\n彼は手段を選ばず、頂点へと這い上がり、暴虐の美神との結婚を宣言した。\nその反逆のためには他者の力を必要とした。\n\nなぜなら……\nその方が ワンダの「お気に入りの綺麗な玩具」になれると思ったからだ。\n\n拙く滑稽な茶番。\n華やかに飾られた贈り物。\nそして、秘められて語ることのできない願いの成就。\n\nあなたはこの「新しい物語」を気に入るだろう。\n彼女の手はすでに掲げられ、猫眼の宝石を待っている。\n\nそこにはあなたの心がある。\nあなたを虐めてくれる人がいる。\nそして、あなたの主人がいる。\n\nあなたの魂は、極限の恐怖と苦悶と甘美に貫かれ、囚われたままなのだ。"
  },
  Item_121772_Name = {
    Text = "毒花の盛衰"
  },
  Item_122106_Desc = {
    Text = "探索中に商品を1回無料で購入できる機能型の命輪。"
  },
  Item_122106_Name = {
    Text = "箱の中の童心"
  },
  Item_122106_StoryDesc = {
    Text = "「終日の苦行を続ける者よ、この贈り物があなたの魂を温めますように。父なる神の慈愛が胸の苦しみを癒やし、甘美な夢をもたらしてくれますように。」\n銀霜夜も終わるころ、蝋燭の火は低く垂れていた。久しぶりに重い石板を脇へ置き、サルバドルは厳かな法衣を脱いで、あたたかな赤い毛織の装いに着替える。明日の冬渡節のため、彼はわざわざダフォダイルの小さな店へ出向き、ミサゴの学生たちに向けたサプライズプレゼントを用意してきたのだ。\n「これが最後のプレゼントですね…………」\nサルバドルは学園の片隅にある古い椅子に腰を下ろし、疲れのあまり無意識のうちに夢の底へ落ちていった。\nそれは温かく甘い夢だった。足元のプレゼントの箱がいつの間にかそっと開き――四体のジンジャーブレッドマンがぱっと飛び出す。アイシングで描かれた瞳はきらきらと輝き、シナモンとクローブの香りが冷たい空気の中で輪を描くように舞い踊る。\nその香りが封じられていた記憶を呼び覚まし、彼は幼い頃の教会の回廊へと戻った気がした。舌先で溶けたタフィーの甘さがさらに過去を思い出させた。苦痛と疫病に侵された祝福の数々が、この濃厚で甘い円舞曲とともに、静かに息を吹き返していく。\n…………\nその頃、四つのこそこそした影が、眠りに落ちたサルバドルへそっと近づいていた。\n「ご主人…………ご主人は、私たちを悪い子だって思うかな…………」\n「ふふーん――オレッタは気になりすぎるの！早く開けようよ〜。ひとつ、ふたつ…………わあ、ジンジャーブレッドマンがいっぱい！」\n「だ、だめ…………名前を言っちゃったら、もしかして…………みんなに嫌われちゃう…………！」\n「へへっ、盗もうと思ってるわけじゃないよ！やったのは全部ブラウンってことで！」\nサルバドルは小さなジンジャーブレッドマンたちがぺちゃくちゃと話し合うのを耳にし、ひとつが膝の上に飛び乗るのを感じた。シナモンの香りがする息遣いが、皺だらけの手の甲をくすぐる。\nいや、夢の中のジンジャーブレッドマンではない。現実の、いたずらっ子たちだ。プレゼントの箱をこっそり開けたときの、子どもたちの幸せそうな笑顔が目に浮かぶ。その一瞬の美しさと幸福、そして安らぎのためなら、彼はあらゆる苦しみを背負うことも厭わない。\n「おや…………私の髭が。髭と髪を結んで遊んでいるのですか？」\nサルバドルはまだ眠っているふりをして、子どもたちの楽しい「秘密の作戦」をそのまま続けさせた。"
  },
  Item_122107_Desc = {
    Text = "カウントダウンの後に強化を得る機能型の命輪。"
  },
  Item_122107_Name = {
    Text = "カウントダウン"
  },
  Item_122107_StoryDesc = {
    Text = "新しい年を迎えるにあたり、あなたは今までにない儀式を執り行うことに決めた。時の移ろいを、これ以上ないほど厳かに迎え入れるために。\nそのために、あなたは長い時間をかけて準備を重ねた。蝋燭に火を灯し、あたたかな光で冬の夜の学園を照らす。訓練場の中央には高台を設け、柄の入った深紅のベルベットの絨毯を敷き詰めた。さらに、金箔と銀の薄絹を合わせた無数のリボンを自らの手で作った。ただ、このカウントダウンの瞬間が別れの侘しさを超えて、年の暮れと新年が抱き合うときの、決して色褪せない印となるようにと。\nしかし…………まだ何かが足りない。\nあなたは古い倉庫の奥へと入り、幾重もの埃を払い落として、ついに一台のアンティーク時計を見つけた。外装はまだらに剥げ、針は時の侵食で折れて落ちてしまっている。明らかに、もう使えるものではなかった。\n途方に暮れかけたそのとき、タイスが現れた。彼女の背後には、いつの間にか真新しい時計が静かに立っていた。\nその時計には、見覚えがあった。彼女は相変わらず軽薄そうに笑うが、その瞳の奥にはどこか優しい確信が宿っている。\n「どう？この時計に私の踊りを添えれば、きっと最も盛大な儀式になるわ」\n「まさか…………タヴィの時計じゃないよね？」\n「あら、あなたも知ってるでしょう？あの子、池の水の中でひとりきりじゃ、あまりに退屈だわ」\n「こうして私たちの儀式に加えて、私の愛を感じさせてあげれば、少しは気分が晴れるかもしれないでしょ〜」\n真夜中がそっと訪れる。タイスが巨大な時計の前に立つ。まるで時間そのものに丁寧に包まれた贈り物のようだった。\nリボンは燃え残る花火のように彼女の身体に絡みつき、巡る灯りの下で金色の混じる赤と銀色の混じる青の波紋を揺らす。腰元のふっくらとした蝶結びは、新年が自ら結んだ最後の結び目――彼女こそが年の瀬最大の捧げものなのだ。歓びの絹に包まれ、時間に封を解かれるのを待っている。\n彼女はゆっくりと腕を上げ、指先で光と影をなぞりながら、背後に垂れ下がる時計へと指を向けた。文字盤の12の数字が光の輪となって繋がり、彼女の指先で踊る。\nミサゴの人々は、タイスの奔放な舞を仰ぎ見た。歓喜の空気に染められたように、彼女のリズムに合わせて皆の心も揺れ動いていく。\nそして鐘の音が落ちる瞬間、彼女の指先がそっと触れたのは永遠の始まりだった。縛られていた贈り物はその両腕を広げ、年の瀬に蓄えられたすべての祝祭を、空いっぱいに舞い散る祝福へと姿を変えて、人の世へ降り注がせた。"
  },
  Item_122263_Desc = {
    Text = "「迷霧」の外縁から漏れ出した物質。茉夏がそれらを集めて、迷霧の源に与える養分として使っているらしい。"
  },
