  Item_122409_Name = {
    Text = "迷霧の視"
  },
  Item_122410_Desc = {
    Text = "イベント「霧境の燔礼」で実績を達成して獲得。\n「私はモシャ、今度こそちゃんと覚えてね。」"
  },
  Item_122410_Name = {
    Text = "銀鍵の名のもとに：モシャ"
  },
  Item_122410_StoryDesc = {
    Text = "モシャプレイイベント"
  },
  Item_123321_Desc = {
    Text = "「銀霜紀行」の全任務完了で、獲得できる追加報酬の総数"
  },
  Item_123321_Name = {
    Text = "銀霜紀行"
  },
  Item_123478_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得できる。\n「純潔無垢なる蒼白の使者よ、父なる神があなたの行く道をお守りくださいますように。」"
  },
  Item_123478_Name = {
    Text = "色褪せない昨日：サルヴァドル"
  },
  Item_123478_StoryDesc = {
    Text = "第28期学期課題"
  },
  Item_123481_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得できる。\n「秘密の守り人、昨日あなたに贈ったマフラー…………気に入ってくれた？」"
  },
  Item_123481_Name = {
    Text = "色褪せない昨日：エジス"
  },
  Item_123481_StoryDesc = {
    Text = "第28期学期課題"
  },
  Item_123482_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得できる。\n「殺！殺！殺！！ハハハ！鱒の血の香りだ！」"
  },
  Item_123482_Name = {
    Text = "色褪せない昨日：ユウハシ"
  },
  Item_123482_StoryDesc = {
    Text = "第27期学期課題"
  },
  Item_123483_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得できる。\n「かつて私を縛ったこの鎖で、私に枷をはめようとする者すべてを引き裂いてやる！」"
  },
  Item_123483_Name = {
    Text = "色褪せない昨日：血鎖·シロ"
  },
  Item_123483_StoryDesc = {
    Text = "第26期課題記録"
  },
  Item_123484_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得できる。\n「薔薇が咲き誇る光景は相変わらず目を楽しませてくれるわね。さあ一杯共に飲みましょう、我が友よ。」"
  },
  Item_123484_Name = {
    Text = "色褪せない昨日：ソレル"
  },
  Item_123484_StoryDesc = {
    Text = "第27期学期課題"
  },
  Item_123485_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得できる。\n「今日は子供たちが何を持ち帰ってくるかしら？」"
  },
  Item_123485_Name = {
    Text = "色褪せない昨日：アグリッパ"
  },
  Item_123485_StoryDesc = {
    Text = "第27期学期課題"
  },
  Item_123486_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得できます。\n「ああ…………もっと痛みをお与えください〜」"
  },
  Item_123486_Name = {
    Text = "色褪せない昨日：レイア"
  },
  Item_123486_StoryDesc = {
    Text = "第29期学期課題"
  },
  Item_123487_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得できる。\n「夜も更けたわね、小さな苗木さん。さあ続けましょう…………昨日やり残したことを〜」"
  },
  Item_123487_Name = {
    Text = "色褪せない昨日：テイシス"
  },
  Item_123487_StoryDesc = {
    Text = "第28期学期課題"
  },
  Item_123552_Desc = {
    Text = "「なんて綺麗な粉雪……え？贈り物？欲しいなんて言ってないだろ！でも、受け取らなかったらお前もがっかりするだろうし……ありがとう。」"
  },
  Item_123552_Name = {
    Text = "冬の祝宴・カエクス"
  },
  Item_123553_Desc = {
    Text = "「銀霜夜おめでとう。ほら、これがプレゼントだ。」"
  },
  Item_123553_EmojiName = {
    Text = "プレゼント"
  },
  Item_123553_Name = {
    Text = "ポリュクス・プレゼント"
  },
  Item_123554_Desc = {
    Text = "「おやおや？魔術師が投げた箱の中身は、プレゼント？それとも爆弾？」"
  },
  Item_123554_EmojiName = {Text = "投擲"},
  Item_123554_Name = {
    Text = "カーシア・投擲"
  },
  Item_123555_Desc = {
    Text = "「森へ1時間ほどお付き合いいただけませんか？あのお菓子の家の気配を、もう一度感じたくて……」"
  },
  Item_123555_Name = {
    Text = "冬の祝宴・オルラ"
  },
  Item_123556_Desc = {
    Text = "「皆様の銀霜夜を、少しでも照らせますように。」"
  },
  Item_123556_EmojiName = {Text = "後光"},
  Item_123556_Name = {
    Text = "ファロス・後光"
  },
  Item_123557_Desc = {
    Text = "「今夜はジンジャーブレッドとメープルシロップを味わいながら、この盛大なパーティーを祝おう！」"
  },
  Item_123557_Name = {
    Text = "冬の祝宴・ドゥルセイン"
  },
  Item_123558_Desc = {
    Text = "「冬渡祭おめでとう、恩人よ。あっ……帽子が羽に当たってしまった。」"
  },
  Item_123558_EmojiName = {
    Text = "おめでとう"
  },
  Item_123558_Name = {
    Text = "カストル・おめでとう"
  },
  Item_123559_Desc = {
    Text = "差出人不明の招待状が、あなたのポストに入っている——そして、香ばしい生姜の香りが漂うクッキーの欠片を残していった。\n使用すると、未獲得の「冬の祝宴」シリーズのアイコンを1つ選択して獲得できる。"
  },
  Item_123559_Name = {
    Text = "冬の祝宴の招待状"
  },
  Item_123560_Desc = {
    Text = "銀霜夜に、靴下をベッドの枕元に掛けておくと、冬渡祭の朝に不思議な贈り物が届くという言い伝えがある。必ず、洗った靴下を掛けること。\n使用すると、未獲得の「冬のミサゴ」シリーズのバトル用スタンプを1つ選択して獲得できる。"
  },
  Item_123560_Name = {
    Text = "冬渡祭の引換券"
  },
  Item_123561_Desc = {
    Text = "「何をしているのですか。この神母をそんな不敬な目で見るとはどういうおつもり？」"
  },
  Item_123561_EmojiName = {Text = "靴下"},
  Item_123561_Name = {
    Text = "偽生・マーフィー・靴下"
  },
  Item_123638_Desc = {
    Text = "銀霜夜の前夜に、子どもたちが用意したお願い箱。欲しいプレゼントを書いた紙が貼られている。\n「一年間いい子にしてたんだもん！これで冬渡節の使者も、きっとプレゼントをくれるよね！」"
  },
  Item_123638_Name = {
    Text = "銀霜夜のお願い箱"
  },
  Item_123639_Desc = {
    Text = "冬渡祭の朝にだけ現れる特別な贈り物。開封するとすぐに消えてしまうため、その存在を知る者はほとんどいない。\n「しーっ。これは『いい子』と冬渡節の使者だけの秘密だよ。」"
  },
  Item_123639_Name = {
    Text = "冬渡祭の贈り物"
  },
  Item_123757_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得できます。\n「あ、ありがとうございます…………あっ！近づかないでください…………け、怪我させてしまいます…………」"
  },
  Item_123757_Name = {
    Text = "色褪せない昨日：フェイント"
  },
  Item_123757_StoryDesc = {
    Text = "第29期学期課題"
  },
  Item_124899_Desc = {
    Text = "このキーオーダーを記録すると、編隊時にキースキル「逃れえぬ輪廻」を選択できます。\n\n織物、測定、そして裁断。\n運命の神は悲しみも喜びもなく、運命の織り車は永遠に回り続けます。"
  },
  Item_124899_Name = {
    Text = "逃れえぬ輪廻"
  },
  Item_124899_StoryDesc = {
    Text = "紡ぎ、測り、そして断つ。\n運命の神は悲も喜もなく、運命の紡車は悠久に止まず。"
  },
  Item_125136_Desc = {
    Text = "属性がダメージ強化の運命の札。"
  },
  Item_125136_Name = {
    Text = "白木蓮の餌"
  },
  Item_125136_StoryDesc = {
    Text = "あれは私と父が海城に移り住んで二年目のこと、イヴリンが手紙の中で泣き訴える内容に苛立ち、私は彼女と別れる決意を固めていた。ここは絹と黒檀で飾られた豊饒の地、すべての腐肉食いがその眠りの中の混沌を嗅ぎつけていた。紙幣の額面で同じ重さの黄金が手に入り、あの航路さえ掌握すれば、極めて小さなコストで千万倍の富を動かせる。\nしかしイヴリン、おそらく彼女の晦渋で追い難い奇怪な血統がもたらす神経質ゆえか、この女は所謂先祖の伝信を固く信じていた。東方には「彼ら」の傍系が信奉する邪異なる神がおり、深海のある種の魚のように、美味そうな餌をぶら下げて揺らし、獲物を気づかぬほど緩やかな捕食へと誘い込むのだと。\n彼女は間違っていた。海城には海の塩の匂いなど微塵もない。\nあるのはただ幾重にも重なり、陶酔させるほど芳醇で、しかし恐怖を抱かせる白木蓮だけ。\n私と父を同時に陥落させた白木蓮。\n彼女を見た時――「徐」という名の女の姿が私の視界に現れたその最初の一秒で、私はもう永遠にこの古い大地から逃れられなくなった。\n彼女は近づきたいと思わせる、彼女は所有したいと思わせる、彼女は@3たいと思わせる\n彼女は思わせる思わせる思わせる思わせる思わせる思わせるたいたいたいたいたい\n\n切り刻み裂き砕き永遠に永遠に永遠に永遠に永遠に…………@2@3@2！！\nああ、私はなぜここに来たのだ？私は何を持ち去ろうとしていた？私は…………誰だ？\nもう重要ではない、彼女が私を招いたのだ、私はあの大邸宅の食卓の前に座っている。\nとうに私と同じく狂気に堕ちた父は、顔に従順な笑みを浮かべ、色とりどりの付け合わせが食卓を埋め尽くし、金属の蓋付き料理皿だけが場違いに映った。\n\n徐は逆光の中、夕陽を背にして座り、光の輪が彼女にふわりとした金の縁取りを施していた。ゆっくりと、あの黒い扇が下ろされた。\nイヴリンのような、幼い頃の遊び仲間のような、朧げな情事のような…………私の母のような。\nそれは廟の鍍金の神像のように端正で美しい顔だった。\n私は啜る音も聞こえず、父の体から漂う生臭さも嗅がなかった。ただ恍惚とあの顔を見つめていた。そしてあの顔の持ち主が白い手を伸ばし、料理皿の蓋を開け、適した肉を拾い上げ、二本の細い木の棒でそれを挟み、持ち上げた。\n彼女は私を呼んだ。焼かれた動物の脂が私の口元に滴った。\n「坊や、何か召し上がれ。」\n私は従順にぼんやりと口を開けた。\n木蓮の花はもう咲いていた。それはさらさらと私に向かって垂れ下がっていた。\n――「無名者の手記」"
  },
  Item_125137_Desc = {
    Text = "男たちは競って珍しい宝を贈ろうとするが、毎日最も濃くて甘い梨膏糖を買ってくるよう求められるばかり。\n彼女はそれがお嬢様の歯を腐食させないようにする。邪神がいつも悪い願いを叶えたがるように。\n\n最低{s1}個ドロップ"
  },
