  Item_125187_Desc = {
    Text = "それは古き意志の失われた霊識。 ミサゴは神秘の儀式を通じて覚醒体の霊識を啓発し、啓発を受けた覚醒体は永久に精神能力を増強する。\n徐を重複獲得した際に変換して入手、徐の啓霊の活性化に使用。"
  },
  Item_125187_Name = {
    Text = "欠片・徐"
  },
  Item_125187_StoryDesc = {
    Text = "徐を重複獲得した際に変換して入手、徐の啓霊の活性化に使用。"
  },
  Item_125188_Desc = {
    Text = "男たちは競って珍しい宝を贈ろうとするが、毎日最も濃くて甘い梨膏糖を買ってくるよう求められるばかり。\n彼女はそれがお嬢様の歯を腐食させないようにする。邪神がいつも悪い願いを叶えたがるように。\n\n最低{s1}個ドロップ"
