  Item_125189_Desc = {
    Text = "男たちは競って珍しい宝を贈ろうとするが、毎日最も濃くて甘い梨膏糖を買ってくるよう求められるばかり。\n彼女はそれがお嬢様の歯を腐食させないようにする。邪神がいつも悪い願いを叶えたがるように。\n\n最低{s1}個ドロップ"
  },
  Item_125190_Desc = {
    Text = "この鍵令を記録すると、編成時に鍵令スキル：「深邸の往事」を選択できるようになる。\n\n深い屋敷には多くの秘密が埋もれている。権力について、執着について、欲望について。\n邪神が塵世に一瞥を投げかけ、「愉悦」と「歪み」に満ちた愛意について。"
  },
  Item_125190_Name = {
    Text = "屋敷に眠る過去"
  },
  Item_125190_StoryDesc = {
    Text = "深い屋敷には多くの秘密が埋もれている。権力について、執着について、欲望について。\n邪神が塵世に一瞥を投げかけ、「愉悦」と「歪み」に満ちた愛意について。"
  },
  Item_125191_Desc = {
    Text = "男たちは競って珍しい宝を贈ろうとするが、毎日最も濃くて甘い梨膏糖を買ってくるよう求められるばかり。\n彼女はそれがお嬢様の歯を腐食させないようにする。邪神がいつも悪い願いを叶えたがるように。\n\n最低{s1}個ドロップ"
