  Item_125194_Desc = {
    Text = "男たちは競って珍しい宝を贈ろうとするが、毎日最も濃くて甘い梨膏糖を買ってくるよう求められるばかり。\n彼女はそれがお嬢様の歯を腐食させないようにする。邪神がいつも悪い願いを叶えたがるように。\n\n最低{s1}個ドロップ"
  },
  Item_125195_Desc = {
    Text = "装備者の毒付与と毒発動の効果を高め、毎ターン胚胎融合が増加する。共振効果を発動すると、他の覚醒体に大量の狂気を獲得させる。"
  },
  Item_125195_Name = {Text = "枉凝眉"},
  Item_125195_StoryDesc = {
    Text = "「後悔しているの？」\n琉璃の杯から蘇った古の神が彼女を嗅ぎ、虚無のように彼女の肩に漂い、窓を開け、淡い香りを伴う夜風を送った。\n「私が眉をひそめれば、連なる城壁に狼煙が上がる。私が微笑めば、四方の流水が珍品と異獣、蜜酒と珍味を運んでくる。私は王朝で最も貴重な宝物なのに、なぜ後悔する必要があるの？」\n彼女は微酔のために顔を赤らめ、クスクス笑いながら、絹と毛皮の積み上げられた高いベッドの枕に埋もれてうとうとしていた。\n…………\n「後悔しているの？」\n線香の煙に宿る古の神が彼と対話し、かすかな煙が楼閣を流れ、開いた花の蕾を描いた。\n「彼らは争いに疲れ果て、私はただ座って利益を享受するだけ。高く登るほど、落ちるのも激しい。私のように、何でも持っている者には、後悔する暇などない。」\n彼はにやにや笑いながら酒を満たし、手近な枝を取り、籠の中で鳴く虫をからかった。\n…………\n「後悔しているの？」\n井戸から這い出た古の神が彼女の耳元で笑い、漂う霧が彼女の髪を撫で、一輪の白玉蘭を枝から揺らした。\n「私は愛があり、絆があり、日没に帰る時の温かい粥があり、集まり祝う時の美酒がある。どうして後悔するの？もちろん後悔なんてしないわ。」\n彼女は花を摘んで鬢に飾り、暖かい黄の蝋燭の影が彼女のスカートの裾に揺れ、彼女の目は窓辺に張り付き、待ち人を見つめていた。\n…………\n「後悔しているの？」\n逃亡する彼女のスカートは宮門前の汚れた泥で汚れ、昨日は親切に贈り物をした衛兵は彼女の哀願を聞かず、二本の冷たい剣戟が交差して彼女の唯一の逃げ道を封じた。\n霧は静かにため息をつき、一輪の紅梅が雪地に咲き、次の雪で完全に埋もれた。\n…………\n「後悔しているの？」\n檀木の箱からこぼれた南海の真珠が青い煉瓦に砕け、地に落ちる音はかつての音楽よりも心地よかった。\n彼が最も愛し、毎日鑑賞していた書画が堂前に転がり、妙手絶筆の墨痕山水が刀の先で破られ、彼が見て見ぬふりをしていた戦火に焼かれた国土のようだった。\n霧は嘲笑しながら漂い、そして火が起こり、彫刻された梁と画棟は前朝の余燼に消えた。\n…………\n「後悔しているの？」\n彼女が舌先で呼んだ名前の主は二度と戻らず、遠くの川辺には枯れた骨、枕には美人。\n彼は天子の門生で公主の婿になったのか？彼は花の中に十年も留まり帰らなかったのか？彼は流民の腹に葬られ、災後の余糧となったのか？\n霧は曖昧に低吟し、彼女の苦しい問いに答えを与えなかった。\n\n王朝が栄える時の最も貴重な宝物は、王朝が傾く時の最も貴重な副葬品となる。\n家族が繁栄する時の最も悠々たる寵児は、家族が衰退する時の最も理想的な捨て子となる。\nそして最後の物語は、世の中にはあまりにも多すぎる。"
  },
  Item_125196_Desc = {
    Text = "男たちは競って珍しい宝を贈ろうとするが、毎日最も濃くて甘い梨膏糖を買ってくるよう求められるばかり。\n彼女はそれがお嬢様の歯を腐食させないようにする。邪神がいつも悪い願いを叶えたがるように。\n\n最低{s1}個ドロップ"
