  },
  Item_126362_Desc = {
    Text = "後方支援部は調査を完了した守秘者に特別許可を発行した。調査完了後、次の出発に向け、貴重なシルバーコア製品を購入可能。\n数量限定、銀の鍵の導きがあらんことを。"
  },
  Item_126362_Name = {
    Text = "調査プロセス特典·星辰篇Ⅴ"
  },
  Item_126491_Desc = {
    Text = "「古国雑俎」にて獲得可能。\n「もう些事に煩わされる必要はない。\nすべての妖しき想いと情熱は、永遠にあの扇の下の語り得ぬ姿に繋がれる。」"
  },
  Item_126491_Name = {
    Text = "扇中の真形"
  },
  Item_126491_StoryDesc = {
