  Item_128552_Name = {
    Text = "チケット"
  },
  Item_128659_Desc = {
    Text = "祈歳節当日だけでなく、その後まるまる半月間、磐龍古国のあちこちに喜びの雰囲気が溢れる。\n人々はプレゼントを持って、親戚や友人を訪ね歩く。富、喜び、そして祝福を象徴するあらゆる良いものが、最高の願いを込めてこのギフトボックスに詰め込まれる。"
  },
  Item_128659_Name = {
    Text = "祈歳鴻運ボックス"
  },
  Item_128660_Desc = {
    Text = "磐龍古国では、どの子供も祈歳節の到来を心待ちにしている。\nナツメ餡餅、ピーナッツ菓子、アーモンド飴、そして両親や年長者が用意したお年玉。こんなプレゼントをもらえたら、きっと吉祥に満ちた一年を過ごせるだろう。"
  },
  Item_128660_Name = {
    Text = "祈歳吉祥箱"
  },
  Item_129143_Desc = {
    Text = "歓喜列車に逸散した感情粒子。触れると、小さな「N」の笑い声が聞こえてくるようだ。\n守密人の「疾走する歓喜専列」における共鳴を高めるために使用する。"
  },
  Item_129143_Name = {
    Text = "留影の心"
  },
  Item_129498_Desc = {
    Text = "VIPポイントが一定値に達すると、「客室グレード」のランクが上昇する。「疾走する歓楽列車」で獲得できる。"
  },
  Item_129498_Name = {
    Text = "VIPポイント"
  },
  Item_129499_Desc = {
    Text = "この鍵令を記録すると、編成時に鍵令スキル：「歳末花火」を選択できるようになる。\n\n年々歳々花相似たり、歳々年々団欒を願う。\n今宵の祈歳、一枕の夢。わらわの小さな茉莉花が故人の傍らにて、共に万千の焰火を賞でる時、わらわの情義を忘れぬよう。"
  },
  Item_129499_Name = {
    Text = "年の瀬の花火"
  },
  Item_129499_StoryDesc = {
    Text = "年々歳々花相似たり、歳々年々団欒を願う。\n今宵の祈歳、一枕の夢。わらわの小さな茉莉花が故人の傍らにて、共に万千の焰火を賞でる時、わらわの情義を忘れぬよう。"
  },
  Item_129628_Desc = {
    Text = "属性がシルバーキー充電レベルに基づく命輪。"
  },
  Item_129628_Name = {
    Text = "泥濘を踏み越えた薔薇"
  },
  Item_129628_StoryDesc = {
    Text = "記録されえないある周回の中で、巡環のラモーナは鐘楼の裏の花壇を踏み越えた。\n視界の端に、薔薇園の中で花々が鮮烈に咲き誇っているのが映った。\n稀に見る一瞬の停滞の後、彼女はすべての無用な空想を振り捨て、最後の戦場へと駆け出した。\n泥濘が血のように濃い花弁に飛び散り、たちまち漆黒の融蝕漿に呑み込まれ、風の中に毅然たる後ろ姿だけが残された。"
  },
  Item_129898_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得できます。\n「雅な料理には時間をかけた仕上げが必要です、ああ〜楽しみにしていますよ、あなたの忘れられない香りを。」"
  },
  Item_129898_Name = {
    Text = "色褪せない昨日：ドゥルセイン"
  },
  Item_129898_StoryDesc = {
    Text = "第29期学期課題"
  },
