  },
  Item_130039_Desc = {
    Text = "属性がブラックマークドロップの運命の札。"
  },
  Item_130039_Name = {
    Text = "汚泥の中の童話"
  },
  Item_130039_StoryDesc = {
    Text = "本棚には退屈な研究文献の他に子供向けの楽しげな本もいくつかあった。\n『シンデレラ』『白雪姫』『人魚姫』『ラプンツェル』…………その所有者がなぜそのようなものを書棚に収めていたのか――今となっては知る術もない。\n\nそれらの物語には現実とは違う物語が紡がれる。「王子」「姫」「愛」…………それらの言葉は少女の心をときめかせる。\n\n夜空に輝く無数の光は地上へと降り注ぎ、やがて流れる光の河となるかのよう。\n差し込む月明かりの中で、少女はそっとつま先立ちをし、透明なガラスの靴を履いているふりをした。あたかもこの深く孤独な暗い夜が明けるのをずっと待ち望むかのように…………"
  },
  Item_130040_Desc = {
    Text = "純粋無垢で、思わず近づきたくなる鱗粉。サヤの苗床と不思議な共鳴を生み出すようだ。\nサヤに持っていくと、彼女からの報酬が得られる。\n\n最低{s1}個ドロップ"
