  },
  Item_130053_Desc = {
    Text = "行動力上限を増加させ、装備者の侵蝕付与と胚胎融合度付与の能力を強化する総合型命輪。"
  },
  Item_130053_Name = {
    Text = "花香る世界を願って"
  },
  Item_130053_StoryDesc = {
    Text = "タンポポの種は、鳥よりも小さく、そよ風よりも軽い。\n\nタンポポが最初の荒野を通りかかったとき、そこで風に転がる草たちに尋ねた。\n「君たちはどうやって繁殖するの？」\n\n風に転がる草たちは言った。\n「種をいろんなところに転がして、根を下ろせる土を見つけるまで旅をさせるのさ」\n\n彷徨う旅人には家がない……\nそうつぶやきながら、タンポポは別の風に乗って飛び去った。\n\nタンポポが次に砂漠を通りかかったとき、まばらに生えるサボテンに尋ねた。\n「君たちはどうやって生きているの？」\n\nサボテンは言った。\n「根を深く地中に伸ばし、わずかな水を吸い上げて生きるんだ」\n\n厳しい環境でもたくましく生きてるものだ。さらにタンポポは砂漠を後にする。\n\nやがてタンポポは都市の上空を通りかかる。闇夜に浮かぶ光は人の営みの証。\n長い旅の果てに、ついにタンポポの種はその地上へと舞い降りようとしていた。"
  },
  Item_130054_Desc = {
    Text = "どこから来たのかわからない鱗粉。サヤの苗床と不思議な共鳴を生み出すようだ。\nサヤに持っていくと、彼女からの報酬が得られる。\n\n最低{s1}個ドロップ"
