  Item_130063_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「新世界に捧ぐ」を選択可能。\n\n咲いて、咲いて——世界すべてを歓喜の色に染め上げて。\nそれは遥かなる平穏、悠久なる至福。\nやがて幕を開ける新世界へと、沙耶が贈る——最後の贈り物。"
