  Item_130224_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\n沙耶を再度獲得した際に変換され、沙耶の霊知啓発を起動するために使用。"
  },
  Item_130224_Name = {
    Text = "欠片・沙耶"
  },
  Item_130224_StoryDesc = {
    Text = "沙耶を再度獲得した際に変換され、沙耶の霊知啓発を起動するために使用。"
  },
  Item_130363_Desc = {
    Text = "覚醒体「ツァトゥグア」を獲得後に解放"
  },
  Item_130363_Name = {
    Text = "ツァトゥグア"
  },
  Item_130364_Desc = {
    Text = "それは古き意志の失われた霊識。ミサゴは神秘の儀式を通じて覚醒体の霊識を啓発し、啓発を受けた覚醒体は永久に精神能力を強化する。\nサトグアを重複獲得した際に変換で入手、サトグアの啓霊の発動に使用する。"
  },
  Item_130364_Name = {
    Text = "カケラ·サトグア"
  },
  Item_130364_StoryDesc = {
    Text = "サトグアを重複獲得した際に変換で入手、サトグアの啓霊の発動に使用する。"
  },
  Item_130366_Name = {
    Text = "ツァトゥグア"
  },
  Item_130367_Name = {
    Text = "ツァトゥグア"
  },
  Item_130468_Desc = {
    Text = "属性がシルバーキー充電レベルに基づく命輪。"
  },
