  Item_130542_Name = {
    Text = "ミサゴ幕間劇：オジール"
  },
  Item_130543_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得可能。\n「その無意味で凡庸な台本は捨てなさい。演劇はどう演じるべきか、私が教えてあげるわ。」"
  },
  Item_130543_Name = {
    Text = "ミサゴ幕間劇：メルトダウン·ドール"
  },
  Item_130543_StoryDesc = {
    Text = "第33期学期課題"
  },
  Item_130544_Desc = {
    Text = "「学期の課題」で「核心課題」を購入後に獲得できます。\n「台本通りに戦うなんて、全然スカッとしないな。」"
  },
  Item_130544_Name = {
    Text = "ミサゴ幕間劇：ロータン"
  },
  Item_130544_StoryDesc = {
    Text = "第36期学期の課題"
  },
  Item_130545_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得可能。\n「ロウソクが小道具かって？自分で試してみればわかるでしょ〜」"
  },
  Item_130545_Name = {
    Text = "ミサゴ幕間劇：パンディア"
  },
  Item_130545_StoryDesc = {
    Text = "第32期学期課題"
  },
  Item_130546_Name = {
    Text = "ミサゴ幕間劇：エルヴァ"
  },
  Item_130547_Desc = {
    Text = "「学期の課題」で「核心課題」を購入後に獲得できます。\n「あの……私、「私たち」はたくさんのキャラクターを演じられます――もしあなたが必要とするなら。」"
  },
  Item_130547_Name = {
    Text = "ミサゴ幕間劇：「24」"
  },
  Item_130547_StoryDesc = {
    Text = "第36期学期の課題"
  },
  Item_130548_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得可能。\n「研究時間を割いて芝居なんて…………いや、嫌いとは言ってない。ゴホン、台本にはこの表情って書いてあるのか？」"
  },
  Item_130548_Name = {
    Text = "ミサゴ幕間劇：ドール"
  },
  Item_130548_StoryDesc = {
    Text = "第31期学期課題"
  },
  Item_130549_Desc = {
    Text = "「学期の課題」で「核心課題」を購入後に獲得できます。\n「これはローズマリー、追憶を意味します；そしてパンジー、思慮を意味します……ああ、すみません、台詞を読んでいました。花を手に登場するこの場面、とても好きです。」"
  },
  Item_130549_Name = {
    Text = "ミサゴ幕間劇：ニンフィア"
  },
  Item_130549_StoryDesc = {
    Text = "第37期学期の課題"
  },
  Item_130550_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得可能。\n「この動き…………十分カッコいいはず。」"
  },
  Item_130550_Name = {
    Text = "ミサゴ幕間劇：環行·ラモーナ"
  },
  Item_130550_StoryDesc = {
    Text = "第30期学期課題"
  },
  Item_130551_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得可能。\n「セリフなんてどうでもいい、大事なのは気迫よ！」"
  },
  Item_130551_Name = {
    Text = "ミサゴ幕間劇：ノディラ"
  },
  Item_130551_StoryDesc = {
    Text = "第31期学期課題"
  },
  Item_130552_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得可能。\n「賭けてみる？この劇の結末がどうなるか、賭けましょうよ？」"
  },
  Item_130552_Name = {
    Text = "ミサゴ幕間劇：ライク"
  },
  Item_130552_StoryDesc = {
    Text = "第34期学期課題"
  },
  Item_130553_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得可能。\n「ごめんなさい…………こういう…………キラキラした感じ、あまり慣れなくて…………」"
  },
  Item_130553_Name = {
    Text = "ミサゴ幕間劇：ラモーナ"
  },
  Item_130553_StoryDesc = {
    Text = "第30期学期課題"
  },
  Item_130554_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得可能。\n「リリー…………キラキラ、ご主人様は好き？」"
  },
  Item_130554_Name = {
    Text = "ミサゴ幕間劇：リリー"
  },
  Item_130554_StoryDesc = {
    Text = "第32期学期課題"
  },
  Item_130700_Desc = {
    Text = "小さな石炭球、嫌い、モス、好き！小さな石炭球、差し出す、ご褒美〜\n\n最低{s1}個ドロップ"
  },
  Item_130700_Name = {
    Text = "ホラガイ三号"
  },
  Item_130701_Desc = {
    Text = "小さな石炭球、好き！モス、好き！集める、多ければ多いほどいい〜\n\n最低{s1}個ドロップ"
  },
  Item_130701_Name = {
    Text = "ホラガイ一号"
  },
  Item_130702_Desc = {
    Text = "友達、好き、モス、集める！手伝う、ご褒美！友達にあげる〜\n\n最低{s1}個ドロップ"
  },
  Item_130702_Name = {
    Text = "ホラガイ二号"
  },
  Item_130703_Desc = {
    Text = "この鍵令を記録すると、編成時に鍵令スキル：「溺れゆく純真」を選択できるようになる。\n\n溺れる運命だと知りながらも、彼女は迷わず冷たい海に身を投じた。\nなぜなら、それが彼女の純真な心で考えた、友を救う唯一の方法だったから。"
  },
  Item_130703_Name = {
    Text = "溺れゆく純真"
  },
  Item_130703_StoryDesc = {
    Text = "溺れる運命だと知りながらも、彼女は迷わず冷たい海に身を投じた。\nなぜなら、それが彼女の純真な心で考えた、友を救う唯一の方法だったから。"
  },
  Item_130704_Desc = {
    Text = "使用者の狂気爆発を増幅することに特化した命輪。探索中に周期的に狂気を回復し、狂気爆発ダメージを上昇させる。怒涛スタンスに切り替えた際、大量の界域マスタリーを提供する。"
  },
  Item_130704_Name = {
    Text = "遠いエデン"
  },
  Item_130704_StoryDesc = {
    Text = "ここはいかなる海図にも記されていない島。\nその誕生の時から、「文明」というウイルスがこの浄土に足を踏み入れたことは一度もない。\nここにあるのは砂浜、密林、果てしなく広がる海、そして…………一人の小さな少女だけ。\n………………………………………………………………\n「パパ、ママ、おさかな！」\n「キュー〜〜」\nニ頭のイルカがゆっくりと少女の足元まで泳いできて、美しく澄んだ鳴き声を上げた。\n一頭が少女を背に乗せ、もう一頭が少女の手から気絶させたばかりの魚を受け取り、一口で飲み込んだ。\n「キュー〜〜」\n「えへへ、モス！すごい！」\n世間知らずの子供のように、少女は力強いポーズをとって、「パパ」と「ママ」の褒め言葉に応えた。\n「きょう、おひさま！いい！」\n「モス！パパ！ママ！おさんぽ！」\n少女の言葉を聞き、少女を乗せたイルカは小さく鳴いて、小島の周りをゆっくりと泳ぎ始めた。\n温かな陽光が少女に降り注ぎ、数日前からまとわりつく湿った冷たさを追い払い、柔らかな風が少女の髪を撫で、海のまどろむような息吹を運んできた。\n笑い声、水を叩く音、はしゃぐ声――世間から隔絶された小島には「文明」がもたらす煩わしさはなく、最も原始的で、最も純粋な笑顔だけが残されていた。\n二頭と一人はいつものように、原始的で憂いのない一日を過ごした。\n………………………………………………………………\nあの果てしない呼び声が、この静寂を完全に呑み込むまでは。\n「帰っておいで…………帰っておいで…………」\n「@1はあなたを必要としている…………@2…………@4…………あなたを必要としている…………」"
  },
  Item_130705_Desc = {
    Text = "友達、好き、モス、集める！手伝う、ご褒美！友達にあげる〜\n\n最低{s1}個ドロップ"
  },
  Item_130705_Name = {
    Text = "ホラガイ二号"
  },
  Item_130706_Desc = {
    Text = "小さな石炭球、嫌い、モス、好き！小さな石炭球、差し出す、ご褒美〜\n\n最低{s1}個ドロップ"
  },
