  Item_131369_Desc = {
    Text = "確率で全体に狂気を提供するリソース型命輪。"
  },
  Item_131369_Name = {
    Text = "ギャンブルの知恵"
  },
  Item_131369_StoryDesc = {
    Text = "絢爛豪華な倶楽部の入口で、白シャツを着た案内係が片手を上げ、礼儀正しくライカーを制した。\n「申し訳ありません、旦那様。招待状をお持ちでなく、当倶楽部の会員でもない方は、ご入場いただけません」\n「そうか……それは困ったな……」\n\nライカーは顎を触り、考えているふりをした。\n実際には、彼は待っているだけだった。\n自分が追っている事件の容疑者を。\nそして、運命の加護を——\n\nかくして待ち続けた甲斐はあった。\n「これはこれは、ロンディニウムで名高い幸運の探偵殿ではありませんか！さあさあ、私があなたの紹介人になりましょう」\n「ぜひ一度、あなたの伝説的な運を拝見したいものだ、どうか期待を裏切らないでくださいよ……」\n紳士はそう言って、穏やかそうでいて悪意を秘めた笑みを浮かべた。\n\nそんな表情はこの倶楽部では珍しくない。\n狂気を追い求めるギャンブラーたちが品行方正であるはずもないのだ。\n自分が仕組まれた罠に嵌められたと悟っても、ライカーは気にも留めない。\nただ口元をわずかに吊り上げ、悠然とホイストのカードを手に取った。\n\n焦ることはない。ゲームは、まだ始まったばかりだからね？\n\nそして、第一局、第二局、第三局……勝負は次から次へと続き、やがてライカーはすべてのチップを失った。\n「幸運の探偵殿、今日はついていないようですね。まあ、当然でしょう、誰だって永遠に運命の寵愛を受けられるわけではない……」\n「まだ続けますか？とはいえ、あなたはもう何も持っていないようですが」\n「何も持っていない？そうとも限らないさ」\n連敗を喫した探偵は微笑み、自分を指差した。\n「この仕立てのいい服がある。高価なステッキも。それに……」\n言葉を切り、胸ポケットから小型の装置を取り出す。\n声を落とし、にこやかにそれを弄びながら続けた。\n「君のイカサマの手口は実に見事だったよ。倶楽部の主人でさえ見抜けず、私に助けを求めたほどにね。だがどれほど巧妙でも、手口には時間がいる。操作もいる。そして……共犯も」\n「残念ながら、このミサゴ大学製の小さな装置は、君と仲間が先ほど行った不正の証拠をすべて鮮明に記録している。」\n\n紳士は一瞬凍りつき、驚愕と怒りを滲ませる。\n共犯者たちは逆上し、探偵に一発食らわせてやろうと身を乗り出す。\nしかし、多くの目が見守る中、紳士は軽率な行動を取ることはできなかった。\n何より探偵は、彼に拒むことのできない選択肢を差し出していた。\n「もう一度、賭けてみるのはどうだい？君が勝てば、この装置も、私の命も、すべて君のものだ。意味は分かるだろう？」\n「もし私が負けたら？」\n「自首してもらおう」\nライカーは笑って肩をすくめ、輝く牙を見せた。\n「自分が負けるとでも？本当のギャンブラーは、自分の勝ちしか信じない」\n\nそう、すべてのギャンブラーは自分が勝つと思っている。\nだから誰もがこの賭けを拒めない。\n再びホイストのカードが卓上を巡る。\n配り、差し込み、すり替え、そして決着。\n「うん、ラッキーだね」\n敗者を一瞥もせず、ライカーは笑いながら札束を空中に放り投げる。\nもともと騒然としていた倶楽部が、さらに熱狂に包まれた。\n奪い合う叫び、富を掴んだ歓声、狂気じみた笑い。\n\nその喧騒の中で、ライカーはミサゴ大学から支給された、誰もが持つ装飾品を胸ポケットに戻し、自分の名前が記された招待状をズボンのポケット越しに軽く叩き、帽子を押さえて口元を緩めた。\n\n本当のギャンブラーは、自分の勝ちしか信じない。\n\n彼は信じている。\n何をしても、運命の寵愛は常に自分と共にあると。\n"
  },
