  Item_132904_Name = {
    Text = "一時的なテキスト"
  },
  Item_132905_Desc = {
    Text = "脆く儚い輝きを放つ銀芯結晶。\n銀芯を繰り返し精製する過程で稀に生成され、一定時間内に高位存在の意志とリンクすることができる。"
  },
  Item_132905_Name = {
    Text = "空幻のコア"
  },
  Item_132906_Desc = {
    Text = "幻装「仮テキスト」を獲得後に解放。\n「仮テキスト」"
  },
  Item_132906_Name = {
    Text = "アラクネ·一時的なテキスト"
  },
  Item_133338_Desc = {
    Text = "爆発的に会心ダメージバフを提供するサポート型命輪"
  },
  Item_133338_Name = {
    Text = "私用の昼休み"
  },
  Item_133338_StoryDesc = {
    Text = "朝の乗馬では郡の紳士たちと馬を並べ、彼らの胸中を探らなければならない。\n懇親の宴では各家の夫人と気の利いた社交辞令を交わし、晩餐会では銀燭台の灯りの下で長々と空虚な食前の祈りに耳を傾け、オペラの幕が下りれば劇場の回廊で際限ない挨拶をこなさなければならない。\n\n「秘密の園のティータイムだけが、本当の私だけの時間なの。」\n「ここにお客様をお招きするのは初めてよ。話題を選ぶ権利はあなたに譲りましょう。」\n\nソレールは注ぎたての紅茶を手に取った。\n\n「ド・クレメ伯爵の議院改革案への立場が知りたい？\nそれともボーモナ家が二大政党間でどんな賭けをしているか？\nそれとも、子爵令嬢の秘密に興味がある？」\n\n「全部いらない？薔薇色のお菓子の味だけ知りたいの？」\n\n彼女はひと口だけ口に含み、遠くを見ていた眼差しをあなたへと戻した。\n\n「だったら、しっかり味わってみて。」\n「味わいというのは、自分で手を伸ばしてみなければ、わからないものだから。」\n\n「そう思わない？わたしの尊敬する……あのお方？」\n\nミサゴ大学の制服をまとった来訪者の襟元と袖口から黒い霧がにじみ出し、霧はみるみるうちに漆黒の混沌へと渦を巻いた。\n\n「ふふふ、まさか宿命から逃げられると思っているのか？」\n\n「お天気がいいから、まずはせっかくの休息を楽しみたいの。今流行りの紅茶とシフォンケーキを味わいたいなら、ご自由にどうぞ。他のことは、ティータイムが終わってからにして。」"
  },
  Item_133339_Desc = {
    Text = "「名園の風雅」の全任務完了で、獲得できる追加報酬の総数"
  },
  Item_133339_Name = {
    Text = "名園の風雅"
  },
  Item_133355_Desc = {
    Text = "持続的に銀鍵エネルギーを提供する命輪、開花時にはより強力な効果を発揮する。"
  },
  Item_133355_Name = {
    Text = "桜花の幻想"
  },
  Item_133355_StoryDesc = {
    Text = "ミサゴの優等生として、ラモンナは理知と理性を行動の絶対的な論理とすることに成功し、冷静さを保ち、ユーモアを保ち、比類なき頼もしさを保っている。\nだが時折、そんなラモンナも迷いに陥ることがある。世界の絶対的なホラー、あるいは絶対的な絢爛さに直面した時――\n果てしなく広がり、視界のすべてを埋め尽くすピンクを見つめ、ラモンナは無言で黙り込んだ。\n彼女の知る限り、三週間も経たないうちに、桜は咲き始めてから散り終わる。だから、この重たく枝を覆い尽くす花々、縦横に茂る枝葉も、やがて衰え、荒涼と寂寥に沈むだろう。\n人の予測しうる寿命は、三週間どころか、三年どころか、三十年どころではない。それでもこの桜の木々と同じく、たった一度きりだ。\n人の最大の幻覚は、自分が永遠に生き続けると信じることだ。\nラモンナは分かっている。\n花が咲き、花が散る。それは自然界のごくありふれた法則であり、人の生死も、突き詰めれば自然界の現象に過ぎない。\nラモンナはそれも分かっている。\nだが人として生まれた以上、自らの存在に意味を与えたいと願うもの。すべての新生もまた、そのためにミサゴのドアを叩いた。\n彼らは融蝕に立ち向かう先駆者であり、人類の未来を見守る重要な防衛線だ。\n彼らのライフは、単なる客観的な自然現象ではない。たとえ消滅する定めにあっても、確かにこの世界の軌跡を変えている。\nそしてその間、彼らは肩を並べて戦い、風雨を共にする。\n一本の木に咲く一輪の花が、もう一輪の花に寄り添うように。共に蕾を膨らませ、共に揺れ落ち、共に開花し、共に枯れる。\nさあ、戻ろう。\n彼女が頼れる、そして彼女を頼るに値するあの花が、まだ待っている。"
  },
  Item_133404_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得可能。\n「じゃじゃ〜ん♪ ご注文のグルメ道具セットでーす〜」"
  },
  Item_133404_Name = {
    Text = "ミサゴ幕間劇：ガレン"
  },
  Item_133405_Name = {
    Text = "ミサゴ幕間劇：タヴィ"
  },
  Item_133406_Desc = {
    Text = "「ああああ！こんなの見たくない！」"
  },
  Item_133406_Name = {
    Text = "秘密の番人·衝撃"
  },
  Item_133406_StoryDesc = {
    Text = "第32期学期課題"
  },
  Item_133477_Desc = {
    Text = "かろうじて動く腕だけを頼りに、少女は傷だらけの体を引きずりながら、漆黒の泥へとゆっくりと這い寄っていく。\n鎖が絡み合う音が、誰もいない牢獄に響き渡る。\n奴隷一人の生き死になど、気にかける者はいない。\nこの一切を見届けるのは、壁の隅に積み重なった白骨だけだ。\n\n自分もあの白骨のひとつになるのかどうか、少女にはわからない。\nただひとつわかるのは――\n人々が泥の力を、かくも恐れているということだ。\n\n「……どうせ、今より悪くなりはしない……」\n\n泥が少女の細い人差し指を伝い、一瞬で全身を覆い尽くした。\n泥は渦巻き、沸き立ち始めた。\nまるでようやく主を見つけたかのように、狂喜しながら。\n\nやがて、牢獄に静寂が戻った。\n繭のような泥から歪んだ両手が突き出し、彼女と世界を隔てていた最後の壁を引き裂いた。\n\n少女は、黒い膿へと変異した四肢を静かに見つめた。\n四肢と首を縛る鎖は、この新たな力の前では脆くも儚い。\n初めて感じる、体の軽さだった。\n\n貪るように牢獄の空気を吸った。\n周囲の死体と汚物の腐臭など、今は少しも気にならなかった。\nなぜなら彼女はついに、生まれてからずっと夢見ていたものを味わったのだから――自由の味を。\n\n牢は破られた。\n復讐の女神は鋭い爪を振るい、己を縛った者すべてに牙を剥く。\n\n人々は叫んだ。\n「た、助けてくれ！奴隷が狂った！衛兵！衛兵はどこだ！？」\n人々は哀願した。\n「殺さないでくれ！頼む、放してくれ……か、金なら全部やる！」\n人々は逃げ惑った。\n「王が死んだ！逃げろ、早く逃げろ！あいつは人間じゃない……人間じゃないぞ！」\n人々は沈黙した。\n「……う……………ぐ………」\n\n少女は虐殺を止め、歪んだ表情が張り付いた頭蓋を投げ捨てた。\n気道に異物が詰まり、窒息死した者の面相だった。\n\n感情を吐き出し終えた少女は、考え始めた。\n自分は何をすべきなのか。\n\n泥と血を孕んだ風が、屍の都をなすりつけるように吹き渡った。\nやがて、少女は歩み出した。\n\n一人の戦士として――\n決して立ち止まることのない戦士として、自由の種を蒔くために。\n北へ、ひたすら北へ。極地の果てに至るまで。"
  },
  Item_133477_Name = {
    Text = "断鎖の刻"
  },
  Item_133478_Desc = {
    Text = "幻衣「断鎖の刻」解放後に解放。\n「もう枷は断ち切った。」"
  },
  Item_133478_Name = {
    Text = "ヘロット・断鎖の刻"
  },
  Item_133705_Desc = {
    Text = "幻衣「螺旋の残響」解放後に解放。\n「まえに、会ったことある？……あったよね、きっと。」"
  },
  Item_133705_Name = {
    Text = "ナウティラ・螺旋の残響"
  },
  Item_133706_Desc = {
    Text = "「ずっと、ずっとずっと昔、人間がまだ生まれていなかった頃から、オウムガイはいた。」\n「その螺旋の殻は、海流の向き、海水の温度、陸と海の移ろいを記憶してきた。」\n「ありとあらゆる音も覚えてる。ほら、聴いてごらん。」\n\n幼いナウティラは好奇心いっぱいに貝殻を耳に当てた。\n目の前の波が岩礁を打ち、殻の中から届く波音がナウティラの耳を打った。\n彼女は驚いて目を丸くした。\n\n「ねえ、お母さん。もし話しかけたら、次に会う時、この子は私のことを覚えていてくれるかな？」\n\n母の優しい答えは、やがて海辺の風と共に消えた。\n答えは誰も知らない。\n幼いナウティラはずいぶん長い間、貝殻に話しかけ続けた。\nでも、こんなに小さな殻に多くの言葉は入らないと思い、考えに考えた挙句、一番大切な言葉を残すことにした。\n\n「オウムガイさん。私はきっと、すごい冒険家になって、また会いに来るよ。\nそのときは、私はあなたのことをきっと覚えてる。\nだから約束ね、あなたも私のことを覚えていてね！」\n\nそれから……何があったのだろう。もう、ずいぶん昔のことだ。\n\nナウティラは、大切な何かを忘れてしまったような気がしていた。\nでも、螺旋の殻が忘れずに刻み続けるように、ナウティラの体は動いた。友を救うために。\nそうするべきだと、ずっとどこかで感じていたのだ――\nかつて、誰かが自分のためにそうしてくれたような気がして。\n\nそして彼女の壮大な冒険は、唐突に幕を閉じた。\nすべての冒険家に突然の結末が訪れるように――彼女もまた、深い海の底へと沈んでいった。\n\n融蝕の泥に飲まれそうになっているオウムガイを見たとき、ナウティラは何かを思い出しかけた。\nそれは、あの遠い昔の午後、自分が海に放した貝殻であるような気がした。\n\n「次に会う時、この子は私のことを覚えていてくれるかな？」\n\n窒息の苦しみが迫りくる前に、最後の一息が水圧に押し出される前に、ナウティラは力の限り手を伸ばし、貝殻を耳に当てた。\nオウムガイは、柔らかな触手をそっと伸ばした。\n\nナウティラには、何も聞こえなかった。"
  },
  Item_133706_Name = {
    Text = "螺旋の残響"
  },
  Item_133766_Desc = {
    Text = "魂の共鳴と共にあるもの、今はその輪郭の欠片のみが残る。各地に散らばった希望の集合が、現実を貫く増幅をもたらさんことを。\n「精錬室」で「返魂のコア」に合成できる。"
  },
  Item_133766_Name = {
    Text = "魂の回溯カケラ"
  },
  Item_133767_Desc = {
    Text = "運命の欠片を垣間見ることができる螺旋の視窓、今はその輪郭の欠片のみが残る。各地に散らばった希望の集合が、現実を貫く増幅をもたらさんことを。\n「精錬室」で「廻命のコア」に合成できる。"
  },
  Item_133767_Name = {
