  Item_140415_Desc = {
    Text = "薔薇が咲き誇り、燃え盛る炎のように。巧みな手で魂を吹き込まれた詩篇もまた火の海へ身を投じ、彼女の透明な影と一つに溶け合う。"
  },
  Item_140415_Name = {
    Text = "焚花成詩"
  },
  Item_140416_Desc = {
    Text = "「魂を楽器とし、宇宙の共鳴を奏でる。\nこの混沌、無秩序、狂乱の音楽は、世界の真相を明かすために鳴り響く。」"
  },
  Item_140416_Name = {
    Text = "不協和音の合奏"
  },
  Item_140416_StoryDesc = {
    Text = "V2.5.1アイコンギフトパック"
  },
  Item_140417_Desc = {
    Text = "第一楽章、起。高く掲げた両手が静寂に降りる前に、宇宙全体が終末の奏鳴の音で響き渡る。"
  },
  Item_140417_Name = {
    Text = "宇宙の奏響"
  },
  Item_140418_Desc = {
    Text = "「薔薇は鮮血を滴らせ、炎の中で最後の詩章と化す。優雅、ロマンス、そして音もなく零れ落ちる涙。」"
  },
  Item_140418_Name = {
    Text = "薔薇の詩篇"
  },
  Item_140418_StoryDesc = {
    Text = "V2.5.1アイコンギフトパック"
  },
  Item_140459_Desc = {
    Text = "指揮棒を振り上げる前、世界は耳障りな雑音に満ちていた。\n父の厳しい手のひらが何度も鍵盤の蓋を叩き、宮廷の廊下では蚊や蝿のような囁き声が飛び交い、新聞紙上では彼についての議論が絶えることなく続いた。\n「静かにしろ。」\n@3王立歌劇場、@3六年の春。\n若き宮廷楽師が初めて首席指揮者の台に立った。疑念と期待の声は、同じくらい強く渦巻いていた。彼はあまりにも若く、無口で、眩いほどの才能を持ち、まるで一度も世に出ることを許されなかった磁器のようだった。今、その磁器が初めて深紅の舞台の上で指揮棒を掲げた。\n指揮棒が持ち上がった瞬間、劇場全体の空気が何か見えない力に掴まれた。それは引力と潮汐であり、音楽の宇宙において抗うことのできない公理だった。\n指揮棒が降り、音符が静寂の帷を切り裂き、首席ヴァイオリン奏者の弓弦が静かに震えた。彼はとうに忘れていた――目の前に立つのが自分より五十歳も若い子供であることを。指揮棒の弧が彼を導き、彼の指はもはや自分のものではなかった。\n弦楽が押し寄せ、金管が応え、ティンパニが正確な節点で轟いた。すべての声部が見えない糸に引かれ、指揮台の上に描かれる優雅な軌跡へと服従した。\nハムリンの唇は冷淡な弧を描いて引き結ばれ、蒼白く若い顔は精緻なまでに現実離れしていた。指揮棒の一振り一振りには有無を言わせぬ命令が宿り、初めて指揮棒を握ったその時から彼は明確に知っていた――音楽とは演奏されるものではなく、支配されるものだと。\n楽章がカデンツァに差し掛かると、ハムリンは操り人形のような奏者たちを見渡した。彼の瞳には、誰の姿も映っていなかった。音楽の舞台において、彼だけが唯一の独裁者だった。\n終章。最後の音符が静寂の中に消え、長い沈黙の後、拍手が潮のように押し寄せた。\n今日の見出しはハムリンのものだった。若き天才は、かつて誰も得たことのない名声と賞賛を手にした。生涯初めての熱狂的な喝采を前にして、若き指揮者の顔には微塵の笑みも浮かばなかった。\n彼は一礼し、ゆっくりと指揮棒を置き、人生で初めて立った舞台を後にした。宮廷の宴を断り、自らの琴房へと戻った。\n凡庸な奏者、精確さに欠けるトレモロ、八分の一拍ずれた呼吸――あらゆる瑕疵は、音楽への冒涜だった。満堂の喝采の中で、彼は唯一真実の声を聞いた。頭上に広がる遥か遠い穹窿の彼方で、何かが彼のために鳴り響いていた。それは彼を呼び、叱り、待ち続けていた。彼らはいつか必ず出会う――その瞬間、彼は完璧でなければならない。\nその日、悪魔の楽師の序曲が、彼の最初の舞台を征服した。\nそして神へと至る長い楽章は、ようやく奏で始められたばかりだった。"
  },
  Item_140459_Name = {
    Text = "万象の序曲"
  },
  Item_140460_Desc = {
    Text = "幻装「万象の序曲」獲得後にアンロック。\n「八分の一拍遅い。失敗した公演だ。」"
