  Item_141173_Name = {
    Text = "巨大な「獲物」"
  },
  Item_141174_Desc = {
    Text = "このキーオーダーを記録後、編隊時にキースキル:「ホロウマン」を選択できる。\n\nあなたのこれまでの人生で経験した物語を語ろう、それはもう二度と響かない。\n海水が深淵に流れ込み、そして永遠にここに留まるように。"
  },
  Item_141174_StoryDesc = {
    Text = "あなたのこれまでの人生で経験した物語を語ろう、それはもう二度と響かない。\n海水が深淵に流れ込み、そして永遠にここに留まるように。"
  },
