  Item_141200_Desc = {
    Text = "周知の通り、深淵の魚は勝手に育つもの。異常に巨大なのは普通のこと。人間に似ているのも……普通のこと。\n\n最低{s1}個ドロップ"
  },
  Item_141200_Name = {
    Text = "巨大な「獲物」"
  },
  Item_141201_Desc = {
    Text = "周知の通り、深淵の魚は勝手に育つもの。異常に巨大なのは普通のこと。人間に似ているのも……普通のこと。\n\n最低{s1}個ドロップ"
  },
  Item_141201_Name = {
    Text = "巨大な「獲物」"
  },
  Item_141202_Desc = {
    Text = "クリティカルダメージの能力を持つ命輪。"
  },
  Item_141202_Name = {
    Text = "岐路を指す羅針盤"
  },
  Item_141202_StoryDesc = {
    Text = "商船と商船の間を渡り歩き、いつも古びた布の上着の影に身を隠している老巫師は、羅針盤は人々をその者が向かうべき場所へと導くと言った。水夫たちはふざけながら、草薬の匂いのする彼女の戯言を笑い飛ばし、五レオフアンを投げ渡して、その精巧な真鍮の装飾品を持ち去った。\nそして彼らは、その後名前を失うことになる小さな町の港に停泊した。ポントスはこの話が好きだった。羅針盤の持ち主はポントスが好きだった。\nもちろん、ユーモアがあって明るく、風のように颯爽と来ては去るポントスを嫌いな者などいなかった。\nそれは本来、素晴らしい記念品になるはずだった。ポントスが愛する甥に譲り渡し、遥か彼方への夢想を開くキーとなるはずだった――しかしそれはポントスに彼の居場所を教えなかった。ポントスは許さなかった。彼の人生に別の可能性など、絶対に存在させるつもりはなかった。\n幾年もの歳月が過ぎ、ポントスが月明かりの中で無数の夜を渡り歩き、エポヤンスへ戻るべきあの姿を探し求めていたとき、彼はそう思っていた。\nああ、あの徒労な、守護の魔法が彼から離れた。ポントスはもう彼を連れ戻せる。\nただポントスはまだ知らなかった。「羅針盤は人々をその者が向かうべき場所へと導く」――すべての船にそれぞれの航路があるように、異なる人はいつも異なる方向を選ぶのだということを。"
  },
  Item_141203_Desc = {
    Text = "なぜ魚が陸上を走っているのか気にしないで。ここはエポヤンスだから。\n\n最低{s1}個ドロップ"
  },
  Item_141203_Name = {
    Text = "新鮮な「獲物」"
  },
  Item_141204_Desc = {
    Text = "周知の通り、深淵の魚は勝手に育つもの。異常に巨大なのは普通のこと。人間に似ているのも……普通のこと。\n\n最低{s1}個ドロップ"
  },
  Item_141204_Name = {
    Text = "巨大な「獲物」"
  },
  Item_141205_Desc = {
    Text = "保有者が与える力減少効果を増幅し、特定のタイミングでチームのクリティカルダメージを増幅できる命輪。キルを達成した後、自身のターン終了時に獲得する狂気も上昇する。"
  },
  Item_141205_Name = {
    Text = "生きた囚人籠"
  },
  Item_141205_StoryDesc = {
    Text = "もし願いが本当に叶うなら、ポントスは別れが訪れる前に、せめて挨拶ができればよかったと思う。\n彼の両親は音もなく消えた。穏やかなある午後、姉のレイサが人力車を雇い、それからあの長い、当時の彼にはまだ名前もわからなかった鉄の怪物に乗り、軽油の匂いと轟音の中で、彼はその海辺の小さな町に辿り着いた。\n両親の行方について、レイサは一言も明かさなかった。激しい口論の末、彼は潮の香りが漂う港へと飛び出した。\n目の間隔が広い海の民たちが、人の手では決して届かないはずの深淵から引き上げた、奇妙な形の魚を売っていた。\n「おい、離れていろ、あの魚は捕まえた連中と同じように呪いに染まっているかもしれないぞ。」\n通りすがりの人が声を潜めた。この見知らぬ美しい若者が厄介事に首を突っ込むのを、誰も見たくなかったのだ。\n彼はいつものように相手に微笑みかけたが、眼差しはいつの間にか、その薄暗く腐敗した擬似餌へと落ちていた。大きく開いた口腔には鋭い歯が並び、醜く、ねじれ、誇示するように広がっていた。脳裏のどこかで声がして、その死物の一生を語り始めた。\n暗く、光のない海底で、それは誘い、略奪し、あらゆる手段を尽くした。その身体は堅固な囚人籠であり、子孫、愛する者、仇敵、そして獲物を閉じ込めていた。\nその生命の中で美しいものは本来、瞬く間に消え去るはずだった。しかしそれは彼らをすべて留め置いた。彼らはその身体を器として、互いに寄り添い、永遠に分離することなく在り続けた。\nポントスは激しく頭を振り、耳元で鋭く鳴り響く騒音の中、恐怖に駆られて周囲を見回した。\n声は潮のように引いていった。彼はすべてを一時の気の迷いとして片付け、心の中で自分の神経質さを嘲笑った。\nそして、何も気づかぬまま、定められた宿命へと落ちていった。"
  },
  Item_141206_Desc = {
    Text = "なぜ魚が陸上を走っているのか気にしないで。ここはエポヤンスだから。\n\n最低{s1}個ドロップ"
