    Text = "巨大な「獲物」"
  },
  Item_141229_Desc = {
    Text = "それは古き意志の失われた霊識。ミサゴは神秘的な儀式によって覚醒体の霊識を霊知啓発し、啓発を受けた覚醒体は永久に精神能力が強化される。\n重複してポントスを獲得した際に変換して入手し、ポントスの霊知啓発を発動するために使用する。"
  },
  Item_141229_Name = {
    Text = "欠片·ポントス"
  },
  Item_141229_StoryDesc = {
    Text = "重複してポントスを獲得した際に変換して入手し、ポントスの霊知啓発を発動するために使用する。"
  },
  Item_141230_Desc = {
