  },
  Item_141233_Name = {
    Text = "古老の「獲物」"
  },
  Item_141508_Desc = {
    Text = "キーエネルギーを徐々に蓄積し、キーオーダーを発動するリソース型の運命の札。"
  },
  Item_141508_Name = {
    Text = "夢遊の異界"
  },
  Item_141508_StoryDesc = {
    Text = "おとぎ話では、子供が森で野ウサギを追いかけると、異世界へと続く木のうろに落ちてしまうことがあるという。\nリリーの滑らかな素足が、丸石を敷いた小道を踏みしめた。\n\n「リリー、ここが好き……地面にガラスの破片はないし、空気に消毒液の匂いもしない。」\n\nリリーは新鮮な空気を深く吸い込んだ。林を吹き抜ける風が、花の香りを運んでくる。\n頭上では木の梢がステンドグラスのような天蓋を織りなし、こぼれ落ちる木漏れ日は地面を跳ねる宝石のようだ。絢爛で幻想的な光景にリリーはどこを見ればよいのかわからなくなった。\n\n「あ、さっきのウサギさん！」\n\n草むらに見覚えのある灰色の長い耳が揺れた。リリーは急いで追いかける。\n踏み出すたびに足元の苔が小さな銀の花を咲かせたが、リリーにそれを気にする暇はなかった。ウサギさんに伝えなければならないことがある。\n\n蜂蜜色の光が流れる小川を渡り、歌声のする葦の茂みをくぐり抜けた。\n息を切らしたリリーは、ついにウサギさんの毛玉のような尻尾をつかまえた。\n\n「ウサギさん、リサと友達になってくれる？」\n「リサはわたしの友達なの。でも今は、みんなが彼女を怖がっていて……ウサギさんなら、きっと友達になれると思うから！」\n\nウサギさんが振り返った瞬間、無数の蛍の光が空へと舞い上がった。\n\n「もちろん、@2はみんなの友達だよ。でも今は、もう休む時間だよ。」\n\nリリーは友達になったウサギさんを抱きしめ、森の奥にそびえる大きな古木の下まで歩いた。\n漂う蛍の温かな光に包まれながら、リリーは巨木の根に寄り添い、静かに眠りついた。\n\n「被験者：リリー。臨床所見：呼吸安定、眼球運動正常。第359回意識干渉実験、成功。」\nそれは夢のように美しい、幻想の世界だった。"
  },
  Item_141529_Desc = {
    Text = "解放後、「秘境紀行」のすべての任務を完了することで、以下の追加報酬を獲得できます"
  },
  Item_141529_Name = {
    Text = "秘境紀行"
  },
