  Item_144286_Desc = {
    Text = "それは古き意志の失われた霊識。ミサゴは神秘の儀式を通じて覚醒体の霊識を霊知啓発し、啓発を受けた覚醒体は精神能力を永久に強化する。\n太歳を重複取得した際に変換して入手し、太歳の霊知啓発を発動するために使用する。"
