  Item_144346_Desc = {
    Text = "一時的なテキスト"
  },
  Item_144346_Name = {
    Text = "銀の鍵の名において：太歳"
  },
  Item_144346_StoryDesc = {
    Text = "太歳ゲームプレイ活動"
  },
  Item_144378_Desc = {
    Text = "敵味方双方に混乱を与え、大量の狂気収益の獲得をレイテンシさせることができる複合型命輪。"
  },
  Item_144378_Name = {
    Text = "上への墜落"
  },
  Item_144378_StoryDesc = {
    Text = "長い駐守の時の中で、タヴィもかつてある土地に足を踏み入れたことがあった。\n彼女はすべての生き物の行動を注意深く観察し、人間の世界の端を静かに歩いた。\n\nある平凡な日の夜、郊外に密集した灯りが彼女の眼差しを引きつけた。\n舞台の背景、歌や踊、菓子を売る露店、笑い騒ぐ子供たち、杯を傾ける暇人たち。それは生命の息吹、束の間の安らぎだった。\nその光景があまりにも魅力的で、彼女は思わず姿を現した。\n\n「こんにちは、飴細工を一つください。」\n「はい、少々お待ちを。何を描きましょうか？」\nタヴィはそっと首を傾けた。彼女は偶然拾った持ち主のない貨幣を渡す必要があることは覚えていたが、自分が望むものを伝えられることをすっかり忘れていた。\n「もしお決まりでなければ、あなたのお姿を描いてみましょうか？まるで仙女のようにお美しい。」\nタヴィは微笑んでうなずき、露店主は声を上げ、糖勺を持ち上げて描き始めた。\n\nぽたり。ぽたり。\n石板に落ちたのは、蜜色の糖蜜ではなかった。\n雨だった。黒い雨だった。\n黒い粘液が目に見えない高空から滴り落ち、空に目を覆いたくなるような亀裂を溶かし開いた。\n\n\nそして、タヴィは上への墜落を始めた。\nそれは世界が沈んでいくことだった。露店主の笑顔はタヴィの記憶の中で静止した一コマに凝固し、そして万物とともに黒い大海に飲み込まれ、無数の逝きし星々の中のとるに足らない一粒となり、彼女にとって遥か遠い過去へと変わった。\nこれは彼女が引き起こした震動であり、彼女が受けるべき懲罰でもあった。\n彼女は遠くを見つめ、静かに黙していた。彼女はただ上へと墜落していく。\nこれこそが彼女の守るべき場所、「時空を超える」銀の扉なのだ。\n彼女はここで永遠に見下ろし続けるだろう。"
  },
  Item_144379_Desc = {
    Text = "解放後、「万象を覗く」の全タスクを完了すると追加で以下の報酬を獲得できる"
  },
  Item_144379_Name = {
    Text = "万象を覗く"
  },
  Item_144520_Name = {
    Text = "コレクションの切手：アグリッパ"
  },
  Item_144521_Desc = {
    Text = "「学期の課題」で「核心課題」を購入後に獲得できます。\n「ミサゴ内部発行の限定切手です。譲渡禁止、紛失禁止。これはあなたの身の安全を考慮してのことです。」"
  },
  Item_144521_Name = {
    Text = "コレクションの切手：ヘロット"
  },
  Item_144521_StoryDesc = {
    Text = "第36期学期の課題"
  },
  Item_144522_Name = {
    Text = "コレクションの切手：レーア"
  },
  Item_144523_Name = {
    Text = "コレクションの切手：ユウハシュ"
  },
  Item_144524_Name = {
    Text = "コレクションの切手：ファイント"
  },
  Item_144525_Name = {
    Text = "コレクションの切手：血鎖・ヘロット"
  },
  Item_145273_Desc = {
    Text = "リヴァイアサンはあなたの野心と冷酷さを喜ぶだろう、愛しき参加者よ。\n\n少なくとも1620個ドロップ"
  },
  Item_145273_Name = {
    Text = "血染めの供物"
  },
  Item_145274_Desc = {
    Text = "リヴァイアサンはあなたの野心と冷酷さを喜ぶだろう、愛しき参加者よ。\n\n少なくとも1848個ドロップ"
  },
  Item_145274_Name = {
    Text = "血染めの供物"
  },
  Item_145275_Desc = {
    Text = "リヴァイアサンはあなたの野心と冷酷さを喜ぶだろう、愛しき参加者よ。\n\n少なくとも1440個ドロップ"
  },
  Item_145275_Name = {
    Text = "血染めの供物"
  },
  Item_145276_Desc = {
    Text = "リヴァイアサンはあなたの野心と冷酷さを喜ぶだろう、愛しき参加者よ。"
  },
  Item_145276_Name = {
    Text = "血染めの供物"
  },
  Item_145277_Desc = {
    Text = "属性がブラックマークドロップの運命の札。"
  },
  Item_145277_Name = {
    Text = "不滅の餓骨"
  },
  Item_145277_StoryDesc = {
    Text = "ロータンの生涯で最も苦しくも満ち足りたその日、彼女の手の中の刃は風のように目の前の神明へと襲いかかった。巨剣とリヴァイアサンの星のように壮大な身体は、その嵐の中でともに寸断された。\n鮮血の王冠を騎士団の奴隷であるあの方に贈った後、交換条件として、ロータンはただ一つの要求を提示した。新しい武器が必要だと。\nロータンへの恐怖と崇敬を胸に、新たな王はリヴァイアサンの骨を取り出すよう命じ、彼女のために比類なき一対の巨剣を鋳造させた。六国最高の鍛冶師たちが昼夜を問わず鍛え上げる中で、死した神明の骸骨は、神を弑した者の手の中で新生を果たした。\n記憶に値する相手がかつてこの不滅の双剣刃を証見したことがある。彼の巨槌はロータンの鎧と巨剣を砕き、亀裂は蜘蛛の巣のように剣身に広がり、乳白色の破片が血色の空気の中に飛び散った。まるで彼女がリヴァイアサンを刺し貫いたあの日のように。彼は弱点を見つけたと思った。しかし彼は、ロータンが再び自分の前に立ち上がるのを見た。砕けるはずだったその巨剣が彼の胸を貫き、彼の血肉を呼吸した。新たな骨が砕けた箇所から湧き出し、以前よりも鋭く、より密になった。断面は節を伸ばして成長し、荒野で狂い咲く茨のようだった。彼は明確に感じ取った。自分の生命が、白骨で鋳られた刃に咀嚼され、飲み込まれていくのを。\nかつて星天を捕食した巨獣は、死んでなどいなかった。契約が結ばれた瞬間から、祂は彼女と一つに融合していたのだ。ロータンが巨剣を手にするたびに、剣身の骨棘が花開き、その鋭い尖刺で相手に残酷な歓喜の叫びを放った。\nそれは彼女の武器。彼女はそれの両足。彼女とそれは、最初から最後まで同じ渇望に囚われていた。彼女たちは不死不滅、永遠に飽くことを知らない。\n止まることのない戦場こそが、彼女たちの唯一の帰る家だった。"
  },
  Item_145278_Desc = {
    Text = "リヴァイアサンはあなたの野心と冷酷さを喜ぶだろう、愛しき参加者よ。\n\n少なくとも1512個ドロップ"
  },
  Item_145278_Name = {
    Text = "血染めの供物"
  },
  Item_145279_Desc = {
    Text = "リヴァイアサンはあなたの野心と冷酷さを喜ぶだろう、愛しき参加者よ。\n\n少なくとも1680個ドロップ"
  },
  Item_145279_Name = {
    Text = "血染めの供物"
