  Item_145299_Desc = {
    Text = "リヴァイアサンはあなたの野心と冷酷さを喜ぶだろう、愛しき参加者よ。\n\n少なくとも1440個ドロップ"
  },
  Item_145299_Name = {
    Text = "血染めの供物"
  },
  Item_145300_Desc = {
    Text = "装備者の打撃および狂気解放のクリティカルダメージを大幅に強化する命輪。"
  },
  Item_145300_Name = {
    Text = "天より堕ちる"
  },
  Item_145300_StoryDesc = {
    Text = "誕生の日より、祂は永遠の飢餓に囚われた。\n恒星の骸が祂の歯の間で砕け、文明の残骸が祂の腹の中で腐り果てる。祂の飢餓は、時間よりも古い呪いである。祂は幾度となく力を捕食し、奴隷を駆り立てて権欲の遊戯を演じさせたが、祂は自らの意義が何であるかを知らなかった。\nそのとき、ロータンという名の戦士が祂の前に現れた。\n「リヴァイアサン。」\n祂は、最後に自らの名を聞いたのがいつだったか覚えていなかった。跪く王たちはその名を口にする勇気を持たず、狂った祭司たちは頌歌でしか代えられなかった。\nしかし彼女は易々と祂を呼びかけた。まるで久しく待ち望んだ相手を呼ぶように。\n「今こそあなたが動く時だ！」\n祂は一万二千年を生きた。その長い永遠の中で、星々は食料であり、生き物は蟻であり、無数の強者たちはただの束の間の慰みに過ぎなかった。何も祂を満たすことができず、何も祂に恐怖を与えることができなかった。今日この日まで。\nこの凡人、この戦士は、巨剣を手に取り、風のように祂へと襲いかかった。\n巨剣が鱗甲を引き裂く。祂の耳に、混沌の中で誕生した時の咆哮が響き渡った。祂の怒りは天体を滅ぼし、祂の飢餓は星雲を捕食した。\n巨剣がつめを断ち切る。祂は思い出した。白い紗をまとったあの「神明」が祂の前に現れ、祂の力と意志を分離したことを。\n巨剣が心臓を貫いた瞬間、リヴァイアサンは笑った。\n一万二千年、失われた意志が、ついに再び祂の前に現れ、祂を斬り砕き、祂を征服し、祂を捕食した。彼女は祂を率いて、あらゆる領域を踏み越え、さらなる星海へと向かい、あらゆる強大な存在を征服するだろう。\nその日、古き混沌の獣は新生を果たした。彼女のもとへ帰還した瞬間、祂は完全に悟った。祂と彼女は、純粋にして徹底した力によって生まれたのだと。\n力そのものこそが、すべての意義である。"
  },
  Item_145301_Desc = {
    Text = "活動「リヴァイアサンの遊戯」で実績を達成して獲得。\n「まだ他にいるか！！」"
  },
  Item_145301_Name = {
    Text = "銀の鍵の名において：蝕滅・ロータン"
  },
  Item_145301_StoryDesc = {
