  Item_145606_EmojiName = {
    Text = "バイク走行"
  },
  Item_145606_Name = {
    Text = "ナウティラ·バイク走行"
  },
  Item_145606_StoryDesc = {
    Text = "第36期学期の課題"
  },
  Item_145970_Desc = {
    Text = "このキーオーダーを記録すると、編成時にキースキル：「偽りなきもの」を選択できる。\n\n悪逆非道の毒蛇はかつてそれでエデンの園の純真無垢な人間を惑わし、嫉妬に満ちた女王はかつてそれで白雪のように無垢な王女を欺き、知恵だけを持つ凡人もかつてそれで荒野の狩人との競走に勝った。\nしかしこれは嘘ではない。\nそれはただ、人の心の奥底にある、口にできない欲望の一欠片に過ぎない。"
  },
  Item_145970_Name = {
    Text = "偽りなきもの"
  },
  Item_145970_StoryDesc = {
    Text = "悪逆非道の毒蛇はかつてそれでエデンの園の純真無垢な人間を惑わし、嫉妬に満ちた王妃はかつてそれで白雪のように無垢な姫を欺き、知恵だけを持つ凡人もかつてそれで荒野の狩人との競走に勝った。\nしかしこれは嘘ではない。\nそれはただ、人の心の奥底にある、口にできないほんの少しの欲望に過ぎない。"
  },
  Item_146353_Desc = {
    Text = "新月雪峰に逸散した感情粒子。触れると策略が成功した時の嬉し笑い声が聞こえるような気がする。\nシークレットキーパーが調査イベント「山の宴」における共鳴を高めるために使用する。"
  },
  Item_146353_Name = {
    Text = "祝福の心"
  },
  Item_146538_Desc = {
    Text = "解放後、「終北紀行」の全任務を完了すると以下の報酬を追加で入手できる"
  },
  Item_146538_Name = {
    Text = "終北紀行"
  },
  Item_146539_Desc = {
    Text = "後方支援部は調査を完了した守秘者に特別許可を発行した。調査完了後、次の出発に向け、貴重なシルバーコア製品を購入可能。\n数量限定、銀の鍵の導きがあらんことを。"
  },
  Item_146539_Name = {
    Text = "調査の旅の特典·星辰篇Ⅵ"
