  Item_146947_Desc = {
    Text = "このキーオーダーを記録すると、編成時にキースキル:「永続新篇」を選択できます。\n\n昨日がどうであれ、太陽が再び昇る時、物語を次のページへとめくりましょう。それはまた新たな一篇となるでしょう。"
  },
