  Item_147229_Desc = {
    Text = "それは古き意志の失われた霊識。ミサゴは神秘の儀式によって覚醒体の霊識を啓発し、啓発を受けた覚醒体は永続的に精神能力が強化される。\n暮星・ティンクトを重複入手した際に変換して獲得し、暮星・ティンクトの霊知啓発を発動するために使用する。"
