  Item_147580_Name = {
    Text = "カラブ手帳"
  },
  Item_147581_Name = {Text = "八咫鏡"},
  Item_147598_Name = {
    Text = "トゥルー王冠"
  },
  Item_148117_Desc = {
    Text = "発射すると行動力を獲得でき、手札に持ち続けることでライフ回復と狂気リソースを蓄積し、さらに一度の復活を提供する複合型命輪。"
  },
  Item_148117_Name = {
    Text = "霊魂同調"
  },
  Item_148117_StoryDesc = {
    Text = "がらんとした実験室の中、各種の精密な機器が整然と並べられ、無数の管線だけが入り乱れ、まるでうねり絡まる蛇のように床を這い、空中に吊り下がっている。\n思考の信号は誰の目にも見えない川のようなものだが、天才はとうにそれと向き合うことに慣れていた。脳はその源であり、機械の管線を流れ、最終的にこの新たに造られた躯体へと注ぎ込まれる。\n意識が伝達されると同時に、久しく封じられていた多くの記憶も引き出された。家族、ミサゴ、未完の実験……ぼんやりとした意識の中で、天才は何年も前のことを思い出した。まだ最初の肉体という桎梏から脱していなかった頃、退屈そうな学生が一人、興味深そうに彼女の周りをうろうろしながら、好奇心という名の光を瞳に宿していた。\n「先生は、人工の躯体が真の魂を宿せると思いますか？」\n凡人はいつも自分たちの視野をはるかに超えた事柄を夢想したがる。陳腐な問いだ。しかし教師として、彼女は目も上げずに、それでも一言二言答えを返した。\n「あなたの身体だって人工の産物と言えなくもない。心臓、四肢、五感といった器官の働きが機械と何が違うというの？」\n「いいから、そんな妄想に時間を費やすくらいなら、その錆びついた頭脳を鍛えることに時間を使いなさい。さもなければ、血液が流れているだけのその肉体はますます無用の長物になるわよ。」\n今となっては、問いを発した者はとうに時の砂に埋もれ、もはや存在しない。知性を宿した脳槽だけが今も思考し続け、永遠に思考し続ける。\n世人が言うところの魂とは、860億個のニューロンが交錯して生まれる電気化学的活動に過ぎない。血肉であれ機械であれ、素材の違いはそれらが単なる器に過ぎないという本質を変えはしない。\nそう、凡人には無理でも、天才たる彼女には可能であり、すでに成し遂げた――そうでなければ、世界の真理を解き明かし、知識の頂点に到達することなどできない。\n視覚とは、光線が眼球を通り、最終的に網膜に像を結ぶに過ぎない。\n嗅覚とは、匂い分子が受容体と結合し、神経を走る化学的知覚経路に過ぎない。\n聴覚とは、音波が蝸牛で変換され、皮質へと送られる電気信号となるに過ぎない。\n人形のいる場所はあまりにも薄暗く、か細い灯りが揺れ、影さえも映し出せない。彼女はそっと目を閉じた。たとえ開けたところで、映るのは変わり映えのない光景だとわかっていたから。\n部屋は塵一つなく掃き清められ、瓶や缶の中の薬液も固く封じられている。機体に呼吸は必要なく、感覚を試すためにこの無味な空気を取り込む必要もない。\nただ一つ、冷たい機械的な通知音だけが、がらんとした実験室に響き渡る：\n「意識同調完了、機体起動確認。」\n十分だ。\n無機質な音声ではあるが、どこか親しみを感じさせる。物質世界の現実を錨のように固定してくれるようでもあり、あるいはただ単純に、短い休息が終わり、新たな研究に身を投じる時が来たと告げているだけのようでもあった。"
  },
  Item_148118_Desc = {
    Text = "解放後、「課外時間」の全任務を完了すると以下の報酬を追加で入手できる"
  },
  Item_148118_Name = {
    Text = "授業後の時間"
  },
  Item_148403_Desc = {
    Text = "これはあなたと覚醒体「彼此為我」の証明です。\n覚醒体の同調率がLv20に達した時に獲得し、自動的にその覚醒体のカード面に装備されて表示されます。"
  },
  Item_148403_Name = {Text = "輝き"},
  Item_148404_Desc = {
    Text = "同心の究極の証。あなたたちの目に映る互いはもはや「他者」ではなく、互いの間には、ただ二つの形体と、同一の魂だけが残る。"
  },
  Item_148404_Name = {Text = "絆の証"},
