  Item_20482_Desc = {
    Text = "金色に輝く勲章で、レオ王国の薔薇が刻まれている。地下市場で高値で売れる。\n調査で優れた成績を収めた守秘者を表彰し、交換商店で物資と交換可能。"
  },
  Item_20482_Name = {
    Text = "調査勲章"
