    Text = "彫刻の習作"
  },
  Item_21775_Desc = {
    Text = "彼らの肉体、霊知、記憶はここに封じられている――覚醒の時が訪れるまで。\n以下の「界域研究」の覚醒体を1体選択して召喚可能：\nナウティラ、ニムフィーア、パンディア、アルバ、カレン。\nゴリアテ、ファロス、カエクス、サンガー、シレスト。\nヘロット、アグリッパ、ユウハシュ、レーア、ファイント。\nリッツ、ティンクト、ウインクル、ジェンキン、カーシア。"
  },
  Item_21775_Name = {Text = "魔封瓶"},
  Item_21799_Desc = {
    Text = "取引アカウントとパスワードを提供してください。\n王国の地下市場で流通する取引証明書で、守秘者はこれにより必要な希少物資を購入可能。"
  },
  Item_21799_Name = {
    Text = "白銀の交換証"
  },
  Item_21898_Desc = {
    Text = "貴重な運命の札を記す神秘の書。\n以下の「輪転の相」のSSR運命の札を1つ選択して獲得可能：\n記憶螺旋、腐朽の贈り物、欲望の海、不屈の意志、無声の宴。\n巨人の刃、暴風雨の中で、疼痛の鰭、珊瑚の女の死、導きの帆。\n鎖を断ち切る日、蒼白の末裔、血肉の宴、暴食寓話、捕食者の子守唄。\n回れ回れ、縛られた歌、計算不能な演算、迷いの道、マジックショー。"
  },
  Item_21898_Name = {
    Text = "輪転の書"
  },
  Item_22164_Desc = {
    Text = "説明書に従って使用し、過剰摂取しないこと。\n霊知の薬剤の補給箱、任務を遂行する守秘者に援助を提供する。"
