  Item_25136_Desc = {
    Text = "貴重な材料を封入したギフトバッグで、密境課室の日常試練と週間試練任務を遂行する守秘者に追加支援を提供する。\n課題レベル50到達後、1レベル上がるごとに1つ獲得可能。\n受け取り時にランダムで以下の1つを獲得：\n「特別薬剤」×1（20％確率）\n「薔薇金券」×5000（80％確率）"
