  },
  Item_25218_Desc = {
    Text = "それは世界のルールを書き換える。直視不可、接触不可。\nミサゴ地下の昏き海から産出される神秘の霊核で、覚醒体を想像を超える高さに引き上げる。覚醒体が60レベルに達した後に使用可能。"
  },
  Item_25218_Name = {
    Text = "原初の霊核"
  },
  Item_25219_Desc = {
    Text = "それらは昏き海に散らばり、神聖な完全の瞬間を渇望している。\nミサゴ地下の神秘の欠片。集めることで「原初の霊核」を合成できる。"
  },
  Item_25219_Name = {
    Text = "霊核の欠片"
  },
  Item_34698_Desc = {
    Text = "豪華に装飾された木箱、初級昇格素材を含む。\n後方支援部が精心準備し、丁寧に組み合わせたセットで、短期間で一定の資源が必要な調査員と守秘者に適している。"
  },
  Item_34698_Name = {
    Text = "初級昇格ボックス"
  },
  Item_34699_Desc = {
    Text = "運命の欠片を覗く螺旋の窓。運命の札と交換可能。\n黄金、希土、シルバーコア…………期待する運命に比べれば、どんな高価な素材も取るに足らない。\n使用時に「輪転の相」、過去の運命の札イベント召喚、現在の運命の札イベント召喚から1つのSSR運命の札を選択可能。"
  },
  Item_34699_Name = {
    Text = "廻命のコア"
  },
  Item_34700_Desc = {
    Text = "豪華に装飾された木箱、中級昇格素材を含む。\n後方支援部が精心準備し、丁寧に組み合わせたセットで、短期間で一定の資源が必要な調査員と守秘者に適している。"
  },
  Item_34700_Name = {
    Text = "中級昇格ボックス"
  },
  Item_34701_Desc = {
    Text = "精巧な刺繍の巾着袋、上級補給品入り。\n重いかも、しっかり持って。絶対に衝撃を与えないで、落とすのも厳禁。"
  },
  Item_34701_Name = {
    Text = "上級スキル補給"
  },
  Item_34702_Desc = {
    Text = "豪華に装飾された木箱、上級昇格素材を含む。\n後方支援部が精心準備し、丁寧に組み合わせたセットで、短期間で一定の資源が必要な調査員と守秘者に適している。"
  },
  Item_34702_Name = {
    Text = "上級昇格ボックス"
  },
  Item_34703_Desc = {
    Text = "奇異な素材で作られた特別な装置で、覚醒体と運命の札の「リセット」に使用される。\n魂の印を洗い流し、精神の傷を消し去り、すべてを原点に戻し、最初の霊知を呼び戻す。\n覚醒体または常設運命の札に「リセット」機能を開放できる。"
  },
  Item_34703_Name = {
    Text = "時の起点"
  },
  Item_34704_Desc = {
    Text = "精巧な刺繍の巾着袋、初級補給品入り。中身がまだ活性を保っているかも、注意。"
  },
  Item_34704_Name = {
    Text = "初級スキル補給"
  },
  Item_34705_Desc = {
    Text = "精巧な刺繍の巾着袋、中級補給品入り。\n無人の時に袋が動いていたら、速やかに後方支援部へ返却を。"
  },
  Item_34705_Name = {
    Text = "中級スキル補給"
  },
  Item_34706_Desc = {
    Text = "魂と共鳴する物。特定の覚醒体を召喚するために使用。\n形状か、素材そのものか――この冷たい物体は幕を貫き、眠る精神を現実に引き戻す。\n使用時に「界域研究」、過去のイベントキャラ召喚、現在のイベントキャラ召喚から1つの覚醒体を選択可能。"
  },
  Item_34706_Name = {
    Text = "返魂のコア"
  },
  Item_34723_Desc = {
    Text = "「物語の魔法」イベントで「脚本の謎」のクリアか、イベント実績を達成して獲得。「魔法の脚本屋」で交換に使うアイテム。\n啓示は一瞬で消える、夜空を駆け抜ける流星のように。しかし、あなたにはそれを永遠に残す方法がある。"
  },
  Item_34723_Name = {
    Text = "揺蕩う閃き"
  },
  Item_34724_Desc = {
    Text = "一時的な撮影現場に逸散した感情粒子。触れると、子供たちの楽しそうな笑い声が聞こえてくるようだ。\n守密人の活動玩法「脚本迷宮」と特遣記録「物語の魔法」における共鳴を高めるために使用する。\n限時活動「物語の魔法」で実績報酬を達成することで入手可能。"
  },
  Item_34724_Name = {
    Text = "演技の心"
  },
  Item_34832_Desc = {
    Text = "イベント「物語の魔法」で達成完了で獲得。\n「ミサゴ覚醒体管理部からの注意：リリーに食べ物を与えすぎないで！！守秘者でも彼女に食べ物を与えるのは禁止です！」"
  },
  Item_34832_Name = {
    Text = "銀の鍵の名のもとに：リリー"
  },
  Item_34832_StoryDesc = {
    Text = "リリーの遊興イベント"
  },
  Item_34858_Desc = {
    Text = "属性が死亡耐性の運命の札。"
  },
  Item_34858_Name = {
    Text = "35mmの魔法"
  },
  Item_34858_StoryDesc = {
    Text = "物語には魔法がある——と以前フランシスはリリーに教えた。\n\nそのとき、彼女は窓際に座って物語の本を抱えていた。\n初夏の陽光が白衣を少し温め、柔らかで優しい、心地よい香りを放っていた。\n\n彼女は穏やかな調子で、物語をゆっくりと語っていた。\n\nしかし、昨夜の手術で長時間集中し続けた疲労の蓄積がたたり物語が終わる前にフランシスは深く眠りについてしまった。\n\nリリーはそれで母を責めたことはない。\n窓枠に寄りかかって疲れて眠る母の寝顔は、とても安心感を与えてくれたからだ。\n\n\n——今やフィルムが本に代わり物語と魔法を運んでいる。\n\nそれは、子供たちの不注意で、露光して壊れたフィルムを新しく代えるように……\n新しい仲間たちのはしゃぎ声がかつての暖かさと痛みが入り混じった、短い休息の時間に取って代わる。\n\nしかし、埋もれた記憶は、露光したフィルムのように、誰も知らない片隅で眠り続けている。\n\nたとえ永遠に光が当たらずともずっと、輝きを放ち続ける。"
  },
  Item_34908_Desc = {
    Text = "芽胞は何を間違えたのか、ただ家が欲しかっただけなのに。\n虫蛹とその芽胞の隣人。\n血肉界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_34908_Name = {
    Text = "胞子ポリマー"
  },
  Item_34909_Desc = {
    Text = "彼らは海百合が咲く春に共に殺戮を誓った。\nユインタのウミユリの化石。\n深海界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_34909_Name = {
    Text = "ユインタ百合"
  },
  Item_34910_Desc = {
    Text = "ある平行宇宙では、破壊的な力を持つ。\n遠い熱帯からの完璧な鉱石。\n超次元界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_34910_Name = {
    Text = "ユカタンの星"
  },
  Item_34911_Desc = {
    Text = "羽ばたく翼は竜巻を生むか、花粉アレルギーを引き起こす。\n群れをなす水晶蝶。\n混沌界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_34911_Name = {
    Text = "混沌の結晶"
  },
  Item_35140_Desc = {
    Text = "「魔法脚本ショップ」での交換に使用する道具。\n啓示は一瞬で消え去る、夜空を駆け抜ける流れ星のように。違うのは、あなたにはそれを永遠に留める方法があるということだ。\n最低ドロップ：\n揺蕩う啓示* {s1}\n追加の揺蕩う啓示を低確率で入手できる。"
  },
