  },
  Item_35711_Desc = {
    Text = "自ら進む道を決める貴重な機会。\n限定供給の輪転の書——\n任務遂行に挑む守秘者諸君へ、希望の航路を守る指針となるよう願う。"
  },
  Item_35711_Name = {
    Text = "限定輪転の書\nギフト"
  },
  Item_35712_Desc = {
    Text = "封入された霊知が自らの意思で覚醒するとは限らない。\n限定供給の魔封瓶で、任務を遂行する守秘者を守る。"
  },
  Item_35712_Name = {
    Text = "限定魔封瓶\nギフト"
  },
  Item_35816_Desc = {
    Text = "「課題」で「核心課題」を購入すると入手可能。\n「現在の課題：守秘者の外勤任務の安全性をどう向上させるか。\n課題難易度：☆☆☆☆☆」"
  },
  Item_35816_Name = {
    Text = "銀の鍵の名のもとに：ドール"
  },
  Item_35816_StoryDesc = {
    Text = "第3期課題"
  },
  Item_35817_Desc = {
    Text = "「課題」で「核心課題」を購入すると入手可能。\n「つまらない！血が流れるまで戦うぞ！」"
  },
  Item_35817_Name = {
    Text = "銀の鍵の名のもとに：ロータン"
  },
  Item_35817_StoryDesc = {
    Text = "第6期学期課題"
  },
  Item_36018_Desc = {
    Text = "イベント「星辰の正位置」で達成完了で獲得。\n「ストロベリージャムスコーンの悪魔、ブラウンプリンセス、ミサゴ食堂のワゴンケーキの新たなる破壊者————ここに降臨！」"
  },
  Item_36018_Name = {
    Text = "銀の鍵の名のもとに：マーフィー"
  },
  Item_36018_StoryDesc = {
    Text = "マーフィーの遊興イベント"
  },
  Item_36782_Desc = {
    Text = "取引アカウントとパスワードを提供してください。\n王国の地下市場で流通する取引証明書で、守秘者はこれにより必要な希少物資を購入可能。"
  },
  Item_36782_Name = {
    Text = "白銀の交換証"
  },
  Item_36801_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「オレッタの宝物」を選択可能。\n\nガラス瓶。アクアリウム。宮殿。\n\n何と呼ぼうとも、それはオレッタの友達が暮らす場所——\n融蝕も苦痛も存在しない、ささやかな楽園。"
  },
  Item_36801_Name = {
    Text = "オレッタの宝物"
  },
  Item_36801_StoryDesc = {
    Text = "ガラス瓶。アクアリウム。宮殿。\n\n何と呼ぼうとも、それはオレッタの友達が暮らす場所——\n融蝕も苦痛も存在しない、ささやかな楽園。"
  },
  Item_36813_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「咆哮する血と砂」を選択可能。\n\n霞の光は血のように染まり、砂塵が舞い上がる。\n\n果てなき砂丘の上で、生まれながらの戦士はためらうことなく自身の手首を噛み裂く。\nその血は、天空へ、大地へと還される——"
  },
  Item_36813_Name = {
    Text = "咆哮する血と砂"
  },
  Item_36813_StoryDesc = {
    Text = "霞の光は血のように染まり、砂塵が舞い上がる。\n\n果てなき砂丘の上で、生まれながらの戦士はためらうことなく自身の手首を噛み裂く。\nその血は、天空へ、大地へと還される——"
  },
  Item_36814_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「最後の誓い」を選択可能。\n\n騎士は誓った——この銃をもって、大切な者を守ると。\n\n今、銃身はその主の胸を貫く。\nそれはただ迫り来る脅威を拒み、守るべきものを外の世界から隔てるために——\nこれは騎士が果たす最後の誓いである。"
  },
  Item_36814_Name = {
    Text = "最後の誓い"
  },
  Item_36814_StoryDesc = {
    Text = "騎士は誓った——この銃をもって、大切な者を守ると。\n\n今、銃身はその主の胸を貫く。\nそれはただ迫り来る脅威を拒み、守るべきものを外の世界から隔てるために——\nこれは騎士が果たす最後の誓いである。"
  },
  Item_36815_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「儚き永遠」を選択可能。\n\n機械の人形は、新たなる霊が約束した永遠を拒絶した。\nコアを駆ける電流が、彼女の魂を焼き尽くす。\n\n崩れ落ちるまでの刹那——\n彼女には、どうしても果たさねばならない最後の使命があった。"
  },
  Item_36815_Name = {
    Text = "儚き永遠"
  },
  Item_36815_StoryDesc = {
    Text = "機械の人形は、新たなる霊が約束した永遠を拒絶した。\nコアを駆ける電流が、彼女の魂を焼き尽くす。\n\n崩れ落ちるまでの刹那——\n彼女には、どうしても果たさねばならない最後の使命があった。"
  },
  Item_36847_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「骨を蝕む抱擁」を選択可能。\n\n血肉は深海に溶け去り、骨は珊瑚へと変わる。\n彼女の瞳は燃えるように熱く——\nその腕に抱きしめるのはあなた、その手で刻み込むものもあなた。\n\n彼女はあなたに約束した。\n共に、帰ろうと。"
  },
  Item_36847_Name = {
    Text = "骨を蝕む抱擁"
  },
  Item_36847_StoryDesc = {
    Text = "血肉は深海に溶け去り、骨は珊瑚へと変わる。\n彼女の瞳は燃えるように熱く——\nその腕に抱きしめるのはあなた、その手で刻み込むものもあなた。\n\n彼女はあなたに約束した。\n共に、帰ろうと。"
  },
  Item_36848_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「湖畔の回想」を選択可能。\n\nカンブリア渓谷の湖水は煌めき、底まで透き通っている。\n\n迷宮の喧騒はいつしか遠のき——\nこの静寂を享受するのは、君と、自由を取り戻した少女だけだ。"
  },
  Item_36848_Name = {
    Text = "湖畔の回想"
  },
  Item_36848_StoryDesc = {
    Text = "カンブリア渓谷の湖水は煌めき、底まで透き通っている。\n\n迷宮の喧騒はいつしか遠のき——\nこの静寂を享受するのは、君と、自由を取り戻した少女だけだ。"
  },
  Item_36849_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「回帰の扉を越え」を選択可能。\n\n少女は、幾度巡った輪廻の数も、変えてきた歴史のすべても、すでに思い出せない——\n\nこれは最後の機会、最後の回帰。\n彼女の剣は確かにタヴィの魂核を貫いたが、その手が掴めたのは、ただあの人の手だけ。\n\nそして二人は共に、昏き海の深くへと沈んでいった。"
  },
  Item_36849_Name = {
    Text = "回帰の扉を越え"
  },
  Item_36849_StoryDesc = {
    Text = "少女は、幾度巡った輪廻の数も、変えてきた歴史のすべても、すでに思い出せない——\n\nこれは最後の機会、最後の回帰。\n彼女の剣は確かにタヴィの魂核を貫いたが、その手が掴めたのは、ただあの人の手だけ。\n\nそして二人は共に、昏き海の深くへと沈んでいった。"
  },
  Item_36850_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「腐敗の饗宴」を選択可能。\n\n宴は最高潮に達し、カンブリアの女王は高らかに笑う。\n\n狂乱する群衆と飛び散る融蝕液を隔てながら、遠く君に杯を掲げ、静かなる敬意を示す。"
  },
  Item_36850_Name = {
    Text = "腐敗の饗宴"
  },
  Item_36850_StoryDesc = {
    Text = "宴は最高潮に達し、カンブリアの女王は高らかに笑う。\n\n狂乱する群衆と飛び散る融蝕液を隔てながら、遠く君に杯を掲げ、静かなる敬意を示す。"
  },
  Item_36857_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「神の御業」を選択可能。\n\n癒しの奇跡——狂気に汚された聖堂へと神の御業が降臨する。\n\nそれは、己を捧げることを厭わぬ、曇りなき慈愛を抱く者の血の代償の果てにもたらされた。"
  },
  Item_36857_Name = {
    Text = "神の御業"
  },
  Item_36857_StoryDesc = {
    Text = "癒しの奇跡——狂気に汚された聖堂へと神の御業が降臨する。\n\nそれは、己を捧げることを厭わぬ、曇りなき慈愛を抱く者の血の代償の果てにもたらされた。"
  },
  Item_36858_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「巨人の覇道」を選択可能。\n\n覇者の道——決して諦めず、決して敗北を認めない。\n\nたとえ地平線が光を呑み込もうとも、彼はその腕で決して沈まぬ太陽を支え続ける。"
  },
  Item_36858_Name = {
    Text = "巨人の覇道"
  },
  Item_36858_StoryDesc = {
    Text = "覇者の道——決して諦めず、決して敗北を認めない。\n\nたとえ地平線が光を呑み込もうとも、彼はその腕で決して沈まぬ太陽を支え続ける。"
  },
  Item_36859_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「すべてが彼女」を選択可能。\n\nすべての「24」がひとつとなり、星の光となって溶け消える——\n\n彼女の人格は分かれたことで完全となり、その肉体は分裂によって生き続けた。\n\nこの世界に存在する「24」はただひとり、そして、すべてが彼女。"
  },
  Item_36859_Name = {
    Text = "すべてが彼女"
  },
  Item_36859_StoryDesc = {
    Text = "すべての「24」がひとつとなり、星の光となって溶け消える——\n\n彼女の人格は分かれたことで完全となり、その肉体は分裂によって生き続けた。\n\nこの世界に存在する「24」はただひとり、そして、すべてが彼女。"
  },
  Item_36860_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「薔薇の勝利」を選択可能。\n\n華麗なる薔薇は、完全なる勝利を掴み取った。\n\n彼女はふたたび、人々に囲まれ称賛される気高き薔薇へと戻る。\n\nただあなたに向けられたその視線が確かに告げていた——オペラハウスで共に過ごした秘密の冒険を。"
  },
  Item_36860_Name = {
    Text = "薔薇の勝利"
  },
  Item_36860_StoryDesc = {
    Text = "華麗なる薔薇は、完全なる勝利を掴み取った。\n\n彼女はふたたび、人々に囲まれ称賛される気高き薔薇へと戻る。\n\nただあなたに向けられたその視線が確かに告げていた——オペラハウスで共に過ごした秘密の冒険を。"
  },
  Item_36861_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「灰霧の正体」を選択可能。\n\nそよ風が彼女の長い髪を揺らし、\n灰霧の海の幻影が一瞬、君の視界に浮かび——消え去る。\n\n目の前にいるのは、変わらず優雅で、静かに微笑む彼女。\nけれど、君は確信している。\n\nあれは、決して幻覚ではない——"
  },
  Item_36861_Name = {
    Text = "灰霧の正体"
  },
  Item_36861_StoryDesc = {
    Text = "そよ風が彼女の長い髪を揺らし、\n灰霧の海の幻影が一瞬、君の視界に浮かび——消え去る。\n\n目の前にいるのは、変わらず優雅で、静かに微笑む彼女。\nけれど、君は確信している。\n\nあれは、決して幻覚ではない——"
  },
  Item_36862_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「真夏の夢」を選択可能。\n\nそれは一夜限りの儚い幻夢。\n軽やかで、柔らか——\n\nフィルムには残らずとも、撮影していた皆の記憶に静かに流れ続けている。"
  },
  Item_36862_Name = {
    Text = "真夏の夢"
  },
  Item_36862_StoryDesc = {
    Text = "それは一夜限りの儚い幻夢。\n軽やかで、柔らか——\n\nフィルムには残らずとも、撮影していた皆の記憶に静かに流れ続けている。"
  },
  Item_36863_Desc = {
    Text = "それに触れて、新たな冒険へ飛び込もう。受け止めて、最も不条理な夢に浸ろう。\n\n未精製のシルバーコアを保存する新装置。\n「特務記録」と「意識潜行」の解放に使用する。"
  },
  Item_36863_Name = {
    Text = "起点装置"
  },
  Item_36889_Desc = {
    Text = "カンブリアに逸散した感情粒子。触れると赤ワインと灰が燃える香りがするようだ。\nシークレットキーパーの活動プレイ「湖中之城」における共鳴を高めるために使用する。\n期間限定イベント「燃烧的群宴」の実績報酬として入手可能。"
  },
  Item_36889_Name = {
    Text = "享楽の心"
  },
  Item_38702_Desc = {
    Text = "「暗淡の縛」で交換に使うアイテム。\nイサラウの風に散らばる巨石の残骸。\nそれらは静止し、失われた都を厳かに悼む。"
  },
  Item_38702_Name = {
    Text = "螺旋遺跡"
  },
  Item_38703_Desc = {
    Text = "「遺跡の守」で交換に使うアイテム。\n一層一層の炭酸カルシウムでできた夢。イサラウの書の秘密を解き明かすために。"
  },
  Item_38703_Name = {
    Text = "円形菊石"
  },
  Item_38704_Desc = {
    Text = "「脊椎針の支配」で交換に使うアイテム。\n脊椎針の原材料の一つ。これで磨かれた脊椎針が人間の胸に刺さると、すべてを支配できる。\n意志と感情？それは生物の脆弱なコードに過ぎない。"
  },
  Item_38704_Name = {
    Text = "原生の脛骨"
  },
  Item_39313_Desc = {
    Text = "イベント「燃える饗宴」で商店交換で入手可能。\n「あたしに服従して、這いつくばりな！それとも、背骨を抜かれる甘苦さをもう一回味わいたいのかい？」"
  },
  Item_39313_Name = {
    Text = "銀の鍵の名のもとに：ワンダ"
  },
  Item_39313_StoryDesc = {
    Text = "ワンダ遊興イベント"
  },
  Item_39379_Desc = {
    Text = "「ワンダの珍宝箱」での交換に使用する道具。\nイサラウの風に散らばった巨石の残骸。\nそれらは静止したまま、厳かに滅びた都城を悼む。\n\n最低{s1}個ドロップ、共鳴「必要性遠征」を発動すると追加50%ドロップボーナスを享受できる"
  },
  Item_39379_Name = {
    Text = "螺旋遺跡"
  },
