  },
  Item_41327_Name = {
    Text = "提灯教会の符号"
  },
  Item_41379_Desc = {
    Text = "属性がダメージ強化の運命の札。"
  },
  Item_41379_Name = {
    Text = "イサラウの眼差し"
  },
  Item_41379_StoryDesc = {
    Text = "最初の王配は、イサラウの出身だった。\n\n彼はイサラウ人特有の淡い金色の瞳を持ち、漆黒の夜空の遥か遠くの微光を放っていた。\n\nだが、その光はイサラウの陥落と共に消え失せた。\nワンダは漆黒の泥沼から最後の遺物をすくい上げ、大切にしまい込んだ。\n\n\n彼女は第二、第三の王配とは、フラン高地で出会った。\n\nその二人は双子の貪欲な領主でワンダは彼らの力を使う事で、失われた湖中の城を再建したいと望んでいた。\n\nしかし彼女は裏切られた。\nそのため、脊椎針を彼らの骨髄に深く埋め込んだ。\n麻痺の中、ワンダはその卑しく無礼な両目を取り出し、自分がいた痕跡としてそこに残した。\n\n\n第四の王配——ワンダは、彼の名を「ジョン」と覚えていた。\n\n彼は無口で退屈だったが、彼女の機嫌をとるのは上手だった。\nさらに彼女を喜ばせたのは、「ジョン」もまた淡い金色の目をしており、彼女のものとほとんど同じだったことだ。\n\n\n「王配の目を抉り出しな」\n\n「畏まりました……\nしかし、王配様は何か間違いを犯したのでしょうか？」\n\nワンダは杯の中の、濁った水を揺らしながら、舌の上を毒が巡るのを感じていた。\n\n本当に愚か者だ。毒を盛ることさえ、こんなに粗雑だなんて。\n\n\n融蝕に蝕まれた「ジョン」を見て、彼女は思い出した——遥か彼方の星の外にいた頃、故郷を離れる彼女を見送った、死んだような無数の瞳を。\n\nそれは、今の「ジョン」の瞳と瓜二つだった。\n\n「……あえて言うなら、ユーモアのセンスが足りなかった」"
  },
  Item_43605_Desc = {
    Text = "期間限定の混乱、無秩序に増殖する結晶を収めるため、研究員は数日間残業した。\n不定期に爆発する擬態凝晶、限定供給で任務を遂行する守秘者を支援する。"
  },
  Item_43605_Name = {
    Text = "擬態爆発の夜"
  },
  Item_44174_Desc = {
    Text = "聖堂内に逸散した感情粒子。触れると、誰かの祈りとささやきが聞こえてくるようだ。\n守密人の活動玩法「聖堂への道」と特遣記録「血の色」における共鳴を高めるために使用する。\n限時活動「魂の牧人」で実績報酬を達成することで入手可能。"
  },
  Item_44174_Name = {
    Text = "懺悔の心"
  },
  Item_44265_Desc = {
    Text = "イベント「霊魂の牧人」で「聖堂の道」「市民の善意」「達成報酬」から入手でき、「チャリティ会場」で交換に使用する。\n\nあなたの思いやりをチャリティ券に変え、その財を誰かの未来へと変える。助け合いこそが、父なる神の望む道だから。"
  },
  Item_44265_Name = {
    Text = "チャリティ券"
  },
  Item_44481_Desc = {
    Text = "イベント「霊魂の牧人」で達成完了で獲得。\n「父なる神はすべての魂の輝きを見ています…………もちろんあなたのも、守秘者。」"
  },
  Item_44481_Name = {
    Text = "銀の鍵の名のもとに：サルバドル"
  },
  Item_44481_StoryDesc = {
    Text = "サルバドル遊興イベント"
  },
  Item_44482_Desc = {
    Text = "イベント「雨の町に潜む影」で達成完了で獲得。\n「世界には自動で謎を解く機械なんてないのよ、かわいいお客様。謎を解きたければ、まずは隣のお友達に聞いてみるのはいかが？」"
  },
  Item_44482_Name = {
    Text = "銀の鍵の名のもとに：ダフォダイル"
  },
  Item_44482_StoryDesc = {
    Text = "ダフォダイル遊興イベント"
  },
  Item_44483_Desc = {
    Text = "イベント「神王の復活」で達成完了で獲得。\n「諦めろ。午後4時以降は、どんな報告書も読まない——たとえ守秘者からのものであっても」"
  },
  Item_44483_Name = {
    Text = "銀の鍵の名のもとに：トゥルー"
  },
  Item_44483_StoryDesc = {
    Text = "トゥルー遊興イベント"
  },
  Item_44576_Desc = {
    Text = "後方支援部は調査を完了した守秘者に特別許可を発行した。調査完了後、次の出発に向け、貴重なシルバーコア製品を購入可能。\n数量限定、銀の鍵の導きがあらんことを。"
  },
  Item_44576_Name = {
    Text = "調査特典Ⅱ\nギフト"
  },
  Item_44577_Desc = {
    Text = "後方支援部は調査を完了した守秘者に特別許可を発行した。調査完了後、次の出発に向け、貴重なシルバーコア製品を購入可能。\n数量限定、銀の鍵の導きがあらんことを。"
  },
  Item_44577_Name = {
    Text = "調査特典Ⅳ\nギフト"
  },
  Item_44578_Desc = {
    Text = "後方支援部は調査を完了した守秘者に特別許可を発行した。調査完了後、次の出発に向け、貴重なシルバーコア製品を購入可能。\n数量限定、銀の鍵の導きがあらんことを。"
  },
  Item_44578_Name = {
    Text = "調査特典Ⅴ\nギフト"
  },
  Item_44579_Desc = {
    Text = "後方支援部は調査を完了した守秘者に特別許可を発行した。調査完了後、次の出発に向け、貴重なシルバーコア製品を購入可能。\n数量限定、銀の鍵の導きがあらんことを。"
  },
  Item_44579_Name = {
    Text = "調査特典Ⅲ\nギフト"
  },
  Item_44580_Desc = {
    Text = "後方支援部は調査を完了した守秘者に特別許可を発行した。調査完了後、次の出発に向け、貴重なシルバーコア製品を購入可能。\n数量限定、銀の鍵の導きがあらんことを。"
  },
  Item_44580_Name = {
    Text = "調査特典Ⅰ\nギフト"
  },
  Item_44581_Desc = {
    Text = "後方支援部は調査を完了した守秘者に特別許可を発行した。調査完了後、次の出発に向け、貴重なシルバーコア製品を購入可能。\n数量限定、銀の鍵の導きがあらんことを。"
  },
  Item_44581_Name = {
    Text = "調査特典Ⅵ\nギフト"
  },
  Item_44809_Desc = {
    Text = "外勤中、日々の訓練代理プランを申請可能。\n代理証明書を提示すれば、日々の訓練報酬を直接受け取れる。\n注意：訓練を長期間欠席しないように。戦闘技術を忘れないため。"
  },
  Item_44809_Name = {
    Text = "代理証明"
  },
  Item_44832_Desc = {
    Text = "属性がブラックマークドロップの運命の札。"
  },
  Item_44832_Name = {
    Text = "鏡の中の人"
  },
  Item_44832_StoryDesc = {
    Text = "その神秘的な女性は、葬儀の後に彼女を訪ねてきた。\n\n「お気の毒に……」彼女は言った。\n\n「あなたはこの悲劇に巻き込まれるべきではなかったのに」\n\n「知りませんでしたか？彼がミリーを殺した後、トンプソンが彼を追い詰めたの。あのエドワードという名のクズは、去年それで死ぬはずでした。なのに彼を助けた人がいるんです」\n\n「そうした理由？ああ、それは私にも分かりません。もしかしたら、彼らは最初から共犯だったのかもしれません。\nあるいは……その罪人自身が、自分の行いが罪だと気づいていないのかも。\nあの人は何て言ってたかしら？\nそう、赦し。罪人への赦し、彼らが犯した罪への赦し」\n\n「あの人は、人には二度目のチャンスがあるべきだと信じていましたが、あなたはどう思います？\n私たちはエドワードにもう一度チャンスを与えるべきでしょうか？\nミリーを、あなたの姉を殺し、母親まで殺したあの男に？」\n\n「そう、こういう人間は変わらない。絶対に。だからあなたはもう分かっているでしょう？」\n\nその通りだ……こういう人間は変わらない。このような人間、このような罪、このような悲劇を終わらせるには……\n\n彼らの欲望を暴露し、醜態をさらさせ、互いに殺し合い争わせそして完全に浄化する——\n\n罪なき地を迎えるために。"
  },
  Item_44841_Name = {
    Text = "リボンベル"
  },
  Item_44842_Name = {
    Text = "蛇の抜け殻"
  },
  Item_44928_Desc = {
    Text = "「チャリティ会場」での交換に使用する道具。\nあなたの愛心をチャリティ券に換え、あなたの財産を他者の未来に換えよう。\n互いに助け合うことこそ、父なる神が望む道である。\n\n最低{s1}個ドロップ"
  },
