  Item_44962_Name = {
    Text = "チャリティ券"
  },
  Item_45297_Desc = {
    Text = "属性がクリティカル率の運命の札。"
  },
  Item_45297_Name = {
    Text = "銀ダラの決意"
  },
  Item_45297_StoryDesc = {
    Text = "<Bold:銀ダラ24>\nあのフィッシュフライの店を通るたびに、叫びたくなるの。\n\nどうして、いつも傷つくのは銀ダラなの？あたしたちは本物のタラですらないのに！\n\n身が締まっていて美味しいのはあたしたちの罪だっていうの？\n\n<Bold:にゃんこ24>\nズルズル……ニャー、ニャーニャー（同意）！\n\n<Bold:銀ダラ24>\nレオ王国では、毎分1匹の銀ダラが非業の死を遂げ、人間の皿に乗せられている。\n\nそう、今こうして話している間にも、すでに10匹の銀ダラが壮絶に犠牲になったの。\nまるまる10匹！\n父なる神よ、彼らの悲鳴が聞こえますか？\n\n<Bold:にゃんこ24>\nエッ……ニャ？\nニャーニャーニャー、ニャーニャー（どこで）？\n\n<Bold:銀ダラ24>\nただの比喩よ、バカね。\nあなたはちょっとおバカだけど金のような心を持っていて、猫の本能と近視眼的な欲望に打ち勝てる。\n\n聞いて、計画があるの。これから一緒に実行してほしい……\n\n——《ビッグジョンのフィッシュフライ店爆発事件・事件概要：証言B-03》より抜粋。\n\n当時ベツレヘム精神病院は満床のため、容疑者は収容を拒否され、ロンディニウムタワーに23日間拘留された後、釈放された。"
  },
  Item_45298_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「春の詩集」を選択可能。\n\nこの詩を、受け取ってほしい——春が庭園へ贈る詩を。\n\n荒寂なる命の中、薔薇は深紅に咲き誇る。"
  },
  Item_45298_Name = {
    Text = "春の詩集"
  },
  Item_45298_StoryDesc = {
    Text = "この詩を、受け取ってほしい——春が庭園へ贈る詩を。\n\n荒寂なる命の中、薔薇は深紅に咲き誇る。"
  },
  Item_45299_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「黒鳥の舞踏」を選択可能。\n\n歩を進め。跳び、切り返し。回転。舞曲のクライマックスで、炎の中へ身を投じる。\n燃え上がれ。燃焼こそが、舞踊の唯一の答え。"
  },
  Item_45299_Name = {
    Text = "ブラックスワン"
  },
  Item_45299_StoryDesc = {
    Text = "盈歩。ジュテ。回転。舞曲のクライマックスで、炎の中へ身を躍らせる。\n燃え上がれ。燃焼こそが、踊りの唯一の答え。"
  },
  Item_45300_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「海の祭」を選択可能。\n\nリモリアの祭司は、決して海の応答を求めはしない——\n\n彼女はそのすべてと献身を海へと捧げるが、それは海そのものとは無関係だ。"
  },
  Item_45300_Name = {Text = "海の祭"},
  Item_45300_StoryDesc = {
    Text = "リモリアの祭司は、決して海の応答を求めはしない——\n\n彼女はそのすべてと献身を海へと捧げるが、それは海そのものとは無関係だ。"
  },
  Item_45301_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「一発の銃声」を選択可能。\n\n「バン——」\n空を切り裂く銃声が響き渡り、陰謀の黒幕の心臓を貫く——\n\n死は生命の終焉ではなく、ただ、謎が反転する頂点に過ぎない。"
  },
  Item_45301_Name = {
    Text = "一発の銃声"
  },
  Item_45301_StoryDesc = {
    Text = "「バン——」\n空を切り裂く銃声が響き渡り、陰謀の黒幕の心臓を貫く——\n\n死は生命の終焉ではなく、ただ、謎が反転する頂点に過ぎない。"
  },
  Item_45302_Desc = {
    Text = "このキーオーダーを記録すると、編成時にキーオーダースキル「銀嶺の覚悟」を選択可能。\n\n極寒の氷河に聳える山々は、勇猛なる戦士と狂乱の獣を呑み込み、純白の雪で物語の残骸を覆い隠す。\nしかし、来春を迎えれば、かすかな生命の力はついに風雪を超えるだろう。山々はすでにその覚悟を決めている。"
  },
  Item_45302_Name = {
    Text = "銀嶺の覚悟"
  },
  Item_45302_StoryDesc = {
    Text = "極寒の氷河に聳える山々は、勇猛なる戦士と狂乱の獣を呑み込み、純白の雪で物語の残骸を覆い隠す。\nしかし、来春を迎えれば、かすかな生命の力はついに風雪を超えるだろう。山々はすでにその覚悟を決めている。"
  },
  Item_46606_Desc = {
    Text = "「人格解析」で交換に使うアイテム。\n\nすべての記憶が忠実で信頼できるわけではない。\n秘密を教えよう：βは完全な嘘つきで、嘘をついている。"
  },
  Item_46606_Name = {
    Text = "記憶パズルα"
  },
  Item_46607_Desc = {
    Text = "「人格解析」で交換に使うアイテム。\n\n真実：αとβは両方とも嘘をついている。\n今、私は完全に消される危険を冒して伝える、それは@#¥%……&"
  },
  Item_46607_Name = {
    Text = "記憶パズルγ"
  },
  Item_46608_Desc = {
    Text = "「人格解析」で交換に使うアイテム。\n\nああ、嫉妬！あなたは噂の母。\n私はαへの非難を深く後悔している。私の知る限り、嘘をついているのはあいつだ。"
  },
  Item_46608_Name = {
    Text = "記憶パズルβ"
  },
  Item_46736_Desc = {
    Text = "「どんな色の光でも、お見せできますよ！」"
  },
