  Item_47302_Desc = {
    Text = "「パース」での交換に使用する道具。\n\nああ、嫉妬よ！お前は噂の母。\nαへの告発を深く遺憾に思う。私の知る限り、嘘をついているのはあいつの方だ。\n\n最低{s1}個ドロップ"
