  Item_47302_Name = {
    Text = "記憶パズルβ"
  },
  Item_47303_Desc = {
    Text = "「パース」での交換に使用する道具。\n\nすべての記憶が忠実で信頼できるわけではない。\n秘密を教えよう：βは徹頭徹尾の嘘つきで、嘘をついている。\n\n最低{s1}個ドロップ"
