  Item_47303_Name = {
    Text = "記憶パズルα"
  },
  Item_47304_Desc = {
    Text = "ワックス像館に逸散した感情粒子。触れると、涙と赤いリボン、霧の中のロンディニウムが見えてくるようだ。\n守密人の活動玩法「記憶コード」と特遣記録「静寂の分裂」における共鳴を高めるために使用する。\n限時活動「多重療癒」で実績報酬を達成することで入手可能。"
  },
  Item_47304_Name = {
    Text = "分裂の心"
  },
  Item_47519_Desc = {
    Text = "クリティカルダメージの能力を持つ命輪。"
  },
  Item_47519_Name = {
    Text = "深海の呼び声"
  },
  Item_47519_StoryDesc = {
    Text = "王座の幻夢の中で、王は神の啓示に耳を傾ける——\n\nリモリアの嵐は静まる。\nリモリアの深淵は消える。\n\n夢を庭とし、星を燭台とせよ。\n\n王はその善良なる民を庇護し、神の国をもたらすだろう。\n\n我が主の信徒よ、汝の心を開き、主を受け入れよ。\n\n遥かなる暗き深淵にて、古の偉大なる魂は眠りにつき、神々の囁きをに耳を傾ける。\n\nその意志は、星々の網のごとく交差し、永遠なる虚無の中で、汝が夢に至るのを待つ。\n\n嵐は静まり、水面は波立たず、地震は収まり大地は安らかに。\n\n災厄は、主の静寂なる夢の中で虚無へと変わり、民はその庇護のもと、安らぎを得る。\n\n願わくば、我らの歌声が深海を越え、主が我らに神託を授けんことを。\n災いより逃れ、果てなき安寧と至福の地へ導かれんことを。\n\n我らの信仰は主と共にある。星々が消え、時の終わるまで。"
  },
  Item_47520_Desc = {
    Text = "属性が死亡耐性の運命の札。"
  },
  Item_47520_Name = {
    Text = "昔日の花と詩"
  },
  Item_47520_StoryDesc = {
    Text = "彼女の詩がシディで人気を博して以来、友人はますます熱心に花を贈ってくれるようになった。\n「こんなにたくさんの花はいらないわ、コレット。無駄になってしまうもの」\n\n今日持ってきた薔薇は昨日、一昨日、その前の日のものと一緒に積み重ねられ、古い花は窮屈さに耐えられなかったのか、腐り始めている。\n\n「どうして無駄になるの？私たちは前に約束したじゃない、私の花とあなたの詩を交換するって」\n\nコレットは頭を振り、少し気まずそうに彼女を見つめた。\nそう、花と詩を交換する、それが彼女たちの約束だった。\n彼女は何かが変わったように感じたが、それ以上考えたくなかった。\n\n彼女は詩を書き続けた。\n昼夜を問わず詩を書いた。\n以前は自然にペン先から流れ出ていた詩が、今では少し詰まるようになっていた。\n\n友人が花を持ってくるときの目つきがますます見知らぬものに変わっていく。\n彼女は部屋いっぱいの腐っていく薔薇を見て、その枯れゆく匂いを嗅ぎながら、それを心から惜しみ、もの悲しさを感じた。\n\nしかし、彼女は決してペンを止めることはなかった。\n\n「この土地に咲く花で、私たちは服も食べ物も買える。いつかは、あの上に建っている建物の部屋だって、きっと買ってみせるわ！」\n\n「人にはそれぞれ、生まれついて果たすべき役目があるの。私はこの花園と、あの家のために生きる。……そしてあなたは、生まれながらに詩を書く人なのよ」\n\n「信じているわ、オルラ！今日から、あなたの詩は全部、私が大切に保管する。これからは——私の花であなたの詩を交換するの」\n\n花と詩。\nそれは彼女たちがお互いに交わした約束だった。\n\n彼女は決してペンを止めることはなかった。"
  },
  Item_47521_Desc = {
    Text = "狂気増加の能力を持つ命輪。"
  },
  Item_47521_Name = {
    Text = "熱い別れのキス"
  },
  Item_47521_StoryDesc = {
    Text = "黒き血に身を浸し、再び生を得た少女は、砂漠に千年にわたり渦巻く風砂の中で、豊穣母樹の神聖な血の種を掲げた。\n\n「この種が生き続ける限り、樹の血脈は途絶えることはない」\n\nそれからまた千年が過ぎた。\nこの種は樹の末裔と共に、栄光と屈辱、興隆と衰退を見届け、流浪と喪失を味わい、消滅と再生を繰り返した。\n\nそして、奔流する河が粘り気のある黒き血へと変わるとき、種は最後の継承を果たした。\n\nそれは熱く燃え上がり、絡みつくような口づけだった。\n\n満たされぬ渇望と、言葉にできぬ別れの哀しみを孕み、温かな心臓の鼓動と共に、新たな継承者を深く包み込んだ。\n\nその瑪瑙のような色彩、白翡翠のような光沢は、生命の鼓動と共に黒い終末を乗り越えていく。\n\nそして新世界の最初の樹の種は彼女の祝福のもと、大地から立ち上がり、天と地を覆う巨樹となるだろう。"
  },
  Item_48014_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「頭の中の音」を選択可能。\n\n手を取り合った瞬間、あなたたちは互いの瞳に迷いと困惑を見た。\n\n失われた過去により、欠けた旋律がここに交差する。\n沈黙の楽章は今まさに紡がれる——君たちが未来へ堕ちることを決意したがゆえに。"
  },
  Item_48014_Name = {
    Text = "忘却に至らぬ黎明"
  },
  Item_48014_StoryDesc = {
    Text = "手を取り合った瞬間、あなたたちは互いの瞳に迷いと困惑を見た。\n\n失われた過去により、欠けた旋律がここに交差する。\n沈黙の楽章は今まさに紡がれる——君たちが未来へ堕ちることを決意したがゆえに。"
  },
  Item_48113_Desc = {
    Text = "不小心人格分裂した場合どうすればいい？心配しないで、ミサグはすでに準備ができています！\n守秘者の心身の健康を保証するための方法で、「多重ヒーリング」期間中に限定供給されます。"
  },
  Item_48113_Name = {
    Text = "解離急性治療"
  },
  Item_48114_Desc = {
    Text = "一つの治療が効果がない場合は、もう一つの治療を試してみてください！\n守秘者の心身の健康を保証するための良方で、「多重ヒーリング」期間中に限定供給されます。"
  },
  Item_48114_Name = {
    Text = "解離強化治療"
  },
  Item_48115_Desc = {
    Text = "永遠に父神、『幾何原本』、そしてドクターの処方を疑問にしてはならない。\n守秘者の心身の健康を保証する良方で、「多重ヒーリング」期間中に限定供給されます。"
  },
  Item_48115_Name = {
    Text = "解離リハビリテーションプログラム"
  },
  Item_48594_Desc = {
    Text = "守秘者の細胞活性を高め、「日々の試練」でヘブンズコア、シルバーコア、守秘者経験値が2倍になり、「相位チェス」で全カード使用可能。本期課題のみ有効。\nシナプス活性の過剰活性化の副作用は不明、時間限定・数量限定、過剰摂取不可。"
  },
  Item_48594_Name = {
    Text = "シナプス活性酵素錠"
  },
  Item_48700_Desc = {
    Text = "「業の芽生え」で交換に使うアイテム。\n\n小さな丸い種。\nやがて芽を出し、根を張り、空を覆う大樹に成長する。"
  },
  Item_48700_Name = {
    Text = "豊穣の種核"
  },
  Item_48828_Desc = {
    Text = "属性が死亡耐性の運命の札。"
  },
  Item_48828_Name = {
    Text = "極夜と暁"
  },
  Item_48828_StoryDesc = {
    Text = "彼らは暗い川を漕ぎ進み、青白く、静かで、疲れ果てていた。\nぼんやりとした霧が触腕を伸ばし、彼らを暗闇に引き込み、終わりのない夜をさまよわせた。\n\nやがて、彼らは一筋の光を見た。\nそれは遠くの岸辺からの日の出で、ちらつきながらも、暗い魂を照らすには十分だった。\n彼らはその光を頼りに、不器用に暗闇を抜け、夜明けの前にたどり着いた。\nそしてあなたたちの前にも。\n\nそれは短い出会いかもしれないが、彼らは力強く手を振り、必死に叫んだ。\n皆が神聖な曙光を浴び、皆が笑っていた。\n彼らは言った——\nすべての出会いの瞬間が祭りのように貴重でありますように。\n誠実な心が永遠に鼓動し続けますように。\n銀の鍵が道を照らさんことを"
  },
  Item_48924_Desc = {
    Text = "レムワシ砂漠に逸散した感情粒子。触れると曖昧な低い唸り声が聞こえるような気がする。\nシークレットキーパーが調査イベント「欲河」における共鳴を高めるために使用する。"
  },
  Item_48924_Name = {
    Text = "愛憐の心"
  },
  Item_49204_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「唯一の種子」を選択可能。\n\n彼女は唯一の種子を、あなたの口へと託す。\n\n血脈の力、継承された信仰、超越する勇気、そして、深く満ちる愛——彼女はそのすべてを、あなたへと託した。"
  },
  Item_49204_Name = {
    Text = "唯一の種子"
  },
  Item_49204_StoryDesc = {
    Text = "彼女は唯一の種子を、あなたの口へと託す。\n\n血脈の力、継承された信仰、超越する勇気、そして、深く満ちる愛——彼女はそのすべてを、あなたへと託した。"
  },
