  },
  Item_49318_Desc = {
    Text = "後方支援部は調査を完了した守秘者に特別許可を発行した。調査完了後、次の出発に向け、貴重なシルバーコア製品を購入可能。\n数量限定、銀の鍵の導きがあらんことを。"
  },
  Item_49318_Name = {
    Text = "調査特典Ⅶ\nギフト"
  },
  Item_49464_Desc = {
    Text = "「5本の羽毛ペンを束ねれば、密契の写し速度を5倍に引き上げることができます。守秘者も試してみてください！」\nあるかわいそうな覚醒体は、小さなコツを使って罰写から逃れようとして、シルヴィアのチョークがちょうど額に当たった。"
  },
  Item_49464_Name = {
    Text = "密契摘録集"
  },
  Item_49465_Desc = {
    Text = "「聖河の負荷能力と自己調整の限度に注意を払って、含砂量の異常な原因を探ること。」\n後方支援部が守秘者に聖河の地理調査のために提供する特殊補給品。"
  },
  Item_49465_Name = {
    Text = "水文モニタリング支援"
  },
  Item_49466_Desc = {
    Text = "「ひみつはきっと地下にあり、母樹の根系が覆う最深部に……そこに絶対何か知られてはならないものが隠されている……」\n後方部が守秘者に提供した聖河地理調査用の特殊補給。"
  },
  Item_49466_Name = {
    Text = "地層掘削サポート"
  },
  Item_49467_Desc = {
    Text = "「A.F.225年以来、聖河の水源の位置を観測できていない。」\n後方支援部が守秘者に聖河の地理調査のために特殊補給を提供している。"
  },
  Item_49467_Name = {
    Text = "流域測量支援"
  },
