  Item_50032_Name = {Text = "下顎骨"},
  Item_51105_Desc = {
    Text = "「物語の魔法·復刻」イベントで「脚本の謎」のクリアか、イベント実績を達成して獲得。「魔法の脚本屋」で交換に使うアイテム。\n啓示は一瞬で消える、夜空を駆け抜ける流星のように。しかし、あなたにはそれを永遠に残す方法がある。"
  },
  Item_51105_Name = {
    Text = "揺蕩う閃き"
  },
  Item_51265_Desc = {
    Text = "「物語の魔法・復刻」活動で「脚本迷宮」をクリアするか活動実績を達成した後に入手でき、「魔法脚本ショップ」での交換に使用する道具。\n啓示は一瞬で消え去る、夜空を駆け抜ける流れ星のように。違うのは、あなたにはそれを永遠に留める方法があるということだ。\n\n最低{s1}個ドロップ"
