  Item_52069_Desc = {
    Text = "リモリアに逸散した感情粒子。触れると誰かの祈りと嘆きが聞こえるようだ。\nシークレットキーパーの活動プレイ「神国誕生」における共鳴を高めるために使用する。\n期間限定イベント「深淵の祀り」の実績報酬として入手可能。"
  },
  Item_52069_Name = {
    Text = "敬虔の心"
  },
  Item_52070_Desc = {
    Text = "イベント「深淵の祀り」の達成完了で獲得。\n「神のご意志はいまだ深海でお眠りです……我々も後れを取るわけには参りません……」"
