  Item_52177_Name = {
    Text = "祭祀者の髄"
  },
  Item_52178_Desc = {
    Text = "「蛍涙の祭壇」での交換に使用する道具。\n涙を捧げよ、祭祀の者よ。すべての苦難を、神国が償う。\n\n最低{s1}個ドロップ"
  },
  Item_52178_Name = {
    Text = "祭祀者の涙"
  },
  Item_52304_Desc = {
    Text = "「週に一度限定、過剰供給は健康に悪影響を及ぼす可能性があります。あなたの安全に責任を持たなければなりませんよ」\n医務室で、シルヴィアは困惑しながら散らばった毛先を整えた。"
  },
  Item_52304_Name = {
    Text = "ルミナスコア\n週間ギフト"
  },
  Item_52305_Desc = {
    Text = "その最深最暗の場所で沈眠する王の誕生は、神識の海全体をねじれさせる。\n異夢の侵食に抵抗するための儀式は、「沈淵の祀り」期間中に限り供給される。"
  },
  Item_52305_Name = {
    Text = "神王誕生の秘儀"
  },
  Item_52306_Desc = {
    Text = "深海の氾濫する潮流が意識の境界にインパクトを与える。\n異夢の侵食に抵抗するための儀式は、「沈淵の祀り」期間中に限定供給される。"
  },
  Item_52306_Name = {
    Text = "潮食防衛密儀"
  },
  Item_52307_Desc = {
    Text = "異夢視界中の天災も、精神共鳴を通じて守秘者のれいちに影響を与える。\n異夢の侵食に抵抗するための儀式は、「沈淵の祀り」期間中に限定供給される。"
  },
  Item_52307_Name = {
    Text = "天災警戒の秘儀"
  },
  Item_53730_Desc = {
    Text = "「おかえりなさい」"
  },
  Item_53730_Name = {
    Text = "カムバックチケット"
  },
  Item_53746_Desc = {
    Text = "「金紅祭典」で交換に使うアイテム。\n\nソレール夫人のコレクションの羽扇。株価の予測ができると信じる人もいる。"
  },
  Item_53746_Name = {
    Text = "霊鳥の羽扇"
  },
  Item_53766_Desc = {
    Text = "イベント「薔薇の書」で達成完了で獲得。\n「これが、権力の香りなのね？大いに満足よ」"
  },
  Item_53766_Name = {
    Text = "銀の鍵の名のもとに：ソレール"
  },
  Item_53766_StoryDesc = {
    Text = "ソレールイベント"
  },
  Item_53767_Desc = {
    Text = "属性がクリティカル率の運命の札。"
  },
  Item_53767_Name = {
    Text = "百万の寵愛の眼"
  },
  Item_53767_StoryDesc = {
    Text = "彼の神は、果てなき混沌の中を這い進み、時折、地に伏す万物に一瞥を投げかける。\n\n目に留まる者、例えばソレールのような者には、拒絶しがたい「契約条項」が与えられた。\n\n粗野で退屈な者に対しては、彼の神は肉体を剥ぎ取り、涙も流せない眼だけを残す。\n\nこれらの眼は寵愛を受けし者——「寵愛者」と呼ばれる。\n\nそれらは洞窟の中で、明滅する光に佇み、希望と絶望を抱き、彼の神に呼ばれるのを待つ。\n\nだが千年、一万年が過ぎても、寵愛者は闇の隅に置き去りにされたままだ。\n\n「それで……君たちは、何か理由があって残されたのだろう。君たちの使命は何？」\n「私たちは待っている」\n\n「何を待っているの？」\n「ただ……待っているだけ」\n\n「苦しくはないの？」\n「むしろ逆だ。彼の神への愛が私たちの全身を満たしている。これが唯一できることだから」\n\n「それを理解して初めて、真の信徒になれる」"
  },
  Item_53871_Desc = {
    Text = "「金紅の祝典」での交換に使用する道具。\n\nソレール夫人が収集した羽扇。株価の動向を予測できると信じる者もいる。\n\n最低{s1}個ドロップ"
  },
  Item_53871_Name = {
    Text = "霊鳥の羽扇"
  },
