  Item_53924_Desc = {
    Text = "「金紅の祝典」での交換に使用する道具。\n\nソレール夫人が収集した羽扇。株価の動向を予測できると信じる者もいる。\n\n最低{s1}個ドロップ"
  },
  Item_53924_Name = {
    Text = "霊鳥の羽扇"
  },
  Item_54015_Desc = {
    Text = "鱗翅目は孤独、愛、絶望に死す。\nランダムで有機形態の密契がドロップする。"
  },
  Item_54015_Name = {
    Text = "有機形態"
  },
  Item_54016_Desc = {
    Text = "回転し、それから忘れる——これが彼女のライフのすべてです。\n三十六房の環の密契セットの部品がランダムにドロップします。"
  },
  Item_54016_Name = {
    Text = "三十六房の環"
  },
  Item_54017_Desc = {
    Text = "必然、偶然。有限、無限。\nランダムで二律背反の密契がドロップする。"
  },
  Item_54018_Desc = {
    Text = "千年前、5分は40オンスの細砂に等しかった。\nランダムで薬となる夢の密契がドロップする。"
  },
  Item_54018_Name = {
    Text = "薬となる夢"
  },
  Item_54032_Desc = {
    Text = "高位にある者の葬儀で演奏されるミサ曲は、生者が死者に対する悲しみと追憶を表現するとともに、死が終わりではなく、永遠の生命への開始であるとの確信を表しています。\n「ローズブックと」期間中限定提供。"
  },
  Item_54032_Name = {
    Text = "追悼の聖祭ミサ"
  },
  Item_54033_Desc = {
    Text = "ある高位の人物の葬儀で演奏されたミサ曲、彼女の栄光と追憶は永遠に残る。\n「ローズブックと」期間中限定提供。"
  },
  Item_54033_Name = {
    Text = "栄光の賛美ミサ"
  },
  Item_54034_Desc = {
    Text = "高位の人物の葬儀で演奏されるレクイエムで、亡くなったソウルを慰め、永遠の安らぎを得るよう祈ります。\n「ローズブックと」期間中限定提供。"
  },
  Item_54034_Name = {
    Text = "安魂の祝福ミサ"
  },
  Item_54104_Desc = {
    Text = "覚醒体「ハムリン」獲得で解放"
  },
  Item_54104_Name = {
    Text = "ハムリン"
  },
  Item_54105_Desc = {
    Text = "装備者のカードを連続で出すことで爆発的に戦闘能力を高め、追加の手札上限と銀鍵の蓄積が柔軟な戦術選択をもたらす。"
  },
  Item_54105_Name = {
    Text = "隠世の転輪"
  },
  Item_54105_StoryDesc = {
    Text = "すべての過去と未来を知ることができる者に待つのは、全知の喜びではなく、無限の悲しみと絶望。\n彼女の目は万物に繋がる糸を見通す。糸の片方は過去に、もう片方は未来に繋がっている。\nその糸は運命と呼ばれる。\n彼女は周囲の人々をどう見ているのだろう？\n人々は善良で慈愛に満ち、人々は傲慢で疑い深い。\nだが彼らの運命と人類の運命は出会った瞬間に既に決まっている。\n彼女は彼らを愛しているに違いない、でなければ何度も手を差し伸べ、火種を与えることはない。\n彼女は彼らを期待しているに違いない、でなければ破滅の中で輪廻の影に進むことはない。\n愛ゆえに、彼女は悲しみを抱く。\n期待ゆえに、彼女は何度も失望する。\n彼女は黒い泥沼に沈み、無数の黒い糸を絶えず解きほぐし、飽きることなく。\n運命の札は何度も回転する。\n彼女は貪欲の炎が空を覆うのを見た。\n彼女は盲目的な偏執が自滅に向かうのを見た。\n彼女は狂気の妄念が破滅を加速するのを見た。\n無秩序の混沌はいつも遅れてやってくる。\n希望と絶望は無駄に回転し、終わりがない。\n彼女は暗闇の中で一瞬の星光を見た。\nその光は微弱だが、彼女は暗闇に長くいた。\n直視した瞬間、涙を流した。"
  },
  Item_54106_Name = {Text = "タヴィ"},
  Item_54107_Name = {
    Text = "ハムリン"
  },
  Item_54108_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nタヴィを再度獲得した際に変換され、タヴィの霊知啓発を起動するために使用。"
  },
  Item_54108_Name = {
    Text = "欠片・タヴィ"
  },
  Item_54108_StoryDesc = {
    Text = "タヴィを再度獲得した際に変換され、タヴィの霊知啓発を起動するために使用。"
  },
  Item_54109_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\n血ノ鎖・ヘロットを再度獲得した際に変換され、血ノ鎖・ヘロットの霊知啓発を起動するために使用。"
  },
  Item_54109_Name = {
    Text = "欠片・血ノ鎖・ヘロット"
  },
  Item_54109_StoryDesc = {
    Text = "血ノ鎖・ヘロットを再度獲得した際に変換され、血ノ鎖・ヘロットの霊知啓発を起動するために使用。"
  },
