  },
  Item_54113_Desc = {
    Text = "狂気解放後に大量の狂気を返還し自身の狂気循環を加速でき、さらに中毒と治療能力を追加で増幅できる。"
  },
  Item_54113_Name = {
    Text = "虚無に堕ちた人形"
  },
  Item_54113_StoryDesc = {
    Text = "人々はいつも自分の尺度で枠を決め、シンボルを確定したがる。\n世界は人間の肉体に限られており、なんと狭く、愚かで悲しいことか。\n彼女は早くに肉体を捨てたが、依然として真の境界に触れることができなかった。\n知識の流れは混乱し尽くし、黒い虚無が再び彼女に追いついた。\n彼女は静かにそれを見つめ、もし有形の面が世界の全貌を覗けないなら、虚無の背後こそが真の答えではないか？\n彼女は自分の命を賭けてこの生涯で最も狂気的な賭けをした。\n彼女はついに終焉を見た。\n真実の扉が開かれ、世界の姿が瞬時に逆転した。\nなるほど、なるほど。\n彼女はすべての人にこの虚無の真実を見せ、無駄なもがきから解放したいと切望した。\nかつて彼女は波の頂に立ち、世界を導いた。\n今も彼女は羊飼いの鞭を振り、軽やかに世界を深淵に導いている。\n人々は恐れて彼女を追放し、彼女を邪悪な狂人と見なした。\nなんて奇妙だ、と彼女は思った。\nでも私の目にはあなたたちも同じだ。\n"
  },
  Item_54114_Desc = {
    Text = "ダメージを与えると同時により多くのキーエネルギーを獲得し、キーオーダー発動で永久にクリティカルダメージを高める。柔軟な「銀鍵曦光」がより多くの可能性をもたらす。"
  },
  Item_54114_Name = {
    Text = "永遠の鎮魂歌"
  },
  Item_54114_StoryDesc = {
    Text = "彼は常に自分を責め続け、その厳しさゆえに仲間を遠ざけてきた。音楽の極致を追い求めるため、独りで歩み続けるつもりだった。\n\n高みは孤独なもの——彼はその運命を受け入れていた。\n\nある時、彼はひとりの演奏を耳にした。\n完璧とは程遠く、自由奔放な音楽。それはまるで、その人自身を表しているかのようだった。時に楽譜を外れ、ふと一節を忘れることさえある。だがその瞬間、両手は即興で鮮やかな音を紡ぎ、聴衆から驚きと喝采を浴びていた。\n\n彼はその人から目を離せなかった。まるで音楽の精霊が、音符の間を自由に舞うさまを見ているようだった。\n\nこれが父の言っていた「天賦の才」というものか。彼もまた深く魅了された。だが、それでも自分の歩みを変えることはできなかった。\n\n彼はあまりにも凡庸で不器用な人間であり、この苦労して敷き詰めた道を歩むことしかできなかった。\n\n皆がその人の後を追う中、彼だけが少しずつ遠ざかっていった。\n本当は近づきたかった。だが、彼は演奏すること以外何もできなかった。\n\nどう声をかければいいのか。どんな楽譜なら、その人の心を掴めるのか。\n\n彼は楽譜を編み続けた。挨拶の言葉を何度も選び直すように。だが気づいたときにはもう、声をかける機会は永遠に失われていた。\n深い後悔が彼を沈め、すべてが意味を失った。\n\n彼の目に映るのは、去りし魂へ送るはずだった、書きかけの手紙だけ。\n彼は心血を注ぎ、そしてその楽譜の前に倒れた。夢の中でさえ、道の果てにある光には触れられなかった。\n\nもし道の終わりにたどり着けないのなら、この一生の執着は何のためだったのか。\n\n遠くから笛の音が響いてきた。光の中から流れてくるその音色は、彼の問いに満ちた魂を静かに慰めた。\n\nぼんやりとした意識の中で、彼は笛を手に取った。そして、自らに課された真の使命を知った。\n\n永遠に演奏し続けること。終わることなく奏で続け、永遠の安らぎをもたらすために。\n"
  },
  Item_54115_Desc = {
    Text = "<SummonRed:『雪融けの刻』獲得報酬UP>\n持有者の基礎ダメージを大幅に向上させると同時に、狂気解放を通じて安定的に自身のカードを引きクリティカルダメージを高める火力型の運命の札。"
  },
  Item_54115_Name = {
    Text = "深紅に沈む"
  },
  Item_54115_StoryDesc = {
    Text = "彼女は闇の底で幾度となく問いかけた、なぜこれほどの苦しみを負わねばならないのか、と。\n答える者は誰もいなかった。\n嗄れた喉から漏れる呟きは、神の耳に届くことさえなかった。\n\n痛みは消えることなく、やがて膿のように滞留し、より濃い憎しみへと変わっていった。\nある日突然、彼女は周囲の人々から黒い液体が滲み出ていることに気づいた。それは、自分の体から流れ出る血とまったく同じ色をしていた。\n彼らはたちまち狂い果て、その姿はまるでかつての自分のようだった。\nそれが彼らの苦しみなのだろう。彼女はただ冷ややかに見つめ、そして悦んだ。\n\nしかし、それが苦しみであるなら、自分はとっくに黒に飲み込まれていたはずだ。\n彼女は残された黒い泥へと近づき、思いがけず自由を得た。\n\nだが、自由は彼女に解放をもたらさなかった。地獄に千年流された悪鬼のように、心に抱いた願いは憎しみによって腐り果てていた。\n彼女の身体は枷に嵌められ、魂には鉛が重くのしかかっていた。\n\nただあの悲痛な叫びだけが、彼女の重い魂を洗い、かろうじて呼吸を取り戻させていた。\n\nさあ、私が味わったものを味わい、私と同じようになるがいい。\n彼女は気づいた。紅とは、これほどまでに美しい色であったのかと。\nそしてついに理解した。苦しみに理由などないのだと。\n自ら飲み干すか、誰かと共に味わうか。\n今夜、彼女は杯に苦酒を満たし、街ごと宴に招いた。\n"
  },
