  },
  Item_55305_Desc = {
    Text = "憂愁は菖蒲の花言葉。\n庭の灰の中で見つけた詩文。「菖蒲の花壇」で物資と交換可能。\n\n最低844個ドロップ"
  },
  Item_55305_Name = {
    Text = "憂愁の詩文"
  },
  Item_55471_Desc = {
    Text = "詩を詠むことで開く神秘な箱。\nそれに花の夢を語れば、あなたに薔薇の花束を贈ってくれる。\n「春が散る前に」期間限定で提供。"
  },
  Item_55471_Name = {
    Text = "花と詩の夢"
  },
  Item_55472_Desc = {
    Text = "詩を詠むことで開く神秘な箱。\nそれに意象を伝えれば、あなたに真実を見せてくれる。\n「春が散る前に」期間限定で提供。"
  },
  Item_55472_Name = {
    Text = "意と詩の夢"
  },
  Item_55473_Desc = {
    Text = "詩を詠むことで開く神秘な箱。\nそれに過去を語れば、あなたに一片の記憶を贈ってくれる。\n「春が散る前に」期間限定で提供。"
  },
  Item_55473_Name = {
    Text = "心と詩の夢"
  },
  Item_55891_Desc = {
    Text = "彼は長夢の中で霊性豊かな者に神啓を授ける：タブーの学識は虚栄者の呪いであり、無知は愚者への恩賜である。\n「神王復活」期間限定供給。"
  },
  Item_55891_Name = {
    Text = "倦怠の悪夢"
  },
  Item_55892_Desc = {
    Text = "彼は長夢の中で霊性豊かな者に神啓を授ける：神は決して意志を残さず、祈りと願いは徒労である。\n「神王復活」期間中に限定提供。"
  },
  Item_55892_Name = {
    Text = "怠惰の悪夢"
  },
  Item_55893_Desc = {
    Text = "彼は長夢の中で霊性豊かな者に神啓を与えます：彼は星々から来られ、彼の国は最終的に昇るでしょう。\n「神王復活」期間中限定供給。"
  },
  Item_55893_Name = {
    Text = "錯乱の悪夢"
  },
  Item_55894_Desc = {
    Text = "不小心人格分裂した場合どうすればいい？心配しないで、ミサグはすでに準備ができています！\n守秘者の心身の健康を保証するための方法で、「多重ヒーリング」期間中に限定供給されます。"
  },
  Item_55894_Name = {
    Text = "解離急性治療"
  },
  Item_55895_Desc = {
    Text = "一つの治療が効果がない場合は、もう一つの治療を試してみてください！\n守秘者の心身の健康を保証するための良方で、「多重ヒーリング」期間中に限定供給されます。"
  },
  Item_55895_Name = {
    Text = "解離強化治療"
  },
  Item_55896_Desc = {
    Text = "永遠に父神、『幾何原本』、そしてドクターの処方を疑問にしてはならない。\n守秘者の心身の健康を保証する良方で、「多重ヒーリング」期間中に限定供給されます。"
  },
  Item_55896_Name = {
    Text = "解離リハビリテーションプログラム"
  },
  Item_55897_Desc = {
    Text = "苦悩の魂よ、汝は報われるだろう。仁愛に満ちた司教が父なる神の名において汝に祝福を下す。\n「魂の牧人・復刻」期間中に限定提供。"
  },
  Item_55897_Name = {
    Text = "ミサ後の祝福"
  },
  Item_55898_Desc = {
    Text = "苦しみの魂よ、決して希望を失ってはなりません。仁愛深き主教会が、あなたのために父なる神に祈りを捧げます。\n「ソウルの牧人・復刻」期間中、限定で供給されます。"
  },
  Item_55898_Name = {
    Text = "ミサの祈り"
  },
  Item_55899_Desc = {
    Text = "苦しみの魂よ、迷いは必要ない、慈愛の主教会が汝の道を照らしてくれるだろう。\n「魂の牧人・リメイク」期間中、限定供給される。"
  },
  Item_55899_Name = {
    Text = "ミサ前のガイド"
  },
  Item_55900_Desc = {
    Text = "あなたは無数の宇宙で無数の声が呼びかけているのを聞く、彼らはあなたの名前を呼んでいる。\nあなたは両手を握りしめ、大声で応える。\n「万象の扉」期間限定供給。"
  },
  Item_55900_Name = {
    Text = "エコーポータル"
  },
  Item_55901_Desc = {
    Text = "虚幻の扉があなたに向かって開かれ、無数の宇宙が破滅し再生する。\n扉の光が閃き、あなたが選ばれたことを知っています。それはすべてをあなたに委ねました。\n「万象の扉」期間中に限定供給。"
  },
  Item_55901_Name = {
    Text = "命定の扉"
  },
  Item_55902_Desc = {
    Text = "あなたは無数の宇宙に無数の人々を見ます。彼らはみなあなたと関係があります。\n無数の手があなたに向かって伸び、彼らは前赴後繼してあなたを高く持ち上げます。\n「万象の扉」期間限定供給。"
  },
  Item_55902_Name = {
    Text = "幻影の扉"
  },
  Item_55904_Desc = {
    Text = "交響楽曲の最終章、楽曲のテーマがここで決定されます。希望に満ち溢れた凱旋の賛美歌をお楽しみください。\n「無形の交響」期間中限定提供。"
  },
  Item_55904_Name = {
    Text = "回転曲楽譜"
  },
  Item_55905_Desc = {
    Text = "エルワースの山頂で新生したタンポポの種子、凍土から生える小さな野草が生命力に満ちています。\n「雪山融解の時期」の期間限定で供給されます。"
  },
  Item_55905_Name = {
    Text = "雪山蒲公英の種子"
  },
  Item_55906_Desc = {
    Text = "エルワース山頂で新生した常緑樹の種子、頑丈な苗木は風霜雨雪を越え、ついに大木へと成長する。\n「雪山融解の時」期間限定で供給される。"
  },
  Item_55906_Name = {
    Text = "雪山常緑樹の種子"
  },
  Item_55907_Desc = {
    Text = "エルワースの山頂で新生した真っ白な花の種子。氷と雪がその枝と葉となり、厳寒もその芳香を挫くことはできない。\n「雪山消融之时」期間限定供給。"
  },
  Item_55907_Name = {
    Text = "雪山銀霜花の種子"
  },
  Item_55908_Desc = {
    Text = "交響楽曲の開篇、劇的な核心がここに展開されます。対照的な主題が互いに引き立てられ、競い合います。\n「無形の交響」期間中限定供給。"
  },
  Item_55908_Name = {
    Text = "ソナタの楽譜"
  },
  Item_55910_Desc = {
    Text = "ベレー帽をかぶった瞬間、探偵の目つきが鋭くなり、誰もあなたのプロフェッショナルな身分を疑わなくなる。\n「名探偵マニュアル」期間限定販売。"
  },
  Item_55910_Name = {
    Text = "名探偵のベレー帽"
  },
  Item_55911_Desc = {
    Text = "トレンチコートを身に纏えば、背後に音楽が流れ、風が裾を揺らし、あなたの推理ポーズがバッチリ決まる！\n「名探偵マニュアル」期間限定販売。"
  },
  Item_55911_Name = {
    Text = "名探偵のトレンチコート"
  },
  Item_55912_Desc = {
    Text = "探偵の定番アクセサリー。思案にふけるときに使ってみよう。棒キャンディを咥えるよりカッコいい。\n「名探偵マニュアル」期間限定販売。"
  },
  Item_55912_Name = {
    Text = "名探偵のパイプ"
  },
  Item_55914_Desc = {
    Text = "痛みは愛の証、女王の愛を感じたときには、女王の名を大声で叫ぶこと。\n「燃える群宴」期間限定で提供されます。"
  },
  Item_55914_Name = {
    Text = "鞭打ちのかわいがり"
  },
  Item_55915_Desc = {
    Text = "あなたの頭を下げ、女王の足元で這いつくばりなさい。あなたは女王の栄光の座と足踏み台となるでしょう。\n「燃える群宴」期間限定で提供されます。"
  },
  Item_55915_Name = {
    Text = "踏みつけられた愛情"
  },
  Item_55916_Desc = {
    Text = "女王の試練を受け、あなたの忠誠を示しなさい。従うだけでよいのです。\n女王の顔に笑みが浮かんだとき、あなたは彼女の側で栄光あるポジションを得るでしょう。\n「燃える群宴」期間限定で提供されます。"
  },
  Item_55916_Name = {
    Text = "命令のかわいがり"
  },
  Item_55917_Desc = {
    Text = "母樹から取り外した妊婦のような樹瘤は、その中に育むような旺盛で無限の生命力を感じられ、よく耳を傾けると、それは母親の呼びかけだ。\n「欲の海の波·クローン」期間中、限定供給。"
  },
  Item_55917_Name = {
    Text = "慈母母樹奇形"
  },
  Item_55918_Desc = {
    Text = "母樹から取り外した少女のような樹瘤。その中に細く柔らかな生命力を感じ取ることができます。よく耳を傾けると、それは青い招待の声が聞こえてきます。\n「欲の海で波立つ・復刻」期間限定で提供されます。"
  },
  Item_55918_Name = {
    Text = "少女の母樹の奇形腫瘍"
  },
  Item_55919_Desc = {
    Text = "母樹から取られたベビーのような樹瘤は、その中にライフが誕生したような活力を感じられ、よく聞くと、それは新生の啼き声だ。\n「欲の海で波立つ·復刻」期間中、限定供給。"
  },
  Item_55919_Name = {
    Text = "嬰児の母樹腫瘍"
  },
  Item_55920_Desc = {
    Text = "あるレディと同じデザインの日傘。開くと、レディが決して頭を下げることがない自信を得られる。\n「群星正位」期間中のみ限定供給。"
  },
  Item_55920_Name = {
    Text = "レディ日傘の贈り物"
  },
  Item_55921_Desc = {
    Text = "交響楽曲の抒情的な部分の後には娯楽の章があり、ライフの力強い脈打ちは、静観と沈思の後に自由で滑稽な面白さを楽しむことができます。\n「無形交響」期間中限定供給。"
  },
  Item_55921_Name = {
    Text = "メヌエットの楽譜"
  },
  Item_55922_Desc = {
    Text = "あるレディからのお茶会への招待状、美味しいお菓子を召し上がりください。人形やテディベアと一緒に踊りましょう。\n「群星正位」期間限定で提供されます。"
  },
  Item_55922_Name = {
    Text = "レディの招待状ギフト"
  },
  Item_55923_Desc = {
    Text = "あるレディと同じデザインのドレスで、着用することでレディのような優雅で高貴な雰囲気を得られます。\n「群星正位」期間中に限定供給されます。"
  },
  Item_55923_Name = {
    Text = "レディのドレス贈り物"
  },
  Item_56483_Desc = {
    Text = "時代の最先端技術を象徴する精密な歯車で、人形の古い部分を代謝できる。\nドールの修理に使う歯車パーツ。商店で必要な物資と交換可能。"
  },
  Item_56483_Name = {
    Text = "人形パーツ"
  },
  Item_56484_Desc = {
    Text = "一見普通のチップが、波乱万丈の人生をもたらす。\n「幸運倶楽部」で物資と交換可能。"
  },
  Item_56484_Name = {
    Text = "勝負チップ"
  },
  Item_56485_Desc = {
    Text = "元初の音符は、始まりの地において、バンド全体を最終のクライマックスへと導く。「安眠の宮殿」で物資を交換するために使用する。"
  },
  Item_56485_Name = {
    Text = "高揚の楽章"
  },
  Item_56486_Desc = {
    Text = "針は止まらず回り続け、帰らぬ者と共に進む。\n終焉の時に至れば、すべての扉があなたに開かれ、すべての楽章が奏でられる。\n窮地の門前の精密な針は、「エコー」で物資と交換可能。"
  },
  Item_56486_Name = {
    Text = "終末の指針"
  },
  Item_56487_Desc = {
    Text = "神の霊知はいまだ深淵で眠る。\n深海に漂う胚胎。\n「聖胎孵化」で物資と交換可能。"
  },
  Item_56487_Name = {
    Text = "無識の胚"
  },
  Item_56488_Desc = {
    Text = "神は万物を貪り、飽くことを知らない。\n深海に漂う胚胎。\n「聖胎孵化」で物資と交換可能。"
  },
  Item_56488_Name = {
    Text = "無我の胚"
  },
  Item_56489_Desc = {
    Text = "神はこの世に何も欲しない。\n深海に漂う胚胎。\n「聖胎孵化」で物資と交換可能。"
  },
  Item_56489_Name = {
    Text = "無欲の胚"
  },
  Item_56490_Desc = {
    Text = "氷雪がそれを深青に染め上げ、不屈の生命の誕生を祝う。\nアイズルワース山頂で新たに咲く蕾、「貪欲の野心」で物資と交換可能。"
  },
  Item_56490_Name = {
    Text = "寒氷の蕾"
  },
  Item_56491_Desc = {
    Text = "月光がそれを銀白に染め上げ、不屈の生命の誕生を祝う。\nアイズルワース山頂で新たに咲く蕾、「復讐の戦意」で物資と交換可能。"
  },
  Item_56491_Name = {
    Text = "銀霜の蕾"
  },
  Item_56492_Desc = {
    Text = "日光がそれを橙黄に染め上げ、不屈の生命の誕生を祝う。\nアイズルワース山頂で新たに咲く蕾、「再生の希望」で物資と交換可能。"
  },
  Item_56492_Name = {
    Text = "日光の蕾"
  },
  Item_56493_Desc = {
    Text = "アイズルワースの雪山に逸散した感情粒子。触れると、野獣の噛みつきと飲み込む音が聞こえてくるようだ。\n守密人の活動玩法「山峦の巨口」と特遣記録「アイズルワースの帰還者」における共鳴を高めるために使用する。\n限時活動「雪山融解の時」で実績報酬を達成することで入手可能。"
  },
  Item_56493_Name = {Text = "獣の心"},
  Item_56494_Desc = {
    Text = "窮極の扉の内部に逸散した感情粒子。触れるとあらゆる次元と時空のざわめきが聞こえるような気がする。\nシークレットキーパーが調査イベント「長い夢尽きる時」における共鳴を高めるために使用する。"
  },
  Item_56494_Name = {
    Text = "究極の心"
  },
  Item_56495_Desc = {
    Text = "ミサゴのキャンパスに逸散した感情粒子。触れると無数の叫びと嘆息が聞こえるような気がする。\nシークレットキーパーが調査イベント「終末交響曲」における共鳴を高めるために使用する。"
  },
  Item_56495_Name = {
    Text = "堅忍の心"
  },
  Item_56635_Desc = {
    Text = "属性がダメージ強化の運命の札。"
  },
  Item_56635_Name = {
    Text = "雪山が溶けるまで"
  },
  Item_56635_StoryDesc = {
    Text = "彼女は山頂に立ち、手にした黒い刺を掲げた。\n猛吹雪の中、彼女は狂気に満ちた山脈へと向かった。捨てられ、裏切られ、踏みにじられた己の運命に抗うために。\n\n必ず勝利する。\n氷雪は必ず溶ける。\nそのとき、自分は新たな姿でこの世に再び現れる。\n彼女はそう言った。\n\nアイズルワースは極寒の地。\nそこでは風雪が一年中消えることがない。それは誰もが知る事実だ。\nいかに強き戦士であろうと崇高な存在には抗えず、いかに強大ない人間であろうと、自らの運命には勝てない。\nだが、あの雪山はついに溶けた。そうではないか？"
  },
  Item_56636_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「扉の彼方の真実」を選択可能。\n\n万物の真実は扉の向こうに潜む。\n\n彼女はただ静かに佇み、降り注ぐ問いのすべてを受け止め、沈黙をもって応じる。\n\nしかし、彼女が待ち続ける者だけは——いつか、自らの手で答えを記すことになる。"
  },
  Item_56636_Name = {
    Text = "扉の彼方の真実"
  },
  Item_56636_StoryDesc = {
    Text = "万物の真実は扉の向こうに潜む。\n\n彼女はただ静かに佇み、降り注ぐ問いのすべてを受け止め、沈黙をもって応じる。\n\nしかし、彼女が待ち続ける者だけは——いつか、自らの手で答えを記すことになる。"
  },
  Item_56637_Desc = {
    Text = "狂気増加の能力を持つ命輪。"
  },
  Item_56637_Name = {
    Text = "羊飼いの杖"
  },
  Item_56637_StoryDesc = {
    Text = "果てしない草原を、無数の羊たちがさまよっている。\nこの世界にはあまりにも多くの羊が存在し、羊は生まれながらにして導いてくれる羊飼いを必要としている。\n彼女は常にこの世界の預言者であり、手には知識の杖を握っていた。\n彼女はいつも良き羊飼いであり、羊の群れを正しい道へ導くことを決して怠らなかった。\n彼女はその杖で子羊を教え導き、その杖で狼を追い払う。\n彼女は羊飼いの杖を高く掲げ、常に先を見通していた。\nかつて、彼女は羊たちを豊かな水源や草原へ導いた。\nしかし今、世界の真実を目にした彼女は、羊たちを「終焉」という名の抱擁へと導く。\nこっちよ、振り返らないで。\n彼女は微笑みながら、叡智の杖を振るう。\nすると羊たちの目には、目の前の断崖が見えなくなる。\n一匹、また一匹。\n羊は落ちていき、羊飼いは喜び歌う。\nああ、この無私なる羊飼いに続け。彼女はあなたに、最も確かな道を示してくれたのだから。\n怖れることはない。たとえ死の陰の谷を歩こうとも、彼女の杖は常にあなたと共にある。\nともに、滅びの深淵へと歩み入るその時まで。"
  },
  Item_56638_Desc = {
    Text = "このキーオーダーを記録すると、編成時にキーオーダースキル「第四楽章」を選択可能。\n\n音符は星の海となって奔り、壮大なる深宇宙に、旋律が舞い踊る。\n\n目を閉じ、耳を澄ませ。\n宇宙の終幕を、その絶頂を聴け。"
  },
  Item_56638_Name = {
    Text = "第四楽章"
  },
  Item_56638_StoryDesc = {
    Text = "音符は星の海となって奔り、壮大なる深宇宙に、旋律が舞い踊る。\n\n目を閉じ、耳を澄ませ。\n宇宙の終幕を、その絶頂を聴け。"
  },
  Item_56639_Desc = {
    Text = "属性がクリティカル率の運命の札。"
  },
  Item_56639_Name = {
    Text = "永劫の演奏"
  },
  Item_56639_StoryDesc = {
    Text = "「まだ完璧ではない、今夜はあと十回練習しなさい。お前の才能は平凡だ。楽団に入りたければ、もっと努力することだ、わかったか？」\n「はい、父さん」\n\nどんな演奏が完璧と言えるのか？\n彼の手は止まることなく舞い、ひとつの失敗も許さない。\n彼は雑念を叱り、自身の平凡さを軽蔑した。\n無数の音符が目の前を巡り、毎日、毎日、彼の人生は音楽だけだった。\n\n幸い、彼は日に日に完璧な演奏へと近づいていった。夢の道の果てにある光を見つめながら。だがその光は、永遠に届かないもののようにも思えた。\n\n完璧への渇望は、すでに彼の魂に刻まれていた。だが、誰もがそう望むわけではなかった。\n\n「陛下のため、世のために最も完璧な音楽を奏でること。それが楽団の責務ではないのか？」\n彼は不満を滲ませるいくつもの顔を見渡した。まるで、かつての自分を軽蔑するように。\n\n父さん、宮廷楽団もこの程度か。\n\nかつて仰ぎ見た目標を捨て、彼は頑なに完璧を追い求める道を歩み続けた。\n立ち止まって彼らの手を取ることも、かつての自分を振り返ることもできなかった。\n\n毎日、毎日、彼は演奏し続けた。\n音楽こそが、彼の命だった。\n\n音楽以外、彼には何もなかった。"
  },
  Item_56640_Desc = {
    Text = "属性がブラックマークドロップの運命の札。"
  },
  Item_56640_Name = {
    Text = "運命のルーレット"
  },
  Item_56640_StoryDesc = {
    Text = "誰もが運命に打ち勝ちたいと思い、誰もが運命を恐れている。\n\n勇者は戦いの怒号を上げ、臆病者は従順の唸り声を発するが、彼だけが運命に勝つ秘密を見つけた。\nそれは運命を賭けに誘い続け、次のゲームを開くよう促すことだ。\n\n彼は運命を恐れたことがない、なぜなら自分が負けないと信じているからだ。\n彼は何を賭けるかを問わず、どんな賭け金でも躊躇なく差し出す、自分の命さえも。\n\nルーレットの銃を手に、彼は多くの賭け狂いの敗者を退け、ロンディニウムで悪名高い賭け狂いとなった。\n本当に残念だ、対等な相手がいないのはどれほど寂しいことか。\n\nそして、彼はその男に出会った。\n彼は無数の凡人を打ち負かし、ついに運命の賭けのテーブルに座った。\nすぐに彼はすべてを失い、すべてを取り戻した。\n\n獣として生まれ変わったとき、彼は地面に最後の弾丸を撃ち出した銃を見た。\n彼は弾丸を再装填し、自分の頭に再び引き金を引いた。\n無音の中で、彼は口を開いた。\n\n彼はまだ負けていない、だからいつか必ず勝つと信じている。\n彼は常にそう信じている、たとえすべてを賭けることになっても。"
  },
  Item_56641_Desc = {
    Text = "キーチャージの運命の札。"
  },
  Item_56641_Name = {
    Text = "氷河の眠り"
  },
  Item_56641_StoryDesc = {
    Text = "「その刻」を待つため、少女は氷河の底で眠りについた。\n\nアイズルワースの千フィートの厚い氷が彼女の肉体を凍結させたが、その意識を完全に閉じ込めることはできなかった。\n\nその意識は、一人の子供のものであり、また、一人の母親のものであった。\n\n娘の暗き胎内では、神が永遠の長い夢を見続けていた。\n\n25年の歳月の中で、彼女は何を考え、何を恋い慕い、何を期待したのだろうか？\n\n今となっては、これらの問いに答えられる者はいない。\n\nそして、その少女自身については……彼女は身近な人々に本心を打ち明けるのだろうか？\n\n今はすべてを委ねよう……これから訪れる時の流れと未来に。"
  },
  Item_56642_Desc = {
    Text = "属性がシルバーキー充電レベルに基づく命輪。"
  },
  Item_56642_Name = {
    Text = "真理の門"
  },
  Item_56642_StoryDesc = {
    Text = "彼女の名前は知恵の化身。\n彼女は世のすべての知識を知り、ミサゴのすべての学者が憧れる究極の存在。\n少しでも彼女の言葉を聞けば、悟りを得ることができる。\nしかし彼女は、自分はただの門番だと言う。\nそれはどんな門なのか？\n誰もその門を見たことがないため、学者たちはそれを真理と呼ぶ。\n彼女は真理の門番であり、ミサゴを守るアテナである。\nタヴィはその推測を否定せず、常にここを見守り、この世界を見つめている。\n無言で哀れみを持って。\nもしあなたがいつかその門を見たなら、門には非常に見覚えのある目があるだろう。\nその目は静かで永遠。\n時間を超え、あなたの魂を貫く。"
  },
  Item_56643_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「虚無の疫病」を選択可能。\n\n虚無は真実がもたらす疫病——\nそれはあらゆる色を消し去り、世界を灰色に染め上げる。\n\n狂気の瞳を直視してはならない。\n気をつけろ、それはすでにあなたを蝕んでいるかもしれない。"
  },
  Item_56643_Name = {
    Text = "虚無の疫病"
  },
  Item_56643_StoryDesc = {
    Text = "虚無は真実がもたらす疫病——\nそれはあらゆる色を消し去り、世界を灰色に染め上げる。\n\n狂気の瞳を直視してはならない。\n気をつけろ、それはすでにあなたを蝕んでいるかもしれない。"
  },
  Item_57171_Desc = {
    Text = "その霊識はいまだ深淵の中に沈眠している。\n深海を漂う胎児、「聖胎孵化する」での物資交換に使用する。\n\n最低{s1}個ドロップ"
  },
