  Item_61391_Desc = {
    Text = "属性がシルバーキー充電レベルに基づく命輪。"
  },
  Item_61391_Name = {
    Text = "純銀の初心"
  },
  Item_61391_StoryDesc = {
    Text = "それは銀白で、澄んでいて、汚れのない心だった。\n純銀でできており、機械の心臓の中で秩序正しく鼓動していた。\n血肉に侵食され、泥に染まったこともあった。\nしかし、死の陰が覆うとき、それはついに元の姿に戻った。"
  },
  Item_61941_Desc = {
    Text = "月光がそれに銀白を纏わせ、不屈のライフがここに誕生したことを祝う。\nアイズルワースの山頂から新生した花蕾、「復讐の戦意」での物資交換に使用する。\n\n最低{s1}個ドロップ"
  },
  Item_61941_Name = {
    Text = "銀霜の蕾"
  },
  Item_61942_Desc = {
    Text = "陽光がそれに橙黄を纏わせ、不屈のライフがここに誕生したことを祝う。\nアイズルワースの山頂から新生した花蕾、「再生の希望」での物資交換に使用する。\n\n最低{s1}個ドロップ"
  },
  Item_61942_Name = {
    Text = "日光の蕾"
  },
  Item_61943_Desc = {
    Text = "雪氷がそれに幽玄な青を纏わせ、不屈のライフがここに誕生したことを祝う。\nアイズルワースの山頂から新生した花蕾、「捕食の野望」での物資交換に使用する。\n\n最低{s1}個ドロップ"
