  },
  Item_66386_Desc = {
    Text = "あなたたちはお互いを信頼します。\n守秘者と覚醒体の精神同調度。より多くの覚醒体のストーリーを解放できます。"
  },
  Item_66386_Name = {Text = "同調率"},
  Item_66763_Desc = {
    Text = "針は休むことなく回り続け、帰らぬ者たちと共に前へ進む。\n終焉に至る刻、すべての扉がお前のために開かれ、すべての楽章がお前のために奏でられる。\n極みの門の前に佇む精密な針、「残響」での物資交換に使用する。\n\n最低{s1}個ドロップ"
  },
  Item_66763_Name = {
    Text = "終末の指針"
  },
  Item_66764_Desc = {
    Text = "針は休むことなく回り続け、帰らぬ者たちと共に前へ進む。\n終焉に至る刻、すべての扉がお前のために開かれ、すべての楽章がお前のために奏でられる。\n極みの門の前に佇む精密な針、「残響」での物資交換に使用する。\n\n最低{s1}個ドロップ"
  },
