    Text = "カオスの夢言葉"
  },
  Item_67086_Desc = {
    Text = "数え切れない世界で漂う聴き取れない夢囁き、感知した瞬間に元初の誕生が心を占める。"
  },
  Item_67086_Name = {
    Text = "原初の夢囁き"
  },
  Item_67087_Desc = {
    Text = "万千の世界で舞い散る、聴き取れない夢囁き、それを感知した瞬間に完全な盲目が心を占める。"
  },
  Item_67087_Name = {
    Text = "痴愚夢囁き"
  },
  Item_67377_Desc = {
    Text = "守秘者にとって、身分証やシルバーコア通信での感情表現は精神力と同じくらい重要――無形者曰く。\n一定数集めて使用すると、専用のアイコンやスタンプ、過去の課題記録や位相対局シーズンのアイコン、スタンプをランダムで入手可能。"
  },
  Item_67377_Name = {
    Text = "無形者のギフト券"
  },
  Item_67378_Desc = {
    Text = "狡猾で変幻自在。あなたは無形者に自らの価値を証明した。まもなく、彼の者はあなたを招待するだろう。それは、万物の化身となり、影も形も持たぬ究極の存在へと至るための招待である。\n一定数集めて使用すると、「無形者のギフト券」の未取得アイコンやスタンプを選択可能。"
  },
  Item_67378_Name = {
    Text = "無形者の招待状"
  },
  Item_68281_Desc = {
    Text = "後方支援部は調査を完了した守秘者に特別許可を発行した。調査完了後、次の出発に向け、貴重なシルバーコア製品を購入可能。\n数量限定、銀の鍵の導きがあらんことを。"
  },
  Item_68281_Name = {
    Text = "調査特典Ⅸ\nギフト"
  },
  Item_68341_Desc = {
    Text = "購入後、すべての予約特典を受け取れます"
  },
  Item_68341_Name = {
    Text = "星辰を超えて・期間限定予約"
  },
  Item_68419_Desc = {
    Text = "長い時を経て、この哀しみはやがて癒される。\n神王の感情が知覚の次元に残した印。「哀愁の海底」で物資と交換可能。"
  },
  Item_68419_Name = {
    Text = "哀愁の思念"
  },
  Item_68420_Desc = {
    Text = "祝う必要はない、喜びもまた虚無である。\n神王の感情が次元に残した印で、「歓喜の海底」で物資と交換可能。"
  },
  Item_68420_Name = {
    Text = "歓喜の思念"
  },
  Item_68421_Desc = {
    Text = "疲れに襲われ、彼は再び永劫の眠りに落ちる。\n神王の感情が知覚の次元に残した印。「疲弊の海底」で物資と交換可能。"
  },
  Item_68421_Name = {
    Text = "疲弊の思念"
  },
  Item_68682_Desc = {
    Text = "狂気増加の能力を持つ命輪。"
  },
  Item_68682_Name = {
    Text = "青石の玉座"
  },
  Item_68682_StoryDesc = {
    Text = "無限の深淵に、青い玉座がそびえ立ち、天幕が低く垂れ、星々が震え、万物が沈黙する。\n\n古く神秘的な存在はすでに消え去り、世代を超えて、生き物たちは夢の中で賛美歌を歌う。\n\n暗い水域、封じられた秘密。\nあなたの囁きは波のように押し寄せ、心の溝を埋め尽くす。\n\nその無辺の夢境で、先知と狂人が共に遊び、無形の魂を追い求め、恐怖と畏敬が交錯する。\n\n青藻が纏う軌跡は、運命の編纂のように、迷える者の心を徐々に青い玉座へと導く。\n\nああ、宇宙の不条理と真理、夢と現実が交錯する場所で、永遠の輝きが閃く。"
  },
  Item_68683_Desc = {
    Text = "属性がダメージ強化の運命の札。"
  },
  Item_68683_Name = {
    Text = "魔女のつば広帽子"
  },
  Item_68683_StoryDesc = {
    Text = "魔女とつば広帽子の因果関係は時に鶏と卵の関係のようで、帽子が魔女を成したのか、魔女が帽子を成したのか分からない。\n\nともあれダフォダイルはそんな優雅なつば広帽子を所持する。\n\nこの帽子は元々、かつての店主のもので、その頃ダフォダイルの名はまだダフォダイルではなく彼女は支配されたばかりの迷える幽霊、無垢な野獣だった。\n\nいつも微笑んでいたあの女性はまるで子どもを育てるように、彼女に「人になる方法」と「人と接する秘訣」を、少しずつ教えてくれた。\n\n港町は商業が繁栄し、当時の人類文化の結晶が集まっていた。商店のある通りにはさまざまな店が立ち並び、店主は不思議とどの店の主人とも旧友のように話せた。\n\n「本当にすごい人」\n当時のダフォダイルは思った。\n「でも不思議じゃない。誰だってあの人を好きになる」\n\n店主は街歩きが好きだった。だからこそ、千年もの間、人間の首を刈る役割を担ってきたダフォダイルが、初めて「自分の意見」を求められたのだった。\n\n「どっちがいいと思う？\nこの小さな帽子、それともこのつば広帽子？」\n\n女性は鏡の前で、さまざまな帽子を試しながら言った。\nダフォダイルにとって帽子とは体を包み、ただ人間らしく見せるための道具にすぎなかった。\n\nしかしその日、店主の頭にある大きな花のようなつば広帽子を見て、ふと、自分とその帽子をかぶった店主が海辺を散歩する姿が頭に浮かんだ。\n\n「これがいい」\n彼女は突然言った。\n\n「この帽子がいい」\n\n店主は少し驚いて振り返った。\n彼女がこれほどはっきりと好みを示すとは思わなかったようだった。\n\n「いいわね確かに素敵な帽子。あなたが選んでくれたから、大切にするわ」\n\nダフォダイルを励ますためか、この帽子は店主の言葉通り、彼女の頭に常に飾られ続けた。\n\n最期の彼女の手から滑り落ちる時、微笑む彼女の首と共にダフォダイルに手渡された。\n\n「本当に素敵な帽子。\nちゃんと大切にするわ」\n艶やかに咲き誇る紫黒の花は、新しい主人の頭に咲き誇った。"
  },
  Item_68688_Desc = {
    Text = "属性がシルバーキー充電レベルに基づく命輪。"
  },
  Item_68688_Name = {
    Text = "真貌・トゥルーSR（仮テキスト）"
  },
  Item_68688_StoryDesc = {
    Text = "真貌・トゥルーSR(仮テキスト)"
  },
  Item_68689_Desc = {
    Text = "属性がシルバーキー充電レベルに基づく命輪。"
  },
  Item_68689_Name = {
    Text = "催眠ペンデュラム"
  },
  Item_68689_StoryDesc = {
    Text = "新生を得たクレメンタインは、まるで無知な幼虫のように、人間界を歩き回り、自分の種族に属さない繁栄した世界をさまよい、困惑していた。\nその時、啓示のような声が響いた——\n「すみません、あなたはシャーロット医師ですか？私はシャーロット医師に心理相談をお願いしたくて……」\nクレメンタインはようやく我に返った。彼女はシャーロットが誰か気にしなかったが、来訪者の口から出た新しい言葉「心理相談」に興味を持った。\nしかし彼女は成熟したハンターで、自分の無知を露呈することは決してなかったので、彼女は笑った。まるで彼女がシャーロットであり、来訪者の口にする救いであるかのように。\n涙、苦痛、無力感、何も誘わずとも、来訪者は魂の奥底の苦しみを絞り出した。\n去る前に、相手は軽やかな顔でクレメンタインを見て、感慨深く言った。「聞いてくれてありがとう。気分がとても良くなった」\nそして、ドアが閉まる音と、クレメンタインが初めて甘美を味わったことによる笑い声が響いた。\nその笑い声は最初は微かで、幼虫の羽音のようだったが、次第に大きくなり、成虫の叫びのようになった。\nその笑い声の中で、クレメンタインという名の虫族も急速に成熟した。\nその後のすべては、当然の成り行きだった。彼女は精神科医師となり、笑顔と振り子を持って、患者の心の奥深くに入り込んだ。\n彼女は依然として人間界を歩き回り、この繁栄した世界に属していないが、もはや迷うことも困惑することもなかった。\nなぜなら、すべての人間界と世界が、彼女の催眠の狩場だからだ。"
  },
