  },
  Item_68854_StoryDesc = {
    Text = "第13期対人戦"
  },
  Item_68855_Desc = {
    Text = "「なるほど、あなたの言うことは理にかなってますね、よく考えてみます」"
  },
  Item_68855_EmojiName = {Text = "確かに"},
  Item_68855_Name = {
    Text = "オルラ・確かに"
  },
  Item_68855_StoryDesc = {
    Text = "第13期課題記録"
  },
  Item_68856_Desc = {
    Text = "「わあ、ご主人すごい！」"
  },
  Item_68856_EmojiName = {Text = "崇拝"},
  Item_68856_Name = {
