  },
  Item_68856_StoryDesc = {
    Text = "第13期対人戦"
  },
  Item_68857_Desc = {
    Text = "「さよならママ、今夜は航海に出るわ！」"
  },
  Item_68857_EmojiName = {Text = "漂流"},
  Item_68857_Name = {
    Text = "マーフィー・漂流"
  },
  Item_68857_StoryDesc = {
    Text = "第13期課題記録"
  },
  Item_68858_Desc = {
    Text = "「主君、一緒に乗馬に行きませんか？」"
  },
  Item_68858_EmojiName = {Text = "嬉しい"},
  Item_68858_Name = {
    Text = "オジール・嬉しい"
  },
  Item_68858_StoryDesc = {
    Text = "第12期対人戦"
  },
  Item_68859_Desc = {
    Text = "「ご来訪に感謝いたします」"
  },
  Item_68859_EmojiName = {
    Text = "フィナーレ"
  },
  Item_68859_Name = {
    Text = "ソレール・フィナーレ"
  },
  Item_68859_StoryDesc = {
    Text = "第12期課題記録"
  },
  Item_69844_Desc = {
    Text = "高位の人物の葬儀で演奏されるレクイエムで、亡くなったソウルを慰め、永遠の安らぎを得るよう祈ります。\n「ローズブックと」期間中限定提供。"
  },
  Item_69844_Name = {
    Text = "安魂の祝福ミサ"
  },
  Item_69845_Desc = {
    Text = "ある高位の人物の葬儀で演奏されたミサ曲、彼女の栄光と追憶は永遠に残る。\n「ローズブックと」期間中限定提供。"
  },
  Item_69845_Name = {
    Text = "栄光の賛美ミサ"
  },
  Item_69846_Desc = {
    Text = "高位にある者の葬儀で演奏されるミサ曲は、生者が死者に対する悲しみと追憶を表現するとともに、死が終わりではなく、永遠の生命への開始であるとの確信を表しています。\n「ローズブックと」期間中限定提供。"
  },
  Item_69846_Name = {
    Text = "追悼の聖祭ミサ"
  },
  Item_69851_Desc = {
    Text = "エルヴォース山の頂上で新たに芽生えたタンポポの種、凍土から育つ小さな野草は生き生きとした生命力を発散している。\n「雪山が解ける時・復刻」期間中、期間限定で提供。"
  },
  Item_69851_Name = {
    Text = "雪山蒲公英の種子"
  },
  Item_69852_Desc = {
    Text = "エルヴォース山の頂上で新たに芽生えた常緑樹の種、たくましい苗木は風や霜や雨を乗り越えて、そびえ立つ巨木になるだろう。\n「雪山が解ける時・復刻」期間中、期間限定で提供。"
  },
  Item_69852_Name = {
    Text = "雪山常緑樹の種子"
  },
  Item_69853_Desc = {
    Text = "エルヴォース山の頂上で新たに芽生えた潔白の花の種、氷と雪がその枝葉を作り、厳寒もその芳香を萎えさせることはない。\n「雪山が解ける時・復刻」期間中、期間限定で提供。"
  },
  Item_69853_Name = {
    Text = "雪山銀霜花の種子"
  },
  Item_69854_Desc = {
    Text = "詩を詠むことで開く神秘な箱。\nそれに花の夢を語れば、あなたに薔薇の花束を贈ってくれる。\n「春が散る前に」期間限定で提供。"
  },
  Item_69854_Name = {
    Text = "花と詩の夢"
  },
  Item_69855_Desc = {
    Text = "詩を詠むことで開く神秘な箱。\nそれに意象を伝えれば、あなたに真実を見せてくれる。\n「春が散る前に」期間限定で提供。"
  },
  Item_69855_Name = {
    Text = "意と詩の夢"
  },
  Item_69856_Desc = {
    Text = "詩を詠むことで開く神秘な箱。\nそれに過去を語れば、あなたに一片の記憶を贈ってくれる。\n「春が散る前に」期間限定で提供。"
  },
  Item_69856_Name = {
    Text = "心と詩の夢"
  },
  Item_69860_Desc = {
    Text = "人形には存在しないはずなのに、自ら回転する歯車のセットは、近づくと囁きのような微細な摩擦音を発します。"
  },
  Item_69860_Name = {
    Text = "ダブルスパイラル人形パーツ"
  },
  Item_69861_Desc = {
    Text = "憂いを解く小さな店で売られているギフトボックスは、百貨店の最新商品よりも洗練されており、貴重な代償で交換する必要があります。\n「雨の町の幽影」期間中に限定供給されます。"
  },
  Item_69861_Name = {
    Text = "百貨店の魔女のギフトボックス"
  },
  Item_69862_Desc = {
    Text = "解憂の小さな店で売られているギフトボックスには、世界中から集められた珍しい品々が入っています。新鮮で完全な頭蓋と交換する必要があります。\n「雨の町の幽影」期間中限定で提供されます。"
  },
  Item_69862_Name = {
    Text = "奇物魔女のギフトボックス"
  },
  Item_69863_Desc = {
    Text = "解憂の小さな店で売られているギフトボックスは、店主のプライベート倉庫から取り出された秘密のコレクションで、聞いたことのない不思議な品々が詰まっています。収集に値する美しい頭蓋と交換する必要があります。\n「雨の町の幽影」期間中限定で提供されます。"
  },
  Item_69863_Name = {
    Text = "秘蔵の魔女ギフトボックス"
  },
  Item_69867_Desc = {
    Text = "あるレディからのお茶会への招待状、美味しいお菓子を召し上がりください。人形やテディベアと一緒に踊りましょう。\n「群星正位」期間限定で提供されます。"
  },
  Item_69867_Name = {
    Text = "レディの招待状ギフト"
  },
  Item_69868_Desc = {
    Text = "あるレディと同じデザインのドレスで、着用することでレディのような優雅で高貴な雰囲気を得られます。\n「群星正位」期間中に限定供給されます。"
  },
  Item_69868_Name = {
    Text = "レディのドレス贈り物"
  },
  Item_69869_Desc = {
    Text = "あるレディと同じデザインの日傘。開くと、レディが決して頭を下げることがない自信を得られる。\n「群星正位」期間中のみ限定供給。"
  },
  Item_69869_Name = {
    Text = "レディ日傘の贈り物"
  },
  Item_69870_Desc = {
    Text = "著名な商業航路が描かれた海図が1枚あり、商人が出入りするのに役立つ。\n「暴風雨の中で揺れる」期間中に期間限定で提供される。"
  },
  Item_69870_Name = {
    Text = "金色の航路の指針"
  },
  Item_69871_Desc = {
    Text = "クレメンタインの精神療法所の特製処方は、長期的な再発を抑制することができる心の障害に作用します。「記憶の奥に埋もれている」期間の限定提供です。"
  },
  Item_69871_Name = {
    Text = "不定性狂気処方"
  },
  Item_69872_Desc = {
    Text = "クレメンタイン心の診療所の特製薬方は、永遠に狂気の深淵に囚われた者を救うことができます。「記憶の底に埋もれる」期間限定で提供されます。"
  },
  Item_69872_Name = {
    Text = "永久的な狂気の処方"
  },
  Item_69873_Desc = {
    Text = "クレメンタイン心の診療所の特製薬方は、一時的な精神的な傷を癒すことができます。「記憶の底に埋もれる」期間限定で提供されます。"
  },
  Item_69873_Name = {
    Text = "一時的な狂気の処方"
  },
  Item_69874_Desc = {
    Text = "深海の氾濫する潮流が意識の境界にインパクトを与える。\n異夢の侵食に抵抗するための儀式は、「沈淵の祀り」期間中に限定供給される。"
  },
  Item_69874_Name = {
    Text = "潮食防衛密儀"
  },
  Item_69875_Desc = {
    Text = "その最深最暗の場所で沈眠する王の誕生は、神識の海全体をねじれさせる。\n異夢の侵食に抵抗するための儀式は、「沈淵の祀り」期間中に限り供給される。"
  },
  Item_69875_Name = {
    Text = "神王誕生の秘儀"
  },
  Item_69876_Desc = {
    Text = "異夢視界中の天災も、精神共鳴を通じて守秘者のれいちに影響を与える。\n異夢の侵食に抵抗するための儀式は、「沈淵の祀り」期間中に限定供給される。"
  },
  Item_69876_Name = {
    Text = "天災警戒の秘儀"
  },
  Item_69877_Desc = {
    Text = "秘匿された航路が描かれた海図が1枚あり、航路に沿って小島で休憩することができる。\n「暴風雨の中で揺れる」期間中に期間限定で提供される。"
  },
  Item_69877_Name = {
    Text = "蒼海の避難所"
  },
  Item_69885_Desc = {
    Text = "精緻で細密な人形の部品が、テクノロジーと狂気の光を放っている。"
  },
  Item_69885_Name = {
    Text = "精製された人形パーツ"
  },
  Item_69889_Desc = {
    Text = "呪文で封印された青銅の箱には、捧げられた物資が収められている。すでに基礎的な除霊儀式を施されており、開封者に危険は及ぼさない。\nあそこは貧しすぎて、最高級の供物ですらこの程度か。――ケティグーラ"
  },
  Item_69889_Name = {
    Text = "青銅の「プレゼント」"
  },
  Item_69890_Desc = {
    Text = "深淵の気配を放つ巨大な箱で、深紅の霧が渦巻いている。内部には大量の物資が詰め込まれているが、開封する際は必ず専門家に協力を依頼してください。\nそんなに緊張しなくて大丈夫、私は上の危険を取り除いておいた。ただこの視覚効果を保留しているので、どこから来たのかがわかる。――ケティグラ"
  },
  Item_69890_Name = {
    Text = "スカーレット深淵の「プレゼント」"
  },
  Item_69891_Desc = {
    Text = "金色の輝きを放つ容器で、液体のゴールドが容器の縁を絶え間なく流れているのが見え、高価な供物が収められている。\n正直に言うと、この箱は中の物よりも価値があると思うが、物があなたに与える助けは限られているでしょう？――ケティグラ"
  },
  Item_69891_Name = {
    Text = "黄金の流れの「プレゼント」"
  },
  Item_69892_Desc = {
    Text = "永遠に父神、『幾何原本』、そしてドクターの処方を疑問にしてはならない。\n守秘者の心身の健康を保証する良方で、「多重ヒーリング」期間中に限定供給されます。"
  },
  Item_69892_Name = {
    Text = "解離リハビリテーションプログラム"
  },
  Item_69893_Desc = {
    Text = "一つの治療が効果がない場合は、もう一つの治療を試してみてください！\n守秘者の心身の健康を保証するための良方で、「多重ヒーリング」期間中に限定供給されます。"
  },
  Item_69893_Name = {
    Text = "解離強化治療"
  },
  Item_69894_Desc = {
    Text = "不小心人格分裂した場合どうすればいい？心配しないで、ミサグはすでに準備ができています！\n守秘者の心身の健康を保証するための方法で、「多重ヒーリング」期間中に限定供給されます。"
  },
  Item_69894_Name = {
    Text = "解離急性治療"
  },
  Item_69895_Desc = {
    Text = "古代の航路が描かれた海図が1枚あり、そこには伝説の秘宝が隠されていると言われている。\n「暴風雨の中で揺れる」期間中に期間限定で提供される。"
  },
  Item_69895_Name = {
    Text = "深海に隠された秘宝"
  },
  Item_69896_Desc = {
    Text = "葬骸城王邸の宴会料理、食屍鬼の王が特製した主菜は、すべての食客の夢の求めです。\n「死霊の美学」期間中の限定供給。"
  },
  Item_69896_Name = {
    Text = "祭りの主菜"
  },
  Item_69897_Desc = {
    Text = "葬骸城王邸の宴会料理、すべてのスープは厳選された食材で煮込まれています。\n「死霊の美学」期間中の限定供給。"
  },
  Item_69897_Name = {
    Text = "祭魂祭のスープ"
  },
  Item_69898_Desc = {
    Text = "葬骸城王邸の宴会料理、前菜でさえも心を込めた作品です。\n「死霊の美学」期間中の限定供給。"
  },
  Item_69898_Name = {
    Text = "祭霊節前菜"
  },
  Item_69899_Desc = {
    Text = "ストーリーの始まり、魔法のシルバーコアフィルムが忽然と消えた。これは女の子とマスターのミステリーストーリーだ。\n「ストーリーの魔法」期間中に限定提供。"
  },
  Item_69899_Name = {
    Text = "ミステリーストーリーフィルム"
  },
  Item_69900_Desc = {
    Text = "ストーリーのインターミッション、滑稽なアマチュア俳優が輝いて登場。これは女の子と怪盗のコメディーストーリーです。\n「ストーリーの魔法」期間中、限定で提供されます。"
  },
  Item_69900_Name = {
    Text = "コメディーストーリーフィルム"
  },
  Item_69901_Desc = {
    Text = "物語の結末、仲間の夕日のシルエットがアルバムに収められ、これは女の子とクジラのファンタジー物語です。\n「物語の魔法」期間中限定提供。"
  },
  Item_69901_Name = {
    Text = "ファンタジー物語フィルム"
  },
  Item_69902_Desc = {
    Text = "なぜ人形の部品が腐食して欠けたのかわからない。錆びた金属の傷から黒い膿血が流れ出ている。"
  },
  Item_69902_Name = {
    Text = "錆びた人形パーツ"
  },
  Item_69985_Desc = {
    Text = "極限の扉が開き、原初に近づく力をもたらす——誰もが恐れ、誰もが憧れる。\nミサゴ地下の昏き海で生まれた神秘の霊核、扉の力で精錬され、原初の本質に近づき、覚醒体を想像を超える高みへと導く。"
  },
  Item_69985_Name = {
    Text = "純粋な原初の霊核"
  },
  Item_69986_Desc = {
    Text = "昏き海に散らばる欠片、極限の扉の光を浴び、原初の力が訪れる瞬間を待つ。\nミサゴ地下で生まれた神秘の欠片、扉の力で精錬され、純粋な原初の霊核を合成できる。"
  },
  Item_69986_Name = {
    Text = "純粋な霊核の欠片"
  },
  Item_70143_Desc = {
    Text = "「欲望の蔓延」での交換に使用する道具。\n\n小さな、丸い種。\nやがて芽吹き、根を張り、天を覆う鬱蒼とした大樹へと成長する。\n\n最低{s1}個ドロップ"
  },
  Item_70143_Name = {
    Text = "豊穣の種核"
  },
