  },
  Item_70292_Desc = {
    Text = "「星辰を超えて・期間限定予約」で入手可能。\n「星辰が正位置に達した刻、偉大なる@1が降臨する」"
  },
  Item_70292_Name = {
    Text = "星辰正しき刻"
  },
  Item_70292_StoryDesc = {
    Text = "V2.0バージョン期間限定予約"
  },
  Item_70919_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「星々の加護」を選択可能。\n\n彼はその王冠を選び——\n王冠もまた、彼を選んだ。\n\n新たな王と、古の神の魂が瞬時に共鳴し、その背後には天地を覆う虚影が現れる。\n\nそして、それは国家に永遠なる安寧をもたらした。"
  },
  Item_70919_Name = {
    Text = "星々の加護"
  },
  Item_70919_StoryDesc = {
    Text = "彼はその王冠を選び——\n王冠もまた、彼を選んだ。\n\n新たな王と、古の神の魂が瞬時に共鳴し、その背後には天地を覆う虚影が現れる。\n\nそして、それは国家に永遠なる安寧をもたらした。"
  },
  Item_71281_Desc = {
    Text = "苦しみの魂よ、決して希望を失ってはなりません。仁愛深き主教会が、あなたのために父なる神に祈りを捧げます。\n「ソウルの牧人・復刻」期間中、限定で供給されます。"
  },
  Item_71281_Name = {
    Text = "ミサの祈り"
  },
  Item_71282_Desc = {
    Text = "苦悩の魂よ、汝は報われるだろう。仁愛に満ちた司教が父なる神の名において汝に祝福を下す。\n「魂の牧人・復刻」期間中に限定提供。"
  },
  Item_71282_Name = {
    Text = "ミサ後の祝福"
  },
  Item_71283_Desc = {
    Text = "苦しみの魂よ、迷いは必要ない、慈愛の主教会が汝の道を照らしてくれるだろう。\n「魂の牧人・リメイク」期間中、限定供給される。"
  },
  Item_71283_Name = {
    Text = "ミサ前のガイド"
  },
  Item_71393_Desc = {
    Text = "時代の最先端技術を象徴する精密歯車。人形の老朽化した部分を代謝させることができる。\nドールが躯体の修理に使用する歯車部品。ショップでの物資交換に使用する。\n\n最低{s1}個ドロップ"
  },
