  Item_71446_Name = {
    Text = "人形パーツ"
  },
  Item_72089_Desc = {
    Text = "「どんぐりは冒険の始まりを象徴する、もっと多くのどんぐりが必要だ！」――イグナティス。イグナティスの魔力で凝結されたどんぐりで、「回合奇賞」で物資を交換するために使用される。"
  },
  Item_72089_Name = {
    Text = "魔法のどんぐり"
  },
  Item_72089_StoryDesc = {
    Text = "逆転回合連動"
  },
  Item_72095_Desc = {
    Text = "このキーオーダーを記録すると、「相位対局」編成時に、キーオーダースキル「酒場の扉」を選択可能。\n\nひとつの世界が幕を閉じる時、次なる世界の序章は始まっている。物語は美酒とともに語り継がれるだろう。しかし、万物の答えを記すのは、常に、時の流れなのだ。"
  },
  Item_72095_Name = {
    Text = "酒場の扉"
  },
  Item_72095_StoryDesc = {
    Text = "ひとつの世界が幕を閉じる時、次なる世界の序章は始まっている。\n\n物語は美酒とともに語り継がれ、人々の声の中で響き渡るだろう。\n\nしかし、万物の答えを記すのは、常に、時の流れなのだ。"
  },
  Item_72824_Desc = {
    Text = "ヘプランデ大陸にある小さな酒場には、異なる世界を接続するポータルがあります。\n酒場の主人イグナティスは万象牌というカードゲームを創造し、かつての英雄たちの物語を伝えています。"
  },
  Item_72824_Name = {
    Text = "逆転回合：万象牌"
  },
  Item_72824_StoryDesc = {
    Text = "逆転回合連動"
  },
  Item_72834_Desc = {
    Text = "「無形者のギフト券」で入手可能。\n「おっと、新しく作ったスパイダー薬茶を飲みたい人はいる？」"
  },
  Item_72834_Name = {
    Text = "銀の鍵の名のもとに：シルヴィア"
  },
  Item_72834_StoryDesc = {
    Text = "外観コレクション券専用"
  },
  Item_72835_Desc = {
    Text = "イベント「織る者、自ら縛る」で実績を達成すると獲得。\n「あらあら、私の織物を邪魔しないでね。これより大事なことなんてないんだから…………」"
  },
  Item_72835_Name = {
    Text = "銀の鍵の名のもとに：アラクネ"
  },
  Item_72835_StoryDesc = {
    Text = "アラクネの遊興イベント"
  },
  Item_72836_Desc = {
    Text = "「あなたの演奏……確かに……頑張ってますね」"
  },
  Item_72836_EmojiName = {Text = "困惑"},
  Item_72836_Name = {
    Text = "ハムリン・困惑"
  },
  Item_72836_StoryDesc = {
    Text = "第18期相位対弈"
  },
  Item_72837_Desc = {
    Text = "イベント「キャンバスのダークサイド」で達成を完了して獲得。\n「肉眼で見える景色しか描けないのなら、凡人と何が違うのか？」"
  },
  Item_72837_Name = {
    Text = "銀の鍵の名のもとに：ピックマン"
  },
  Item_72837_StoryDesc = {
    Text = "ピックマンの遊興イベント"
  },
  Item_72838_Desc = {
    Text = "「逃げないで、本当に美味しいから、ちょっと試してみて！」"
  },
  Item_72838_EmojiName = {
    Text = "お茶を飲む"
  },
  Item_72838_Name = {
    Text = "シルヴィア・お茶を飲む"
  },
  Item_72838_StoryDesc = {
    Text = "外観コレクション券専用"
  },
  Item_72839_Desc = {
    Text = "「おやすみ、アイギスは明日も良い子になるよ」"
  },
  Item_72839_EmojiName = {
    Text = "おやすみ"
  },
  Item_72839_Name = {
    Text = "アイギス・おやすみ"
  },
  Item_72839_StoryDesc = {
    Text = "第23期学期課題"
  },
  Item_72840_Desc = {
    Text = "「ありがとう、ご主人！」"
  },
  Item_72840_EmojiName = {
    Text = "ありがとう"
  },
  Item_72840_Name = {
    Text = "リリー・ありがとう"
  },
  Item_72840_StoryDesc = {
    Text = "第22期課題記録"
