    Text = "長い間放置されて枯れ果てた花束。\nその主人を永遠に待っている。"
  },
  Item_74093_Desc = {
    Text = "遥かな星々が瞬くときに残した壊れた夢。その中の霊性を感じることができれば、肉眼では観測できない未来を覗くことができる。"
  },
  Item_74093_Name = {
    Text = "割れた残夢"
  },
  Item_74143_Desc = {
    Text = "遥かなる星々が輝く時に残した完全な夢。古代の霊性が、運命の未来を示す——星辰の正位置に着く。"
  },
  Item_74143_Name = {
    Text = "星々の残夢"
  },
  Item_74200_Desc = {
    Text = "灰燼の霧都に逸散した感情粒子。触れると誰かの絶望に満ちた咆哮が聞こえるような気がする。\nシークレットキーパーが調査イベント「霧都への帰還」における共鳴を高めるために使用する。"
  },
  Item_74200_Name = {
    Text = "絶滅の心"
  },
  Item_75778_Desc = {
    Text = "干からびて白い野獣の頭蓋骨。時折、歯ぎしりのようなカタカタという音を発するが、おそらく気のせいだろう。\nあの店主の気に入りそうな品だ。\n\n最低{s1}個ドロップ"
  },
  Item_75778_Name = {
    Text = "蒼白の獣の頭蓋骨"
  },
  Item_75779_Desc = {
