  },
  Item_76216_Name = {
    Text = "異世界紀行"
  },
  Item_76294_Desc = {
    Text = "後方支援部は調査を完了した守秘者に特別許可を発行した。調査完了後、次の出発に向け、貴重なシルバーコア製品を購入可能。\n数量限定、銀の鍵の導きがあらんことを。"
  },
  Item_76294_Name = {
    Text = "調査歴程特典・星辰篇Ⅰ"
  },
  Item_77858_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nファラオを再度獲得した際に変換され、ファラオの霊知啓発を起動するために使用。"
  },
  Item_77858_Name = {
    Text = "欠片・ファラオ"
  },
  Item_77858_StoryDesc = {
    Text = "ファラオを再度獲得した際に変換され、ファラオの霊知啓発を起動するために使用。"
  },
  Item_77859_Desc = {
    Text = "通常時は安定してシールド獲得し、超次元ターンでは狂気を爆発的に獲得する命輪。「湮滅」使用後、チームのクリティカルダメージを増加させる。"
  },
  Item_77859_Name = {
    Text = "耐え難き自由"
  },
  Item_77859_StoryDesc = {
    Text = "今日に至るまで、カストルは「自由」の真の意味を言葉にできずにいる。\n\n彼は常々、双子の中でも自分の方が愚鈍だと感じていた。\n幼い頃から、ポリュクスの後ろを黙ってついていき、弟が語る自由奔放で奇想天外な考えに耳を傾けてきた。\n\n退屈で、感覚が麻痺するような修行生活の中で、彼はそのわずかな安らぎこそが何よりの幸福だと思っていた——ジュリエットがポリュクスに、定期的な「改造儀式」を命じるまでは。\n\n終わりのない苦痛が、ポリュクスひとりに降り注いだ。\nカストルはただ弟の傍らに寄り添い、あれほど明るかった横顔から笑みが次第に消えていくのを、見つめることしかできなかった。\n自分にできることは、何ひとつ思いつかなかった。\n\n「自由って、どういう意味か知ってる？」\n\n深夜、ポリュクスは二人で読み古した写本を抱え、静かにカストルに尋ねた。\nカストルは首を横に振った。\n\n「じゃあ、外の世界を見たいと思ったことはある？兄さん」\n\nカストルは呆然として立ち尽くした。ポリュクスが追い求めようとしているものを、ようやく理解したのだ。\nそれはこれまで一度も目にしたことのない、乾いた文字の中だけの、自分の想像をはるかに超えた世界だった。\n\nその衝撃的な考えに強く心を揺さぶられ、カストルは言葉を失った。\n長い時間が流れたのかもしれないし、ほんの数瞬だったかもしれない。やがて彼は、恐れることなく頷いた。\n\nたとえそれが、教会すべてを敵に回すことになろうとも。たとえ、自らの命を捧げることになろうとも。\n\nこうして二羽の鳥は、一度も出たことのない檻から飛び立った。しかし彼らは、思いもよらなかったのだ。自由の代償が、これほどまでに耐え難く、重いものであることを。\n\n狩人の銃声が響き渡り、鳥たちは空から堕ちていった。\n\nカストルはようやく自由の味を知ったばかりで、自由へ向かう弟の翼が無残にも引き抜かれるのを目の当たりにした。\nジュリエットの恐ろしい怒りを前にして、顔を青ざめさせ、震えながらも、弟は群衆に背を向け、決して屈することのない笑みをカストルに向けた。\n\n「耐え抜こう、自由のために」\n\nカストルはポリュクスの唇の動きを何度も思い返した。\n苦痛で朦朧とする意識の中で、信仰にも似たその二つの言葉を噛みしめ、心に焼き付くまで刻み込んだ。\n\nだが、彼はようやくポリュクスと再会し、愕然とした。\nいつも自分を導いてくれたその人は、あろうことか、その二つの言葉を無情にも捨て去っていたのだ。"
  },
  Item_77862_Name = {
    Text = "シャタク鳥"
  },
