  },
  Item_77875_Name = {
    Text = "カストル"
  },
  Item_77876_Name = {
    Text = "クレメンタイン"
  },
  Item_77877_Desc = {
    Text = "狂気と力の獲得量が増加し、他の覚醒体が次に発動する「狂気解放」の効果も強化する命輪。血肉界域の覚醒体が「狂気解放」を発動すると、大きく狂気を回復する。"
  },
  Item_77877_Name = {
    Text = "写実主義の逆説"
  },
  Item_77877_StoryDesc = {
    Text = "彼は、教会の尖塔が蝋燭のように溶け、神父の白い翼の上に滴り落ちるのを見た。\nステンドグラスの聖人像は、凄まじい速さで腐敗して骸骨となり、そして瞬時に逆戻りして赤子へと変わる。鋭利な、あるいは柔らかな幾何学体が、信徒たちの口から詠唱され、聖堂を埋め尽くしていく。\n\n彼は、駅の空間が幾重にも折り畳まれ、非ユークリッド幾何学的な空間へと変貌する様を見た。\n遠くのホームは目の前にあり、近くの改札口ははるか彼方にある。ホールの時計は反時計回りに回転し、骸のような人々の群れは、見えない糸に操られるかのように後ろ向きに歩いていく。濃い菫色の煙が雲間から現れ、列車の煙突へと吸い込まれていった。\n\n彼は、森の中の「空」が凝縮して実体を持つのを見た。\n樹木も岩も蔓も、ただ「空」が描き出す輪郭によって区切られた、半透明の境界線に過ぎなかった。白鳥の羽は絶えず変化するモザイクの塊で、それらが泳ぎ去った跡には、湖水が半透明の彩色ガラスへと凝固する。寄り添う恋人たちのベンチの下では、鮮やかな橙黄色の影が、主人の足首を喰らおうと蠢いていた。\n\n彼は、オペラ劇場で音符が雨粒のように客席へと降り注ぐのを見た。\n彼は、墓地がかすかに起伏し、まるで呼吸する巨大な怪物の皮膚のようにうねるのを見た……\n\n彼は多くのものを見た。あまりにも多くのものを。彼はその光景を、母に、教師に、友人に語り、絵に描いた。自らの目に映る世界を人々に届けようとしたが、周囲の人々は次第に去り、ひとつの世界が彼から遠ざかっていった。\n\nだが、なぜなのだろうか？彼はただ、目にしたものを記録しただけなのに。ピックマンは、それがどうしても理解できなかった。\n\n悲しみに沈んだピックマンは、鏡の前に立った。そこには、鋭い牙をむき出しにして嗤う一体のグールが映っていた。\n「真実を目撃することほど重要なものはない。狂気、混沌、貪欲……見に行きたいか、ピックマン？」\n悟りを得たピックマンは微笑み、鏡の中へ足を踏み入れた。\n\n彼はただ、その極致にある狂気の真実を、自らの目で確かめ、それを忠実にキャンバスへ描き出したかったのだ。\n\n彼は人間ではない。グールでもない。\n彼はただの、写実主義の画家、ピックマンなのだ。"
  },
  Item_77879_Name = {
    Text = "ポリュクス"
  },
  Item_77880_Name = {Text = "カラブ"},
  Item_77882_Desc = {
    Text = "狂気解放でより多くのシールドを獲得すると同時に、チームのクリティカルダメージを増加させる命輪。触腕を駆使するチームでは、さらに高い効果を発揮する。"
  },
  Item_77882_Name = {
    Text = "聖なる炎の導き"
  },
  Item_77882_StoryDesc = {
    Text = "「我らは凡俗なる銅と鉄で星の軌跡を測れども、果てなき深淵には独自の理があり、誰にも予測はできぬ」\n徐々に沈みゆく船の上で、コーパサントは《航海士の挽歌》を口ずさんだ。\n彼女はすでに自らの運命を知り、そして自ら選び取っている。ゆえに、死を前にしても恐れはなく、ただ静寂だけがあった——静かに燃え、静かに最後の航路を導こうとしていた。\nしかし、燃え上がる炎はあまりにも熾烈で、前を見ることも、声を発することも、旗を振ることもできない。このような不完全な誘導で、果たして船は正しく進めるのだろうか？\n彼女には分からなかった。恐怖と不安が胸に広がる。\nその時、《航海士の挽歌》が答えを示した。「若き航海士よ、汝はいずれ塩の海に抱かれ、導きの燐火とならん」\n導きの燐火？コーパサントは黙り込んだ。船乗りたちの間で語り継がれる「聖エルモの火」の伝説を耳にしたことは確かにある。だが、たかが人の身で、どうして世界を照らす聖なる炎になどなれようか？\nそれでも、希望はわずかだとしても、コーパサントは心の中で祈り続けた。自らの責務を果たし、最後の誘導を終えられるように、と。\nコーパサント自身以外に、誰もその祈りを聞いた者はいなかった。だが、それだけで十分だった——。\n「潮汐の黒き書は汝の名を記し、荒れ狂う波が汝に永遠の鎮魂歌を奏でよう」\n彼女はついに《航海士の挽歌》の言葉通り、大海に死した。\nだが同時に、彼女は《航海士の哀歌》をも超えた。\nそれは航海士が大海に対峙した際の、傲慢と戒めを綴った詩にすぎなかった。だが今や、彼女は聖エルモの火となり、永遠に船を導く存在となったのだ。"
  },
  Item_77884_Name = {
    Text = "ファラオ"
  },
  Item_77885_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nケティグラを再度獲得した際に変換され、ケティグラの霊知啓発を起動するために使用。"
