  },
  Item_77887_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nカストルを再度獲得した際に変換され、カストルの霊知啓発を起動するために使用。"
  },
  Item_77887_Name = {
    Text = "欠片・カストル"
  },
  Item_77887_StoryDesc = {
    Text = "カストルを再度獲得した際に変換され、カストルの霊知啓発を起動するために使用。"
  },
  Item_77888_Desc = {
    Text = "狂気解放の基礎ダメージとキーエネルギー獲得能力を強化し、「湮滅」を使用することで、自身の狂気獲得とチームへの狂気支援のどちらかを柔軟に選択できる命輪。"
  },
  Item_77888_Name = {
    Text = "隠された痛み"
  },
  Item_77888_StoryDesc = {
    Text = "クレメンタインは強い子ではなかった。それゆえ、奇妙な病を患い、痛みと忍び寄る死の影に苦しめられていた頃、彼女はよく深夜に目を覚まし、声を殺して泣いていた。\n\nそうして泣いた日の翌朝には、決まって枕元に「贈り物」が置かれていた。\n綺麗な包み紙のキャンディー、流行りの髪飾りに、愛嬌のあるテディベア……。\nしかし、彼女の印象に最も強く残ったのは、蛹の標本だった。\n\nその頃にはすでに病は重く、彼女はベッドから降りることさえできなくなっていた。彼女は必死にその標本を持ち上げ、光を透かす蛹を、じっと見つめた。\n\nその命はすでに安らかな眠りについていたが、同時に永遠の生を手に入れていた。\n一方で彼女は、死の淵に立っている。\n\nそう思うと、涙が静かに頬を伝った。その涙を、優しい手がそっと拭ってくれた。\n\n「泣かないでおくれ、クレメンタイン。いつかお前も、この蛹のように新たな生を得られる」\n「私が、お前に新しい命をあげよう」\n\n父は決して嘘をつかない。少なくとも、彼女に対してだけは。だからクレメンタインは、その言葉を疑いもしなかった。\n\n彼女は父を信じていた。だからこそ、あの穢れた山脈へ足を踏み入れるときもためらわず、肉体が溶けるほどの激痛に耐えるときでさえ、不満ひとつ漏らさなかった。\n\nこれらはすべて、新しい命を得るための代償であり、必要な過程なのだと信じていた。\n\nすべての苦痛と絶望が過ぎ去ったとき、身体は癒え、「家」と呼ばれるあの場所へ帰り、唯一の肉親と再会できるのだと。"
  },
  Item_77889_Desc = {
    Text = "装備者の指令カードが与える基礎ダメージとクリティカルダメージを強化し、定期的に指令カードの最終ダメージを増加させる命輪。超次元ターン中は効果が2倍！"
  },
  Item_77889_Name = {
    Text = "歪んだ騎士詩"
  },
  Item_77889_StoryDesc = {
    Text = "ポリュクスは夢を見た。\n\n夢の中の彼は、銀色の鎧を身にまとい、威厳ある王の手から、月のように冴え渡る一振りの長剣を授かっていた。\nそして背の高い白馬に跨ると、ある洞窟へと駆けた。地の底へと進むと、洞窟の入口にある木が、ざわざわと微かな囁きを交わすように揺れていた。\n\n洞窟の奥深くには、暗緑色の影が潜んでいた。それは肉の山のように巨大な怪物で、歪な両目からは緑色の光が溢れていた。\n「国家に害をなす怪物よ。神聖なる国をこれ以上脅かすことは、我が許さぬ。今こそ、この正義の剣でお前を滅ぼさん！」\n怪物は震え、答えるかのように恐ろしい咆哮を上げた。\nポリュクスにはその言葉は理解できず、理解するつもりもなかった。彼は剣を振り上げ、邪悪な気配を放つ怪物へと斬りかかった。怪物の触手は薄暗い洞窟の隅々まで広がり、光輝く長剣とぶつかり合って、甲高い音を立てた。\n\nあらゆる英雄譚の結末がそうであるように、勇敢な騎士は怪物の背に乗り、怒号とともに剣先をその胸へと突き立てた。\n怪物は力なく崩れ落ちた。安堵の息を吐きながら、ポリュクスは剣の下にゆっくりと広がっていく痕跡を、呆然と見つめた——あの醜く邪悪であるはずのその肉体から、なぜこれほど温かく、鮮やかな赤い血が流れ出るのだろうか？\n\n彼ははっとして夢から覚めた。両手にこびりつく血のような、粘つく感覚は、どうしても拭い去ることができなかった。\nふと視界の端に、カストルが大切にしていた写本が映った。それは、ベッドの裏の隙間に慎重に隠されていた。\n\n彼は何気なくその本を開いた。\nそこはちょうど、カストルが何度も読み返していた騎士の物語のページで、中央には、次のような預言が記されていた。\n「邪悪なる怪物が勇者に討たれし時、人々は天に異変を見る。太陽は闇に、月は血に染まる」\nポリュクスは眉をひそめ、くだらないとばかりにその写本を元の場所へと放り投げた。そして月明かりの下で、祈りの言葉をひそやかに唱えた。\n\n「神の僕は、汝らに祝福を与えんがためにこの地へ遣わされり。汝らの罪を洗い清め、闇より光へと立ち返らせ、すべての清らかなる正しき者らとともに浄土へ入らんことを……」\nだが、灯明者がその敬虔な従者を顧みることはなかった。悪夢がもたらした不安は、なおも心臓の奥底で震えている。それは眠りに沈んだ彼の魂が、夢の中で密かに泣いている声だった。"
  },
  Item_77890_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nクレメンタインを再度獲得した際に変換され、クレメンタインの霊知啓発を起動するために使用。"
  },
  Item_77890_Name = {
    Text = "欠片・クレメンタイン"
  },
  Item_77890_StoryDesc = {
    Text = "クレメンタインを再度獲得した際に変換され、クレメンタインの霊知啓発を起動するために使用。"
  },
  Item_77891_Name = {
    Text = "ランティゴス"
  },
  Item_77893_Desc = {
    Text = "所持者が生成するシールドを増幅し、周期的に「追撃」効果の発動に伴い大量のダメージバフを付与、「次元シャトル」効果の発動に伴い大量の狂気を獲得する。"
  },
  Item_77893_Name = {
    Text = "永世に紡ぐ網"
  },
  Item_77893_StoryDesc = {
    Text = "アラクネは、自分が失敗する運命にあることを知っていた。\n彼女は静かに紡ぎ車を回し、日々人間の悲喜、王朝の興亡、星火のような詩と愛を、時空を超えた巨大な網に織り込んでいた。\n彼女は非常に上手に、正確で、抑制され、優しく行っていた。「間違った」ものを排除し、「正しい」ものを選んでいた。\n何世代もの人々が新たな笑顔を見せ、無数の文明が灰燼の中で新しい歴史を書いた。しかし、編織によって生まれた喜び、編織によって生じた疲労、そしてすべての柔らかな感情は、永遠の苦役の摩耗の中で静かに枯れ果てていた。彼女は自ら脆弱を断ち切り、冷静な意志だけを残し、すべての選択が責任から生じるように、弱さではなく確実にするためだけに。\nしかし、最も深い悲劇は、苦役そのものではなく、彼女がどれほど修復し、編織しようとも、世界は依然としてその静寂な虚無へ向かうことを彼女が明確に知っていることだった。文明は脆弱な砂の城のようで、潮流は必ずやってくる。彼女の努力は、観客のいない演劇であり、決して反響のない見守りだった。\n「運命はすでに私たちを永遠の孤独に定めており、なぜこの残酷な罰を受け入れなければならないのか？」\n「引き裂け、破壊せよ…………そうすればこの苦役から逃れられる…………」\n彼女は目を伏せ、余計な考えを静かに断ち切り、退屈で集中して編み続け、維持し、泣き、耐え続けた…………\nすべての無駄な抵抗、すべての解決のない運命はすでにこの網の中に織り込まれていた。\nそして網の中心で、彼女は自分自身を見つけた。"
  },
  Item_77894_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nアラクネを再度獲得した際に変換され、アラクネの霊知啓発を起動するために使用。"
  },
  Item_77894_Name = {
    Text = "欠片・アラクネ"
