  Item_77909_Name = {
    Text = "琥珀色の死"
  },
  Item_77909_StoryDesc = {
    Text = "多くの場合、死は音もなく訪れる。人の意識が反応するより早く、死神は静かに近づき、瑞々しく脆い命を刈り取っていく。\nだが、人知れぬどこかの砂漠には、琥珀色の死神が存在するという。彼女は宣告を下した後、琥珀の炎と琥珀の銃で、琥珀色の死をもたらすのだと。\n\n月夜の砂漠に、男は立っていた。銃を握る手は絶えず震え、彼はキャティグラの琥珀色の姿を見据えたまま、一瞬とて気を緩めることができなかった。\n冷や汗が額から滴り落ち、それは背後に控える部下たちの胸にも重く沈んだ影を落とす。連れてきた人数こそ多いが、今この瞬間に役に立つ者は、ほとんどいなかった。\n彼は理解できなかった。すでに無人となった倉庫を襲撃するだけのはずだったのに、なぜ伝説の死神と対峙することになったのか。\n「死神？あんなもの、ただの退屈な噂だろ」\nキャティグラは何食わぬ顔でそう言った。\n「前に全部、琥珀色に塗っただけだ。まだ剥げ落ちていない塗料が、どこかに残ってるかもしれないぜ？」\n彼女は惜しげもなく、手にした二丁拳銃を目の前の男に見せつける。\n「銃口から出る琥珀色の炎だって、ちょっと特殊な物質を撒いただけだっての」\n彼女は指を銃口へ突っ込み、くるりと回して、正体不明の粉末を取り出してみせた。\n「死神なんて、昔の私が作り上げたイメージに過ぎねえよ」\n「強くて、神秘的で、何でもできる存在」\n「無能な子悪党どもを威圧するには、ちょうどよかったな」\n彼女は傲慢に語り、目の前の男の視線が次第に凶悪さを増していようと、気にも留めない。\n危険がすぐそこまで迫っていることさえも、気づいていないようだった。\n銃弾が彼女に向かって降り注いだ瞬間、その瞳にはかすかな驚愕と戸惑いの色が浮かんだ。\nだがそれは、意識の底に潜む興奮と狂気を覆い隠すための、仮面に過ぎなかった。\n…………………………\n銃声が止み、すべては彼女が思い描いた通りになった。\n彼女は戦場の中央に立ち、周囲のあらゆるものには、無数の焼け焦げた痕が刻まれている。\nキャティグラがしたことは、ただ二つ——銃を構え、引き金を引く。\n彼女が長銃を構えた時、死神は万物の背後へと舞い降り、等しく死の予兆を下した。\n彼女が引き金を引いた時、炎はすべてを呑み込み、世界に琥珀色の花束を捧げた。\n「こいつらは私と共に長い年月を歩み、数えきれないほどの血と死を見届けてきた」\n「かつては嘘という衣を着せられ、私の弱さと無力さを覆い隠すために使われていた」\n「だがそれはもう、嘘なんかじゃねえんだよ」"
  },
