  },
  Item_78761_Name = {
    Text = "真貌・眠れる主"
  },
  Item_78762_Name = {
    Text = "真貌・眠れる主"
  },
  Item_78774_Desc = {
    Text = "装備者のキーエネルギーと「狂気解放」によるシールドの獲得量が増加する命輪。触腕姿勢を切り替えると、大量の狂気を獲得し、敵が受けるダメージが増加する。"
  },
  Item_78774_Name = {
    Text = "暗闇の中の安眠"
  },
  Item_78774_StoryDesc = {
    Text = "嵐が吹き荒れる夜、神の娘は舷窓の下にひとり座っていた。\n冷たい月光がおくるみを照らし、その中には黒い粘液の滴る「聖なる赤子」が安らかに眠っている。\n神の娘は子守唄を歌い始めた。\n「眠れ、眠れ、海の赤子よ」\n「黒き月影、揺りかごに」\n「星を飲み込み、夢の中」\nその歌声は祈りでもあり、深海の魚たちが導かれるように集まってくる。\n船全体がまるで巨大な祭壇のようで、それは彼女が聖なる赤子を産み落としたあの日を彷彿とさせた。\n自らの胸を裂き、鮮血が滴る骨肉を抉り出し、その命をもって養育の恩と種族の宿命に報いたのだ。\n彼女が払った犠牲は、渇望していた自由をもたらさなかった。死は永遠の安らぎではなく、悲劇の始まりに過ぎなかった。\nそれ以来、彼女に安らぎが訪れるのは夜だけだった。\n「眠れ、眠れ、海の赤子よ」\nこの子守歌が終わるとき、偉大なる神の国が海面を突き破り、荒れ狂う大海原の中から姿を現すだろう。\nそんな虚ろな幻想を抱きながら、マーフィーもまた、そっと瞼を閉じた。"
  },
  Item_78775_Desc = {
    Text = "イベント「神誕の祭礼」で実績を達成して獲得。\n「おや？これがお前の捧げる貢物か？随分と粗末だな、神母の罰を恐れぬのか？」"
  },
  Item_78775_Name = {
    Text = "銀の鍵の名のもとに：誕妄・マーフィー"
  },
  Item_78775_StoryDesc = {
    Text = "誕妄・マーフィー遊興イベント"
  },
  Item_78871_Desc = {
    Text = "属性がダメージ強化の運命の札。"
  },
  Item_78871_Name = {
    Text = "孤高の羽"
  },
  Item_78871_StoryDesc = {
    Text = "生まれた時から、双子は自由に翼を使って飛ぶことを許されず、背中に生えた第二の腕は、神子の威厳を示す礼器のように、常にあるべき姿勢が規定されていた。\n幼い頃、ポリュクスは二人の中で最もその翼を大切にしており、毎日羽を梳き、精油を塗り、その羽を絹のように輝かせていた。\n彼はいつも短い無人の時間を利用して、こっそりとその翼を羽ばたかせ、カストルの驚愕の中でふらふらと地面を離れ、装飾が施された天井に触れようとした。\nポリュクスが翼を使って様々な舞踊のような動きをするのに対し、カストルは自分の翼が木の板のように不器用だと感じていた。双子が毎晩就寝後の秘密の時間に、カストルはポリュクスが暗闇の中で跳ね回り、狭い檻の中で飛翔を模倣するのを静かに見つめていた。\n「弟の翼は本当に美しい。でも僕は一生飛ぶことを学べないかもしれない。」カストルは思った。\nそして後に彼らが逃亡した夜、カストルは初めて夜風が翼を持ち上げる涼しさと軽やかさを感じた。より熟練したポリュクスは、ふらふらと飛ぶ兄をしっかりと掴み、高空で心から笑い、急降下や旋回の弧を描き、まるで本物の空に属する鳥のようだった。\nカストルは頭を傾け、月光がポリュクスの細長く力強い翼に輝き、羽の間に目眩がするような青緑色の光輪を反射しているのを見た。\n「それは世界で最も美しいものだ。どんなことがあっても、僕はポリュクスを守り、その翼を守る。」\nやがて、厳しい野外生活でポリュクスの翼が野獣に傷つけられ、カストルはポリュクスの落ちた羽を拾い上げ、胸にしまい、二度とこんなことが起こらないようにと静かに誓った。しかし彼は知らなかった、その後この孤独な羽が彼にとって最も貴重なものとなり、その翼に関する最後の遺物となることを。"
  },
  Item_78872_Desc = {
    Text = "属性がシルバーキー充電レベルに基づく命輪。"
  },
  Item_78872_Name = {
    Text = "ハゲワシSR(仮テキスト)"
  },
  Item_78872_StoryDesc = {
    Text = "ハゲワシSR(仮テキスト)"
  },
  Item_78873_Desc = {
    Text = "属性がシルバーキー充電レベルに基づく命輪。"
  },
  Item_78873_Name = {
    Text = "ファラオSR（仮テキスト）"
  },
  Item_78873_StoryDesc = {
    Text = "ファラオSR（仮テキスト）"
  },
  Item_78874_Desc = {
    Text = "狂気増加の能力を持つ命輪。"
  },
  Item_78874_Name = {
    Text = "渇望の筆"
  },
  Item_78874_StoryDesc = {
    Text = "食屍鬼に変わり始めてから七日目、彼は四肢が日々腐敗していく激痛にうめいていた。微細な動き一つ一つが敏感な神経を引き裂くような痛みを引き起こし……そして戦慄するような啓示の閃き。\nしかし、恐怖の影はこの芸術家を常に覆っていた——どんな筆があれば、最も極致の真実を描けるのか？\nピックマンは弱った目で周囲を探し、邸宅の脇の煉瓦から墓の上の枝まで、ついに彼の萎縮し腐敗した右脚の露出した白骨に目を留めた。\n何か神聖な呼び声を聞いたかのように、ピックマンは脚の骨を取り出し、指先で粘着した血肉を何度も磨き、硬い筆に仕立てた。\n彼は筆先を鋭い牙のように磨いたが、筆先がキャンバスに噛みつく前に、まず主人の痩せた指先に刺さった。ピックマンは痛みに手を離し、筆は彼の制御を逃れた。\n飛び跳ね！跳躍！回転！それはキャンバス上で狂舞し、錯乱した異次元級の線を刻んだ。線は増殖し、膨張し続ける奇怪な暗色の汚れを引きずり、ゆっくりと確実にピックマンの喉を噛み砕いた。\n瞬間の狂喜が彼の残された心臓を鋭く貫いた——その膨れ上がった器官、混沌とした形態は彼を震え上がらせたが、同時に枯れかけた感覚を蘇らせた。それらは逆転した無秩序な方法で、直接的で鋭く痛み、怪異、欲望を示し、隠すことのない衝撃的な力を爆発させた。\nこの倒錯の中で、ピックマンは「美」の聖域により近づいたかのようだった。\nすべてが静まった後、ピックマンは腐食した爪を伸ばし、その白い筆を何度も撫でた。このまだ人形を保つ躯殻の中から、より熱く、より切実な渇望が噴き出した。\n彼はこの筆と共に、その世紀の大作の最後の一筆を完成させるだろう。"
  },
  Item_78877_Desc = {
    Text = "界域知識の能力を持つ命輪。"
  },
  Item_78877_Name = {
    Text = "宿命の紡輪"
  },
  Item_78877_StoryDesc = {
    Text = "七歳の誕生日、父は「モイライ」という名の紡ぎ車を彼女の膝に置いた。その名は、もはや誰にも祀られることのない三柱の運命の女神のものだったが、紡ぎ車そのものは滑らかで真新しく、銅の軸は金属の光沢を帯び、冷たく重かった。\nその時からアラクネは運命の輪を手に取った。それは選択によるものではなく、何気なく口にした言葉がいつも後に現実となるがゆえに、この定められた責務から目を背けることができなかったからだ。\nその時から彼女はずっと織り続けた。来る日も来る日も、運命の糸が精密な紡ぎ車の上で静かに回るのを見つめながら、人々のために初めての口づけの震え、軍馬の嘶き、赤子の産声、そして墓石に刻まれた粗い文字を織り上げた。\nその時から彼女は、幾千もの交差する糸の中から「より良い」方向を選び取り、漆黒の疫病を早めに退かせ、歴史を戦火から逃れさせ、文明を廃墟の中から再建させた…………だがそれと同時に、狂気や裏切り、あるいは永遠の闇夜へと通じる糸もまた織り出した。時空を跨ぐ運命の網を維持するために。\n「何がより良いというのだろう？」\n沈黙の紡ぎ車は答えず、ただ回り続ける。良きことも悪しきことも、誕生も死も、同じ一本の糸の上に交互に浮かび上がる。若き日の彼女は自らの宿命が何であるかをまだ知らなかったが、無数の糸の先に、世界の終局をすでに見ていた。\n「もし世界が滅びの宿命から逃れられないのなら…………」\n「いいえ、私はこの世界を愛している。」\nアラクネは紡ぎ車を見つめ、口にしなかった想いを捨て去った。\n「では…………私の宿命は？」\n彼女は呟いた。空虚な反響だけが四方の壁の間を彷徨っていた。\n…………\n数え切れないほどの文明が運命の網の上で興り、そして崩れ去った。ピラミッドは砂の中で眠り、宇宙船は星の海を駆け抜け、言語は季節のように移り変わり、神々の名は埃を被った辞典に記された…………だが彼女はずっとそこに座り、手の中の紡ぎ車を回し、人類が希望と滅びの循環を何度も繰り返すのを見つめていた。\nある日、一つの小さな呼び声が、永遠の牢獄と万古の静寂を超えた。\n「お姉ちゃん…………」\n彼女はようやく終末へと向けていた視線を引き戻し、目を閉じてネフレアを見つめた——彼女の中にいるもう一人の自分を。その新生児のように澄んだ瞳には、裁きも恐れもなく、ただ全幅の信頼だけがあった。まだ何も書かれていない白紙のように。\nその瞬間、アラクネはついに悟った。愛と責任、憎しみと滅び、すべては運命の前では何の違いもないのだと。そして彼女は、自らの手で断ち切り、捨て去った記憶——本来起こるはずだったのに訪れなかった痛み、後悔、喪失を一本の糸に織り上げ、最も重く、最も優しい贈り物として、ネフレアの手首に結んだ。\n「ここを離れなさい、ネフレア。」アラクネは微笑んだ。「あなたは自由よ。」\nアラクネはもう、自らの宿命を見定める必要はなかった。なぜなら七歳のあの日、紡ぎ車を手に取った瞬間に、彼女はすでに未来の行く先を選んでいたのだから。そして宿命の紡ぎ車は静かに回り続け、彼女がこれから身を投じる、終幕なき戦いを見届けるだろう。"
  },
  Item_78878_Desc = {
    Text = "属性が死亡耐性の運命の札。"
  },
  Item_78878_Name = {
    Text = "海上の航行者"
  },
  Item_78878_StoryDesc = {
    Text = "ブオ——ブオ——\n汽笛の音の中、遊覧船はコーパサントの指示で安全に接岸した。\n乗客たちは笑いながらタラップを降り、帽子を取って彼女に感謝し、水夫たちは集まって称賛を表した。\n「よくやった、コーパサント。君が事前に警告してくれなかったら、嵐に飲み込まれていたよ。」\n「そうだね、君の正しい指示のおかげで、海で迷わずに済んだよ！」\n水夫たちは笑いながら彼女の肩を叩き、親指を立てた。\n実際、コーパサントはこうした近距離の社交に慣れることができず、彼女の古風で理性的な頭脳には「仕事」と「職務」以外の考えはなかった。\nそこで、彼女はこれも「仕事」と「職務」の一部とみなすしかなかった。\n「私はただ自分の仕事を果たしただけです。航海士としての私の職務は、皆さんを安全に帰港させることです。」\n形式的で退屈な返答だが、彼女の人柄を知る水夫たちは大笑いし、彼女に別れを告げ、船歌を歌いながら肩を組んで港を去った。\n「ノーチラス号がついに出航できる。出発だ、ノーチラス号。」\n歌声は次第に遠ざかり、コーパサントはまだ岸辺に残っていた。彼女は未来の出航に備えていた。\n海は気まぐれで、どの航海士も毎回勝利を保証することはできず、彼女もそうだった。しかし、彼女はわずかでも勝算を増やすために無数の時間を費やすことをいとわなかった。\n点検、巡回、学習、確認、彼女の生命には「仕事」だけが残っているようだった。\nしかし、彼女はそれを喜んで受け入れた。なぜなら、それはすべてその瞬間のため、成功した航海で皆を安全に帰港させるその瞬間のためだった。"
  },
  Item_78879_Desc = {
    Text = "属性がシルバーキー充電レベルに基づく命輪。"
  },
  Item_78879_Name = {
    Text = "シャタク鳥SR（仮テキスト）"
  },
  Item_78879_StoryDesc = {
    Text = "シャタク鳥SR（仮テキスト）"
  },
  Item_78880_Desc = {
    Text = "界域知識の能力を持つ命輪。"
  },
  Item_78880_Name = {
    Text = "甘美なる真相"
  },
  Item_78880_StoryDesc = {
    Text = "「燐寸を一本、買っていただけませんか？」冬の夜、手足が真っ赤に凍えた少女がつぶやいた。「一本、一本だけでいいんです。」\n「ごめんなさいね、あなたの燐寸は買わないわ、」純白の影がわずかに身をかがめ、冬の月を遮った。「むしろ、あなたに何かを売ってあげようと思って。」\n「でも、お金が……」\n「大丈夫よ。仙女の祝福を信じなさい、すぐに燐寸が売れるようになるから。」\n白衣の仙女は少女の手に飴を一つ握らせ、それから少女の耳元に顔を寄せた。\n「通りの向こうにいる毛皮のコートを着た中年の女の人が見える？あの人の裾をつかんで、思いっきり泣くの。こう言うのよ、心優しい奥様、こんなに寒いのに、おばあちゃんが重い病気にかかってしまって、一度でもお腹いっぱい食べられなければもうすぐ死んでしまいます、どうかお金を少し恵んでください、って。」\n「でも、おばあちゃんはずっと前に、もういなくなってしまったから……」\n「それならなおさらいいじゃない！その時の気持ちを思い出して、もっと本当らしく泣くのよ……」\n「もしそれでもケチってお金を出さなかったら、私にも手がある。こんな大晦日に外をうろついている人は、家庭が幸せじゃないに決まってる。だからこう付け加えるの、おばあちゃんは私の唯一の家族なんです、今日は大晦日なのに、誰だって一人ぼっちは嫌でしょう、お願いです、きれいな奥様、三文だけでいいんです、早く燐寸を売り切って、おばあちゃんのところへ帰れるようにしてください、って。」\n「燐寸は一文なのに……」\n「残りの二文は、一文が私の取り分、もう一文はあれへの供物よ。」カラブは手の中の魔法の杖を振った。眠っている白い幼虫が水面の波紋のように揺れた。\n「難しく考えないで、仙女の祝福を信じればいいだけよ。この手は必ず効く。覚えておいて、お金を出すまでは絶対に手を離しちゃだめよ。失敗したら、次の孤独なお金持ちの奥様を探せばいいだけ。安心して、この世の中、手元に余裕のある女性はあたし達二人を養えるくらいいくらでもいるんだから。」\n必ず効くはずの方法がなぜ失敗するのか、もはや誰も追及しようとはしなかった。とにかく、百八十二套の話術を更新した末に、少女の燐寸は無事に売り切れた。\n本物の「仙女の名付け親」が現れない物語の中でも、偽りの仙女は同じように、凍え死にそうな、貧しくかわいそうな少女を救ったのだった。\nめでたし、めでたし。"
  },
