  },
  Item_78884_Name = {
    Text = "御子の威厳"
  },
  Item_78884_StoryDesc = {
    Text = "「神子は灯を持つ者に見守られ、生まれながらにしてその恩恵を受ける。」\n「神子はその意志を広め、光を信仰深い義人に授けるべきである。」\n「神子は魂の清浄を保つべきである。」\n「神子は俗欲を断ち、信仰を修行し、全心で光に仕えるべきである。」\n「神子は多言を慎み、妄言を慎むべきである。」\n「神子は罪を遠ざけ、罪ある者を遠ざけ、汚れた魂に汚されてはならない。」\n「神子……」\n彼が記憶を持つようになってから、戒律の一つ一つが鎖のように彼を縛り、彼を尊崇の高台に捧げ、失礼を許さず、頭を下げることを許さず、喜怒を放縦することを許さなかった。\n彼は広大で華麗な衣をまとい、無数の従者に囲まれ、要求に従ってその神聖な代表を演じ、信仰深い信者がひれ伏し、慎重に彼の衣の裾に口づけるのを見下ろした。\n神子は本来そうあるべきであり、その高慢で変わらない顔の下にどんな感情や好みがあるかを気にする者はいなかった。\n彼はその高慢な笑顔に慣れ、人がいない時でも自分がどんな表情をしたいのか分からなかった。\n「神子ポリュクス、あなたは祝福の儀式に向かうべきです。」頭を垂れた侍女が彼の変わらない生活を敬意を持って手配した。\n彼は振り返り、頭を上げ、同じく変わらない笑顔を見せた。それはまるで自ら神聖な仮面をかぶるようだった。\nその仮面の下には、迷い、虚無、孤独が隠されており、まるで存在しなかったかのようだった。"
  },
  Item_78885_Desc = {
    Text = "クリティカルダメージの能力を持つ命輪。"
  },
  Item_78885_Name = {
    Text = "迫り来る太陽"
  },
  Item_78885_StoryDesc = {
    Text = "太陽は毎秒300垓ジュールを超えるエネルギーを放出している。そのうちの数十億分の一が光と熱の形で、1億4700万キロメートル以上の距離を旅し、宇宙から地球へと降り注ぐ。\nこのエネルギーが地球上のすべての生物の需要を満たし、この複雑で巨大で混沌とした三ドメインのすべての種が順調に繁殖し、進化することを可能にしている。\n\n「これは世界の真理であり、いかなる状況でも変わることはない。」\n彼は絶えずそう自分に言い聞かせ、精神の安定を保とうとした。\n「なのになぜ…………こんなに熱く、こんなに眩しいのだ。」\nなぜなら、あの1億4700万キロメートルの彼方にあるものが、ゆっくりと彼の瞳を占めつつあったからだ。\n光と熱が彼の瞳孔から溢れ出し、華麗な肉体の隅々を焼き焦がしていく。\n「理解した、理解した、なぜ光が8分20秒もかかって地球に届くのか、理解した。」\n「我々には、光輝を直視する代償を支払えないからだ。」\nすべてを受け入れたとき、彼は高らかに笑い始めた。\n「なんと、私はイカロスよりも太陽に近かったのだ。」"
  },
  Item_79294_Name = {
    Text = "逆転回合"
  },
  Item_79412_Desc = {
    Text = "ごく少数の守秘者が持つ身分証明。\n無数に広がる次元で、あなたは勝者の証を示した。この勝利は物理的な境界を超え、無限の平行世界に示される。"
  },
  Item_79412_Name = {
    Text = "次元の桂冠"
  },
  Item_79412_StoryDesc = {
    Text = "対局イベントアイコンフレーム"
  },
  Item_79413_Desc = {
    Text = "ごく少数の守秘者が持つ身分証明。\n夜はあなたのキャンバス、血の月を絵の具に、深淵はあなたの手から生まれる——誇りに思え、あなたが創り出したのは恐怖そのものだ。"
  },
  Item_79413_Name = {
    Text = "描写された深淵"
  },
  Item_79413_StoryDesc = {
    Text = "創作イベントアイコンフレーム"
  },
  Item_79414_Desc = {
    Text = "ごく少数の守秘者が持つ身分証明。\n無限の宇宙で、あなたは星辰の羅針盤である。\n星辰が位置を定め、混沌が立ち上がるとき、名状しがたい旧日が目覚める。"
  },
  Item_79414_Name = {
    Text = "星宇の航海"
  },
  Item_79414_StoryDesc = {
    Text = "攻略イベントアイコンフレーム"
  },
