  Item_80189_Name = {
    Text = "お得ギフト空パッケージ"
  },
  Item_80191_Desc = {
    Text = "このキーオーダーを記録すると、編成時にキーオーダースキル「特別な治療」を選択可能。\n\n彼女はかつて数えきれないほどの患者を癒し、新たな人生へと導いてきた。今起こっていることも、ただの心理療法に過ぎない。\nただ一つ特別なのは、その患者が彼女自身であるということだ。"
  },
  Item_80191_Name = {
    Text = "特別な治療"
  },
  Item_80191_StoryDesc = {
    Text = "彼女はかつて数えきれないほどの患者を癒し、新たな人生へと導いてきた。今起こっていることも、ただの心理療法に過ぎない。\nただ一つ特別なのは、その患者が彼女自身であるということだ。"
  },
  Item_80192_Desc = {
    Text = "心の療養院に散らばる感情粒子は、触れると誰かの崩壊寸前のささやきが聞こえるようだ。\n守秘者が事件「蜕変」における共鳴を高めるために使用される。"
  },
  Item_80192_Name = {
    Text = "認知の心"
  },
  Item_80285_Desc = {
    Text = "ロックを解除後、「療養記行」のすべてのタスクを完了することで、以下のボーナスを追加で獲得できます"
  },
  Item_80285_Name = {
    Text = "療養紀行"
  },
  Item_81021_Desc = {
    Text = "ガレン特製の掃除道具は、どんなものでも滑らかにきれいに掃除できます。"
  },
  Item_81021_Name = {
    Text = "掃除ツール"
  },
  Item_81069_Desc = {
    Text = "後方支援部は調査を完了した守秘者に特別許可を発行した。調査完了後、次の出発に向け、貴重なシルバーコア製品を購入可能。\n数量限定、銀の鍵の導きがあらんことを。"
  },
  Item_81069_Name = {
    Text = "調査特典・星辰篇Ⅱ"
  },
  Item_81250_Desc = {
    Text = "「航海士が乗船中」という意味を持つ信号旗。コーパサントが集めているようだ。商店で物資と交換可能。"
  },
  Item_81701_Desc = {
    Text = "「パイロットが本船に乗船中」を意味する信号旗。コーパサントが収集しているかもしれない。ショップでの物資交換に使用する。\n\n最低{s1}個ドロップ"
