  Item_81756_Desc = {
    Text = "このキーオーダーを記録すると、編成時にキーオーダースキル「不死の雷光」を選択可能。\n\n燃えろ、燃えろ、燃えろ。\nたとえ骨と血が沸き立ち、皮や肉が焼け焦げようとも、体中の最後の一滴の血まで絞り尽くして、光を放つのだ。\nなぜなら、この深い闇の中で、私だけが唯一の道標なのだから。"
  },
  Item_81756_Name = {
    Text = "不死の雷光"
  },
  Item_81756_StoryDesc = {
    Text = "燃えろ、燃えろ、燃えろ。\nたとえ骨と血が沸き立ち、皮や肉が焼け焦げようとも、体中の最後の一滴の血まで絞り尽くして、光を放つのだ。\nなぜなら、この深い闇の中で、私だけが唯一の道標なのだから。"
  },
