  Item_88872_Name = {
    Text = "数理の書"
  },
  Item_88873_Desc = {
    Text = "このキーオーダーを記録すると、編成時にキーオーダースキル:「すれ違う運命」を選択可能。\n彼らはいつも、巡り合わせの悪さゆえに、一瞬の希望とすれ違ってしまう。\nかつて、その幼い手は彼を手を取り、共に自由の光へと駆けた。\n必死に翼を羽ばたかせ、運命の檻を再び抜け出そうとしたのに、なぜ、その見覚えのある手は今、彼の胸を貫いているのだろうか？"
  },
  Item_88873_Name = {
    Text = "すれ違う運命"
  },
  Item_88873_StoryDesc = {
    Text = "彼らはいつも、巡り合わせの悪さゆえに、一瞬の希望とすれ違ってしまう。\nかつて、その幼い手は彼の手を取り、共に自由の光へと駆けた。\n必死に翼を羽ばたかせ、運命の檻を再び抜け出そうとしたのに、なぜ、その見覚えのある手は今、彼の胸を貫いているのだろうか？"
