  Item_89573_Desc = {
    Text = "狂気増加の能力を持つ命輪。"
  },
  Item_89573_Name = {
    Text = "湮土での再誕生"
  },
  Item_89573_StoryDesc = {
    Text = "あなたは人の気配のない荒原に足を踏み入れた。\n人間の活動の痕跡はとっくに消え去り、魂が枯れた生き物たちが灰と塵霾の中で苦しみながら進んでいる。\nここでの生存は羨ましがる価値もなく、誰も旅の終わりを知らず、ただ無限に繰り返される光景の中を彷徨い、彷徨い、彷徨っている。\n彼らの足取りが鈍くなり、重く地面に倒れ込み、空を仰ぎ見て呼びかけの手を伸ばすまで——\n\n私の旅が終わるとき、\n死体が沃土となり、滋養となり、源泉となって、か弱い新芽が再び破土することを願う。"
  },
  Item_89651_Desc = {
    Text = "探索過程中に爆発的に狂気を獲得する命輪。"
  },
  Item_89651_Name = {
    Text = "入学の日"
  },
  Item_89651_StoryDesc = {
    Text = "それは、あなたがミサゴへ来てから一年目のことだった。\n\nあの大爆発から目覚め、初めてこの学校の門をくぐった日のことは今もよく覚えている。\n整った制服が支給され、自分だけの寮部屋が与えられ、初めて食堂を訪れて二皿分の食事をぺろりと平らげた。\n楽な時間はその日限りで終わった。\n知識が貧弱すぎることと、乳児並みに滑らかな脳回路とやらのおかげで、予科クラスへの一年間の強制入学が告げられる。\n\n言語学習、体力訓練、シルバーコア能力の測定、特殊生物の知識補習……多くの試験を経ても、成績はまちまち。\nライ国共通語は赤点だったが、一度に三人の覚醒体とリンクを成功させたという話で一躍キャンパスの有名人になった。\n\n幸運にも、あなたの特異な能力と優れた素質のおかげで、調査員としての基準にはすぐに達し、予科課程の延長は免れた。\n足りない部分は、次第に絆を深めてきた仲間たちが補ってくれた。\nここには魔物のような教師も多いが、信頼できて優しい魔物たちだ。\n\nこの地は曇天と雨が多く、晴れの日は少ない。\n忘れられた者たち、そしていずれ忘れられる者たちが、それでも立ち続け、犠牲を払い、前へ進み続けている。\n\nそんな何気ない一日に、ミサゴはまた新たな一年の始まりを迎える。\n鏡の前で制服の襟を整え、皺をひとつひとつ撫でる。\n寮のドアを開き、外へ踏み出す。\n\n「ふぁ〜……ようやく来たな。我は、眠ってしまう所だったぞ」\n「寮の中で巣作りでもしてたの？新入生くん」\nあなたはロータンにぎこちなく笑い返し、生理的な恐怖を感じるピンク色の姿に思わず首をすくめて、ラモンナとオジールの後ろにそっと隠れる。\n\n早朝のキャンパスで、五つの影が並んで揺れながら伸びていく。\n「行きましょう、パートナー」\n「今日からあなたも、正式にミサゴの一員よ」"
  },
  Item_89652_Desc = {
    Text = "キーオーダー発動後、装備者の一時的なクリティカル率を高める命輪。"
  },
  Item_89652_Name = {
    Text = "パートナーの特訓"
  },
  Item_89652_StoryDesc = {
    Text = "たとえそれ以前の人生の記憶を失っていたとしても、発達しているとは言い難いあなたの筋肉を見れば、かつてのあなたが、運動や暴力を好むタイプではなかったことは容易に想像がつく。\n\nそれなのに、ミサゴ大学が調査員に課している戦闘基準は、あまりにも高く、あまりにも万能を求めすぎる。\nどうしてこんなにも徹底しているのか、どうしても理解できなかった。\n\n調査員にとって重要なのは「調査」ではないのか。\n鋭い知性、緻密な論理、そして少しばかりの、ちょうどいい幸運。\nそれこそが本分ではないのだろうか。\n\n毎朝きっかりと、ラモンナに寮の布団から引きずり出され、がらんとした訓練場に立たされ、幾度となく繰り返される攻撃を受けるたびに、あなたはドール教授の皮肉に満ちた論理学の講義を恋しく思った。\n山のような課題も、髪が抜け落ちそうな試験問題でさえ、戦闘訓練で何度も殴られ、倒される痛みに比べれば、ずっと優しいものだった\n\n19回目、すべての動線を封じる細剣に追い詰められ、あなたはついにバランスを崩し、尻もちをつくように地面へ倒れ込んだ。\n全身の骨がばらばらになりそうな感覚に襲われる。\n荒い息をつきながら、額の汗を力なく拭い、もう二度と立ち上がるものかと、頑なに地面に座り込んだ。\n\nラモンナは、少しも意外そうな顔を見せなかった。\n美しい剣の花を描いて剣を収め、小気味よい靴音を響かせながら、あなたの方へ歩み寄ってくる。\nあなたはぎゅっと目を閉じ、あらゆる叱責と批判を覚悟して頭を抱えた。\n\nだが、不思議なことに、、叩かれたり罵られたりすることはなく、3秒後に目を開けると、そこには淡い微笑みを浮かべた顔があるだけだった。\n\nラモンナは少し腰をかがめ、白い手袋に包まれた手をあなたに差し出す。\n「本当によく頑張っているわ。私はちゃんと分かってる。でも、私たちが向き合うのは、いつだって未知の恐怖と危険よ。私でさえ、思いがけない事態に目が届かないことがあるんだから」\n「だから……私を少し安心させると思って、もう一度だけやりましょう。ね、私のパートナー。」"
  },
  Item_89842_Desc = {
    Text = "いつ現れたのかわからない紙の券を触れると、目の前に神秘的な幻像が浮かび上がる。「幻衣訂購」で一期のシンプルな幻衣を交換するために使用できます。"
  },
  Item_89842_Name = {
    Text = "シンプルな幻衣描形券（一期）"
  },
  Item_89873_Desc = {
    Text = "日毎の補給物資"
  },
  Item_89873_Name = {
    Text = "日毎の補給物資"
  },
  Item_89952_Desc = {
    Text = "静かな部屋の中で、24人の宿主たちがお茶会を始めた。\n\n「ジェンキンは今日、どうしてるかしら？」\n穏やかな24が、心配そうに窓の外を見つめる。\n\n「今日は私たちが逃げ出した記念日よ。約束したじゃない、この日だけは私たちだけのもの。もっと楽しんで、24たち、これはパーティーなんだから！」\n熱っぽい24が両手を振り上げる。\n\n「静かで、深みのある過ごし方を考えてもいいかも……」\n学者の24の言葉に、誰も耳を傾けていないようだった。\n\n「踊りたい人はいる？音楽なら任せて！」\n道化の24がラッパを鳴らす。\n\n「さあ、今日のお茶会はあなたたちのためのものよ。」\n主人格の24が2人の手を引いて、舞踏の場へと導く。彼女はこの屋敷の女主人という役割に、すっかり慣れていた。\n\n「私たちの痛みは、あなたたちが背負ってくれている……悩みは忘れて。少なくとも、今日だけは。」\n\n「にゃあ〜」\n影の24に撫でられながら、猫の24は期待に尾を揺らす。\n\n鬱の24と躁の24が、互いに目を合わせる。\nこの屋敷のすべての苦しみと混乱を、彼女たちは共に背負ってきた。\n彼女たちは朝夕を共にする親友であり、生涯変わらぬ仇敵でもある。\n\n手を取り合い、部屋の中央の空間へと歩み出る。\n不安も悲しみも静まり返り、彼女たちは笑い、絡み合い、声を揃えて歌い、跳ね、回る。\n\n血と涙が衣服と床を濡らし、音楽と舞踏が、ひとつの脳内に響き渡る。\n\n静かな部屋の中で、24人の宿主たちは息をひそめる。\nこの瞬間の静けさを、彼女たちはただ、自分たちのために味わっていた。"
  },
  Item_89952_Name = {
    Text = "二面性の共鳴"
  },
  Item_89953_Desc = {
    Text = "リーン、リーン。\nそれは錆びついたオルゴールが歌っている音。\n調子外れになった白鳥の挽歌を歌っている。\n哀しげな人形はオルゴールの中で絶え間なく回り続け、舞い散る熱い涙が青緑の炎へと投げ込まれ、きらめく宝石の雨となって結晶化する。\n\n無数の歪んだ顔がその炎の中から浮かび上がり、貪るように涙の雫を食らいつくし、苦しげに彼女のスカートの裾に縋りつく。\n「踊れ！踊り続けろ！永遠に止まるな！」\n「お前にまだ踊る資格があるのか？どの面下げて？人殺しが！殺人鬼め！」\n\nそれはリッツが毎夜ごとに繰り返し巡らせる悪夢だ。\n無数の魂が彼女の視界の中で口を大きく開け、泣き叫び、そして歌う。\nその一方で彼女は、つま先を張り、腕を硬直させ、身体を最も正しい踊るための姿勢に固定されたまま、歯車の回転に合わせて、ただひたすら回転し、回転し続ける。\n\nもし夢から覚めかけた頃に彼女に出会っても、なぜもう踊らないのかと尋ねてはいけない。\n彼女は愛も憎しみも涙も、すべて夢の炎に投げ尽くしてしまったのだから。\n\n彼女は愛をその火へ投じ、ゆえに生涯愛したものを手放した。\n彼女は憎しみをその火へ投じ、ゆえにあの穢れと罪を二度と口にしない。\n愛と憎しみは絡み合って燃え尽き、共に彼女の魂を果てしない、青い哀愁で染め上げた。"
  },
  Item_89953_Name = {
    Text = "旋舞人形"
  },
  Item_89954_Desc = {
    Text = "可愛らしい部屋、繊細な彫刻の入った家具、ふわふわの毛布、華麗なスカート、端正な礼儀作法。\n淑女マーフィーは、他人には到底及ばぬほどの地位と、誰もが羨む宝物を惜しみなく与えられていた。\nしかし彼女は終始、屍のように生きていた。\n\n誰にも知られないある夜、彼女はひっそりと古びた衣装戸棚の中に身を潜めると、海踊人の魚人たちに担がれて教会の外へ運び出される。\nそして、人気のない荒野へと捨て置かれた。\n\n彼女が戸棚を押し開けると、荒野には星明かりが燦々と煌めいていた。\n彼女はゴミの小山を跳び越え、そこでひとつの小さな球を拾った。\n\nゴリアテが、怯えた魚人の小隊を連れて、いなくなった聖女を探し当てたとき、彼女はまだ戸棚からそう遠くない場所に座っていて、手の中の小さな球を高く投げ上げ、落ちるのを待っては、また高く投げ上げる——\nその繰り返しをしていた。\nゴリアテは一言も問いただすことなく、聖女を座敷牢のような檻へ再び押し戻した。\n\nだから彼女の行いの真意は、ついに語られることがなかった。\n胸に短剣を突き立てるその瞬間に至るまで、ずっと心の奥底に埋められたまま。\n\n——彼女は、あの大きくて丸い月へ球を投げ上げたかった。\n——そうすれば、それはもう二度と落ちてこないから。"
  },
  Item_89954_Name = {
    Text = "淑女の奇妙な嗜み"
  },
  Item_89955_Desc = {
    Text = "創生の父は星空より降り立ち、血によって生を生み出し、骨で規則を書き記した。 \n万物は父なる神の言葉に従い、父なる神の意のままに生きるはずだった。\n \nだが時は流れ、神言は砕け散り、父なる神の言葉は実行されず、父なる神の意は届かず。 \n万物は悲しみに沈み、苦難が満ちた。\n\n蒼白の主よ\n私は再び「救世の神言」を世に響かせ、あらゆる苦しみを終わらせよう。\n万物の苦を、万物の罪を、万物の悲しみを、我が骨と血が尽き、魂が天へ還るその時まで。\n\n第一の神言が響き、肉体の欲は超越された。 \nかくして「色欲」は滅んだ。\n\n第二の神言が響き、生きとし生ける物は快楽に溺れなくなった。\nかくして「暴食」は滅んだ。\n\n第三の神言が響き、貪りの魔の舌は沈黙した。\nかくして「強欲」は滅んだ。\n\n第四の神言が響き、怠惰に日々を費やす者はもはやいなくなった。\nかくして「怠惰」は滅んだ。\n\n第五の神言が響き、人々は理由なく暴力を振るわなくなった。\nかくして「憤怒」は滅んだ。\n\n第六の神言が響き、妬みに囚われ、死を招く愚者はいなくなった。\nかくして「嫉妬」は滅んだ。\n\n第七の神言が響き、万物は互いを尊び敬った。\nかくして「傲慢」は滅んだ。\n\n我は父なる神の骨をもって、父なる神の権能を代行する。\n父なる神の光よ、万物を照らしたまえ。\n\n救世の神言よ……\n永遠に、世に在らんことを……"
  },
  Item_89955_Name = {
    Text = "救世の神言"
  },
  Item_89964_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「頭の中の音」を選択可能。\n\n手を取り合った瞬間、あなたたちは互いの瞳に迷いと困惑を見た。\n\n失われた過去により、欠けた旋律がここに交差する。\n沈黙の楽章は今まさに紡がれる——君たちが未来へ堕ちることを決意したがゆえに。"
  },
