  Item_90554_Desc = {
    Text = "葬骸の都市に漂う感情の粒子は、触れると屍食鬼欲望に満ちた息遣いが聞こえるようです。\n秘密保持者が調査事件「餍飨」で共鳴を向上させるために使用されます。"
