  Item_90984_Desc = {
    Text = "さあ、ソースと香辛料をたっぷりまとった黄金色の肉料理を運んでこい。慈悲深き奴隷主が食べ終えたなら、残った骨をお前に下賜してくださるかもしれない。「貢物を捧げる」での物資交換に使用する。\n\n最低{s1}個ドロップ"
  },
  Item_90984_Name = {
    Text = "美味しいレオの焼き肉"
  },
  Item_91121_Desc = {
    Text = "彼女の当時の決断と勇気を称賛する人がいる一方で、その再生の幸運を羨む人もいる。\n\n活発な脳の下には、刃も銃弾も恐れず、老いることのない、無数の代替可能な肉体があった。\n\n永遠の命への誘惑は、禁断の果実。輝く灯火のように、富と権力を手にした者たちを引き寄せた。\n\nかつてミサゴでも拒めぬ程の大物が、非常に高額な対価を差し出し、ドールに同様の脳移植手術と覚醒プロセスを希望した。\n\nドールは断らなかった。彼の無知を嘲笑うこともなく、忙しい実験の合間に短い面会時間を取り、その大物を精密に診察した。\n\nそして穏やかに、彼を激昂させる結論を告げた——彼の脳は再生の条件を備えていなかった。\n\nミサゴ側のあらゆる調整の末、重病により死を目前にした大物は一連の免責協定に署名し、かすかな希望に賭ける覚悟を決めた。\n\nドールは自ら手術を執刀したが、残念ながら希望は初めから存在しなかった。\n\nドールが否定の判決を下した時点で、その発達が不十分な脳が本来の霊性を取り戻すことは不可能だった。\n\nとはいえ、誠意ある報酬を考慮し、ドールは丁寧にアフターサービスを施した——活性を維持したままの脳は脳缶に収められ、その性能にぴったり合う装置システムに接続された。\n\nこうしてドールの研究室には『飛翔する真菌』の美学にかなった小さな助手たちが増えていった。\n\nそれらの短時間飛翔できる小さなものたちは、器用な鋏足を動かし、単純な作業をこなし、科学の研究と進歩に貢献している。\n\n「I03、新しい蒸留水をひとつ」\n「I05、先週の培地を交換して」\n「I01、コーヒーを一杯お願い」\n\n無知な脳も、まったくの無駄というわけではないらしい。\n\nコーヒーの湯気に包まれながら、ドールは微笑んだ。\n"
  },
  Item_91121_Name = {
    Text = "霊性の再生"
  },
  Item_91157_Desc = {
    Text = "胸のシルバーキーが突然光り、宇宙の外のどこかと共鳴しているようだ。これは二つの魂の共鳴の証だとあなたは知っている。"
  },
  Item_91157_Name = {
    Text = "銀の鍵の輝き"
  },
  Item_91237_Desc = {
    Text = "いつ現れたのか分からない紙券を手にすると、目の前に神秘的な幻像が浮かびます。「幻衣注文」で第二期のシンプルな幻衣と交換するために使用できます。"
  },
  Item_91237_Name = {
    Text = "シンプルスタイル幻想の衣装デザインクーポン(第2版)"
  },
  Item_91353_Desc = {
    Text = "後方支援部は調査を完了した守秘者に特別許可を発行した。調査完了後、次の出発に向け、貴重なシルバーコア製品を購入可能。\n数量限定、銀の鍵の導きがあらんことを。"
  },
  Item_91353_Name = {
    Text = "調査特典・星辰篇Ⅲ"
  },
  Item_91354_Desc = {
    Text = "解放後、「亡城紀行」の全タスクを完了することで、以下の報酬を追加で獲得できます"
  },
  Item_91354_Name = {
    Text = "死の街への紀行"
  },
  Item_91397_Desc = {
    Text = "「真実は一つだけ。」"
  },
  Item_91397_EmojiName = {Text = "探偵"},
  Item_91397_Name = {
    Text = "レイク・探偵"
  },
  Item_91397_StoryDesc = {
    Text = "第19期課題記録"
  },
  Item_91435_Desc = {
    Text = "「軽く眠る心を目覚めさせる……」"
  },
  Item_91435_EmojiName = {Text = "叩く"},
  Item_91435_Name = {
    Text = "シアン・ノック"
  },
  Item_91435_StoryDesc = {
    Text = "第19期フェイズチェス"
  },
  Item_91730_Desc = {
    Text = "ミサガレストランが提供する日常的な肉料理セットのひとつ、小ぶりで皮がパリッと肉が柔らかい、確実に間違いない選択。\n「偉大なる征服」の期間中、限定提供。"
  },
  Item_91730_Name = {
    Text = "スパイスドローストチキンセット"
  },
  Item_91731_Desc = {
    Text = "ミサガレストランが時折提供する肉料理セットのひとつ、新鮮な仔羊肉を低温で焼き上げ、香ばしい香りが漂い、ジューシーで、学生に非常に人気があり、すぐに完売するだろう。\n「偉大なる征服」の期間中、限定提供。"
  },
  Item_91731_Name = {
    Text = "柔らかいローストラムのセット"
  },
  Item_91732_Desc = {
    Text = "ミサガレストランの祝祭特別肉料理セット、贅沢なボリューム、魅惑の蜜色と脂肪にあふれた肉汁で、祝祭の雰囲気を最も引き立て、人々に満ち足りた幸福感を与える。\n「偉大なる征服」の期間中、限定提供。"
  },
  Item_91732_Name = {
    Text = "火山ステーキセット"
  },
  Item_91764_Desc = {
    Text = "幻衣「血塗られた栄冠」解放後に解放。\n「俺は来た、俺は見た、俺は殺した」"
  },
  Item_91764_Name = {
    Text = "ユウハシュ・血塗られた栄冠"
  },
  Item_91765_Desc = {
    Text = "どれだけの時が過ぎようと、彼はあの時代、剣闘士としての栄光を決して忘れない。\n\n「ユウハシュ……」\n\n最初の頃は、金を積んで買った奴隷を紹介する主人が、その名を観客に告げていた。\nだが、彼が敵を皆殺しにし、素手で内臓を引き裂き、その血を飲み干した頃には、闘技場は彼の名を狂ったように叫んだ。\n\n「血を好む者」「悪魔」「闘技場の暴君」……\n呼び名は変わっていき、それにつれ対戦相手も強くなった。\n子供、老人、女、男、虎やライオンさえ、彼の敵となり、すべて敗れ去った。\n\n敗者の断末魔に興味はなく、「何のために戦う？」などという臨終の戯言に気を掛けることもない。\n彼が繰り返したのは、ただ一つ。\n\n殺すこと。\n\n生きている限り、闘技場に立つ限り、彼はここで不滅の王だった。\n\nその単純な営みは、彼にすべてをもたらした。\n名を呼ぶ観客の咆哮はローマ最大の闘技場を揺らしたが、彼は鼻で笑った。\n金貨は雨のように降り注ぎ、砂と血の大地を埋め尽くしたが、彼は軽蔑した。\n\nその声も、金も、崇拝も、彼にとっては吐き気を催す穢れに過ぎない。\n\n唯一触れられるのは温かい血だけ。\n唯一真実なのは殺戮のみ。\n彼が求め続けるのは、永遠に変わらぬただ一つ。\n\n「俺は来た、俺は見た、俺は殺した」"
  },
  Item_91765_Name = {
    Text = "血塗られた栄冠"
  },
  Item_91766_Desc = {
    Text = "暗く果てしない迷宮の中に、また新たな迷い人がやってきた。\nそれは、いつも苛立ちと不満を燻ぶらせている蒼白の主を、久しぶりに笑顔にした。\n\n「選びなさい。あたしと契約を結んで、あたしの下僕になるか、それとも迷宮で飢え死にして、やっぱりあたしの下僕になるか」\n\n迷宮に迷い込んだ新人は目を見開いた。\n表情は戸惑い、困惑、恐怖のあいだをめまぐるしく行き来したかと思うと、踵を返して駆け出した。\nこれまでの無数の「先輩」たちと同じように。\n\n「あら、逃げる方を選ぶのね～。あはは、頑張って走りなさい。力の限りね。どうせ、お前は永遠にあたしの迷宮から逃げ出せないんだから」\n\nその後に待つのは、幾百幾千と繰り返された、しかしアグリッパにとっては今なお心躍る一連の過程だった。\n走って、力尽きて、倒れる。\n闇と恐怖に呑まれた人間が助けを求め、叫び、絶望し、やがて精神も肉体も徹底的に砕け散る。\n\n哀れな人間の脳が絶望にかき混ぜられ、どろどろの泥のようになったときこそ、迷宮の主である彼女の出番だ。\n多くを語る必要すらない。\n可哀想で惨めな人間は、ただ本能のままに救いの手を求めて、手を伸ばす。\n\n「助けて……誰でもいい、助けて……」\n\nアグリッパは憐れみと残酷さを同時に湛えたまま、その相手を見下ろし、微笑む。\n「もちろん救ってあげるわ。お前の先輩たちと同じように……私の下僕になりなさい」\n「そう、契約さえ結べば、すべての苦しみも痛みも終わるわよ」\n\n理性を失い、哀れで不憫な人間は、反射的にこくりと頷く。\n暗く果てのない迷宮の中で、蒼白の主は再び笑みを浮かべた。\n\n契約は既に成立した。\nあとは待つだけ——\n彼らが育ち、産み落とされるその時を待つだけだ。"
  },
  Item_91766_Name = {
    Text = "蒼白の契約"
  },
  Item_91767_Desc = {
    Text = "幻衣「蒼白の契約」解放後に解放。\n「契約をして、あたしの下僕になりなさいよ」"
  },
  Item_91767_Name = {
    Text = "アグリッパ・蒼白の契約"
  },
  Item_94417_Desc = {
    Text = "どれだけの時が過ぎようと、彼はあの時代、剣闘士としての栄光を決して忘れない。\n\n「ユウハシュ……」\n\n最初の頃は、金を積んで買った奴隷を紹介する主人が、その名を観客に告げていた。\nだが、彼が敵を皆殺しにし、素手で内臓を引き裂き、その血を飲み干した頃には、闘技場は彼の名を狂ったように叫んだ。\n\n「血を好む者」「悪魔」「闘技場の暴君」……\n呼び名は変わっていき、それにつれ対戦相手も強くなった。\n子供、老人、女、男、虎やライオンさえ、彼の敵となり、すべて敗れ去った。\n\n敗者の断末魔に興味はなく、「何のために戦う？」などという臨終の戯言に気を掛けることもない。\n彼が繰り返したのは、ただ一つ。\n\n殺すこと。\n\n生きている限り、闘技場に立つ限り、彼はここで不滅の王だった。\n\nその単純な営みは、彼にすべてをもたらした。\n名を呼ぶ観客の咆哮はローマ最大の闘技場を揺らしたが、彼は鼻で笑った。\n金貨は雨のように降り注ぎ、砂と血の大地を埋め尽くしたが、彼は軽蔑した。\n\nその声も、金も、崇拝も、彼にとっては吐き気を催す穢れに過ぎない。\n\n唯一触れられるのは温かい血だけ。\n唯一真実なのは殺戮のみ。\n彼が求め続けるのは、永遠に変わらぬただ一つ。\n\n「俺は来た、俺は見た、俺は殺した」"
  },
  Item_94417_Name = {
    Text = "血塗られた栄冠"
  },
  Item_94418_Desc = {
    Text = "暗く果てしない迷宮の中に、また新たな迷い人がやってきた。\nそれは、いつも苛立ちと不満を燻ぶらせている蒼白の主を、久しぶりに笑顔にした。\n\n「選びなさい。あたしと契約を結んで、あたしの下僕になるか、それとも迷宮で飢え死にして、やっぱりあたしの下僕になるか」\n\n迷宮に迷い込んだ新人は目を見開いた。\n表情は戸惑い、困惑、恐怖のあいだをめまぐるしく行き来したかと思うと、踵を返して駆け出した。\nこれまでの無数の「先輩」たちと同じように。\n\n「あら、逃げる方を選ぶのね～。あはは、頑張って走りなさい。力の限りね。どうせ、お前は永遠にあたしの迷宮から逃げ出せないんだから」\n\nその後に待つのは、幾百幾千と繰り返された、しかしアグリッパにとっては今なお心躍る一連の過程だった。\n走って、力尽きて、倒れる。\n闇と恐怖に呑まれた人間が助けを求め、叫び、絶望し、やがて精神も肉体も徹底的に砕け散る。\n\n哀れな人間の脳が絶望にかき混ぜられ、どろどろの泥のようになったときこそ、迷宮の主である彼女の出番だ。\n多くを語る必要すらない。\n可哀想で惨めな人間は、ただ本能のままに救いの手を求めて、手を伸ばす。\n\n「助けて……誰でもいい、助けて……」\n\nアグリッパは憐れみと残酷さを同時に湛えたまま、その相手を見下ろし、微笑む。\n「もちろん救ってあげるわ。お前の先輩たちと同じように……私の下僕になりなさい」\n「そう、契約さえ結べば、すべての苦しみも痛みも終わるわよ」\n\n理性を失い、哀れで不憫な人間は、反射的にこくりと頷く。\n暗く果てのない迷宮の中で、蒼白の主は再び笑みを浮かべた。\n\n契約は既に成立した。\nあとは待つだけ——\n彼らが育ち、産み落とされるその時を待つだけだ。"
  },
  Item_94418_Name = {
    Text = "蒼白の契約"
  },
  Item_94440_Desc = {
    Text = "覚醒体「ムシェット」獲得で解除"
  },
  Item_94440_Name = {
    Text = "ムシェット"
  },
  Item_94441_Desc = {
    Text = "それは古代の意志の失われた霊識である。ミサグは神秘的な儀式を通じて覚醒体の霊識を啓発し、受けた影響を受けた覚醒体は精神能力を永遠に強化される。\n繰り返しモカを得ることで転換を得られ、モカの霊知啓発を活動させるために使用する。"
  },
  Item_94441_Name = {
    Text = "欠片・ムシェット"
  },
  Item_94441_StoryDesc = {
    Text = "繰り返し茉夏を得ることで転換を得られ、茉夏の啓霊を活動させるために使用する。"
  },
  Item_94442_Desc = {
    Text = "覚醒体「本源オージル」を獲得後にロック解除"
  },
  Item_94442_Name = {
    Text = "本源オージル"
  },
  Item_94443_Desc = {
    Text = "属性が死亡耐性の運命の札。"
  },
  Item_94443_Name = {
    Text = "理性の灯"
  },
  Item_94443_StoryDesc = {
    Text = "「理性を灯にすれば、人生の霧を晴らせる。」\nかつて、茉夏はそんな言葉を聞いたことがある。\nそれはソロー社の技術者が霧除け灯を調整している時にふと漏らした感慨か？それともフィリンゲンのレストランで誰かが冗談で言ったのか？\n茉夏はもう覚えていない。ただ、彼女がその言葉を聞いた時の、顔に浮かべた社交的な微笑みと、その笑顔の裏に隠された嘲笑だけははっきりと覚えている。\n「灯？ハッ、何て古臭い骨董品、今はみんな懐中電灯を使うわよ。」\n彼女はそれが比喩であることを知らないわけではない。ただ理解する気がないだけだ。\nいつか彼女は死ぬ。そして死んだ後には、理性も霧も存在しない——彼女はこの世界から完全に解放される。\nそれは合理的で必然的な推測だ。彼女がすべきことは、この「必然」が訪れる前の過程を楽しむことだけ。\nしかし、誰も彼女に「必然」が「予想外」にも遭遇することを教えてくれなかった。\n似たような霧、似たような困難、しかしここには霧除け灯も調査団も、彼女が知っているものは何もない。彼女の斧は世の敵を断ち切ることができるが、自身の孤独と困惑が変じた霧を断ち切ることはできない。\n彼女は戻れるのか？戻るのか？一体いつ戻れるのか……\n次々と心の中に浮かぶ問いは、無形の深い水のように、彼女の心をゆっくりと飲み込んでいく。今この瞬間、彼女の心にある唯一の、すべての考えは——\n理性を保つこと。\n狂わないで！狂わないで！狂わないで！\nあの世界の霧、この世界の霧、そして自分の心の霧に直面しても。\n再び戻るために。"
  },
  Item_94444_Name = {
    Text = "ムシェット"
  },
  Item_94445_Desc = {
    Text = "それは古代の意志の失われた霊識である。ミサグは神秘的な儀式を通じて覚醒体の霊識を啓発し、啓発された覚醒体は精神能力が永久に強化される。\n繰り返し本源オジールを得ることで転換を得られ、本源オジールの霊知啓発を活動させるために使用する。"
  },
  Item_94445_Name = {
    Text = "残片・本源オージル"
  },
  Item_94445_StoryDesc = {
    Text = "繰り返し本源オージルを得ることで転換を得られ、本源オージルの啓霊を活動させるために使用する。"
  },
  Item_94446_Name = {
    Text = "負誓·オジール"
  },
  Item_94447_Desc = {
    Text = "属性がクリティカル率の運命の札。"
  },
  Item_94447_Name = {
    Text = "過去は影のように寄り添う"
  },
  Item_94447_StoryDesc = {
    Text = "名も知れぬ疫病が町と村を飲み込み、戦を好む人々は動乱の中で思う存分殺戮を繰り広げ、鉄と血の交響曲が沸き立ち狂乱した。\n恐怖ゆえに、あるいは恐怖を利用して。\n恐怖は目に見えぬ敵、古き敵、致命的な敵。\n彼は失格の騎士であり、恐怖に敗れた。\n\nしかし、かつて厳かに誓った言葉は今も耳に響き続け、一年また一日と、すでに虚無と化した故郷を越えて。\n「私は弱き者に慈悲をもって接し、強き敵に勇敢に立ち向かう。」\n黒夜は凶行者の足跡を隠し、悲鳴と泣き声の奔流が街路を溢れ、群衆はパニックに陥った羊の群れのようだった。\n「私は悪人に対して一切の容赦なく戦い、戦えぬ者のために戦う。」\n槍先は血に染まり、銀の盾は錆び、影は満足げに微笑み、群れをなすカラスが頭上を旋回し、瞳には悪魔の閃光が宿っていた。\n「私は助けを必要とする者を助ける。」\n「あいつだ、あいつが来た。」人々は小声で囁き、恐怖が彼らの顔を歪めた。「うつろな怪物、復讐の亡霊、死の深淵から戻り、己の敵を怨恨の黒い沼へと引きずり込もうとしている。」\nそれは彼だ。彼は忘れていなかった、一度も忘れたことはなかった。\n\nなぜ続けるのか？万物がいつか滅びるならば、栄光と信仰でさえも。\nなぜ退くのか？運命がどれほど嘲ろうとも、人はただ膝を屈して従うしかないのならば。\nただ忠誠に忠実であり、献身に捧げるためだけなのか？\n公国最後の騎士は徒労に問いかけ、魂は残骸と同じく荒廃し、恐怖の残滓が奔放に流れ、滅びの大海へと集まっていった。\nしかし空洞の胸腔は依然として沈黙を守り、失われた答えはまだどこへ行ったかもわからなかった。"
  },
  Item_94448_Desc = {
    Text = "装備者の「狂気爆発」と「追撃」による基礎ダメージを上昇させ、打撃カードの使用に伴い、装備者の打撃ダメージを持続的に上昇させる。"
  },
  Item_94448_Name = {
    Text = "終末まで蹂躙"
  },
  Item_94448_StoryDesc = {
    Text = "「世界が終末に向かうとき、どんな楽しみがあるのだろう？」\nムシェットは知らないが、期待している。\nこの期待は以前とは違い、今回はいくつかの古物を扱う小さな楽しみではなく、世界を尺度とした研究と調査である。そしてこの研究と調査の中で、最も重要で核心となるのは一人の人間——\nミサゴの守秘者。\n「私はこの世界を救う……」\n「この世界は、決して崩壊の運命に向かわない……」\nその理想を抱き、世界の興亡を背負った人がこう約束する。応じて、ムシェットは感動の表情を見せるべきだと知っているが、これは人間社会の暗黙の社交礼儀である。\nしかし、彼女はもう偽装したくない、あるいは、守秘者が@4に直面し、自らを犠牲にして世界を救うのを見た後、宇宙の恐怖を経験した人に対して偽装する必要はないと感じた。\n「偽装」は人間社会のゲームルールで、体面だが退屈であり、宇宙は……宇宙は真実で率直だ——\n生存するか、滅びるか。\nだから、彼女は守秘者への答えも真実で率直だ。\n「私はこの世界が救われるか、滅びるかは気にしない……それよりも、あなたに興味がある。」\n私はあなたが理想を実現できるのか、それとも理想を追求する道で挫折するのかに興味がある。\nまた、この世界があなたの願いに応えるのか、それとも避けられない滅びに向かうのかにも興味がある。\nどちらにしても、それは壮大で貴重な楽しみになるだろう。\n私はその日を常に期待している……\n私の目で、私の斧で、待っている。"
  },
  Item_94449_Desc = {
    Text = "装備者の「狂気解放」が与えるシールドと力を増幅し、「防御」使用時により多くのシールドと力を提供する。"
  },
  Item_94449_Name = {
    Text = "それでもデイジーは開花する"
  },
  Item_94449_StoryDesc = {
    Text = "「花冠をきちんと被りなさい、これがあなたへの叙勲式よ、愛しき小さな騎士よ。」\n雛菊が野原に咲き乱れる頃、怠惰な兵士がいつも護衛という名目で少年を連れ出し、ここをぶらついていた。\nアキタニア公国で最もよく見られる花で編まれた飾り物が、金色の髪にそっと置かれた。\n「閣下、もしかして……訓練をすべきでは？」\n少年はそう言いながらも、素直に白い花冠を正しく被り直した。\nこの小さな植物は常に光の中に浴し、少年の国では希望の象徴でもあった。\n\n再び目を開けた時、あの明るく美しい光景はもはや存在しなかった。\n軍馬が嘶き、敵は侮りながら一斉に押し寄せ、千軍万馬の中で彼はただ一人孤独だった。\nそして、耳障りな喧騒が突然止まった――\n黒い潮が彼の魂へと流れ込んだ。\n続いて響いたのは、長槍が皮肉を貫く裂ける音、血が溢れる音、敵の哀号する声。\nあの顔々に浮かんでいた侮蔑は跡形もなく消え去り、代わりに天地を覆う恐怖と後退が広がった。\nそして少年はただ機械的に手を上げ、突き刺し、引き抜き、また構えた。\n最後の兵士が倒れるまで。\n煙塵が無数の顔を覆い隠し、征服者と征服された者の残骸が地に積み重なり、もはや区別もつかなかった。\n\n影が彼の背に纏わりつき、嘲笑いながら言った。「続けなさい。槍を振り下ろせ、もう一度。」\n「守護者と破壊者の間には、元々一線しかない。今や、お前はすでに選択を下した。」\n\n闇が空を覆い、血が大地に染み渡った。\n彼は遠くの郊野を見やった――たった一夜のうちに、そこは永遠に往日の色彩を失っていた。\n風が少年の衣の裾を吹き上げ、辛うじて残ったその草地をも掠めた。\n静寂の夜の中で、悪魔さえも知らぬ片隅に、かすかな純白がまだ彼の瞳の奥に残っていた。\nそれはこの国の最後の一輪の雛菊で、誰も気に留めぬ場所でひっそりと育っていた。\n赤に染まり、茎は折れ曲がりながらも、それでもまだ倒れてはいなかった。"
  },
  Item_94559_Desc = {
    Text = "このキーオーダーを記録すると、編成時にキーオーダースキル「狩りの決意」を選択可能。\n\nここは、かつてミサゴが戦士たちに約束した地。あの壺には蜜が、あの棚には肉がある。\n勇敢な戦士たちを阻むものは何もない。彼らは必ず、自らの手で得るべきものを取り戻すだろう。"
  },
  Item_94559_Name = {
    Text = "狩りの決意"
  },
  Item_94559_StoryDesc = {
    Text = "ここは、かつてミサゴが戦士たちに約束した地。あの壺には蜜が、あの棚には肉がある。\n勇敢な戦士たちを阻むものは何もない。彼らは必ず、自らの手で得るべきものを取り戻すだろう。"
  },
  Item_94660_Desc = {
    Text = "幻衣「霊性の再生」獲得後解放。\n「すべての脳が同じ知恵と幸運を持つわけではない」"
  },
  Item_94660_Name = {
    Text = "ドール・霊性の再生"
  },
  Item_94733_Desc = {
    Text = "「学期課題」にて「核心課題」を購入した後に獲得。\n「一つの極秘文書の表紙の写真で、撮影者はカメラを直視するのが恥ずかしく、笑顔が非常にぎこちない。」"
  },
  Item_94733_Name = {
    Text = "ぼんやりとしたアーカイブ写真：オルラ"
