  Item_95179_Name = {
    Text = "豊かさの「印」"
  },
  Item_9517_Desc = {
    Text = "メイン能力はクリティカル率、クリティカルダメージ、界域知識、黒章ドロップからランダムに1つ獲得。"
  },
  Item_9517_Name = {
    Text = "有機形態Ⅱ"
  },
  Item_9517_StoryDesc = {
    Text = "鱗翅目は孤独、愛、絶望に死す。"
  },
  Item_9518_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「注射の加護」を選択可能。\n\n彼女は「痛くない」と言った——\nでも、それは嘘だ。\n彼女は誰よりも痛みを怖がる子だったから。"
  },
  Item_9518_Name = {
    Text = "注射の加護"
  },
  Item_9518_StoryDesc = {
    Text = "彼女は「痛くない」と言った——\nでも、それは嘘だ。\n彼女は誰よりも痛みを怖がる子だったから。"
  },
  Item_9519_Desc = {
    Text = "メイン能力は界域知識、黒章ドロップ、死亡抵抗、ダメージ強化からランダムに1つ獲得。"
  },
  Item_9519_Name = {
    Text = "深紅の抱擁Ⅵ"
  },
  Item_9519_StoryDesc = {
    Text = "伝説の最初のゴーレム創造主、ゴーレムを自らの手で殺す。"
  },
  Item_9520_Desc = {
    Text = "メイン能力はクリティカル率、クリティカルダメージ、死亡抵抗、ダメージ強化からランダムに1つ獲得。"
  },
  Item_9520_Name = {
    Text = "四月の賛歌Ⅲ"
  },
  Item_9520_StoryDesc = {
    Text = "彼は@2年の春に埋葬された。"
  },
  Item_9521_Desc = {
    Text = "蠕動し、ねじれ、暗闇を這い回る……シュー……シュー……\n寄生された虫蛹。\n血肉界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_9521_Name = {
    Text = "原生虫の蛹"
  },
  Item_9522_Desc = {
    Text = "密約転写時に2つのサブ能力を固定する。材料変換で「密約の断片」に交換可能。\n\n今でも、その筆跡を懐かしんでいる。"
  },
  Item_9522_Name = {
    Text = "追憶の羽ペン"
  },
  Item_9523_Desc = {
    Text = "企画試験用SR武器のみ"
  },
  Item_9523_Name = {
    Text = "試作長剣（界域）開発用"
  },
  Item_9524_Desc = {
    Text = "メイン能力はクリティカル率、クリティカルダメージ、界域知識、黒章ドロップからランダムに1つ獲得。"
  },
  Item_9524_Name = {
    Text = "荒野の狼Ⅱ"
  },
  Item_9524_StoryDesc = {
    Text = "ワオーン、ワオーン。"
  },
  Item_9525_Desc = {
    Text = "メイン能力はクリティカル率、クリティカルダメージ、死亡抵抗、ダメージ強化からランダムに1つ獲得。"
  },
  Item_9525_Name = {
    Text = "薬となる夢Ⅲ"
  },
  Item_9525_StoryDesc = {
    Text = "千年前、5分は40オンスの細砂に等しかった。"
  },
  Item_9526_Desc = {
    Text = "メイン能力はクリティカル率、クリティカルダメージ、死亡抵抗、ダメージ強化からランダムに1つ獲得。"
  },
  Item_9526_StoryDesc = {
    Text = "科学はスペクトル分析、芸術は光合成。"
  },
  Item_9527_Desc = {
    Text = "そう、すべては精錬可能だ。あなたの本能、理性、そして心さえも……結局、あなたは彼らと何も変わらないことに気づくでしょう。\n深海界域の覚醒体を昇格させるための素材。"
  },
  Item_9527_Name = {
    Text = "本能の精錬"
  },
  Item_9528_Name = {Text = "南京錠"},
  Item_9529_Desc = {
    Text = "装備者が与えるシールドと治療効果を高め、装備者の反撃獲得能力を強化する運命の札。"
  },
  Item_9529_Name = {
    Text = "疼痛の鰭"
  },
  Item_9529_StoryDesc = {
    Text = "（以下の回答はクレメンタインの診療手帳からの抜粋で、参考用です）\n\n1. カエクス。\n2. 16、17…………？誰が知るか。\n死んだ後、こんな無意味なことを気にして何になる？\n3. ぼろぼろの漁村、地図には載っていない。\n4. 言いたくない。\n5. 奇妙な奴、醜い化け物、愚か者、馬鹿@1…………よくあることだ。 \n6. 黄金に輝くナマズのような顔、略してナマズ顔。\n7. 雨の日。\n8. わからない。雨の日には浜辺を歩き回る…………\n何年もそうしてきた。ただ遠くを見ているだけ。\n9. 言っただろう、#¥%わからないんだ@1消えろ！！\n-------\n14. うーん…………もしかするとオーン叔父さんが言ってたことが頭に残っているのかもしれない。\n「雨の日に大帆船で、お前を『家』に迎えに行く」って…………\n15. そうだ、彼は約束を果たした…………\n俺は数日間、海底を漂っていた。喉が渇き、腹も減り、全身が痛んだ…………\nそして白い大帆船とオーン叔父さんの姿が見えた。\nいや、正確には帆船のマストにぶら下がる彼の骨だった——彼も変異に失敗した。\n最後の力を振り絞り、船へと泳ぎ、マストの上で彼に寄り添った。\n16. 俺たちは、一緒に家へ帰ると約束したんだ。"
  },
  Item_9530_Desc = {
    Text = "装備者のライフ回復能力を高め、狂気解放で一定の遅延治療を獲得できる。"
  },
  Item_9530_Name = {
    Text = "導きの帆"
  },
  Item_9530_StoryDesc = {
    Text = "カシュリアには沈没文明の伝説が伝わっている。\n\n歴史記録以前に、星辰の異常な移動がある先史文明を海底に沈めたとされ、カシュリア人はその文明の子孫だという。\n商業や漁業の他に、カシュリア人が海に出る大きな目的は、失われた祖先の文明を探すことだった。\n特定の星辰の位置の刻に生まれた少女が祖先の文明と感応し、沈没文明の位置を指し示し、船団を風浪から守ると彼らは信じていた。\n\nシレストはそのように選ばれた。\n彼女は白い帆を高く掲げたマストに縛り付けられ、下の人々の忙しさを見ていた。\n彼女は関心も興味も持たなかった。\n\nシレストは海風や海鳥の動きから海上の天気を感じ取ることができ、時には遠く眠る地からの気配を探知することもあった。\n彼女は生まれつき海に、航海に属しているのだろう——シレストはよくそう思い、拘束されている事実は彼女の心に何の波紋も起こさなかった。\n時々彼女はマストを離れ、海空を飛ぶ白い鳥を追いかけ、その時船は彼女を追い続けた。\n人々は少女が航海の順調の象徴であり、祝福された船は無事に帰港し、多くの富と先進的な文明をもたらすと信じていた。\nしかし、彼女はそれを何も知らなかった。"
  },
  Item_9531_Desc = {
    Text = "クリティカルダメージの能力を持つ命輪。"
  },
  Item_9531_Name = {Text = "呼吸"},
  Item_9531_StoryDesc = {
    Text = "深呼吸して、ドミニク。"
  },
  Item_9532_Name = {
    Text = "祭祀のナイフ"
  },
  Item_9533_Name = {
    Text = "シルバーキー"
  },
  Item_9534_Desc = {
    Text = "これで誰も占いに使おうとは思わないだろう。\n融蝕液に覆われた紫色の水晶。\n超次元界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_9534_Name = {
    Text = "破損した鉱晶"
  },
  Item_9535_Desc = {
    Text = "メイン能力はクリティカル率、クリティカルダメージ、界域知識、黒章ドロップからランダムに1つ獲得。"
  },
  Item_9535_Name = {
    Text = "生命力搾取Ⅱ"
  },
  Item_9535_StoryDesc = {
    Text = "へその緒は無限の未来に繋がっている。"
  },
  Item_9536_Desc = {
    Text = "融蝕漿から抽出された高純度の源液。非常に貴重で、シルバーコアへ精製・減衰が可能。\n\n「源液」消費時、贈呈分の「源液」が優先的に差し引かれる。\n抽出：{s1}\n贈呈：{s2}"
  },
  Item_9536_Name = {
    Text = "プラチナジェル"
  },
  Item_9537_Desc = {
    Text = "企画試験用SR武器のみ"
  },
  Item_9537_Name = {
    Text = "試作長剣（クリティカル）開発用"
  },
  Item_9538_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nファロスを再度獲得した際に変換され、ファロスの霊知啓発を起動するために使用。"
  },
  Item_9538_Name = {
    Text = "欠片・ファロス"
  },
  Item_9538_StoryDesc = {
    Text = "ファロスを再度獲得した際に変換され、ファロスの霊知啓発を起動するために使用。"
  },
  Item_9539_Desc = {
    Text = "ウインクルが故郷から持ち込んだ神秘技術で作られた特別な許可。時間を圧縮し、流れを加速させ、守秘者が試練を早く終えるのを助ける。\n「融蝕の廃墟」と「禁忌編纂」のステージで三つ星を達成後、このアイテムを消費してリプレイ可能。"
  },
  Item_9539_Name = {
    Text = "時間圧縮許可（廃棄済み）"
  },
  Item_9540_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nリッツを再度獲得した際に変換され、リッツの霊知啓発を起動するために使用。"
  },
  Item_9540_Name = {
    Text = "欠片・リッツ"
  },
  Item_9540_StoryDesc = {
    Text = "リッツを再度獲得した際に変換され、リッツの霊知啓発を起動するために使用。"
  },
  Item_9541_Desc = {
    Text = "それは工芸品ではなく、錬金術師にぶつかった蝶の悲劇的な結末。\n普通の蝶水晶。混沌界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_9541_Name = {
    Text = "失色の蝶水晶"
  },
  Item_9542_Desc = {
    Text = "災厄が磨いた奇跡。\n毎週の試練で獲得できる希少な融蝕結晶で、月光のような輝きを放つ。ミサゴ商店でアイテムと交換可能。"
  },
  Item_9542_Name = {
    Text = "融蝕の珠"
  },
  Item_9543_Desc = {
    Text = "無数の戦争がこれによって始まった。\n「第五元素」と呼ばれる赤いクリスタルで、その錬成方法はすでに失われている。\n汎用の覚醒体スキル向上素材。"
  },
  Item_9543_Name = {
    Text = "賢者の石"
  },
  Item_9544_Desc = {
    Text = "歴史は繰り返すが、宇宙は例外かもしれない。\n神秘的な文字が記された紙片。\n混沌界域の覚醒体を昇格させるための素材。"
  },
  Item_9544_Name = {
    Text = "純白の紙片"
  },
  Item_9545_Desc = {
    Text = "「自分が再び立ち上がれるとは思わなかった。正義のために再び戦える機会を得たことは光栄だ」\n・チームのデバフを解除\n・爆発的な防御能力。"
  },
  Item_9545_Name = {Text = "アルバ"},
  Item_9546_Desc = {
    Text = "彼女は直視されるのを嫌う、それが彼女の内なる弱さを暴露するから。\n・防壁を作り、攻撃を防ぐ\n・毒を仕込み、敵を打ち砕く。"
  },
  Item_9546_Name = {
