  },
  Item_9547_Name = {
    Text = "標準密約SSR"
  },
  Item_9549_Desc = {
    Text = "風通しの良い家。それでも無いよりはマシ。\n残された蛹の殻。\n血肉界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_9549_Name = {
    Text = "風乾した蛹"
  },
  Item_9550_Desc = {
    Text = "クリティカルダメージの能力を持つ命輪。"
  },
  Item_9550_StoryDesc = {
    Text = "我々は空っぽの人間、我々は藁人形。"
  },
  Item_95510_Desc = {
    Text = "深海に古来より伝わる秘聞を記した、神秘的な古書。\n「忘却篇」の「深海」界域の限定運命の札を1つ無料で獲得可能。"
  },
  Item_95510_Name = {
    Text = "深海の秘典・忘却篇"
  },
  Item_95511_Desc = {
    Text = "あなたがよく知る世界において、混沌界域を指定して覚醒を行うための根源捕獲技術。\n「忘却篇」の「混沌」界域の限定覚醒体を1体無料で召喚可能。"
  },
  Item_95511_Name = {
    Text = "混沌の共鳴・忘却篇"
  },
  Item_95512_Desc = {
    Text = "あなたがよく知る世界において、血肉界域を指定して覚醒を行うための根源捕獲技術。\nそこから「忘却篇」の「血肉」界域の限定覚醒体を1体無料で召喚可能。"
  },
  Item_95512_Name = {
    Text = "血肉の誕臨・忘却篇"
  },
  Item_95513_Desc = {
    Text = "精神次元における覚醒装置の係留点を解除し、精神リンク装置のみで根源の捕獲を行うことで、刹那的な未知の共振が引き起こされる。\n「忘却篇」のランダムな限定覚醒体を1体無料で召喚可能。"
  },
  Item_95513_Name = {
    Text = "根源の捕獲・忘却篇"
