  Item_9551_Desc = {
    Text = "翅は美しさをもたらすのみ。5ペニーの価値。\n輝色の蝶水晶。体の大部分が結晶化されている。\n混沌界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_9551_Name = {
    Text = "輝色の蝶水晶"
  },
  Item_9552_Desc = {
    Text = "メイン能力は、クリティカル率、クリティカルダメージ、キーチャージ、狂気増加の中からランダムに1つを獲得。"
  },
  Item_9552_Name = {
    Text = "標準密約SSR"
  },
  Item_9553_Desc = {
    Text = "「環行・ラモンナ」を振り向かせるための道具。使用すると「ラモナ」の起源形態が解放される。\n\nあなたは彼女の新たな悪夢にはならない、あなたが彼女のそばを離れないから。"
  },
  Item_9553_Name = {
    Text = "失われた響き"
  },
  Item_95548_Desc = {
    Text = "このキーオーダーを記録すると、編成時にキーオーダースキル「沈まぬ太陽」を選択可能。\n\nたとえ偽りの太陽が空を覆っても、真の太陽は決して消えはしない。\n今この一瞬の日没は、より激しく燃え盛る太陽を生み出すためのものだ。\nそして今、琥珀色の炎をまとった太陽が再び昇り、二度と沈むことはない。"
  },
  Item_95548_Name = {
    Text = "沈まぬ太陽"
  },
  Item_95548_StoryDesc = {
    Text = "たとえ偽りの太陽が空を覆っても、真の太陽は決して消えはしない。\n今この一瞬の日没は、より激しく燃え盛る太陽を生み出すためのものだ。\nそして今、琥珀色の炎をまとった太陽が再び昇り、二度と沈むことはない。"
  },
  Item_9554_Desc = {
    Text = "メイン能力は、界域知識、狂気増加、黒章ドロップ、キーチャージの中からランダムに1つを獲得。"
  },
  Item_9554_Name = {
    Text = "深紅の鼓動Ⅳ"
  },
  Item_9554_StoryDesc = {
    Text = "伝説の最初のゴーレム創造主、血液でゴーレムを養う。"
  },
  Item_9555_Desc = {
    Text = "そう、すべては精錬可能だ。あなたの本能、理性、そして心さえも……結局、あなたは彼らと何も変わらないことに気づくでしょう。\n深海界域の覚醒体を昇格させるための素材。"
  },
  Item_9555_Name = {
    Text = "精神の精錬"
  },
  Item_9556_Desc = {
    Text = "経験値が一定値に達すると、調査レベルが上がる。調査ステージや強化演習などでエンフェリンを消費して獲得可能。"
  },
  Item_9556_Name = {Text = "経験値"},
  Item_9557_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nアグリッパを再度獲得した際に変換され、アグリッパの霊知啓発を起動するために使用。"
  },
  Item_9557_Name = {
    Text = "欠片・アグリッパ"
  },
  Item_9557_StoryDesc = {
    Text = "アグリッパを再度獲得した際に変換され、アグリッパの霊知啓発を起動するために使用。"
  },
  Item_9558_Desc = {
    Text = "無垠の海に逸散した感情粒子。触れると「任せて」という言葉が聞こえるような気がする。\nシークレットキーパーが調査イベント「倒錯の群星」における共鳴を高めるために使用する。\n「倒錯の群星」ステージの初回クリア報酬で入手可能。"
  },
  Item_9558_Name = {
    Text = "渇望の心"
  },
  Item_95592_Desc = {
    Text = "大量の珍しい凝晶が詰まった箱で、研究員のどれだけの髪が消費されたのかはわからない。無秩序な細胞は混乱と豊かな美で満ちており、覚醒体は自らの力を迅速に向上させることができる。\n「ネクロティック・エスティティックス」期間中限定で提供。"
  },
  Item_95592_Name = {
    Text = "ミメーシス支援箱"
  },
  Item_95593_Desc = {
    Text = "すべての力の秘訣がこの赤いクリスタルに凝縮されている。この箱を開けるその瞬間、あなたはミサグがあなたに寄せる信頼と決意を感じることができる。校方はすべてのリソースを注ぎ込むことで、優れた守秘者を育成できると信じている。\n「ネクロティック・エスティティックス」の期間中に限り供給。"
  },
  Item_95593_Name = {
    Text = "賢石支援箱"
  },
  Item_95594_Desc = {
    Text = "ミサガは特に勤勉な調査員のために、訓練支援物資を準備し、大量の厳しい練習と組み合わせることで、強力な覚醒体の部隊を迅速に鍛え上げることができる。\n「死霊の美学」の期間中に限り供給。"
  },
  Item_95594_Name = {
