  },
  Item_95674_Desc = {
    Text = "クリティカルダメージの能力を持つ命輪。"
  },
  Item_95674_Name = {Text = "珍味"},
  Item_95674_StoryDesc = {
    Text = "静かに死を迎えた魂だけが、じっくりと味わうに値する。生者のあがきは、ただ味わいを雑然と濁らせるだけだ。\n円卓に運ばれてきたとき、皿にはまだほのかな温もりが残っていた。中央には心臓がひとつ、安らかに横たわっている。表面は微かに脈打つように盛り上がり、まるでつい先ほど最後の一拍を打ち終えたばかりのようだった。脇には二つの眼球が添えられ、瞳孔には死の直前、その一瞬の驚愕が封じ込められ、煮込まれて従順な乳白色へと変わっていた。\n彼はナイフを持ち上げ、ゆっくりと心尖に刃を入れたが、ふと手を止めた。\nその魂は今もなお、かすれた声で叫び続け、ひと筋の執念が血管の中に滞留したまま、散りきっていなかった。彼はナイフを置き、両手を合わせ、静かに亡霊の声に耳を傾けた。\nこの心臓は、死の直前まで病苦に苛まれていた一人の詩人のものだった。死によって積年の失意からは解放されたものの、いまだ生への未練が残っていた。彼は知っていた。この心臓を真に「馴染ませる」ためには、料理に相応の敬意を払わねばならない。その唯一の方法は、待つことだった。\nただ待つのだ——肉に絡みついた執念が、死の中で完全に崩れ去るのを。亡者の記憶の最後の残響が沈香となり、血管の壁から静かに滲み出してくるのを。\n彼は両手を優雅に膝の上で組み、目を閉じ、深く息を吸い込んだ。\n香りが空気中にゆっくりと広がる。それは複雑ありながら優しい香りで、恋人の震えや別れの苦みを帯び、墨の香りや薬草の香り、朝霧のようなかすかな臆病さが混じっていた。\n彼は生命が豊かに生い茂る樹の下に静かに腰を下ろし、熟した果実が期せずして落ちるのを待っている。"
  },
