  Item_9568_Desc = {
    Text = "彼女は絶対的な純粋美を追求し、刹那を永遠に刻む。\n・遅延シールドを付与し、同時にダメージを与える\n・シールドを付与し触腕を獲得。"
  },
  Item_9568_Name = {
    Text = "サンガー"
  },
  Item_95690_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nドゥルセインを再度獲得した際に変換され、ドゥルセインの霊知啓発を起動するために使用。"
  },
  Item_95690_Name = {
    Text = "欠片・ドゥルセイン"
  },
  Item_95690_StoryDesc = {
    Text = "ドゥルセインを再度獲得した際に変換され、ドゥルセインの霊知啓発を起動するために使用。"
  },
  Item_95691_Desc = {
    Text = "このキーオーダーを記録すると、編成時にキーオーダースキル「残酷な敬意」を選択可能。\n\n満月は天に昇り、グールの王があなたに敬意を示す。\n今宵、我らは敵の頭蓋を啜り、憎しみを味わう。\n今宵、我らは愛する者の肋骨をもって、永遠を測る。"
  },
  Item_95691_Name = {
    Text = "残酷な敬意"
  },
  Item_95691_StoryDesc = {
    Text = "満月は天に昇り、グールの王があなたに敬意を示す。\n今宵、我らは敵の頭蓋を啜り、憎しみを味わう。\n今宵、我らは愛する者の肋骨をもって、永遠を測る。"
