  },
  Item_95699_Desc = {
    Text = "装備者の与える基礎ダメージを強化し、探索が進むにつれて狂気解放のダメージとクリティカル率を持続的に増加させる命輪。胎胚を捕食するたび、追加の狂気を獲得する。"
  },
  Item_95699_Name = {
    Text = "安息の口づけ"
  },
  Item_95699_StoryDesc = {
    Text = "死を恐れる必要はない。それはただ、肉体が魂を夜の闇へと返す過程に過ぎず、潮が引くように、深い安らぎへと還るだけだ。完全に融蝕へと溶け、誰にも知られず、何の意味も持たぬ存在へとなり果てることこそ、真の恐怖である。\n彼女の死は、消して安らかなものではなかった。\n枯れ衰えた体は冷え切り、血は融蝕液と混じり合い、暗赤色のガラスのように固まっていた。だが、彼女の若い魂はいまだに喉の奥で震えていた。消えきらないわずかな意識が、煙のように骨の隙間に滞留している。まるで翼の折れた、脆く美しい蝶のように。\nドゥルセインは静かに部屋へ足を踏み入れた。その足取りは塵ひとつも揺らさなかった。彼は彼女の傍らに跪き、固く閉じられた瞼、強張った指の節、そして不安げに揺れる魂へと、優しく視線を滑らせた。\n「私は、まだ生きているの？」\n「この闇は、私を飲み込んでしまうの？」\n彼は答えなかった。ただ手を伸ばして、ひび割れた彼女の指を一本ずつ広げていく。まるで震える花弁の折れ目を、そっと撫でて整えるかのように。そこには哀れみも、咎めもなかった。あるのは、ただ穏やかで静謐な忍耐だけ。あたかもこの世で最も公正で荘厳な神が、彼女に安らぎの権利を授けるかのようだった。その刹那、彼女は永遠の静寂に触れたように感じた。\nやがて、二人が重ねた手から清らかな芳香が漂い出した。彼は身を屈め、満ち足りた表情で、そして厳かに彼女の指の甲へそっと口づけを落とした。その口づけが落ちた瞬間、死の最後の余韻はゆっくりと引き延ばされ、やがて空へ溶ける一陣の風となった。嵐が去った湖のように、あたりは静まり返った。疑いも、怨みも、恐れも、もはやどこにもない。彼女はようやく、死そのものへと還ったのだ。\n「あなたのことを、忘れはしません」\n彼は身を起こし、今や完全に静寂に包まれた彼女の姿を見つめる。そのとき、ふと意識が揺らぎ、鋭い牙が肌を貫く感覚とともに、彼はセリーヌの声を聞いた。\n「信じています、お兄さま」\n彼女は幸福だ。ドゥルセインの記憶の中で永遠の安息を得るのだから。"
  },
  Item_9569_Desc = {
    Text = "メイン能力は、界域知識、狂気増加、黒章ドロップ、キーチャージの中からランダムに1つを獲得。"
  },
  Item_9569_Name = {
    Text = "36の廻る部屋Ⅳ"
  },
  Item_9569_StoryDesc = {
    Text = "回転して、忘れる——それが彼女の人生のすべて。"
  },
  Item_95700_Desc = {
    Text = "イベント「死霊の美学」でアチーブメントを完了して獲得。\n「死の美は、静かで永遠です。」"
  },
  Item_95700_Name = {
    Text = "銀の鍵の名のもとに：ドゥルセイン"
  },
  Item_95700_StoryDesc = {
    Text = "杜勒赛因のプレイスタイルの活動"
  },
  Item_95701_Desc = {
    Text = "ネクロポリスの主は、亡者が冒涜されるのを好まない。たとえこれらの残骸であっても例外ではない。レストランでそれなりの贈り物と交換できるかもしれない。\n\n最低{s1}個ドロップ"
