  Item_95703_Name = {
    Text = "腐敗した手の骨"
  },
  Item_95704_Desc = {
    Text = "ネクロポリスの主は、亡者が冒涜されるのを好まない。たとえこれらの残骸であっても例外ではない。レストランでそれなりの贈り物と交換できるかもしれない。\n\n最低{s1}個ドロップ"
  },
  Item_95704_Name = {
    Text = "腐敗した手の骨"
  },
  Item_9570_Desc = {
    Text = "持有者の指令カード効果を全面的かつ総合的に向上させ、「黒渦消滅」を通じてより多くの鍵エネルギー獲得と単発の鍵令効果向上を柔軟に選択できる総合型の運命の札。"
  },
  Item_9570_Name = {
    Text = "詩の結び"
  },
  Item_9570_StoryDesc = {
    Text = "彼女が温室で目を覚ましたとき、すでに大火は庭全体を覆い、彼女の目の前に迫っていた。\n温室のドアは外から鍵がかけられ、空気には強いアルコールと油脂の匂いが漂う。彼女はコレットの名前を大声で呼び続け、声が煙でかすれるまで叫んだが、応えるのは大火の轟音だけだった。\n\n彼女は安堵した。よかった。コレットは外出している。\nこんな火事では彼女も危険だった。\n\n彼女は悲しかった。人生の最後の瞬間に、親友に最後に会えなかったことが。\nコレットが戻ってきて、焼けた庭と自分を見たら、きっと悲しむだろう。\n\n彼女は後悔した。二人の生活は良くなり始めていたのに、この炎がすべてに終わりを告げようとしている。\n\n燃える。\n家が燃える。空が燃える。葉が燃える。花が燃える。\n庭園で過ごした数々の光景が、彼女の眼前で次々と浮かんでいき、流れていく。\n彼女が庭に連れてきてくれたこと。\n彼女が薔薇を渡してくれたこと。\n彼女が一日の労働の末に柔らかいパンを持ってきてくれたこと。\n彼女たちが遊び、追いかけ、静かな陽光の下で寝そべり、伯爵夫人の部屋に住む日を夢見ていたこと。\n\n燃える。\n過去が燃える。未来が燃える。庭はすべての物語と感情を抱えて、狂ったように燃えている。\n\n涙が彼女の顔を滑り落ち、炎の熱で消えていった。\n\n彼女は美を感じていた。詩の中では、痛みも後悔も美しいのだ。\n彼女は周囲を見渡し、炎に侵された紙とペンを見つけた。\n\n感謝、愛着、未練、祝福、美。その美しさすべてをコレットに残したい。\n\n「……コレットへ。オルラ、炎の中より」\n詩の結びに、彼女は最後の署名を残した。\n\n百メートル先、庭の向かいの道で、コレットは何かを感じたように足を止める。彼女が顔を上げると、激しい炎が彼女の顔を照らしていた。\n\n涙が彼女の顔を滑り落ち、炎の熱で消えていった。"
  },
  Item_9571_Desc = {
    Text = "神秘的な紫色の輝きを放つ。カンブリア渓谷に隕石が落ちた際の残骸と言われている。\n超次元界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_9571_Name = {
    Text = "隕石の破片"
  },
