  Item_9574_Desc = {
    Text = "「フラスコは新品のように洗い、机は反射するまで磨き、天秤は三日ごとに再校正する」\n・チームに狂気を提供\n・チームのライフを大量に回復。"
  },
  Item_9574_Name = {Text = "ドール"},
  Item_9575_Desc = {
    Text = "これで誰も占いに使おうとは思わないだろう。\n融蝕液に覆われた紫色の水晶。\n超次元界域の覚醒体のスキルレベルを上げるために使用。"
