  },
  Item_9576_Desc = {
    Text = "メイン能力は、クリティカル率、クリティカルダメージ、キーチャージ、狂気増加の中からランダムに1つを獲得。"
  },
  Item_9576_Name = {
    Text = "歪みの双子・白Ⅰ"
  },
  Item_9576_StoryDesc = {
    Text = "霧白の祈り。"
  },
  Item_9577_Desc = {
    Text = "敵の撃破に伴い永久的に大量のクリティカルダメージを向上させ、躍遷効果発動後に本ターンのダメージ能力をさらに高めるバフ型の運命の札。"
  },
  Item_9577_Name = {
    Text = "至高の秘蔵品"
  },
  Item_9577_StoryDesc = {
    Text = "あなたが初めて生きたゴーレムを見たのは、女学者の家だった。\n「今でも彼女には驚かされるの。私にとって、彼女は宇宙そのものですわ」\n彼女——そのゴーレムは機械的な微笑を見せ、口からは不明瞭な呟きを漏らす。\nその灰色の瞳を見つめると、荒れ狂う灰色の海の中で波の光が地平線から別の地平線へと移ろうようだった。\n\n家を去る前、女学者はあなたにゴーレムの製作法が記された古びた手記を手渡した。  \nその夜、あなたはそれを広げ、乱雑に記された術式や呪文を読み込む。  \nしかし、脳裏にはゴーレムの不可解な微笑が焼き付いて離れない——  \nあなたは、彼女を決して忘れることができなかった。  \n\n数日後、あなたは口実を作り、再びその家を訪れる。 \n山積みの書籍、器具、骨格を越え、厚いカーテンと絡みつく蜘蛛の巣をかき分けて、最後にゴーレムの前に跪いた。\n隅に身を丸めた女学者は、わずか数日で痩せ衰え、瞳から光を失っていた。  \n「やはり来たのね……他の者たちと同じように」  \n彼女は弱々しく咳をする。  \n\n「ええ……僕はきました」\nあなたはゴーレムの手を拾い、繰り返し唇を押し当てる。  \n冷たい指先があなたの首筋を優しく撫でると、微細な痛みが伴い、あなたはゆっくりと瞼を閉じた。  \n\n——目覚めた時、あなたは柔らかな海の波に揺られ、白い陽光に包まれていた。  \n身体は軽く、まるで魂が肉体を捨て去ったような浮遊感に襲われる。  \nあなたは振り返り、そこに無数の灰黒色の頭部があるのを見た。  \nそれらは泣き叫び、歪み、まるで黒い野花のように密集して、灰色の原質の海に咲き乱れていた。  \n\n「いやだ——」\n喉から黒い粘液が吐き出される。あなたはもう動けなくなっていた。\nあなたもまた、彼らの一員となったのだ。  \n\n「@2年6月、著名な錬金術師ロマリン・ルートヴィヒが、書斎で謎の死を遂げた。  \n彼の首は忽然と消え去り、あの神秘的な錬金術の手記も同時に行方不明となった……」  \n\n（この記録はミサゴ図書館の《錬金術逸話》第二巻に記載されています）"
  },
  Item_9578_Desc = {
    Text = "ウインクル開発の神秘的な製剤。調査員が密境で理性を保つのを助ける。副作用は不明で、慎重に使用した方がよい。\n\n所持数が300未満の場合、5分毎に1本自動で補充される。\n所持数が300を超えると 15分毎に1本自動で補充される。\n最大3000本まで所持できる。"
  },
  Item_9578_Name = {
    Text = "エンフェリン"
  },
  Item_9579_Desc = {
    Text = "密約の本質は禁忌で、認識しにくい知識である。拓片を使って再描写すると、密約の力がさらに強化される。"
  },
  Item_9579_Name = {
    Text = "密約の拓写（廃止済み）"
  },
  Item_9580_Name = {
    Text = "海踊教団のロゴ（不明瞭）"
  },
  Item_9581_Desc = {
    Text = "<SummonBlue:『星辰の正位置』獲得報酬UP>\nより堅固なシールドを提供すると同時に爆発ダメージを高めより多くの鍵エネルギーを獲得し、触腕の打撃に伴い自身の狂気循環を加速する総合的な運命の札。"
  },
  Item_9581_Name = {
    Text = "秘められた誕生"
  },
  Item_9581_StoryDesc = {
    Text = "母親、お母様。\n\nマーフィーはそれに関するほとんどの記憶を、とうに失ってしまっている。\n\nある人は言った。瀕死の母親は彼女を庇い、隠したが、母親の血で窒息寸前であったのだと……\n\nそして人々が駆け寄り、無理やり彼女たちを引き離したのだと。\n\nマーフィーは、その瞬間の母の顔を見ていた。\nその顔は狂気に満ちていたが、とても美しかった。\n\n物心ついてから、彼女には新しい「母親」ができた。\n\n彼女は穏やかで思慮深く、マーフィーのあらゆる無茶な要求も満たしたが、つかず離れずの距離を保った。\n\n彼女たちの関係は——ミリアムの表情が永遠に変わらないように——このまま続いていくとマーフィーは思っていた。\n\nしかし、そんな折、彼女は高く掲げられて漆黒の王座に座らされ、夢の中でリン光を放つ「卵」を見た。\n\nそれは暗闇の中でキラキラと輝き、目のようであり、星のようでもあった。\n\n聖域の周囲には、幽玄な歌声が響き渡っていた。\n\n<Italic:その娘の@1から、@1の神が@1へと降臨する……>\n\n彼女は、自分に関係しない偉大な使命を与えられた。\n神を復活させるための母親となることだった。\n\n本当に不思議だ。彼女はまだ、母親とは何か、娘とは何かを理解していないのに、「母親」になることを学ばなければならない。\n\nマーフィーは母親の狂気に満ちた美しい顔を思い出し、舌の上の甘く苦い味を思い出した。\n\nあの美しい人は、わたくしがこのように墓に落ちることを望んでいないのでは？\nそうでしょう？"
  },
  Item_9582_Desc = {
    Text = "メイン能力は、界域知識、狂気増加、黒章ドロップ、キーチャージの中からランダムに1つを獲得。"
