  },
  Item_9610_StoryDesc = {
    Text = "ワード・フィリップス氏に引き取られて以来、アリステアは彼と共にミサゴの高層会議に何度も出席してきた。\n\n高層会議と言っても、実際には毎月一度の討論会のようなものだった：\nフィリップス氏は穏やかな口調で、優しく導く；\nクラークシュは辛辣な言葉で、一歩も譲らない。\n彼らは交互に賛成または反対の立場を取り、ミサゴの未来や来月の覚醒学部の予算配分について激しく議論した。\nタヴィ嬢は静かな傍観者で、簡単には意見を出さない。\n彼自身は正直な得点係を務め、時には審判を兼任し、ある時は小さな会議テーブルを守るために格闘技を使うことさえあった。\n\n今では、会議のメンバーは二人だけになり、一人は昏き海から永遠に出られず、もう一人もその「未来」を得るために地下から出られなくなった。\nあのテーブルは、あの事件の後、二度と見つからなかった。"
  },
  Item_9611_Desc = {
    Text = "ハレト学長代理特別支給の豊富な補給。\n貴重な材料が封入された木箱で、課題任務を遂行する守秘者に援助を提供。\n以下のすべての素材を獲得：\n輝色の蝶水晶×9\n高茎ウミユリ×9\n原生虫の蛹×9\n隕石の破片×9"
  },
  Item_9611_Name = {
    Text = "Ⅰ級全界域補給"
  },
  Item_9612_Desc = {
    Text = "セット：\nナメクジプリンⅠ\nナメクジプリンⅡ\nナメクジプリンⅢ\nナメクジプリンⅣ\nナメクジプリンⅤ\nナメクジプリンⅥ"
  },
  Item_9612_Name = {
    Text = "ナメクジプリン"
  },
  Item_9613_Desc = {
    Text = "歴史は繰り返すが、宇宙は例外かもしれない。\n神秘的な文字が記された紙片。\n混沌界域の覚醒体を昇格させるための素材。"
  },
  Item_9613_Name = {
    Text = "純白の紙片"
  },
  Item_9614_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nワンダを再度獲得した際に変換され、ワンダの霊知啓発を起動するために使用。"
  },
  Item_9614_Name = {
    Text = "欠片・ワンダ"
  },
  Item_9614_StoryDesc = {
    Text = "ワンダを再度獲得した際に変換され、ワンダの霊知啓発を起動するために使用。"
  },
  Item_9615_Desc = {
    Text = "未知を沈殿させる。\n根源の泡を脱水した後の沈殿物。大切に保管しよう、これはミサゴ商店の硬貨だ。"
  },
  Item_9615_Name = {
    Text = "根源の澱"
  },
  Item_9616_Desc = {
    Text = "属性がシルバーキー充電レベルに基づく命輪。"
  },
  Item_9616_Name = {Text = "核溶解"},
  Item_9616_StoryDesc = {
    Text = "A. F.@1年@1月@1日\n\n08:00\n\n部品107から133の組み立てを行う。\n\nCタイプの部品はこれで最後、完成後はオートマタ「チクタクマン」のエネルギーコアとして使用される。\n\n自分で組み立てたかったが、@2が言うには、責任者は仲間を信頼することを学ぶべきだと。\n\nよく言うよ、彼女こそが部品を夜中までチェックしているのに。\n\n-------\n\nA. F.@1年@1月@1日\n\n00:21\n\nモーターMF311000の組み立て完了、ギアは合っていて、パイプも通っている。現在すべての機能は正常。最終調整を行う。\n\n13:07\n\n特殊エネルギーSを接続、モーターMF311000は良好に動作し、EA307850号の人工体と適合、人工体は正常に動作。\n\n@2は楽観的で、今回は前よりも進めると思っている。私は彼女に第五回召喚試行時のことを忘れないようにと注意したが、彼女は耳を塞いで聞こえないと言った。あの時、私が素早く反応しなければ、エネルギーコアの火が彼女の髪を焼き尽くしていただろう。\n\n彼女に一度スキンヘッドを味わわせるべきだ、そうすれば慎重さを学ぶかもしれない。\n\n-------\n\nA. F.@1年@1月@1日\n\n14:55\n\n最終準備完了、エネルギー準備完了、拘束装置が起動、拘束状態：良好。胴体は召喚完了後に取り付ける。\n\n15:00\n\n「チクタクマン」第13回起動試行開始。\n\n15:05\n\n胴体EA307853は正常に動作、モーターMF311000も正常。「チクタクマン」の首関節は正常に動き、頭部部品も正常に動作。\n\n15:15\n\n「チクタクマン」は瞬き、視線追従、口開け指令を成功。モーターに発熱現象があるが、許容範囲内。\n\n四肢部品の取り付けを行う、神よ、どうか今回うまくいきますように。\n\n18:07\n\n歩行指令を実行中に、モーターコアが溶解、配線が焼損。特殊エネルギーSは無傷。\n\n@2はこの特殊エネルギーを非常に大切にしており、私でさえ触れることを禁じられている。理解できる、それは確かに神秘的な物体で、見た目は普通の銀の金属のようで、エネルギーを蓄える能力があるようには見えないが、本当にオートマタにエネルギーを供給でき、高温でも損傷しないのは驚くべきことだ。\n\nもしこれが大量生産または大量採掘できれば…………\n\nいつか彼女に再度尋ねるべきかもしれない、彼女がこの人形にどれだけの時間を費やすのかもわからない。いつか彼女自身が人形になっても驚かないだろう。\n\n"
  },
  Item_9617_Desc = {
    Text = "幽霊船に逸散した感情粒子。触れると「仕方ない」という呟きが聞こえるような気がする。\nシークレットキーパーが調査イベント「嵐の目」における共鳴を高めるために使用する。\n「嵐の目」ステージの初回クリア報酬で入手可能。"
  },
  Item_9617_Name = {
    Text = "絶望の心"
  },
  Item_9619_Desc = {
    Text = "符号、文字、記憶……それはすべてを改ざんする。\n密約強化と密約転写に使用される。\n密約強化はメイン能力を向上する。また、密約転写はランダムにサブ能力を獲得する。"
  },
  Item_9620_Desc = {
    Text = "メイン能力は、界域知識、狂気増加、黒章ドロップ、キーチャージの中からランダムに1つを獲得。"
  },
  Item_9620_Name = {
    Text = "ナメクジプリンⅣ"
  },
  Item_9620_StoryDesc = {
    Text = "甘くて、ねばねば。"
  },
  Item_9621_Desc = {
    Text = "翅は美しさをもたらすのみ。5ペニーの価値。\n輝色の蝶水晶。体の大部分が結晶化されている。\n混沌界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_9621_Name = {
    Text = "輝色の蝶水晶"
  },
  Item_9622_Desc = {
    Text = "そう、すべては精錬可能だ。あなたの本能、理性、そして心さえも……結局、あなたは彼らと何も変わらないことに気づくでしょう。\n深海界域の覚醒体を昇格させるための素材。"
  },
  Item_9622_Name = {
    Text = "理性の精錬"
  },
  Item_9623_Desc = {
    Text = "持有者の毎回のダメージ値を向上させ、超次元ターン終了後に追加で敵の毒を発動させる運命の札。"
  },
  Item_9623_Name = {
    Text = "回れ回れ"
  },
  Item_9623_StoryDesc = {
    Text = "大きな舞台で、一人の少女が踊っている。\n彼女の髪はきつくまとめられ、白い羽と小さな王冠が飾られている。純白の舞踏服は彼女の動きに合わせて広がり、哀愁漂うバイオリンの音色に合わせて回り続ける。\n腕を伸ばし、つま先を地に付け、白鳥は長い首を垂れ、王子に悲しみと憂いを語る。\n幼いリッツは口を開けて舞台上の軽やかで優雅な少女を見つめていた。それは彼女の従姉妹で、彼女が生まれる前から家に来て、祖母の下で厳しい訓練を受けていた。普段は質素で静かな従姉妹が今日ほど生き生きとしていることはなかった。彼女はまるで羽ばたこうとする白鳥のようで、彼女も、彼らも、劇場の全員が彼女の影に魅了されていた。\n彼女の心臓はどんどん速くなり——なんて羨ましい！彼女もあの白鳥になりたい、永遠の舞台に自分の影を長く残したい。彼女は自分ができると知っていた。祖母が彼女の足を長くてまっすぐだと褒めたことがあるではないか？長年首席を務めた従姉妹が彼女に舞踊の才能があると言ったことがあるではないか？そう、彼女が始めれば、彼女がトウシューズを履けば、人々は遠くの街から公演を見に来るだろう。彼女は今世紀最大の舞踊家、バレエ芸術の輝かしい星となるだろう！\nその時の彼女はまだ知らなかった、自分を待っているのは熱い炎だけだ。"
  },
  Item_9624_Desc = {
    Text = "高慢で、わがままで、自己中心的……彼女と接した多くの人がそう評価する。\n・ライフ上限を犠牲にし、シールドと行動力を獲得。\n・シールドを付与し、触腕の力を強化。"
  },
  Item_9624_Name = {
    Text = "マーフィー"
  },
  Item_9625_Desc = {
    Text = "持続的かつ安定した狂気と銀キーエネルギーの獲得。狂気爆発に依存する銀キーキャラクターに適している。"
  },
  Item_9625_Name = {
    Text = "アクートの春"
  },
  Item_9625_StoryDesc = {
    Text = "災厄が突然消え、危機から一時的に解放された後、ミサゴの特別行動隊は「思わぬ収穫」をアクートから持ち帰える事になった。\nデクスター嬢が最後に爆発の中心の大穴を振り返った時、見知らぬ植物の芽がいつの間にか土を破っていた。\n彼女は安堵の息をつき、心が少し晴れた。\nアクートの森は春を迎える。\n柳は次の春にも芽を出し、スズランは次の雨季の後に静かに咲くだろう。すべての生命が新生を迎える。\nそして彼らの未知への旅も新たな始まりを迎える。"
  },
  Item_9626_Desc = {
    Text = "メイン能力は界域知識、黒章ドロップ、死亡抵抗、ダメージ強化からランダムに1つ獲得。"
  },
  Item_9626_Name = {
    Text = "有機形態Ⅵ"
  },
  Item_9626_StoryDesc = {
    Text = "鱗翅目は孤独、愛、絶望に死す。"
  },
  Item_9627_Desc = {
    Text = "メイン能力は界域知識、黒章ドロップ、死亡抵抗、ダメージ強化からランダムに1つ獲得。"
  },
  Item_9627_Name = {
    Text = "深紅の鼓動Ⅵ"
  },
  Item_9627_StoryDesc = {
    Text = "伝説の最初のゴーレム創造主、血液でゴーレムを養う。"
  },
  Item_9628_Desc = {
    Text = "メイン能力は、狂気増加、死亡抵抗、キーチャージ、ダメージ強化の中からランダムに1つを獲得。"
  },
  Item_9628_Name = {
    Text = "荒野の狼Ⅴ"
  },
  Item_9628_StoryDesc = {
    Text = "ワオーン、ワオーン。"
  },
  Item_9629_Desc = {
    Text = "数億年前、温暖な海で一世を風靡した。\n高茎ウミユリの化石。\n深海界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_9629_Name = {
    Text = "高茎ウミユリ"
  },
  Item_9630_Desc = {
    Text = "「攻撃」の使用と同時に一定確率で追加の算力を獲得し、触腕を駆使して敵を攻撃する。"
  },
  Item_9630_Name = {
    Text = "暴風雨の中で"
  },
  Item_9630_StoryDesc = {
    Text = "船が何かにしっかりと纏着され、プロペラが苦しそうに回転し、恐ろしい音を立てていた。\n積乱雲が頭上に集まり、黒い雲の中で雷が渦巻いていた。\n雷がマストに落ちた瞬間、プロペラは束縛を解かれ、再び回転を始めた。\n私は安堵の息をついたが、機関長は叫び始めた。\n\n海水に混じった粘り気のある液体が、嵐の野外で風に乗って遠くへ運ばれ、私の鼻には死の匂いしか感じられなかった。\nしかし、私はその蛍光を放つ液体が何らかの血液であることに気づいた。\n私の最愛の仲間、最も信頼する船は、沈む前に全力を尽くした——彼女の海を切り裂くはずのブレードは、敵の触腕を激しく切り落とした。\n\nこれは幸運の兆しだ！私たちはすぐに嵐を抜け出せる！\n私はこれで船員たちを安心させようと思ったが、顔を上げた瞬間、暗い海の中央に光が現れた。\nそれは灯台だろうか？そんなはずはない。いや、あり得ない。\nここは大洋の中央で、最も近い陸地は数百海里も離れている。どうして人が、どうしてここに灯台を建てられるのか？\n\n私の水夫たちは泣き始め、祈り始め、故郷の歌を一斉に歌い始めた。\nそして、その灯台は突然消えた。\nすべての光が消え去り、荒れ狂う嵐も静かな小雨となって甲板に降り注いだ。\n水夫たちは慈悲深い主を讃え、生き延びた喜びに浸っていた。\nしかし、私ははっきりと見た。\n\nその光の中に消えたのは、確かに優雅な女性の姿だった。"
  },
  Item_9631_Desc = {
    Text = "メイン能力はクリティカル率、クリティカルダメージ、死亡抵抗、ダメージ強化からランダムに1つ獲得。"
  },
  Item_9631_Name = {
    Text = "深紅の抱擁Ⅲ"
  },
  Item_9631_StoryDesc = {
    Text = "伝説の最初のゴーレム創造主、ゴーレムを自らの手で殺す。"
  },
  Item_9632_Desc = {
    Text = "未知の精神を与える。\n映画詩クラブの特殊フィルムから生まれ、人の精神を転写できる。\n超次元界域の覚醒体の昇格素材として使用。"
  },
  Item_9632_Name = {
    Text = "精神テンプレート"
  },
  Item_96331_Desc = {
    Text = "「課題レコード」で「核心課題」を購入すると獲得できます。\n「いつ黒い池に行っても、彼女の顔にはその不気味な笑顔が浮かんでいる。あなたはしばしば、融蝕が彼女の脳の運動皮質を破壊してしまったのか、またはアミグダラが感情を表現する部分がこの固定された一つだけになってしまったのか疑ってしまう。」"
  },
  Item_96331_Name = {
    Text = "色あせない昨日：熔毁·朵尔"
  },
  Item_96331_StoryDesc = {
    Text = "第20期学期課題"
  },
  Item_96332_Desc = {
    Text = "「課題レコード」で「核心課題」を購入すると獲得できます。\n「36時間に及ぶ実験室での作業は、その天才的な脳の疲労を人形の体を通じて放出させ、無機的な顔に幻想的なクマが現れたかのように見えます。命を守るための常識：こんな時、彼女の理性に絶対に挑戦してはいけません、絶対に。」"
  },
  Item_96332_Name = {
    Text = "色あせない昨日：朵尔"
