  },
  Item_9642_StoryDesc = {
    Text = "彼女は夢を見ない。\n\n若い彫刻家の見習いは、絶対的な理性と秩序を信じていた。それは彼女の冷たい作品のように。\nしかし、それを初めて見た瞬間から、彼女は魅了された。\n柔らかく、純粋——それは完璧な着色素材だった。\n彼女は月光の下で忙しく働き、乱葬地から黒い粘液をアトリエに持ち帰った。\n\n一週間後、《@2》という名の彫刻が博覧会で展示された。\nその夜、彼女は遠くからの波の音を聞いた。\n彼女は初めて夢を見た。\n静かな朝の光の中で、埃に覆われた海底の宮殿が眠っていた。\n彼女は白いサンゴの中を歩き、孤独と忘却の息吹を感じた。\n\n目覚めると、彼女の指は縮こまり、黒くなり、最後には白いサンゴが生えていた。\n彼女は何度も嗅ぎ、そこに古代からの無数の生物の囁きを感じた。\nそれは本当に柔らかい化石だった。\n彼女は神経質に笑った——これが夢を見ることなのか。\n彼女はアトリエに閉じこもり、夢中で創作を始めた。\n型取り、粘土細工、着色……\n混沌とした、有序な。無機的な、有機的な。\n\n彼女は永遠に夢を見る。"
  },
  Item_9643_Desc = {
    Text = "ベテラン守秘者の精神力が変化した立方体の結晶で、ダフォダイルの店で貴重な素材と交換可能。"
  },
  Item_9643_Name = {
    Text = "塩岩（廃止済み）"
  },
  Item_9644_Desc = {
    Text = "戦闘初期に爆発的に大量の狂気を提供し、持続的に狂気循環を加速できる。狂気に依存する爆発型のキャラクターに適している。"
  },
  Item_9644_Name = {
    Text = "神王の讃歌"
  },
  Item_9644_StoryDesc = {
    Text = "彼は万事を知る王であり、リモリアの至高である。\nラピスラズリは彼の王座であり、黄金は彼の冠である。魂は彼の権威であり、彼は最上で安眠する。\n神に仕える祭司も彼に仕え、彼の前にひれ伏す。\n彼らは彼の忠実な臣下であり、彼の敬虔な信徒である。\n\n神は夜に月光を送り、彼を永遠の眠りの宮殿に招く。\nそこでは、神々が彼と魂の食事を分かち合い、神の知恵を授ける。\n神々は彼に終わりなき夢を与え、彼は万物の始まりと時間の終わりを観る。\n彼はこうして知るのである――万物の始まりは混沌であり、神々はその中で目覚め、暗闇に浮かぶ宮廷を築いたことを。\n彼はこうして知るのである――時間の終わりは暗闇であり、すべてが混沌に帰ることを。\n\n王の中の王よ、神の寵児よ、\n誰があなたに匹敵しようか？\n誰があなたのように夢から統治し、誰があなたのように威厳を持つであろうか？\n\n尊き神王よ、若き支配者よ、\nどうか存分に熟睡あれ。\nあなたの臣民と信徒は、あなたが神の予言を持ち帰るのを辛抱強く待つのだ。\n\n敬愛なるルルイエの支配者よ、深淵の主よ、\nどうか我らがあなたの御名を呼ぶことを許し、庇護を与え給え。\n――トゥルー、トゥルー。"
  },
  Item_9645_Desc = {
    Text = "メイン能力は、狂気増加、死亡抵抗、キーチャージ、ダメージ強化の中からランダムに1つを獲得。"
