  Item_9653_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「鼠の知恵」を選択可能。\n\n小さな鼠とその主人には、多くの共通点がある——\n狡猾で、勇敢で、そして素早い。\n彼らは東区の入り組んだ屋根の隙間を自由に駆け抜け、空を毛布に、屋根を寝床にする。\n彼らは都市の片隅で、たくましく成長していく。"
