  },
  Item_9672_StoryDesc = {
    Text = "私はあなたの墓を唾棄する。"
  },
  Item_9673_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nパンディアを再度獲得した際に変換され、パンディアの霊知啓発を起動するために使用。"
  },
  Item_9673_Name = {
    Text = "欠片・パンディア"
  },
  Item_9673_StoryDesc = {
    Text = "パンディアを再度獲得した際に変換され、パンディアの霊知啓発を起動するために使用。"
  },
  Item_9674_Desc = {
    Text = "彼女は罪人の恐怖と欲望、死にゆく者への甘露と毒酒、甘美な痛みと狂気のロマンをもたらす。\n・敵の力を奪う\n・敵の攻撃が激しいほど、ダメージ回数が増える。"
  },
  Item_9674_Name = {
    Text = "パンディア"
  },
  Item_9675_Desc = {
    Text = "数億年前、温暖な海で一世を風靡した。\n高茎ウミユリの化石。\n深海界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_9675_Name = {
    Text = "高茎ウミユリ"
  },
  Item_9676_Desc = {
    Text = "120分の1の奇跡。\n暗赤色の宝石の破片は、賢者の石の合成に使用できる。"
  },
  Item_9676_Name = {
    Text = "賢石の破片"
  },
  Item_9677_Desc = {
    Text = "<SummonPurple:『燃える饗宴』獲得報酬UP>\n持有者の反撃重ね掛け能力を大幅に向上させ、持有者のカードが超次元空間に入る際に追加で大量の狂気を獲得できる運命の札。"
  },
  Item_9677_Name = {
    Text = "女王の戒律"
  },
  Item_9677_StoryDesc = {
    Text = "ワンダの正確な素性について、カンブリアの村人たちは様々な説を唱えている。\n\nある者は、ワンダが巨大な石に乗って湖に落ちてくるのを見たと言った。\n\nある者は、彼女はヴォルムワヒ出身の女ファラオで、ミイラの針の様な脊椎が彼女の背中にもあるのを見たと言った。\n\nまたある者は、彼女はフラン高地から来た女公爵で、4人の夫を次々亡くして、巨額の財産を相続したと言った。\n……\n\n噂は風のように消え、村人たちは耕作し、織物をし、そして粉を挽き続ける。\n\n苦しい年月、重い税金は頭上にぶら下がる刃のようであり、あらゆる余計なものや夢想を断ち切った。\n\nただ……女王が住む湖の森を通るたびに、木々の間から聞こえる音楽が、村人たちの心をたやすく捉えた。\n\nそれは、ここにあるべきではない旋律だった。\n\nあまりに快く、怠惰であり邪悪にさえ聞こえる、悪魔のささやきのようだった。\n\n「おいで、すべてを捨てて」\n\n「慈悲深き王は湖の中央に座し盲目の僕の奉仕を静かに待っている……」\n\n\nそして風のない夜、ある疲れた村人が農具を置き、忍び寄る好奇心を満たすことを決意した。\n\n彼は森を回り込んで、小さな橋を渡った。\n道端には花が咲き乱れていたが彼は見向きもしない。\n\n彼は緑色の湖面を見た。\nその湖は低く垂れ下がる星空とつながるかのようで、その縁の中に古城がそびえ立っていた。\n\n\n棘茨の冠をかぶった女王は湖の城の中央に座り、巡礼の民を辛抱強く待っていた。\n\n彼女は手を差し出し、人間からの口づけと崇拝を楽しんだ。\n\n雲は散り、月が昇る。\n\n女王は彼の背骨に脊椎針を突き刺した。\n\n麻痺させる液体が血管に沿って広がり、彼は地面にひざまずいた。\n\n四肢を切り落とされ、両目を抉り取られた。\n\n\nこうして、大地の重力は彼を引きつけることができなくなり、彼のすべての詩と夢は、ただその女王だけに捧げられた。\n\n彼はついに自分の運命を迎えたのだ。"
  },
  Item_9679_Desc = {
    Text = "メイン能力はクリティカル率、クリティカルダメージ、界域知識、黒章ドロップからランダムに1つ獲得。"
