  },
  Item_9682_Desc = {
    Text = "メイン能力は、クリティカル率、クリティカルダメージ、キーチャージ、狂気増加の中からランダムに1つを獲得。"
  },
  Item_9682_Name = {
    Text = "呪いのウサギⅠ"
  },
  Item_9682_StoryDesc = {
    Text = "みんな白いふわふわウサギが好き。"
  },
  Item_9683_Desc = {
    Text = "メイン能力は、クリティカル率、クリティカルダメージ、キーチャージ、狂気増加の中からランダムに1つを獲得。"
  },
  Item_9683_Name = {
    Text = "薬となる夢Ⅰ"
  },
  Item_9683_StoryDesc = {
    Text = "千年前、5分は40オンスの細砂に等しかった。"
  },
  Item_9684_Desc = {
    Text = "ファイントは色褪せた、殻を破りにくい種子だ。\n・死に向かい生きる\n・ライフを吸収し、シールドを形成。"
  },
  Item_9684_Name = {
    Text = "ファイント"
  },
  Item_9685_Desc = {
    Text = "このキーオーダーを記録すると、編成時に、キーオーダースキル「純白の出会い」を選択可能。\n\n私は願う。\nリリーのカルテが、何も書かれていない白紙であることを。\nまるで、彼女と初めて出会ったあの雪原のように——"
  },
  Item_9685_Name = {
    Text = "純白の出会い"
  },
  Item_9685_StoryDesc = {
    Text = "私は願う。\nリリーのカルテが、何も書かれていない白紙であることを。\nまるで、彼女と初めて出会ったあの雪原のように——"
  },
  Item_9686_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nカエクスを再度獲得した際に変換され、カエクスの霊知啓発を起動するために使用。"
  },
  Item_9686_Name = {
    Text = "欠片・カエクス"
  },
  Item_9686_StoryDesc = {
    Text = "カエクスを再度獲得した際に変換され、カエクスの霊知啓発を起動するために使用。"
  },
  Item_9687_Name = {Text = "軟膏"},
  Item_9688_Desc = {
    Text = "セット：\n深海航路Ⅰ\n深海航路Ⅱ\n深海航路Ⅲ\n深海航路Ⅳ\n深海航路Ⅴ\n深海航路Ⅵ"
  },
  Item_9688_Name = {
    Text = "深海航路"
  },
  Item_9689_Desc = {
    Text = "装備者が与えるシールドとダメージを高め、追加で補充される打撃と防御がより多くの可能性をもたらす。"
  },
  Item_9689_Name = {
    Text = "不屈の意志"
  },
  Item_9689_StoryDesc = {
    Text = "「撤退、撤退！」\n「@3に向かって撤退！急げ！」\n「助けて、助けてくれ！置いていかないで！」\n「彼は放っておいて、早く撤退しろ——アルバ！」\n銃剣を持った兵士が一気に飛び出し、砲火が彼女の側で炸裂し、兵士の戦いの声、悲鳴、急な戦争の号角が一体となって響き渡る。血液が土を黒く染め、硝煙の匂いすら覆い隠せない濃厚な血の匂いを放ち、倒れた兵士たちの目は空洞で、どの色の軍服もこの瞬間には眩しい赤に変わっていた。\nアルバは歯を食いしばり、次々と彼女に攻撃してくる者たちに向かって進んだ。彼女は見えていた、助けを求める若者が、地面に押さえつけられ、両手で高い敵軍のナイフを必死に防いでいる。\n爆発する銃声と激しい痛みが同時に襲い、近くの敵がゆっくりと倒れ、アルバはすぐに振り返って刀を振り、足の痛みに耐えながら前に力強く突進し、敵がバランスを失った瞬間に相手の胸を貫き、同時に引き金を引いた。\n弾丸が体に入り血肉を飛び散らせ、彼女は顔を適当に拭い、若者の安全を確認しようと振り返ったが、彼はいつの間にかいなくなっていた。\n彼女は下を見て、ナイフが左膝の上から彼女の脚を貫いているのを見た。温かい血液がどくどくと流れていた。\n彼女はマントから布を裂いて脚の根元に巻きつけて血流を何とか抑え、銃剣を仮の杖として足を引きずりながらチームに追いついた。"
  },
  Item_9690_Desc = {
    Text = "涙で尊敬されることも、泣き声で葬られることもない、なぜなら生前にすでにローマで名を馳せたから。\n・戦い続け、死ぬまで\n・ライフが減るほど、狂気が深まる。"
  },
  Item_9690_Name = {
    Text = "ユウハシュ"
  },
  Item_9691_Desc = {
    Text = "狂気増加の能力を持つ命輪。"
  },
  Item_9691_Name = {
    Text = "貴族の杖"
  },
  Item_9691_StoryDesc = {
    Text = "デクスター卿の杖について、ミサゴ大学内では多くの噂が流れている。\n\n「間違いなく、卿の杖は彼の笑顔と同じくらい秘密を隠している。\n果たしてシルバーコアが埋め込まれて覚醒体の力を引き出すのか、それとも火薬が隠されていていつでも銃に変わるのか？\nデクスター卿にその謎を解いてもらおう！」\n\n開幕の言葉を読み上げながら速記した後、ハンナはカメラをデクスター卿に向け、持ち主本人からの続きに期待した。\n\n「それかい？特に特別なものじゃない、ただのデクスター家のオーダーメイドの日常用の杖さ。\nこの杖に使われている宝石は、兄のものよりも価値がないくらいだ。\nもし特別なところがあるとすれば……\nそれはかつて両親と兄弟の血が付いたことがあるってことかな、どうだい？」"
  },
  Item_9692_Desc = {
    Text = "界域知識の能力を持つ命輪。"
  },
  Item_9692_Name = {
    Text = "情報は命"
  },
  Item_9692_StoryDesc = {
    Text = "ロンディニウムの地下世界にはこんな話が伝わっている。\n\n忙しい港、静かな路地、賑やかな酒場……\nいつどこでカメラを持ち、眼鏡をかけ、制服を着た少女に出会えるかわからないが、彼女を見つければ欲しい情報は何でも買える。代償はただ一つ——\n\nあなただけが知っている秘密を提供すること。\n\n誰かはカウンターで聞いた酔っ払いの真実を使って競争相手の致命的な弱点を手に入れた。\n誰かは自分の弱点を使って恋人の過去を知った。\n少女は無数の情報を握っているが、ただ一つ、どんな秘密でも交換できない情報がある。\n\n「私のこと？ごめんね、それは非売品だよ」"
  },
  Item_9693_Desc = {
    Text = "狂気増加の能力を持つ命輪。"
  },
  Item_9693_Name = {
    Text = "心の障壁"
  },
  Item_9693_StoryDesc = {
    Text = "ミサゴキャンパスで最も関わりたくない人がいるなら、ドールが二番目に名乗りを上げるだろうが、一番はシルヴィアさんに違いない。\n\nミサゴ唯一の精神科医であるこの神秘的な女性は、任務中に驚いた調査員を慰めるだけでなく、覚醒体の不安定な感情を和らげるのも彼女の役目だ。\n覚醒体を恐れず、精神的に彼らと対等に渡り合える——一体どんな強者なのだろうか？\n\n未知への好奇心を抱き、敬意を欠いた新入生が深夜にシルヴィアさんの診療室に忍び込んだ。\n\nそして、彼らは意識を失った。\n翌朝、キャンパスの広場で目を覚ました時、彼らは頭痛がひどかったが、心はかつてないほど明るかった。\n誰かが彼らのポケットから落ちた手紙を拾い上げた：\n\n「心理相談が必要なら、エリカさんに事前に申し込んでね——\nシルヴィア」"
  },
  Item_9694_Desc = {
    Text = "これで誰も占いに使おうとは思わないだろう。\n融蝕液に覆われた紫色の水晶。\n超次元界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_9694_Name = {
    Text = "破損した鉱晶"
  },
  Item_9695_Desc = {
    Text = "属性がクリティカル率の運命の札。"
  },
  Item_9695_Name = {
    Text = "忘却の手"
  },
  Item_9695_StoryDesc = {
    Text = "手は暗闇の中で彷徨い、主人を探している。\n\nその血塗られた夜に、手は主人から無慈悲に引き剥がされた。\n今、この瞬間、手を奪った元凶が周囲を流れ、奇妙な振動音を発している。\n \n「諦めて、私たちと行こう。蝋人形師は君を完全に忘れるだろう」\n\n手は動じず、誇りに思う長い指を動かす。\n\n「主人は私を忘れない。\n私は彼の芸術を実現する唯一の手段——\n君たちは私が彼にとって何を意味するか理解していない」\n\n「人は愛する人を忘れ、時間を忘れるが、自分を忘れない」\n\n暗闇から同情の笑い声が聞こえる。\n「まさにその逆だ、人はまず自分を忘れる。\nでも大丈夫——」\n\n時間がすべてを説明する、手はいつかこの真理を理解するだろう：\n忘れられないものはない。\nそれらは何世紀も流れ続け、人間の物語がその周りで起こり、翌日には忘れられる。\nそれでも流れ続ける。"
  },
  Item_9696_Desc = {
    Text = "企画試験用SSR武器のみ"
  },
  Item_9696_Name = {
    Text = "試作レーザー砲（クリティカルダメージ）開発用"
  },
  Item_9697_Desc = {
    Text = "属性がブラックマークドロップの運命の札。"
  },
  Item_9697_Name = {
    Text = "存在しない場所"
  },
  Item_9697_StoryDesc = {
    Text = "タヴィは昏き海の底で眠っている。\n\nそこは一年中、音も光もなく、絶望的な暗闇だけが広がっている。\nここを訪れる客人はなく、音も届かない。\nここは破滅が及ばない場所——\n\nなぜなら災厄がすでに降りてきたから。\n\n時の管理者として、彼女は多くの悲惨な終局を目撃してきた。\n規則の一員として、彼女もまた夜の到来を阻止できない。\nだからこそ、存在しない場所で、存在しない姿で「変数」と呼ばれる者の到来を待つしかない。\n\nその人は必ずやってくる。"
  },
