  Item_9703_Name = {Text = "落日"},
  Item_9703_StoryDesc = {
    Text = "A.F. 314、冬の深夜、爆発音がアクートの森に響き渡った。\n大地は震え、森は昼のように明るくなった。生命の叫び声と自然の嘆きと共に、村や町は平地となった。\n「アクート災厄調査」に参加した覚醒学部予科生デクスターによれば、その夜の火光には黒と銀の色が輝いていたという。"
  },
