  Item_9704_Name = {
    Text = "魂の誕生"
  },
  Item_9704_StoryDesc = {
    Text = "時間の弦が次々と切れ、流れる鍵盤が粉々に砕ける。\n彼らは現実の外に立ち、現実を材料にして欠けた部分を縫い合わせ、永遠に終わらない楽章を再び高天に響かせる。\nその一瞬の夢から覚めた時に流れた涙がどこへ行ったのか、誰も知らない。"
  },
