  Item_9705_Desc = {
    Text = "メイン能力はクリティカル率、クリティカルダメージ、界域知識、黒章ドロップからランダムに1つ獲得。"
  },
  Item_9705_StoryDesc = {
    Text = "必然、偶然。有限、無限。"
  },
  Item_9706_Desc = {
    Text = "メイン能力は界域知識、黒章ドロップ、死亡抵抗、ダメージ強化からランダムに1つ獲得。"
  },
  Item_9706_Name = {
    Text = "呪いのウサギⅥ"
  },
  Item_9706_StoryDesc = {
    Text = "みんな白いふわふわウサギが好き。"
  },
  Item_9707_Desc = {
    Text = "未知の精神を与える。\n映画詩クラブの特殊フィルムから生まれ、人の精神を転写できる。\n超次元界域の覚醒体の昇格素材として使用。"
  },
  Item_9707_Name = {
    Text = "精神テンプレート"
  },
  Item_9708_Desc = {
    Text = "セット：\n墓地の囁きⅠ\n墓地の囁きⅡ\n墓地の囁きⅢ\n墓地の囁きⅣ\n墓地の囁きⅤ\n墓地の囁きⅥ"
  },
  Item_9708_Name = {
    Text = "墓地の囁き"
  },
  Item_9709_Desc = {
    Text = "セット：\n遠くの宴Ⅰ\n遠くの宴Ⅱ\n遠くの宴Ⅲ\n遠くの宴Ⅳ\n遠くの宴Ⅴ\n遠くの宴Ⅵ"
  },
  Item_9709_Name = {
    Text = "遠くの宴"
  },
  Item_9710_Name = {
    Text = "赤いサテンリボン"
  },
  Item_9711_Desc = {
    Text = "人類存続のため。\n額縁に保存された記憶。\n血肉界域の覚醒体を昇格させるための素材。"
  },
  Item_9711_Name = {
    Text = "記憶のコピー"
  },
  Item_9712_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nレーアを再度獲得した際に変換され、レーアの霊知啓発を起動するために使用。"
  },
  Item_9712_Name = {
    Text = "欠片・レーア"
  },
  Item_9712_StoryDesc = {
    Text = "レーアを再度獲得した際に変換され、レーアの霊知啓発を起動するために使用。"
  },
  Item_97139_Desc = {
    Text = "ピックマン画室特供、初心者専用のセットで、基本的な画材と実用的な道具が含まれており、あなたが芸術の殿堂に楽に足を踏み入れる手助けをします。\n「キャンバスのダークサイド」期間限定で供給。"
  },
  Item_97139_Name = {
    Text = "初心の出発セット"
  },
  Item_9713_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nタイスを再度獲得した際に変換され、タイスの霊知啓発を起動するために使用。"
  },
  Item_9713_Name = {
    Text = "欠片・タイス"
  },
  Item_9713_StoryDesc = {
    Text = "タイスを再度獲得した際に変換され、タイスの霊知啓発を起動するために使用。"
  },
  Item_97140_Desc = {
    Text = "ピックマン画室特供、上質な画材を使用し、あなたの筆致で古い規則を引き裂き、色彩と線の衝突の中で内なる動揺を解放します。\n「キャンバスのダークサイド」期間限定で提供。"
  },
  Item_97140_Name = {
    Text = "タッチ昇格ギフトボックス"
  },
  Item_97141_Desc = {
    Text = "ピックマン画室特供、比類のないピックマンマスターのコレクション。あなたの情熱と狂気をキャンバスの上で自由に発揮し、本当のアートの美を創造しましょう！\n「キャンバスのダークサイド」期間限定で提供。"
  },
  Item_97141_Name = {
    Text = "狂彩マスターのコレクション"
  },
  Item_9714_Desc = {
    Text = "囚われた少女の魂は血を渇望する、盲目の者が光を求めるように、淫らな者が愛欲に溺れるように。\n・胚胎融合度を生成\n・ライフを力に変換。"
  },
  Item_9714_Name = {Text = "レーア"},
  Item_9715_Name = {
    Text = "血ノ鎖・ヘロット"
  },
  Item_9716_Desc = {
    Text = "企画試験用SR武器のみ"
  },
  Item_9716_Name = {
    Text = "試作長剣（死抗）開発用"
  },
  Item_9717_Desc = {
    Text = "それは工芸品ではなく、錬金術師にぶつかった蝶の悲劇的な結末。\n普通の蝶水晶。混沌界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_9717_Name = {
    Text = "失色の蝶水晶"
  },
  Item_9718_Desc = {
    Text = "メイン能力は、クリティカル率、クリティカルダメージ、キーチャージ、狂気増加の中からランダムに1つを獲得。"
  },
  Item_9718_Name = {
    Text = "ナメクジプリンⅠ"
  },
  Item_9718_StoryDesc = {
    Text = "甘くて、ねばねば。"
  },
  Item_9719_Desc = {
    Text = "無垢のシルバーコア結晶。\nシルバーコアを精製後に得られ、高位存在の意志をリンク可能。"
  },
  Item_9719_Name = {
    Text = "ヘブンズコア"
  },
  Item_97206_Desc = {
    Text = "解除後、「葬骸紀行」の全てのミッションを完了すると追加報酬を受け取ることができます"
  },
  Item_97206_Name = {
    Text = "葬骸紀行"
  },
  Item_9720_Desc = {
    Text = "ある平行宇宙では、破壊的な力を持つ。\n遠い熱帯からの完璧な鉱石。\n超次元界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_9720_Name = {
    Text = "ユカタンの星"
  },
  Item_9721_Desc = {
    Text = "セット：\n再進化Ⅰ\n再進化Ⅱ\n再進化Ⅲ\n再進化Ⅳ\n再進化Ⅴ\n再進化Ⅵ"
  },
  Item_9721_Name = {Text = "再進化"},
  Item_9722_Desc = {
    Text = "メイン能力はクリティカル率、クリティカルダメージ、死亡抵抗、ダメージ強化からランダムに1つ獲得。"
  },
  Item_9722_Name = {
    Text = "36の廻る部屋Ⅲ"
  },
  Item_9722_StoryDesc = {
    Text = "回転して、忘れる——それが彼女の人生のすべて。"
  },
  Item_9723_Desc = {
    Text = "メイン能力はクリティカル率、クリティカルダメージ、界域知識、黒章ドロップからランダムに1つ獲得。"
  },
  Item_9723_Name = {
    Text = "四月の賛歌Ⅱ"
  },
  Item_9723_StoryDesc = {
    Text = "彼は@2年の春に埋葬された。"
  },
  Item_97242_Desc = {
    Text = "葬骸城では、誰ひとりとして死の訪れを恐れる者はいない。\n死が訪れるその日まで、人々は毎日を人生最期の日であるかのように、歌い、踊り、宴を楽しんで過ごす。この死の都は、生者が想像するどんな場所よりも、はるかに賑やかだ。\n\n紫色の勿忘草が一輪、静かに窓辺へと舞い落ちたとき、その「手紙」を受け取った者は、喜んで身を清め、身支度を整え、一番お気に入りの衣を纏う。そしてその花を髪に飾り、城の人々に別れを告げ、最後には愛する者の手を取るのだ。\nそれは葬骸の主からの祝福であり、同時に彼の約束でもある。彼は、人々が愛する者と一つになり、誰一人として見捨てられず、忘れ去られぬことを祝福する。そして、その再会は、彼自身がこの世から消え去るその時まで一一すなわち永遠であると約束するのだ。\n\n現世にある墓地の近くや、救いを求める人々の間にも、似たような伝説が語り継がれている。\nこの世の苦難に苛まれ、命の灯火が消えようとするとき、静寂に包まれた夜明けの中で、魂に安らぎをもたらす一筋の霧を見るだろう。\nその霧を追い、誰も知らない世界の果てへと続く荒野を進めば、無数の墓標の中に咲き誇る紫の花の海に辿り着く。\n霧の果てには、まるで花が人の姿をとったかのように美しい青年が佇んでいる。彼はあなたの一生と同じくらいの時間を待ち続けていたかのようで、定められた運命の約束に従い、あなたを苦痛なき安らかな夢の国へと迎え入れるだろう。\n彼はあなたのすべてを受け入れ、すべてを癒し、最後の救いをもたらす。\nその花の海の中で、彼はそっとあなたに掌を差し伸べるのだ。\n\n「私と一緒に、踊っていただけますか？」"
  },
