  Item_9730_Desc = {
    Text = "セット：\n環状詩篇Ⅰ\n環状詩篇Ⅱ\n環状詩篇Ⅲ\n環状詩篇Ⅳ\n環状詩篇Ⅴ\n環状詩篇Ⅵ"
