  },
  Item_97317_Desc = {
    Text = "キーチャージの能力を持つ命輪。"
  },
  Item_97317_Name = {
    Text = "ブルーリングの毒素"
  },
  Item_97317_StoryDesc = {
    Text = "幾年もの歳月を経て、地に伏して祈りを捧げる海踊人たちを前にしたとき、偽誕・マーフィーは、「母」がヒョウモンダコの話をしてくれたあの遠い午後のことを思い出すだろう。\n瓶の中の生き物は柔らかく、眩いほどに美しかった。奇妙な青白い光が水の中で揺らめき、幼い彼女を魅了した。\nだがミリアムは彼女の頭を撫でつつ、拒むことを許さぬ強さで、薄暗い船室の隅へと視線を向けさせた——そこには海踊人の死体が力なく横たわり、毒にすべてを吸い尽くされたかのような虚ろで青白い姿を晒していた。\n「覚えておきなさい。海において最も静かで、そして最も致命的なのは、往々にして最も美しいものなのです。」\nガラス瓶の冷たい光が、彼女の慈悲深い横顔を照らし出し、偽誕・マーフィーはただ、美しさに包まれた恐怖を感じていた。\n\n歳月は星々の巡りに従い、静かに流れていった。偽誕・マーフィーは相変わらず傲慢ではあったが、沈黙と観察を身につけていた。\n「リモリア、リモリア…………」\n祭壇の上で、あの常に穏やかで優しかった顔が、次第に狂気に染まっていくのを見て、彼女はようやく、自分がミリアムのことを何ひとつ理解していなかったのだと悟った。彼女の頭を撫でてくれた、あの優しい母の手は、神の国に仇なす者に対して、最も過酷な裁きを下す手でもあったのだ。\nその瞬間、記憶の奥底に封じられていた恐怖が蘇り、やがて冷ややかな認識へと変わった——彼女の慈悲とは擬態した触手に過ぎず、優しい外見が化けた美しい青い輪こそが、触れれば死に至る猛毒そのものだったのだ。\n\nそして今、虚無の神はついに偽誕・マーフィーに冠を授けた。彼女は地に伏す海踊人たちを見下ろし、ミリアムの瞳に残る、未だ消えぬ——滑稽ですらある期待を受け止める。それはまるで、ガラス瓶の前で美しい生き物を見つめながら震えていた、あのちっぽけなかつての自分を見ているかのようだった。"
  },
