  },
  Item_9734_Desc = {
    Text = "「攻撃」の使用に伴い持続的にシールドを生成し、より多くのシールドで味方を庇護すると同時に追加で中毒を付与する。"
  },
  Item_9734_Name = {
    Text = "痛みを越えて"
  },
  Item_9734_StoryDesc = {
    Text = "「記憶とは何？」\n「それはあなたが忘れたもの」\n\nリリーには物忘れのひどい母がいる。\n\n一緒にご飯を食べるのを忘れ、薬を与えることを忘れ、時にはリリーの名前さえ忘れる。\n\n「どうしたらいいんだろう？」\nリリーは病床に座り、深刻そうに、大きくため息をついた。\nこんな母親では、本当に手がかかる。\n\nその後、リリーは自分の名前を木の札に書き、毎日首からぶら下げるようになった。\nこれなら、きっと覚えていてくれるかな？\n\n最初は、母も笑って「そんなことする必要はない。これはただの長期的な疲労による合併症」と言っていた。\n\nしかし、次第に、母は困惑し、いらだち始める。\n\n「リリー……リリーって何？」\nリリーを見つめる、その琥珀色の瞳には、わずかに警戒心さえ帯びていた。\n\n文字の意味さえ忘れられると、言葉によりかろうじて保たれていた穏やかな関係は、ついに終わるのだとリリーは悟った。\n\nリリーは母を抱きしめた。\n母娘の心臓の鼓動はほんの数インチしか離れていないのに、彼女はこの上ない孤独を感じた。\n\nその日以来、リリーは木の札をしまい、母に甘えるのをやめ、何日も食べていないことを思い出させることもなくなった。\n\n彼女は死にかけの患者として麻痺したまま死神の宣告を待つ。\n\n彼女は対岸の火事を眺める観客として、自分が注射され、麻酔をかけられ、母が望むどんな姿にでもいじくり回されるのを遠くから見ていた。\n\n母娘の間の楽しい会話や、やわらかな抱擁……\n\n夢のような泡のようにきらめく楽しい思い出を、リリーは心の中に大切に閉じ込めた。\n\nそして、疲れた夜にだけ、それをそっと取り出して、優しくなでるのだった。"
  },
