  Item_97415_Desc = {
    Text = "「課題レコード」で「核心課題」を購入すると獲得できます。\n「誰かがエルバが母親を失った子犬の世話をするために、まる一ヶ月間、静かに夜中に起きて眠れなかったのを見たことがある。軍人として、彼女の忠誠は集団に属しているが、かつての仲間に残酷に捨てられた。最終的に傷を負った獣は、彼女を再び受け入れてくれる一族を見つけた。もし彼女にあなたが後ろに置かれる幸運があれば、その硬い外見の下には、最も優しい心が埋もれていることに気づくでしょう。」"
  },
