  Item_97417_StoryDesc = {
    Text = "第21期フェイズチェス"
  },
  Item_97418_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得できます。\n「おかしいな、私はここに何をしに来たんだっけ…………あっ！思い出した！伝説の素材を探しに来たんだった！」"
  },
  Item_97418_Name = {
    Text = "色あせない昨日：ノティラ"
  },
  Item_97418_StoryDesc = {
    Text = "第24期学期課題"
  },
  Item_97419_Desc = {
    Text = "「もし、これが血脈を受け継ぐための避けられない宿命であるならば……」"
  },
  Item_97419_EmojiName = {
    Text = "宿命の嘆き"
  },
  Item_97419_Name = {
    Text = "ケクス・宿命の嘆き"
  },
  Item_97419_StoryDesc = {
    Text = "第25期フェーズ・チェス"
  },
  Item_9741_Desc = {
    Text = "クリティカルダメージの能力を持つ命輪。"
  },
  Item_9741_Name = {Text = "臨界点"},
  Item_9741_StoryDesc = {
    Text = "貴族夫人が憐れみと嫌悪を込めてハンカチで鼻を覆い、不要な宝石を彼女に渡すよう召使いに命じた時、彼女は思った：\nなんと素晴らしい、ワークハウスの貧しい子供たちが肉を食べられるようになった。\n\n彼女が自分の食事をすべて子供たちに分け与え、長時間の空腹で廊下で倒れた時、彼女は言った：\n大丈夫、医者を呼ばないで、診察料はパン数個分の価値があるから。\n\n親切な芸術家が知り合いの医者を連れて訪れ、長期的な協力を提案した時、彼女は思った：\nまず私で試してもらわないと、子供たちにこの治療を受けさせるのは安心できない。\n\nサラは何でも我慢できるが、唯一我慢できないのは、すべての努力が悲劇的な結末を招くことだ。"
  },
  Item_97420_Desc = {
    Text = "「……こうすればよいのか？」"
  },
  Item_97420_EmojiName = {
    Text = "サムズアップ"
  },
  Item_97420_Name = {
    Text = "カストル・サムズアップ"
  },
  Item_97420_StoryDesc = {
    Text = "第26期対人戦"
  },
  Item_97421_Desc = {
    Text = "一時的なテキスト"
  },
  Item_97421_Name = {
    Text = "シルバーキーの名において：聖嬰"
  },
  Item_97421_StoryDesc = {
    Text = "「聖嬰」プレイイベント"
  },
  Item_97422_Desc = {
    Text = "「学期課題」で「コア課題」を購入すると獲得できます。\n「パートナー…………この呼び方が気にならないといいのですが、私たちが初めて出会った時のこと、覚えていますか？ああ…………そう、つまり…………ラモーナと出会った時のことです。」"
  },
  Item_97422_Name = {
    Text = "色あせない昨日：リング・ラモナ"
  },
  Item_97422_StoryDesc = {
    Text = "第23期学期課題"
  },
  Item_9742_Desc = {
    Text = "メイン能力は、クリティカル率、クリティカルダメージ、キーチャージ、狂気増加の中からランダムに1つを獲得。"
  },
  Item_9742_StoryDesc = {
    Text = "必然、偶然。有限、無限。"
  },
  Item_9743_Desc = {
    Text = "芽胞は何を間違えたのか、ただ家が欲しかっただけなのに。\n虫蛹とその芽胞の隣人。\n血肉界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_9743_Name = {
    Text = "胞子ポリマー"
  },
  Item_9744_Name = {Text = "腸"},
  Item_9745_Desc = {
    Text = "彼女は修理できないバイクの周りをいつも回っている：ここでネジを締め、あそこでパイプを修理……\n・強力なシールドを付与\n・反撃でダメージを与える。"
  },
  Item_9745_Name = {
    Text = "ナウティラ"
  },
  Item_9746_Desc = {
    Text = "巨刃の牙で無数の敵や同族の首を斬り、自らの首も斬った。\n・力を付与し重撃を発動する\n・力は彼に追加効果を与える。"
  },
  Item_9746_Name = {
    Text = "ゴリアテ"
  },
  Item_9747_Desc = {
    Text = "メイン能力はクリティカル率、クリティカルダメージ、死亡抵抗、ダメージ強化からランダムに1つ獲得。"
  },
  Item_9747_Name = {
    Text = "環形詩篇Ⅲ"
  },
  Item_9747_StoryDesc = {
    Text = "環形時間の裂け目に漂う。"
  },
  Item_9748_Name = {
    Text = "蝋人形先生"
  },
  Item_9749_Desc = {
    Text = "メイン能力は界域知識、黒章ドロップ、死亡抵抗、ダメージ強化からランダムに1つ獲得。"
  },
  Item_9749_Name = {
    Text = "墓地の囁きⅥ"
  },
  Item_9749_StoryDesc = {
    Text = "私はあなたの墓を唾棄する。"
  },
  Item_9750_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nエリカを再度獲得した際に変換され、エリカの霊知啓発を起動するために使用。"
  },
  Item_9750_Name = {
    Text = "欠片・エリカ"
  },
  Item_9750_StoryDesc = {
    Text = "エリカを再度獲得した際に変換され、エリカの霊知啓発を起動するために使用。"
  },
