  Item_9761_Desc = {
    Text = "セット：\n有機形態Ⅰ\n有機形態Ⅱ\n有機形態Ⅲ\n有機形態Ⅳ\n有機形態Ⅴ\n有機形態Ⅵ"
  },
  Item_9761_Name = {
    Text = "有機形態"
  },
  Item_9762_Desc = {
    Text = "ミサゴ大学の創始者が研究した、覚醒体の能力を高める薬剤。\nシルバーコアと秘薬で調合され、奇妙な色合いを持つ。\n覚醒体に10000経験値を提供。"
  },
  Item_9762_Name = {
    Text = "霊知の薬剤Ⅲ"
  },
  Item_9763_Name = {
    Text = "蝋人形グループ"
  },
  Item_9764_Desc = {
    Text = "属性が死亡耐性の運命の札。"
  },
  Item_9764_Name = {
    Text = "夜に伏す"
  },
  Item_9764_StoryDesc = {
    Text = "巨獣は夜の中に潜む。\n\n小屋の中では、愛娘を失った悲しみの声が毎晩、昼間の忍耐と抑圧を破り、激しく噴き出す。\nすすり泣きから悲鳴へ、最後には巨獣にはもう属さない名前を痛みの呼び声で貫く。\n\n帰っておいで、リサ。\nああ、私のリサ。\n巨獣は無言で、夜の中に潜む。身を縮め、深く眠る。\nいつの日か、彼女は帰るだろう、「家」と呼ばれる場所へ。"
  },
  Item_9765_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nリリーを再度獲得した際に変換され、リリーの霊知啓発を起動するために使用。"
  },
  Item_9765_Name = {
    Text = "欠片・リリー"
  },
  Item_9765_StoryDesc = {
    Text = "リリーを再度獲得した際に変換され、リリーの霊知啓発を起動するために使用。"
  },
  Item_9766_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nヘロットを再度獲得した際に変換され、ヘロットの霊知啓発を起動するために使用。"
  },
  Item_9766_Name = {
    Text = "欠片・ヘロット"
  },
  Item_9766_StoryDesc = {
    Text = "ヘロットを再度獲得した際に変換され、ヘロットの霊知啓発を起動するために使用。"
  },
  Item_9767_Desc = {
    Text = "「繁殖」と「存続」がタイスの追求——この馬鹿げた主張の裏に何が隠されていようとも。\n・味方に狂気を提供\n・仲間のスキルを模倣。"
  },
  Item_9767_Name = {Text = "タイス"},
  Item_9768_Desc = {
    Text = "未知の霊知を授ける。\n映画詩クラブの特殊フィルムから生まれ、人の霊知を転写できる。\n超次元界域の覚醒体を昇格させるための素材。"
  },
  Item_9768_Name = {
    Text = "霊知テンプレート"
  },
  Item_9769_Desc = {
    Text = "羽ばたく翼は竜巻を生むか、花粉アレルギーを引き起こす。\n群れをなす水晶蝶。\n混沌界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_9769_Name = {
    Text = "混沌の結晶"
  },
  Item_9770_Desc = {
    Text = "それは工芸品ではなく、錬金術師にぶつかった蝶の悲劇的な結末。\n普通の蝶水晶。混沌界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_9770_Name = {
    Text = "失色の蝶水晶"
  },
  Item_9771_Desc = {
    Text = "花言葉：近寄らないで。\n低茎ウミユリの化石。深海界域の覚醒体のスキルレベルを上げるために使用。"
  },
  Item_9771_Name = {
    Text = "低茎ウミユリ"
  },
  Item_9772_Name = {
    Text = "特殊な融蝕痕"
  },
  Item_97737_Desc = {
    Text = "このキーオーダーを記録すると、編成時にキーオーダースキル「浜辺の思い出」を選択可能。\n\nどんな宴にも終わりは訪れる。だが、魂に刻まれた記憶は決して消えない。\n何度思い返しても、あの一瞬を思い出すたび、愛しさが波のように押し寄せる。"
  },
  Item_97737_Name = {
    Text = "浜辺の思い出"
  },
  Item_97737_StoryDesc = {
    Text = "どんな宴にも終わりは訪れる。だが、魂に刻まれた記憶は決して消えない。\n何度思い返しても、あの一瞬を思い出すたび、愛しさが波のように押し寄せる。"
  },
  Item_9773_Desc = {
    Text = "液体がその表面であり、万物の基礎であり、すべての構成要素である。\nガラス瓶に封じられた特殊な物質で、運命を干渉する力を持つと言われている。\n運命の札のレベルを上げるのに使える。"
  },
