  Item_9784_Name = {
    Text = "原初の瞳"
  },
  Item_9785_Desc = {
    Text = "不吉を象徴する夢捕り網、永遠への扉を繋ぐと言われる。\n提灯教会が神の夢の呟きを捕らえるための道具。\n覚醒体スキルレベルを上げるために使用。"
