  },
  Item_9786_StoryDesc = {
    Text = "陰鬱な雲がロンディニウムの空を覆い、月光を遮っている。真夜中の鐘が鳴り、高い煙突はまだ高温の黒煙と水蒸気を噴き出している。雪の結晶は風に舞い、地面に落ちる前に灰色に染まり、街灯に落ちてすぐに灯火の熱で溶け、通り過ぎる少女の上に滴り落ちる。\n少女は茶色のドレスを着て、袖が大きすぎて無造作にまくり上げられ、痩せた腕が露出している。彼女は苦労して小走りし、時折袖を引き上げ、前を行く女性を追いかけようとする。\n女性は少女を横目で見て、舌打ちした。「早くしなさい、遅く歩けば行かなくていいと思わないで」\n「はい、ママ、」少女は急いで女性のそばに走り、息を切らしながら言った、「ごめんなさい、ママ」\n「ママと呼ばないで！」女性は少女の腕を掴み、引きずるように歩調を速めた、「血を吸う穀潰し、あなたがいなければこんなところに落ちぶれることはなかった」\n「ごめんなさい……」\n「黙れ、役立たずめ」女性の爪が少女の腕に食い込み、深い痕を残した、「言っておくけど、これからは工場がお前の家だ、私を探しに来るなんて考えないで、死んでも会いたくない、わかった？」\n「わ……わかりました」少女は頭を下げ、落ちた涙が靴に踏まれ、汚れた雪水と共に石畳に消えた。遠くの工場が終業の笛を鳴らし、一匹の野良猫が路地を駆け抜け、細かい音が二人の足音に消えた。彼女たちは角を曲がり、洗濯物が干され湿気を放つ裏庭を通り、金属の門がある建物の前で立ち止まった。\n「ここで待ってなさい、」女性の声は非常に落ち着いていて、少し無表情だった、「夜が明ければ中の人が出てくる、彼らがあなたを受け入れてくれる。\nついて来ないで、さもないと殴り殺すわよ」\n女性は振り返り、同じく痩せて少し猫背の姿がすぐに暗闇に消えた。少女は無力に自分の手を握りしめ、女性が去った場所を見つめながら、袖で顔の涙を拭った。\n彼女の背後から薄暗い光が現れ、鉄の門と彼女の影を長く引き伸ばし、一つの手が少女の肩に落ち、少女を驚かせた。\n「かわいそうな子、一人でここにいるの？」来たのは若い女性で、修道女のような服を着ていた、「さあ、サラお姉さんが中に連れていってあげるわ。すぐに寒くなくなるよ」"
  },
  Item_9787_Desc = {
    Text = "緑炎がすべての悪党の魂を燃やし、舞台上のすべての汚れを焼き尽くす。\n・その緑炎は超次元空間で成長し続ける\n・狂気解放ですべての緑炎を燃やし尽くす。"
  },
  Item_9787_Name = {Text = "リッツ"},
  Item_9788_Desc = {
    Text = "メイン能力は界域知識、黒章ドロップ、死亡抵抗、ダメージ強化からランダムに1つ獲得。"
