  Item_9792_Desc = {
    Text = "液体がその表面であり、万物の基礎であり、すべての構成要素である。\nガラス瓶に封じられた特殊な物質で、運命を干渉する力を持つと言われている。\n運命の札のレベルを上げるのに使える。"
