  },
  Item_97989_Desc = {
    Text = "「課題レコード」で「核心課題」を購入すると獲得できます。\n「世界の頂点に立ち、ただ一人強さを味わう孤独。ああ、長寿種の人生とは、このように退屈で味気ないものなのか。」"
  },
  Item_97989_Name = {
