  },
  Item_97989_StoryDesc = {
    Text = "第21期課題記録"
  },
  Item_9798_Desc = {
    Text = "未知の認知を与える。\n映画詩クラブの特殊フィルムから生まれ、人の知識を転写できる。\n超次元界域の覚醒体の昇格素材として使用。"
  },
  Item_9798_Name = {
    Text = "認知テンプレート"
  },
  Item_97991_Desc = {
    Text = "良い祝祭とは、思いきり羽目を外すための口実になるものを指す。\n\n祭りがどれほど人々に愛されるかを決めるには、その由来が特に重要だ。\n\nあまりに小さな祝日――たとえば「植樹を奨励する日」や「間抜けなモグラを愛でる日」などでは、心ゆくまで楽しむ理由にはならない。\n\nかといって、あまりに大きな祝祭では、格式ばかりが目立ち、自由が利かない。\n\nカレンダーを一冊まるごとめくって、マーフィーが一番心待ちにしているのは、この「巡聖の祝日」だ。\n\nこの心のこもった祝祭には、夜のパーティが標準装備でついてくる。\n誰もが奇抜で滑稽な装いに身を包むこともできる。\n\nそして何より重要は事は――この日は、ミサゴのあらゆる場所が、甘味と菓子で埋め尽くされるということだ！\n\nリキュール入りキャンディ、フルーツグミ、ミント、トフィー、ミルクキャンディ、色とりどりのチョコレート……\n\nふふっ！これはもう、淑女のために用意された祭日なのではないかしら？\n\nマーフィーは意気揚々と尖った魔女帽をかぶり、ふわふわのパンプキンスカートに着替えた。\n\nそして真剣に選び抜いた特大のカボチャバスケットを手に、扉を押し開けた。\n\n「ええっ？このお菓子は、子ども専用ですって？」\n\n両手いっぱいにお菓子を抱えて帰っていくジェンキンの背中を見送りながら、淑女は信じられないというように眉を吊り上げた。\n\nスカートの下から伸びた触手が、苛立ったようにびくびくと揺れる。\n\nぎり、と噛みしめる歯。\n彼女は冷笑を浮かべると、カボチャバスケットをカウンターにドンと叩きつけた。\n\n「もらえないっていうのね？ならいいわ、今のわたくしは子どもじゃない――強盗よ！三つ数えるわ！その間にこのお菓子、ぜ～んぶ包みなさい！早く！」\n\n冷や汗をかいた給仕は泣く泣くキャンディコーナーを空にし、溢れんばかりのバスケットを手にした淑女が、高笑いとともに堂々と立ち去るのを見送った。\n\nその不気味な笑い声は、学園のあちこちにこだまし、夜通し止むことはなかった。\n\nそして後日、ミサゴ大学にはこんな噂が広まった――\n巡聖の祝日の夜、スイーツを持ち歩いている者は、幽霊に取り憑かれた「キャンディ狩りの魔女」に必ず見つかる。\n\n彼女の恐ろしい手から逃れるにはすべての菓子を捧げるしかないのだ、と。"
  },
  Item_97991_Name = {
    Text = "キャンディ魔女"
  },
  Item_97992_Desc = {
    Text = "特別にパンプキンの形に作られた祭り用キャンディで、中のフィリングは様々な具材が混ざっており、非常に奇妙な味に出会うことがあると言われている。"
  },
