  Item_9813_Name = {
    Text = "再進化Ⅰ"
  },
  Item_9813_StoryDesc = {
    Text = "繁殖せよ、繁殖せよ。母樹の血が流れる魂を世界に広めよ。"
  },
  Item_9814_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nダフォダイルを再度獲得した際に変換され、ダフォダイルの霊知啓発を起動するために使用。"
