  Item_9815_Desc = {
    Text = "メイン能力は界域知識、黒章ドロップ、死亡抵抗、ダメージ強化からランダムに1つ獲得。"
  },
  Item_9815_Name = {
    Text = "生命力搾取Ⅵ"
  },
  Item_9815_StoryDesc = {
    Text = "へその緒は無限の未来に繋がっている。"
  },
  Item_9817_Desc = {
    Text = "属性がシルバーキー充電レベルに基づく命輪。"
  },
  Item_9817_Name = {
    Text = "時を遡る時計"
  },
  Item_9817_StoryDesc = {
    Text = "両手剣は長く重く、十分な力があれば人を二つに切ることができる。\n\n短剣は軽くて巧妙で、隠しやすく、不意打ちに最適だ。\n\n湾曲した刀は美しい曲線を持ち、刃が鋭く、切り裂くときに簡単に肉に食い込み、深い傷を開くことができる。\n\n銃器は速くて強力で、クロスボウの矢は無音で迅速だ。さまざまな金属部品が灯りの下で冷たい光を放っている。十歳のラモンナは、壁一面に掛けられた武器の前に立ち、年齢にそぐわない成熟と慎重さを顔に浮かべている。\n\n「どれを選ぶ？」養父——いや、育ててくれた父——の声が背後から聞こえる。「選んだら、先生を見つけてあげるよ」\n\nどれにしよう？大剣の重さは利点でもあり欠点でもある。短剣は長い武器には対処しにくい。湾曲した刀は長いが、切るときに多くの不必要な損傷をもたらす。銃器は音が大きすぎ、クロスボウの矢は弾薬が尽きやすい。\n\nミサゴの訓練場で何日も観察して、彼女は戦う両者の弱点を一目で見抜き、ほぼ直感的に攻撃ルートを計画できることを知っている。それらは大量の経験を積まなければわからないことだが、彼女には一瞬で推測できる。いや、彼女が求めているのはそれではない。彼女は最小の力で最大のダメージを与えることができる、より正確な武器を必要としている。\n\n少女はしばらく考え、横にあった椅子を持ってきて、その上に立ち、高いところに掛けられた細剣に手を伸ばした。\n\n細く優雅で、柔軟で軽く、非常に正確にダメージを与えることができる——そう、これだ。彼女のすべての要求に合っている。"
  },
  Item_9818_Desc = {
    Text = "彼女がどうやって話すのか——それは学院の無数の未解決の謎の一つとなっている。\n・力の獲得と警戒の獲得を行き来する\n・超次元跳躍時に攻防を兼ね備える。"
  },
  Item_9818_Name = {Text = "エリカ"},
  Item_9819_Desc = {
    Text = "セット：\n無垢の啓示録Ⅰ\n無垢の啓示録Ⅱ\n無垢の啓示録Ⅲ\n無垢の啓示録Ⅳ\n無垢の啓示録Ⅴ\n無垢の啓示録Ⅵ"
  },
  Item_9819_Name = {
    Text = "無垢の啓示録"
  },
  Item_9822_Name = {
    Text = "フランシスの懐中時計"
  },
  Item_9823_Desc = {
    Text = "そう、すべては精錬可能だ。あなたの本能、理性、そして心さえも……結局、あなたは彼らと何も変わらないことに気づくでしょう。\n深海界域の覚醒体を昇格させるための素材。"
  },
  Item_9823_Name = {
    Text = "理性の精錬"
  },
  Item_9824_Desc = {
