  },
  Item_9826_StoryDesc = {
    Text = "ライカーを再度獲得した際に変換され、ライカーの霊知啓発を起動するために使用。"
  },
  Item_98279_Desc = {
    Text = "幻衣「血の如き紅葉」獲得後に解放。\n「その揺らめく純白のドレスの裾には、鮮やかな紅葉が咲き誇っていた」"
  },
  Item_98279_Name = {
    Text = "「24」・血の如き紅葉"
  },
  Item_9827_Desc = {
    Text = "狂気解放後に臨時クリティカルダメージを提供し、一定確率で装備者のカードコストを低下させる。"
  },
  Item_9827_Name = {
    Text = "巨人の刃"
  },
  Item_9827_StoryDesc = {
    Text = "分かれる。経験する。群がる。侵略する。\n\nペリシテ人のセム語の語根「p-l-sh」の真の意味について、学者たちは常に意見が分かれている。\n生まれて初めて、ゴリアテはこれらの学者たちが少しは本物の知識を持っていると感じた。\nこれらの四つの短い言葉は、彼のペリシテ人としての人生をほぼ要約しているからだ。\n\nペリシテ人は名実ともに海の民だ。\n彼らは群れを成す長尾のサメで、血の匂いを頼りに住む島を見つけ、そこにいるすべての原住民を殺す。\n\nペリシテ人は疲れを知らない。\n彼らは決して留まらず、すべてが終わると、落ち着かない遺伝子が彼らを駆り立て、新たな獲物を探しに行く。\n\nペリシテ人は明日を気にしない。\n彼らは驚くべき速さで略奪した富を浪費し、最後の一滴のワインを飲み干し、繁殖し、争い、裏切る……\n\n出航の時、ゴリアテは船が海面に残した軌跡を振り返る。\nペリシテ人の血、原住民の血、敵の血、海鳥の血……\nそれらは一つに混ざり、暗赤色のインクが無限の青に流れ込むようだ。\n\n翌日、太陽はいつも通り昇り、海水は無数の金の破片のように揺れ輝き、すべては跡形もなくなる。\n彼らは海にいるが、海はすでに彼らを忘れている。"
  },
  Item_9828_Desc = {
    Text = "あまりに強硬な者には、彼女は戦いで魂を和らげる。\n・チームの力を上げる。\n・すべての敵を攻撃するスキルを持つ。"
  },
  Item_9828_Name = {
    Text = "ロータン"
  },
  Item_9829_Desc = {
    Text = "彼は超人的な知恵に飽き、狂信的な崇拝に飽き、永遠の夢にも飽きていた。\n・触腕を指揮し、攻撃を仕掛ける\n・行動力を消費し、触腕の力を強化。"
  },
  Item_9829_Name = {
    Text = "トゥルー"
  },
  Item_9831_Desc = {
    Text = "メイン能力は、界域知識、狂気増加、黒章ドロップ、キーチャージの中からランダムに1つを獲得。"
  },
  Item_9831_Name = {
    Text = "深海航路Ⅳ"
  },
  Item_9831_StoryDesc = {
    Text = "帰還せよ、いつか再現される失われた都市よ。"
  },
  Item_9833_Desc = {
    Text = "霊知が無限に拡大されると、真実の一端に触れる。\nシルバーコアで駆動する特殊装置で、設定値に従って覚醒体の能力を永久に向上させる。\n守秘者がレベル30に達すると、任意の覚醒体を選び、以下の強化を受けることができる：\n・レベル40に増加\n・全スキルがレベル2に増加\n・突破等階が3階に増加"
  },
  Item_9833_Name = {
    Text = "霊知増幅器Ⅳ"
  },
  Item_9834_Desc = {
    Text = "ミサゴ大学の創始者が研究した、覚醒体の能力を高める薬剤。\nシルバーコアと秘薬で調合され、奇妙な色合いを持つ。\n覚醒体に2000経験値を提供。"
  },
  Item_9834_Name = {
    Text = "霊知の薬剤Ⅱ"
  },
  Item_9835_Desc = {
    Text = "たとえそれが彼女の本意でなくとも、世には暗闇に独り住むべき生き物がいるかもしれない。\n・敵の行動を遅延\n・敵に軟化を与える。"
  },
  Item_9835_Name = {
