  },
  Item_9880_Desc = {
    Text = "古代の意志の失われた霊知。\nミサゴは神秘的な儀式で覚醒体の霊知を啓発し、啓発された覚醒体は精神能力を永久に強化する。\n\nサンガーを再度獲得した際に変換され、サンガーの霊知啓発を起動するために使用。"
