  Item_9880_Name = {
    Text = "欠片・サンガー"
  },
  Item_9880_StoryDesc = {
    Text = "サンガーを再度獲得した際に変換され、サンガーの霊知啓発を起動するために使用。"
  },
  Item_9881_Desc = {
    Text = "安定して鍵エネルギーを獲得すると同時に鍵令の発動に伴いチームに狂気を提供し、追加の手札上限と胚胎獲得がより柔軟な選択をもたらす総合型の運命の札。"
  },
  Item_9881_Name = {
    Text = "慈悲の育み"
  },
  Item_9881_StoryDesc = {
    Text = "歴史とは常に勝者の独壇場だ。\n母樹の消滅、国家の転覆など、過去に関するすべては、静かに姿かたちを変えられている。\n\n詩人はニニバーの美女の物語を歌い継ぎ、旅人たちは焚き火を囲んで耳を傾ける。\n\n「銀色の砂漠を越え、異国の美女がニニバーに踏みいる——\n\n天の川の水が、その肩を滑り落ち。シナイの真珠が、その瞳からこぼれ落ちる——\n\n黄金の瞳の奥には異国の過去が映り。蜜色の肌には、ニニバーの未来が記されていた——」\n\nその後どうなったのか？\nこの美女は王妃になったのか？\n\n年老いた詩人は七弦琴を爪弾きながら、長いため息をついた。\n\n「彼女は媚薬——\n人々は皆、彼女に酔いしれる。\n\n彼女は猛毒——\n王と臣下の肺腑に染み渡る。\n\n彼女は洪水——\n人々は皆、逃れられぬ。\n\n彼女は黒い疫病の使者——\n疫病と、悪夢と、死、そして、ニニバーの終焉をもたらした」\n\n琴がまだ置かれぬうちに、酒卓のそばから一人が立ち上がり、酒客たちの視線を集めた。\n\nその人物の細い指の間から数枚の酒銭がこぼれ落ちる。金銀が転がり、チリンと音を立てた。 \n\n彼女の歩む先を視線が追従し、灯火がきらめいた。\n\n「時は流れゆく……\nだけど構わない、あのお方はこんな戯言には応えない……\n\nいつかあなた達も、あのお方の慈悲と寛容を理解する……\n私がそう理解したように……」\n\n彼女は酒場の古びた小さな扉を押し開けた。まるで宝石箱を、開けるように。\n\n月の光が露わな肩に降り注ぎ、きらめく光を映し出した。\n\nその月の光に愛された美女は、まさに蜜色の肌をしていた。"
  },
