  },
  Item_9884_Desc = {
    Text = "<SummonRed:『薔薇の書』獲得報酬UP>\nダメージを与える際に本ターン中無限にクリティカルダメージを重ね掛けでき、単ターンで連続して敵を攻撃できる覚醒体に適した運命の札。"
  },
  Item_9884_Name = {
    Text = "薔薇の名において"
  },
  Item_9884_StoryDesc = {
    Text = "田舎の娘が派手なドレスや金銀の装飾品、羽扇を身にまとい、上流社会に潜り込むなんて……\nこれ以上不適切なことはない。下克上、まさに下克上……！\n私の意見では、下層の者には相応の識別マークやバッジを強制的に付けさせるべきだ。\nそうすれば我々と混同されることはない。\n——フィリップ・ハロルド公爵\n\nもしロンディニウムに住んでいるなら「ソレール効果」について聞いたことがあるだろう。\n自分の服が売れないことに悩んでいる？\nそれならソレール夫人の目に留まることを祈るべきだ——\nそう、たとえそれが愚かしい豚の尻尾帽子でも、ソレール夫人が被れば大ヒットする。\n彼女は新時代の大衆アイドルなのだから。\n——「ソレール夫人の人気テスト」《淑女の心得》\n\nそれは晴れた夏の夜だった。\n私たちは大理石のテラスに座り熟成された貴腐ワインを飲みながら詩と世界平和について語り合った。\nそして@4が起こった——要点を言え？\nこほん、すまない……\nとにかく、この女性は私から3000スタール、スリランの不動産2件、そして誠実な心を騙し取った！\n——匿名希望の心痛の子爵"
  },
