  Item_99102_Desc = {
    Text = "このキーオーダーを記録すると、編成時にキーオーダースキル「虚空の色彩」を選択可能。\n\n崩壊した幻覚が網膜の上に歪んだネオンを生み出す――\n腐りゆく幻覚が網膜に歪んだネオンを生み出す——\nかくして「色彩」という概念は虚の世界へと昇華され、現実の骸の上を流れる、狂おしいほど鮮烈な色だけが残された。"
  },
  Item_99102_Name = {
    Text = "虚空の色彩"
  },
  Item_99102_StoryDesc = {
    Text = "腐りゆく幻覚が網膜に歪んだネオンを生み出す——\nかくして「色彩」という概念は虚の世界へと昇華され、現実の骸の上を流れる、狂おしいほど鮮烈な色だけが残された。"
  },
  Item_9910_Desc = {
