  Item_9913_Desc = {
    Text = "ハレト学長代理特別許可の豊富な補給。\n貴重な材料を封入した木箱、課題任務を遂行する守秘者に援助を提供。\n以下の素材から1つ選択：\n純白の文書×12\n理性の精錬×12\n感情のコピー×12\n精神テンプレート×12"
