  },
  Item_99724_Desc = {
    Text = "このキーオーダーを記録すると、編成時にキーオーダースキル「泣血の聖心」を選択可能。\n\n彼はついに、すべての記憶と力を取り戻した。だがそれは、守りたかったすべてを代償にしてのことだった。\n彼は遅すぎたのだ。\nただ、怒りと後悔に満ちた血の涙だけが、震える心臓を焼き焦がしている。"
  },
  Item_99724_Name = {
