    Text = "彼はついに、すべての記憶と力を取り戻した。だがそれは、守りたかったすべてを代償にしてのことだった。\n彼は遅すぎたのだ。\nただ、怒りと後悔に満ちた血の涙だけが、震える心臓を焼き焦がしている。"
  },
